                Translate(GUID, null, value.DisplayedName + " in a Bottle", value.DisplayedNameLocalized + " in bottiglia", Language.Italian);
                string text2 = "A";
                string text2Loc = "Una carta";
                string text3 = "[define:" + value.Name + "]";
                string text3Loc = "[define:" + value.Name + "]";
                if (NameStartsWithVowel(value.DisplayedName))
                {
                    text2 = "An";
                    string text4 = "";
                    string text4Loc = "";
                    foreach (Ability ability in value.Abilities)
                    {
                        text4 = text4 + ", " + AbilitiesUtil.GetInfo(ability).rulebookName;
                        text4Loc = text4Loc + ", " + ItalianLanguagePack.Localize(AbilitiesUtil.GetInfo(ability).rulebookName);
                    }
                    text4 += ".";
                    text4Loc += ".";
                    text3 = string.Format("An {0} is defined as: {1} Power, {2} Health", value.DisplayedName, value.Attack, value.Health) + text4;
                    text3Loc = string.Format("{0} ha: {1} di potenza, {2} di salute", value.DisplayedNameLocalized, value.Attack, value.Health) + text4Loc;
                }
                string text5 = string.Concat(new string[] { text2, " ", value.DisplayedName, " is created in your hand. ", text3 });
                string text5LocCardName = value.DisplayedNameLocalized;
                string text5Loc = string.Concat(new string[] { text2Loc, " ", text5LocCardName, " viene creata nella tua mano. ", text3Loc });
                Translate(GUID, null, text5, text5Loc, Language.Italian);
                Translate(GUID, null, "While " + value.DisplayedNameLocalized + " is on the board, remove ally Terrain and Pelt cards and transform the rest into random Apostles.", "Finché " + value.DisplayedNameLocalized + " è sul tavolo, rimuovi le carte alleate Terreno e Pelle e trasforma le altre in Apostoli casuali.", Language.Italian);
                Translate(GUID, null, "[c:bR]The Clock[c:] and your [c:bR]" + value.DisplayedNameLocalized + "[c:] will remain in that abandoned time.", "[c:bR]L'Orologio[c:] e la tua carta [c:bR]" + value.DisplayedNameLocalized + "[c:] resteranno in quel tempo abbandonato.", Language.Italian);
                Translate(GUID, null, "False " + value.DisplayedNameLocalized, value.DisplayedNameLocalized + " (imitazione)", Language.Italian);
                Translate(GUID, null, "[c:bB]That " + value.DisplayedNameLocalized + " costs more energy than you have.[c:]", "[c:bB]Non hai abbastanza energia per giocare " + value.DisplayedNameLocalized + ".[c:]", Language.Italian);
            }
            if (source == null)
            for (int max = 1; max <= 10; max++)
            {
                Translate(GUID, null, "[c:bB]Do you still not get it? It costs " + max.ToString() + " energy and you don't have enough.[c:]", "[c:bB]Non hai ancora capito? Costa " + max.ToString() + " energia e non ne hai abbastanza.[c:]", Language.Italian);
                for (int count = 0; count < max; count++)
                {
                    Translate(GUID, null, "[c:bB]That costs " + max.ToString() + " energy and you have " + count.ToString() + ".[c:]", "[c:bB]Costa " + max.ToString() + " energia e tu ne hai " + count.ToString() + ".[c:]", Language.Italian);
                }
            }


            // LifeCostAPI
            if (source == null) Debug.Log("Post Register Translations for LifeCostAPI");
            foreach (var value in cards)
            {
                if (!value.HasDisplayedNameEnglish) continue;
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:bG]Scales[c:] are too tipped to play [c:bG]" + value.DisplayedNameLocalized + "[c:].", "La tua [c:bG]bilancia[c:] è troppo inclinata per giocare [c:bG]" + value.DisplayedNameLocalized + "[c:].", Language.Italian);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]" + value.DisplayedNameLocalized + "[c:] requires you to pay in life, in which you can not fullfill without killing yourself.", "Giocare [c:bG]" + value.DisplayedNameLocalized + "[c:] costa vita e non puoi pagare senza morire.", Language.Italian);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You would kill yourself if you played [c:bG]" + value.DisplayedNameLocalized + "[c:]. Your [c:bG]Scales[c:] are too tipped", "Giocare [c:bG]" + value.DisplayedNameLocalized + "[c:] ti ucciderebbe. La tua [c:bG]bilancia[c:] è troppo inclinata.", Language.Italian);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:bG]Scales[c:] are too tipped and you lack the [c:gray]Foils[c:] to play " + value.DisplayedNameLocalized + ".", "La tua [c:bG]bilancia[c:] è troppo inclinata e non hai abbastanza [c:gray]carte laminate[c:] per giocare " + value.DisplayedNameLocalized + ".", Language.Italian);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You lack the foils to play that [c:gray]" + value.DisplayedNameLocalized + "[c:].", "Non hai abbastanza carte laminate per giocare [c:gray]" + value.DisplayedNameLocalized + "[c:].", Language.Italian);
                for (int count = 0; count <= 20; count++)
                {
                    Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:gray]" + value.DisplayedNameLocalized + "[c:] requires you pay it's cost in [c:gray]foils[c:], that which you have [c:gray]" + count.ToString() + "[c:].", "[c:gray]" + value.DisplayedNameLocalized + "[c:] costa [c:gray]carte laminate[c:]; ne hai [c:gray]" + count.ToString() + "[c:].", Language.Italian);
                    Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That [c:gray]" + value.DisplayedNameLocalized + "[c:] has the cost of [c:gray]" + count.ToString() + "[c:] foils, which you do not have.", "[c:gray]" + value.DisplayedNameLocalized + "[c:] costa [c:gray]" + count.ToString() + "[c:] " + (count == 1 ? "carta laminata" : "carte laminate") + " e non ne hai abbastanza.", Language.Italian);
                }
            }

            // Sire_MoDeers
            if (source == null) Debug.Log("Post Register Translations for Sire_MoDeers");
            foreach (var value in cards)
            {
                if (!value.HasDisplayedNameEnglish) continue;
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, value.DisplayedName + "'s Protector", "Spirito protettore di «" + value.DisplayedNameLocalized + "»", Language.Italian);
            }

            if (source == null) Debug.Log("Post Register Translations Ended");
            stopwatch.Stop();
            if (source == null) Debug.Log($"PostRegisterTranslations 执行时间: {stopwatch.ElapsedMilliseconds} ms");
        }

        private static List<PostRegisterCardData> CachePostRegisterCardData(IEnumerable<CardInfo> source)
        {
            var cards = new List<PostRegisterCardData>();
            foreach (var card in source)
            {
                if (card.SafeIsUnityNull()) continue;
                cards.Add(new PostRegisterCardData(card, card.IsBaseGameCard()));
            }
            return cards;
        }

        private sealed class PostRegisterCardData
        {
            public PostRegisterCardData(CardInfo card, bool isBaseGameCard)
            {
                IsBaseGameCard = isBaseGameCard;
                DisplayedNameEnglish = card.DisplayedNameEnglish;
                DisplayedNameLocalized = card.DisplayedNameLocalized;
                DisplayedName = card.displayedName;
                Description = card.description;
                Name = card.name;
                Attack = card.Attack;
                Health = card.Health;
                Abilities = card.Abilities?.ToArray() ?? Array.Empty<Ability>();
            }

            public bool IsBaseGameCard { get; }
            public string DisplayedNameEnglish { get; }
            public string DisplayedNameLocalized { get; }
            public string DisplayedName { get; }
            public string Description { get; }
            public string Name { get; }
            public int Attack { get; }
            public int Health { get; }
            public Ability[] Abilities { get; }
            public bool HasDisplayedNameEnglish => DisplayedNameEnglish != null;
            public bool HasDisplayedName => DisplayedName != null;
        }
        private static bool NameStartsWithVowel(string name)
        {
            if (string.IsNullOrEmpty(name))
            {
                return false;
            }
            char c = name.ToLowerInvariant()[0];
            return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
        }

    }

