            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RESET RUN", "REIMPOSTA L'AVVENTURA", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEW LESHY RUN", "NUOVA SESSIONE CON LESHY", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONTINUE LESHY RUN", "CONTINUA SESSIONE CON LESHY", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEW GRIMORA RUN", "NUOVA SESSIONE CON GRIMORA", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONTINUE GRIMORA RUN", "CONTINUA SESSIONE CON GRIMORA", Language.Italian);

            // Config
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This option will allow you to see what cards are left in your deck.", "Questa opzione permette di vedere quali carte restano nel tuo mazzo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This option will disable all effects that might cause motion sickness and other visually jarring effects.", "Questa opzione disattiva tutti gli effetti che possono causare nausea da movimento o altri disturbi visivi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Does not generate blocker pieces. Chests fill first row, enemy pieces fill first column.", "Non genera pezzi che bloccano il passaggio. I forzieri riempiono la prima fila e i pezzi nemici la prima colonna.", Language.Italian);
