            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For players who want to continue playing with their deck after defeating Grimora.", "Per chi vuole continuare a giocare con il proprio mazzo dopo aver sconfitto Grimora.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "0 = Default. Use the mod's internal blueprint system.\n1 = Randomized. Encounters are completely randomized using the mod's internal card pool.\n2 = Custom. Encounters are from made and used from the JSON files.\n3 = Mixed. Encounters are from both default list and custom list.", "0 = Predefinito. Usa il sistema di schemi interno della mod.\n1 = Casuale. Gli incontri sono completamente casuali e usano la raccolta di carte interna della mod.\n2 = Personalizzato. Gli incontri vengono creati dai file JSON.\n3 = Misto. Gli incontri provengono sia dall'elenco predefinito sia da quello personalizzato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "0 = W for viewing deck, S for getting up from the table.\n1 = Up arrow for viewing deck, down arrow for getting up from the table.", "0 = W per vedere il mazzo, S per alzarsi dal tavolo.\n1 = Freccia su per vedere il mazzo, freccia giù per alzarsi dal tavolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "0 = Default. Flat 50% burn rate for each lever option on second shock.\n1 = Base 30% chance to burn plus 0%, 10%, or 20% for low, medium, high, respectively. Meaning, if the first shock is high then the second is high, the chance for the card to be destroyed is 70%.\n2 = Low: 12.5%, Medium: 17.5%, High 30%. Meaning, if the first shock is high, then the second one is also high, the chance for the card to be destroyed is 60%.\n3 = Low: 12.5%, Medium: 20%, High 27.5%. Meaning, if the first shock is high, then the second one is also high, the chance for the card to be destroyed is 55%.", "0 = Predefinito. Ogni posizione della leva ha una probabilità fissa di distruzione del 50% alla seconda scossa.\n1 = Probabilità base del 30%, più 0%, 10% o 20% per intensità bassa, media o alta. Se entrambe le scosse sono ad alta intensità, la carta ha quindi il 70% di probabilità di essere distrutta.\n2 = Bassa: 12.5%, media: 17.5%, alta: 30%. Se entrambe le scosse sono ad alta intensità, la carta ha quindi il 60% di probabilità di essere distrutta.\n3 = Bassa: 12.5%, media: 20%, alta: 27.5%. Se entrambe le scosse sono ad alta intensità, la carta ha quindi il 55% di probabilità di essere distrutta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dont change this value, it is used by the game to store certain events.", "Non modificare questo valore: il gioco lo usa per memorizzare alcuni eventi.", Language.Italian);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 Souls to select any card on the board, [creature] will deal 1 damage to the selected card if it is an opponent card, if it isn't, [creature] will heal it for 1 health.", "Spendi 3 anime per scegliere una carta qualsiasi sul tavolo. Se è una carta avversaria, [creature] le infligge 1 danno; altrimenti, [creature] le ripristina 1 salute.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Comin' right up!", "Arriva subito!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Shot", "Colpo d'anima", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Soul to deal 1 damage to the creature across from [creature].", "Spendi 1 anima per infliggere 1 danno alla creatura di fronte a [creature].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disinter", "Esumazione", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Bone to create a Skeleton in your hand.", "Spendi 1 osso per creare uno Scheletro nella tua mano.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Materialize", "Materializzazione", Language.Italian);
