            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opponent creature perishes, [creature] will store a charge of soul energy, up to 4. Activating this sigil will add 3 soul energy to your current energy counter, and one max energy.", "Quando una creatura avversaria muore, [creature] accumula una carica di energia dell'anima, fino a un massimo di 4. Attivare questo sigillo aggiunge 3 energia dell'anima al tuo contatore di energia attuale e aumenta di un punto l'energia massima.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weighted Die", "Dado truccato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones for the power of [creature] to be randomized between 0 and 5.", "Spendi 2 ossa per assegnare alla potenza di [creature] un valore casuale tra 0 e 5.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] alternates between striking the opposing space to the left and right from it.", "[creature] attacca alternativamente gli spazi avversari alla propria sinistra e alla propria destra.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is unaffected by the motion of the ship.", "[creature] non subisce gli effetti del movimento della nave.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike its adjacent slots, and each opposing space to the left, right, and center of it.", "[creature] attacca gli spazi adiacenti e ciascuno degli spazi avversari a sinistra, a destra e al centro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] yields no bones upon death.", "[creature] non produce ossa alla morte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another creature, gain 2 bones.", "Quando [creature] uccide un'altra creatura, ottieni 2 ossa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] takes 1 Soul from you at the end of every turn and stores it as 2 Bones, up to a maximum of 8. When [creature] dies, you gain all bones contained in it.", "Alla fine di ogni turno, [creature] prende 1 anima da te e la accumula sotto forma di 2 ossa, fino a un massimo di 8. Quando [creature] muore, ottieni tutte le ossa che contiene.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] empowers each Skeleton on the owner's side of the board, providing a +1 buff to their power.", "[creature] potenzia ogni Scheletro sul lato del tavolo del suo proprietario, conferendogli +1 potenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sea Shanty", "Canto marinaresco", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike the opposing slots to the left, right, and center of it randomly, up to 3 times.", "[creature] attacca casualmente gli spazi avversari a sinistra, a destra e al centro, fino a 3 volte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the card opposing it is Frozen Away if not already frozen.", "Quando [creature] muore, la carta di fronte viene congelata se non lo è già.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, gain a consumable item, if you have a free slot.", "Quando [creature] muore, ottieni un oggetto consumabile se hai uno spazio libero per gli oggetti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Skeleton is created in each empty space on the owner's side. [define:Skeleton]", "Quando si gioca [creature], viene creato uno Scheletro in ogni spazio vuoto sul lato del suo proprietario. [define:Skeleton]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleton Horde", "Orda di scheletri", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shipwreck Finder", "Cercatore di relitti", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Shipwreck is created on each empty adjacent space. [define:arackulele.inscryption.grimoramod_Shipwreck_Dams]", "Quando si gioca [creature], viene creato un Relitto in ogni spazio adiacente vuoto. [define:arackulele.inscryption.grimoramod_Shipwreck_Dams]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeletons Within", "Scheletri interiori", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once [creature] is struck, draw a card from your Skeleton pile.", "Quando [creature] viene colpita, pesca una carta dalla tua pila di Scheletri.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Full o' candy", "Pieno di caramelle", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will yield candy upon death, maybe this will be useful for later.", "[creature] produce caramelle alla morte. Forse torneranno utili più avanti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in a random direction.", "Alla fine del turno del suo proprietario, [creature] si muove in una direzione casuale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever [creature] moves, it leaves a trail of Embers. [define:arackulele.inscryption.grimoramod_Flames]", "Ogni volta che [creature] si muove, lascia una scia di braci. [define:arackulele.inscryption.grimoramod_Flames]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guarding Presence", "Presenza protettiva", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opposing creature is placed opposite to an empty space, [creature] will move to that empty space.", "Quando una creatura avversaria viene posizionata di fronte a uno spazio vuoto, [creature] si sposta in quello spazio vuoto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Starved", "Affamato d'ossa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you have no Bones, at the start of your turn [creature] deals 2 more damage.", "Se non hai ossa, all'inizio del tuo turno [creature] infligge 2 danni aggiuntivi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space. If only one creature is in the opposing spaces, this card will strike that creature twice. ", "[creature] attacca ogni spazio avversario. Se negli spazi avversari si trova una sola creatura, questa carta la attacca due volte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enraged Giant", "Gigante infuriato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space.", "[creature] attacca ogni spazio avversario.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fledgling", "Astro nascente", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After one turn on the board, [creature] will evolve into a greater form.", "Dopo un turno sul tavolo, [creature] evolve in una forma superiore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Random Ability", "Entità amorfa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, this sigil is replaced with another sigil at random.", "Quando si pesca [creature], questo sigillo viene sostituito da un altro sigillo casuale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it haunts the space it died in. The first creature played on this space gain its old sigils.", "Quando [creature] muore, infesta lo spazio in cui è morta. La prima creatura giocata in quello spazio ottiene i suoi vecchi sigilli.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunting Call", "Richiamo spettrale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every turn [creature] is on the Board, it will take a Bone from you, if you have no Bones, it perishes.", "A ogni turno in cui [creature] è sul tavolo, ti prende un osso. Se non hai ossa, muore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the creature in the opposing slot is dragged onto the owner's side of the board.", "Quando [creature] muore, la creatura nello spazio di fronte viene trascinata sul lato del tavolo del proprietario della carta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-brittle ally card perishes, [creature] gains 1 power.", "Quando muore una carta alleata senza Fragilità, [creature] ottiene 1 di potenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike the opposing slot as if the board was flipped. A card in the far left slot will attack the opposing far right slot.", "[creature] attacca lo spazio di fronte come se il tavolo fosse capovolto. Una carta nello spazio più a sinistra attacca lo spazio avversario più a destra.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Bonedigger sigil.", "Quando [creature] muore, il suo proprietario sceglie una creatura che ottiene il sigillo «Scavaossa».", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Waterborne sigil.", "Quando [creature] muore, il suo proprietario sceglie una creatura che ottiene il sigillo «Acquatico».", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] loses 1 health per turn. When [creature] dies, the creature opposing it, as well as adjacent friendly creatures, are dealt 10 damage.", "[creature] perde 1 di salute per turno. Quando [creature] muore, la creatura di fronte e le creature alleate adiacenti subiscono 10 danni.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] would be struck, a severed limb is created in its place and this card moves into an adjacent open slot.", "Quando [creature] sta per essere colpita, al suo posto viene creato un arto reciso e questa carta si sposta in uno spazio libero adiacente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each time [creature] deals damage directly, it loses 1 power and health.", "Ogni volta che [creature] infligge danni diretti, la sua potenza e la sua salute diminuiscono entrambe di 1.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, also play the cards in your hand that were adjacent to this card for free.", "Quando si gioca [creature], si giocano gratuitamente anche le carte che le erano adiacenti nella tua mano.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Douse", "Estinzione", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When played,[creature] will extinguish all cards on the Board.", "Quando si gioca [creature], spegne tutte le carte sul tavolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cannot be attacked from the opposing slot. The opposing slot, if possible, instead attacks one of its adjacent friendly cards.", "[creature] non può essere attaccata dallo spazio di fronte. Se possibile, la carta in quello spazio attacca invece una delle carte alleate adiacenti a essa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards on the owner's side of the field are unaffected by Brittle.", "Le carte sul lato del tavolo del proprietario non subiscono gli effetti di Fragilità.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike its adjacent slots, except other Raiders.", "[creature] attacca gli spazi adiacenti, a eccezione degli altri Predoni.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it carves its Sigils into adjacent Cards.", "Quando si gioca [creature], incide i propri sigilli sulle carte adiacenti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sculptor", "Incisore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attempt to find a host in an adjacent friendly slot, hiding under it providing a +1/+1 buff. Cards on the left take priority.", "[creature] cerca un ospite in uno spazio alleato adiacente, si nasconde sotto di esso e gli conferisce un potenziamento di +1/+1. Le carte a sinistra hanno la precedenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] hits an opposing card, one of the targets adjacent allies will take damage as well ", "Quando [creature] colpisce una carta avversaria, anche uno degli alleati adiacenti al bersaglio subisce danni.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it provides an energy soul to its owner.", "Quando si gioca [creature], fornisce un'anima energetica al suo proprietario.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HellHound's Thirst", "Sete del segugio infernale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 1 attack for each bone the player currently has.", "Una carta che possiede questo sigillo ottiene 1 di potenza per ogni osso attualmente posseduto dal giocatore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wrath Of Halloween", "Ira di Halloween", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil has 10 attack, 1 for each Candy Bucket Sawyer has left.", "Una carta che possiede questo sigillo ha 10 di potenza, 1 per ogni Secchio di caramelle rimasto a Sawyer.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trusty ol' Crew", "Cara vecchia ciurma", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 1 attack for every pirate on the board.", "Una carta che possiede questo sigillo ottiene 1 di potenza per ogni pirata sul tavolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inanimate Attack", "Attacco inanimato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 1 attack for every card that has 0 attack on the board.", "Una carta che possiede questo sigillo ottiene 1 di potenza per ogni carta con 0 di potenza sul tavolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Half Bones", "Mezzo osso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Bones that the owner has on their side of the table.", "Il valore di questo sigillo equivale al numero di ossa che il proprietario ha sul proprio lato del tavolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double Death", "Doppia morte", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Soul to add power to [creature] randomly between 1 and 6.", "Paga 1 anima per conferire a [creature] una quantità casuale di potenza compresa tra 1 e 6.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to heal [creature] to max health.", "Paga 2 ossa per riportare [creature] alla salute massima.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alternating Strike", "Colpo alternato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anchored", "Ancorato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Area Of Effect Strike", "Colpo ad area", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Guzzler", "Succhiasangue", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boneless", "Senz'ossa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Thief", "Ladro d'ossa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bounty", "Cacciatore di taglie", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning", "In fiamme", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] takes 1 Damage at the end of your turn, when it gets attacked by another Card, that card gets set on fire.", "[creature] subisce 1 danno alla fine del tuo turno. Quando viene attaccata da un'altra carta, quella carta prende fuoco.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chaos Strike", "Colpo del caos", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cold Front", "Fronte freddo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Collector", "Collezionista", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Erratic", "Imprevedibile", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flame Strafe", "Incursione di fuoco", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Strike", "Colpo gigante", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunter", "Infestatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hook Line And Sinker", "Amo, lenza e piombo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Imbued", "Infuso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inverted Strike", "Colpo invertito", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Latch Bone Digger", "Donazione di scavaossa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Latch Submerge", "Donazione di acquatico", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lit Fuse", "Miccia accesa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loose Limb", "Arto staccabile", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malnourishment", "Malnutrizione", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Marching Dead", "Morti in marcia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Possessive", "Possessivo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puppeteer", "Burattinaio", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raider", "Predone", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skin Crawler", "Strisciapelle", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slasher", "Squartatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spirit Bearer", "Portatore di anime", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The power of this card is equal to the number of Green Gems that the owner has on their side of the table.", "La potenza di questa carta equivale al numero di gemme verdi che il proprietario ha sul proprio lato del tavolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "APPENDIX XII, SUBSECTION I - ABILITIES {0}", "APPENDICE XII, SEZIONE I - ABILITÀ {0}", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "APPENDIX XII, SUBSECTION II - VARIABLE STATS {0}", "APPENDICE XII, SEZIONE II - STATISTICHE VARIABILI {0}", Language.Italian);

            // Card
            RegisterCard("Skeleton", "Scheletro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The puppet becomes the puppeteer, yet still forever cursed by their dangling restraints.", "Il burattino diventa burattinaio, ma resta per sempre maledetto dai fili che penzolano.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animator", "Burattinaio", Language.Italian);
            RegisterCard("Animator", "Burattinaio");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A formless Creature, that yet lingers. Truly a horrific sight.", "Una creatura senza forma che ancora indugia. Una vista davvero orribile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apparition", "Apparizione", Language.Italian);
            RegisterCard("Apparition", "Apparizione");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only a fool would need such assistance.", "Solo uno sciocco avrebbe bisogno di un simile aiuto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Graven Ashes", "Ceneri incise", Language.Italian);
            RegisterCard("Graven Ashes", "Ceneri incise");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's foul breath doesn't concern me, it's the Tampered Coffins it leaves behind!", "Il suo alito fetido non mi preoccupa, sono le Bare manomesse che lascia dietro di sé!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bal-Bal", "Bal-Bal", Language.Italian);
            RegisterCard("Bal-Bal", "Bal-Bal");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE SCREAMING TERROR. THEY GO STRAIGHT THROUGH TO ATTACK THEIR PREY.", "IL TERRORE URLANTE. ATTRAVERSANO OGNI OSTACOLO PER ATTACCARE LA PREDA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Banshee", "Banshee", Language.Italian);
            RegisterCard("Banshee", "Banshee");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bartender", "Il barista", Language.Italian);
            RegisterCard("The Bartender", "Il barista");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "spent his days serving harmful cocktails for those deserving of his poisonous wrath. Doesn't regret it at all.", "Passava le giornate a servire cocktail nocivi a chi meritava la sua ira velenosa. Non se ne pente affatto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Bones", "Ossa giganti", Language.Italian);
            RegisterCard("Big Bones", "Ossa giganti");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burly Bones", "Ossa vigorose", Language.Italian);
            RegisterCard("Burly Bones", "Ossa vigorose");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beefy Bones", "Ossa robuste", Language.Italian);
            RegisterCard("Beefy Bones", "Ossa robuste");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cal C. Um", "Signor Calcio", Language.Italian);
            RegisterCard("Cal C. Um", "Signor Calcio");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sizeable Bones", "Ossa imponenti", Language.Italian);
            RegisterCard("Sizeable Bones", "Ossa imponenti");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Considerable Bones", "Ossa considerevoli", Language.Italian);
            RegisterCard("Considerable Bones", "Ossa considerevoli");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vigorous Bones", "Ossa energiche", Language.Italian);
            RegisterCard("Vigorous Bones", "Ossa energiche");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hefty Bones", "Ossa pesanti", Language.Italian);
            RegisterCard("Hefty Bones", "Ossa pesanti");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A RATHER BURLY SKELETON, IT IS VERY RICH IN CALCIUM.", "UNO SCHELETRO PIUTTOSTO ROBUSTO, RICCHISSIMO DI CALCIO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This sack is full of body parts. Maybe you'll find something useful in there.", "Questo sacco è pieno di parti del corpo. Forse ci troverai qualcosa di utile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloody Sack", "Sacco insanguinato", Language.Italian);
            RegisterCard("Bloody Sack", "Sacco insanguinato");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Collective", "Collettivo osseo", Language.Italian);
            RegisterCard("Bone Collective", "Collettivo osseo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THOUSANDS OF TINY BONES COALESCE INTO A HUMANOID FORM ONLY TO DISPERSE IN A CLATTERING SWARM THE NEXT MOMENT.", "MIGLIAIA DI OSSICINI SI UNISCONO IN UNA FORMA UMANOIDE, PER POI DISPERDERSI UN ISTANTE DOPO IN UNO SCIAME SFERRAGLIANTE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "USED TO BE A VERY LOYAL DOG BACK IN THE DAY. WELL, ONE DAY HIS OWNER DIED.", "UN TEMPO ERA UN CANE MOLTO FEDELE. POI, UN GIORNO, IL SUO PADRONE MORÌ.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonehound", "Segugio d'ossa", Language.Italian);
            RegisterCard("Bonehound", "Segugio d'ossa");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SO YOU HAVE MADE IT HERE, YOU CANNOT END WHAT I HAVE STARTED, IT HAS GONE TOO FAR.", "DUNQUE SEI ARRIVATO FIN QUI. NON PUOI FERMARE CIÒ CHE HO INIZIATO, È ANDATO TROPPO OLTRE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord", "Il Signore delle ossa", Language.Italian);
            RegisterCard("The Bonelord", "Il Signore delle ossa");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BONELORD SHEDS ITS OLD HORNS, THEY TAKE ON A LIFE OF THEIR OWN, TO ONE DAY USURP THEIR MASTER.", "IL SIGNORE DELLE OSSA PERDE LE VECCHIE CORNA. ESSE PRENDONO VITA, PER USURPARE UN GIORNO IL LORO PADRONE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonelord's Horn", "Corno del Signore delle ossa", Language.Italian);
            RegisterCard("Bonelord's Horn", "Corno del Signore delle ossa");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOT PARTICULARLY INSPIRING. YOU CAN HAVE IT.", "NON È MOLTO ISPIRANTE. PUOI TENERLO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Heap", "Cumulo di ossa", Language.Italian);
            RegisterCard("Bone Heap", "Cumulo di ossa");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IF I AM TRAPPED, SO WILL YOU. YOU CANNOT END THIS.", "SE IO SONO IN TRAPPOLA, LO SARAI ANCHE TU. NON PUOI PORRE FINE A TUTTO QUESTO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Prince", "Principe delle ossa", Language.Italian);
            RegisterCard("Bone Prince", "Principe delle ossa");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHE FEEDS ON PEOPLES BREATH, MAYBE ONE IS STANDING RIGHT BEHIND YOU RIGHT NOW.", "SI NUTRE DEL RESPIRO DELLE PERSONE. FORSE UNA DI LORO È PROPRIO DIETRO DI TE IN QUESTO MOMENTO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boo Hag", "Boo Hag", Language.Italian);
            RegisterCard("Boo Hag", "Boo Hag");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHE COMMANDS OTHERS WITH STRENGTH AND GLAMOUR. THEY WILL FOLLOW HER EVERYWHERE.", "COMANDA GLI ALTRI CON LA FORZA E IL FASCINO. LA SEGUIRANNO OVUNQUE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calavera Catrina", "La Catrina", Language.Italian);
            RegisterCard("Calavera Catrina", "La Catrina");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A GROUP OF SKELETONS IS CALLED A CATACOMB. THIS IS A RATHER LARGE GATHERING.", "UN GRUPPO DI SCHELETRI SI CHIAMA CATACOMBA. QUESTO È UN RADUNO PIUTTOSTO NUMEROSO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catacomb", "Catacomba", Language.Italian);
            RegisterCard("Catacomb", "Catacomba");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Centurion", "Centurione", Language.Italian);
            RegisterCard("Centurion", "Centurione");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A heavily armoured warrior. Last of his century, leader to none.", "Un guerriero con un'armatura pesante. L'ultimo della sua centuria, un comandante senza soldati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compound Fracture", "Frattura composta", Language.Italian);
            RegisterCard("Compound Fracture", "Frattura composta");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CRUSHED BY THE ROOF OF HIS OWN HOUSE. LIVING ON AS A PILE OF GOO.", "SCHIACCIATO DAL TETTO DI CASA SUA. CONTINUA A VIVERE COME UN AMMASSO DI MELMA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A SPIRIT THAT TAKES THE FORM OF AN EGG. ITS PRESENCE HARMS THOSE THAT GAZE UPON IT.", "UNO SPIRITO CHE ASSUME LA FORMA DI UN UOVO. LA SUA PRESENZA NUOCE A CHI LO GUARDA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dalgyal", "Uovo demoniaco", Language.Italian);
            RegisterCard("Dalgyal", "Uovo demoniaco");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FOREVER BOUND TOGETHER BY A TERRIBLE CURSE, THIS GROUP DANCES ONWARD INTO DOOM.", "UNITO PER SEMPRE DA UNA TERRIBILE MALEDIZIONE, QUESTO GRUPPO DANZA VERSO LA ROVINA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Danse Macabre", "Danzatore macabro", Language.Italian);
            RegisterCard("Danse Macabre", "Danzatore macabro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deadeye", "Occhio morto", Language.Italian);
            RegisterCard("Deadeye", "Occhio morto");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SOME SAY THIS EYE ONCE BELONGED TO AN ANCIENT GOD. IT GAZES UPON YOUR ARMY, PICKING ITS FAVORITE TO AID IT ON THE BATTLEFIELD.", "SI DICE CHE QUEST'OCCHIO APPARTENESSE A UN DIO ANTICO. OSSERVA IL TUO ESERCITO E SCEGLIE IL SUO PREFERITO PER AIUTARLO SUL CAMPO DI BATTAGLIA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SOME SAY THIS HAND ONCE BELONGED TO AN ANCIENT GOD. ANYTHING IT TOUCHES ROTS. AS WITH ANYTHING THAT ENDS, IT IS ALSO A NEW BEGINNING.", "SI DICE CHE QUESTA MANO APPARTENESSE A UN DIO ANTICO. TUTTO CIÒ CHE TOCCA MARCISCE. COME OGNI FINE, È ANCHE UN NUOVO INIZIO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Hand", "Mano morta", Language.Italian);
            RegisterCard("Dead Hand", "Mano morta");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A DOOMED FATE SHOULD DISCOURAGE ONE FROM GOING ON, AT LEAST THATS WHAT A STILL LIVING MAN WOULD TELL YOU.", "UN DESTINO SEGNATO DOVREBBE SCORAGGIARE DAL PROSEGUIRE. ALMENO, È CIÒ CHE TI DIREBBE UN UOMO ANCORA VIVO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Man Walking", "Morto che cammina", Language.Italian);
            RegisterCard("Dead Man Walking", "Morto che cammina");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FAMED AMONG THE FOLLOWERS OF THE PHARAOH. THEY WERE BLESSED WITH ETERNAL LIFE LONG AGO.", "CELEBRI TRA I SEGUACI DEL FARAONE. FURONO BENEDETTI CON LA VITA ETERNA MOLTO TEMPO FA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pharaoh's Pets", "Fiere del Faraone", Language.Italian);
            RegisterCard("Pharaoh's Pets", "Fiere del Faraone");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FOR WHOM THE BELL TOLLS? FOR WHOM THE TAP DRIPS DRY AND THE BATHWATER RUNS COLD.", "PER CHI SUONA LA CAMPANA? PER COLUI IL CUI RUBINETTO SI PROSCIUGA E LA CUI ACQUA DEL BAGNO SI RAFFREDDA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Knell", "Rintocco funebre", Language.Italian);
            RegisterCard("Death Knell", "Rintocco funebre");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chime", "Campana", Language.Italian);
            RegisterCard("Chime", "Campana");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This lonesome doll was returned from seas of slate and silent shores... it stares lifelessly.", "Questa bambola solitaria è tornata da mari d'ardesia e lidi silenziosi... Fissa il vuoto senza vita.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doll", "Bambola", Language.Italian);
            RegisterCard("Doll", "Bambola");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HIDING IN A SUIT OF ARMOR, OR ICE, WHAT DOES IT MATTER. THIS SKELETON WON'T LAST FOREVER.", "NASCOSTO IN UN'ARMATURA O NEL GHIACCIO, CHE DIFFERENZA FA? QUESTO SCHELETRO NON DURERÀ PER SEMPRE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draugr", "Draugr", Language.Italian);
            RegisterCard("Draugr", "Draugr");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT A SAD SIGHT, NO ONE SHALL KNOW WHAT LIES AT THE BOTTOM OF THAT WELL.", "CHE TRISTE VISTA. NESSUNO SAPRÀ COSA GIACE IN FONDO A QUEL POZZO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drowned Soul", "Anima affogata", Language.Italian);
            RegisterCard("Drowned Soul", "Anima affogata");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NO ONE KNOWS WHAT EXACTLY THE DYBBUK IS, SOME SAY IT IS BETTER LEFT UNKNOWN.", "NESSUNO SA ESATTAMENTE COSA SIA IL DYBBUK. ALCUNI DICONO CHE SIA MEGLIO NON SAPERLO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dybbuk", "Dybbuk", Language.Italian);
            RegisterCard("Dybbuk", "Dybbuk");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ectoplasm", "Ectoplasma", Language.Italian);
            RegisterCard("Ectoplasm", "Ectoplasma");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE ESSENCE OF A SPIRIT, HIDDEN IN EVERY CORNER AND EVERY SHADOW. ONCE YOU SEE ONE, YOU WILL FIND THE REST SOON ENOUGH.", "L'ESSENZA DI UNO SPIRITO, NASCOSTA IN OGNI ANGOLO E OGNI OMBRA. QUANDO NE VEDRAI UNA, TROVERAI PRESTO ANCHE LE ALTRE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A LIVING FAILURE, ITS KNOWLEDGE ONLY BROUGHT IT DEATH, OR AT LEAST AN APPROXIMATION OF IT.", "UN FALLIMENTO VIVENTE. LA SUA CONOSCENZA GLI HA PORTATO SOLO LA MORTE, O ALMENO QUALCOSA DI SIMILE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boneclaw", "Artiglio d'osso", Language.Italian);
            RegisterCard("Boneclaw", "Artiglio d'osso");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boneless", "Senz'ossa", Language.Italian);
            RegisterCard("Boneless", "Senz'ossa");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's Skeleton seems to have left this lifeless husk in order to achieve greater things.", "Il suo scheletro sembra aver lasciato questo involucro senza vita per dedicarsi a imprese più grandi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lesser Mummy", "Mummia minore", Language.Italian);
            RegisterCard("Lesser Mummy", "Mummia minore");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A loyal servant to the Pharao, buried with him to serve eternally in death.", "Un fedele servitore del faraone, sepolto con lui per servirlo in eterno nella morte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eidolon", "Eidolon", Language.Italian);
            RegisterCard("Eidolon", "Eidolon");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A GOLEM ENCHANTED LONG AGO, BOUND TO PROTECT THE AGE OF SUN.", "UN GOLEM INCANTATO MOLTO TEMPO FA, VINCOLATO A PROTEGGERE L'ERA DEL SOLE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "QUITE A MISCHIEVOUS SPIRIT, IT SPREADS ITS FLAMES TO CAUSE DISMAY.", "UNO SPIRITO PIUTTOSTO BIRICHINO, CHE DIFFONDE LE SUE FIAMME PER SEMINARE SGOMENTO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ember Spirit", "Spirito della brace", Language.Italian);
            RegisterCard("Ember Spirit", "Spirito della brace");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE FAMILY WISHES TO REST IN PEACE, ONLY TO BE SUMMONED AGAIN AND AGAIN IN AN ETERNAL BATTLE.", "LA FAMIGLIA VORREBBE RIPOSARE IN PACE, MA VIENE EVOCATA DI CONTINUO IN UNA BATTAGLIA ETERNA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Walkers", "Fam. Cadaverini", Language.Italian);
            RegisterCard("The Walkers", "Fam. Cadaverini");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is said their odor is so strong and repugnant, even the undead can feel it!", "Si dice che il loro odore sia tanto forte e ripugnante che persino i non morti riescono a sentirlo!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Festering Wretch", "Relitto purulento", Language.Italian);
            RegisterCard("Festering Wretch", "Relitto purulento");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flames", "Fiamme", Language.Italian);
            RegisterCard("Flames", "Fiamme");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flameskull", "Teschio fiammeggiante", Language.Italian);
            RegisterCard("Flameskull", "Teschio fiammeggiante");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Always flying, always angry, always annoying nearby allies in the process.", "Sempre in volo, sempre arrabbiato e sempre pronto a infastidire gli alleati vicini.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A waterlogged sailor who carries his tragic past beside him. I don't remember the details.", "Un marinaio fradicio che porta con sé il proprio tragico passato. Non ricordo i dettagli.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forgotten Man", "Uomo dimenticato", Language.Italian);
            RegisterCard("Forgotten Man", "Uomo dimenticato");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BEST FRIENDS, BROTHERS, AND FIGHTERS.", "MIGLIORI AMICI, FRATELLI E COMBATTENTI.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frank & Stein", "Frank e Stein", Language.Italian);
            RegisterCard("Frank & Stein", "Frank e Stein");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FrankenStein", "Frankenstein", Language.Italian);
            RegisterCard("FrankenStein", "Frankenstein");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A ghastly guardian spirit. It's presence lingers behind as it sprints through the dark.", "Un terrificante spirito guardiano. La sua presenza permane mentre sfreccia nell'oscurità.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fylgja", "Fylgja", Language.Italian);
            RegisterCard("Fylgja", "Fylgja");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warding Presence", "Presenza protettiva", Language.Italian);
            RegisterCard("Warding Presence", "Presenza protettiva");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT CREATED THESE BONES, WAR, FAMINE OR ANOTHER TRAGEDY? It may be insignificant now, but I fear what it might become...", "DA DOVE VENGONO QUESTE OSSA? DA UNA GUERRA, UNA CARESTIA O UN'ALTRA TRAGEDIA? Ora forse non è nulla di importante, ma temo ciò che potrebbe diventare...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mass Grave", "Fossa comune", Language.Italian);
            RegisterCard("Mass Grave", "Fossa comune");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rising Hunger", "Fame divorante", Language.Italian);
            RegisterCard("Rising Hunger", "Fame divorante");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gashadokuro", "Gashadokuro", Language.Italian);
            RegisterCard("Gashadokuro", "Gashadokuro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE PIRATES CALL THIS SHIP THEIR HOME, EVEN IN DEATH. A SLAIN GIANTS SKULL SERVES AS THEIR FIGUREHEAD.", "I PIRATI CHIAMANO QUESTA NAVE CASA, ANCHE NELLA MORTE. IL TESCHIO DI UN GIGANTE UCCISO FUNGE DA POLENA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Ship", "Nave fantasma", Language.Italian);
            RegisterCard("Ghost Ship", "Nave fantasma");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant", "Gigante", Language.Italian);
            RegisterCard("Giant", "Gigante");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE FAMED RACE OF GIANTS IS SAID TO HAVE DIED OUT LONG AGO, THIS IS PROOF. TRULY A SIGHT TO BEHOLD.", "SI DICE CHE LA CELEBRE RAZZA DEI GIGANTI SI SIA ESTINTA MOLTO TEMPO FA. QUESTA NE È LA PROVA. UNO SPETTACOLO DAVVERO IMPRESSIONANTE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOUND TO EARTH, THEY CLING ON SO THEY MAY ONE DAY GET PROPER BURIAL.", "VINCOLATI ALLA TERRA, RESISTONO NELLA SPERANZA DI RICEVERE UN GIORNO UNA DEGNA SEPOLTURA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grateful Dead", "Morto riconoscente", Language.Italian);
            RegisterCard("Grateful Dead", "Morto riconoscente");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE LOWLY GRAVEBARD, MUSIC ALWAYS BROUGHT HIM COMFORT IN THE WORST OF TIMES. NOW, EVEN AT THE END OF THE WORLD HE SHARES HIS SONG.", "L'UMILE BARDO DELLE TOMBE. LA MUSICA GLI HA SEMPRE DATO CONFORTO NEI MOMENTI PEGGIORI. ORA, PERSINO ALLA FINE DEL MONDO, CONDIVIDE IL SUO CANTO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravebard", "Bardo delle tombe", Language.Italian);
            RegisterCard("Gravebard", "Bardo delle tombe");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE HAS SPENT HIS LIFE CARVING THESE CREATURES, THIS CARD CONTAINS A PART OF HIS SOUL.", "HA PASSATO LA VITA A SCOLPIRE QUESTE CREATURE. QUESTA CARTA CONTIENE UNA PARTE DELLA SUA ANIMA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grave Carver", "Incisore di tombe", Language.Italian);
            RegisterCard("Grave Carver", "Incisore di tombe");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE SPENDS HIS TIME ALONE DIGGING FOR BONES IN HOPES OF FINDING A TREASURE. JUST LIKE HIS GRANDMA BEFORE HIM.", "PASSA IL TEMPO A SCAVARE OSSA DA SOLO, NELLA SPERANZA DI TROVARE UN TESORO. PROPRIO COME SUA NONNA PRIMA DI LUI.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravedigger", "Becchino", Language.Italian);
            RegisterCard("Gravedigger", "Becchino");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A POOR, BRUTALIZED SOUL. THEIR MYCELIA PROBES FAR INTO THE SOIL, GUIDING THEIR SPADE.", "UNA POVERA ANIMA TORMENTATA. IL SUO MICELIO SONDA IL TERRENO IN PROFONDITÀ, GUIDANDONE LA VANGA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sporedigger", "Scavaspore", Language.Italian);
            RegisterCard("Sporedigger", "Scavaspore");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A devoted guardian spirit. Even when dispelled, it grants a protective blessing.", "Uno spirito guardiano devoto. Anche quando viene dissolto, concede una benedizione protettiva.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haltia", "Haltia", Language.Italian);
            RegisterCard("Haltia", "Haltia");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I advise against staring into it, you won't like what stares back.", "Ti sconsiglio di fissarlo. Non ti piacerà ciò che ricambierà il tuo sguardo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunted Mirror", "Specchio infestato", Language.Italian);
            RegisterCard("Haunted Mirror", "Specchio infestato");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY CALL HER THE RIDER OF THE APOCALYPSE. HER FLAMING BLADE CUTS THROUGH THE LIVING AND DEAD ALIKE.", "LA CHIAMANO LA CAVALIERA DELL'APOCALISSE. LA SUA LAMA FIAMMEGGIANTE FENDE VIVI E MORTI ALLO STESSO MODO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Headless Horseman", "Fantino decapitato", Language.Italian);
            RegisterCard("Headless Horseman", "Fantino decapitato");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I WOULDN'T GET TOO CLOSE DEAR. YOU CAN'T BREAK THE HOLD FROM THE DEEPEST PITS OF HELL, ONCE IT LATCHES ON.", "NON MI AVVICINEREI TROPPO, TESORO. UNA VOLTA NELLA SUA MORSA, NON PUOI SFUGGIRE ALLA PRESA CHE VIENE DAGLI ABISSI PIÙ PROFONDI DELL'INFERNO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hellhand", "Mano infernale", Language.Italian);
            RegisterCard("Hellhand", "Mano infernale");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hell Hound", "Segugio infernale", Language.Italian);
            RegisterCard("Hell Hound", "Segugio infernale");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A RABID DOG. IT KILLED ONE OF MY GHOULS.", "UN CANE RABBIOSO. HA UCCISO UNO DEI MIEI GHOUL.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LEGENDS HAVE BEEN TOLD ABOUT THE LEGENDARY HYDRA, THE BEAST THAT SWALLOWS ALL AND THE BANE OF ALL THAT SAIL THE SEAS.", "SI NARRANO LEGGENDE SULLA LEGGENDARIA IDRA, LA BESTIA CHE INGHIOTTE OGNI COSA E IL FLAGELLO DI CHIUNQUE SOLCHI I MARI.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hydra", "Idra", Language.Italian);
            RegisterCard("Hydra", "Idra");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overtaken by it's gluttony in life, doomed to it's gluttony in death. Oddly inspires a greed for bones.", "Sopraffatto dalla gola in vita, condannato alla gola nella morte. Stranamente ispira avidità di ossa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jikininki", "Jikininki", Language.Italian);
            RegisterCard("Jikininki", "Jikininki");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avalanche", "Valanga", Language.Italian);
            RegisterCard("Avalanche", "Valanga");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glacier", "Ghiacciaio", Language.Italian);
            RegisterCard("Glacier", "Ghiacciaio");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I WONDER WHAT HAS BEEN FROZEN AWAY FOR SO LONG.", "MI CHIEDO COSA SIA RIMASTO CONGELATO COSÌ A LUNGO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Giant", "Gigante del gelo", Language.Italian);
            RegisterCard("Frost Giant", "Gigante del gelo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Cube", "Cubetto di ghiaccio", Language.Italian);
            RegisterCard("Ice Cube", "Cubetto di ghiaccio");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A CORPSE WHO DIED WITH HIS HEAD IN A GLACIAL STREAM. AFTER HIS REANIMATION, HE COULDN'T BEAR TO PART WITH THE ICE THAT HAD FORMED.", "UN CADAVERE MORTO CON LA TESTA IN UN TORRENTE GLACIALE. DOPO ESSERE STATO RIANIMATO, NON SOPPORTAVA DI SEPARARSI DAL GHIACCIO CHE SI ERA FORMATO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After drowning her children and then herself, she continues to drown others.", "Dopo aver annegato i figli e poi se stessa, continua ad annegare gli altri.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "La Llorona", "La Llorona", Language.Italian);
            RegisterCard("La Llorona", "La Llorona");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Manananggal", "Manananggal", Language.Italian);
            RegisterCard("Manananggal", "Manananggal");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NO BRUTALITY SATIATES THE MANANANGGAL. WHEN YOU SEE HER SEVER FROM HER TORSO, YOU TOO WILL BE A VICTIM OF THE HUNT.", "NESSUNA BRUTALITÀ SAZIA LA MANANANGGAL. QUANDO LA VEDRAI SEPARARSI DAL TORSO, ANCHE TU SARAI VITTIMA DELLA CACCIA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moroi, also known as the hairy ghost. It leeches the souls from those struck down near it.", "Il Moroi, noto anche come fantasma peloso. Risucchia le anime di chi viene abbattuto vicino a lui.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moroi", "Moroi", Language.Italian);
            RegisterCard("Moroi", "Moroi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HIS AGE OF GLORY IS LONG GONE, YET IT IS WHAT KEEPS HIM GOING.", "LA SUA EPOCA DI GLORIA È FINITA DA TEMPO, MA È CIÒ CHE LO SPINGE AD ANDARE AVANTI.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mummy Lord", "Re delle mummie", Language.Italian);
            RegisterCard("Mummy Lord", "Re delle mummie");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ALL EFFORTS TO PRESERVE LIFE AFTER DEATH HAVE BEEN FUTILE, YET THE NECROMANCER GOES ON. HE HAS TO.", "OGNI SFORZO PER PRESERVARE LA VITA DOPO LA MORTE È STATO VANO, MA IL NECROMANTE CONTINUA. DEVE FARLO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Necromancer", "Necromante", Language.Italian);
            RegisterCard("Necromancer", "Necromante");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A troublesome lake spirit that enjoys dragging others down to a watery grave.", "Un fastidioso spirito lacustre che ama trascinare gli altri in una tomba d'acqua.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nixie", "Ninfa d'acqua", Language.Italian);
            RegisterCard("Nixie", "Ninfa d'acqua");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The shambling corpse of a pale, sickly noble. it spreads it's filth as it sheds it's flesh.", "Il cadavere barcollante di un nobile pallido e malaticcio. Sparge il proprio sudiciume mentre perde brandelli di carne.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nosferat", "Nosferat", Language.Italian);
            RegisterCard("Nosferat", "Nosferat");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ancient Obol", "Obolo antico", Language.Italian);
            RegisterCard("Ancient Obol", "Obolo antico");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT WILL ALL MAKE SENSE SOON. THE OBOL IS OLDER THAN TIME ITSELF, AND THUS IT WILL REVEAL ITSELF IN DUE TIME.", "PRESTO OGNI COSA AVRÀ SENSO. L'OBOLO È PIÙ ANTICO DEL TEMPO STESSO E SI RIVELERÀ QUANDO SARÀ IL MOMENTO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Armed Bandit", "Bandito con un braccio", Language.Italian);
            RegisterCard("One Armed Bandit", "Bandito con un braccio");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Took the ten paces, that ordeal cost him an arm, and his life.", "Ha fatto i dieci passi. Quella prova gli è costata un braccio e la vita.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT IS SAID ALL IS WELL THAT ENDS. IT IS SAID TIME IS LIKE AN OUROBOROS, IT DOES NOT END, IT ONLY REPEATS ITSELF.", "SI DICE CHE TUTTO È BENE QUEL CHE FINISCE. SI DICE CHE IL TEMPO SIA COME UN UROBORO: NON FINISCE, SI RIPETE SOLTANTO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ourobones", "Ourossa", Language.Italian);
            RegisterCard("Ourobones", "Ourossa");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plague Doctor", "Medico della peste", Language.Italian);
            RegisterCard("Plague Doctor", "Medico della peste");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE HAS DETERMINED THE UNDEAD ARE SICK WITH A TERRIBLE ILLNESS. THE ONLY CURE IS DEATH.", "HA STABILITO CHE I NON MORTI SOFFRONO DI UNA TERRIBILE MALATTIA. L'UNICA CURA È LA MORTE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AN EVIL TRICKSTER, THE POLTERGEIST HAS ENJOYED THEIR DEATH VERY MUCH.", "UN MALVAGIO BURLONE. IL POLTERGEIST SI È GODUTO MOLTISSIMO LA PROPRIA MORTE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poltergeist", "Poltergeist", Language.Italian);
            RegisterCard("Poltergeist", "Poltergeist");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A suit of ancient armour in which an occult spirit has taken up residence. Her iron fist drags more creatures to the fight.", "Un'antica armatura in cui ha preso dimora uno spirito occulto. Il suo pugno di ferro trascina altre creature in battaglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Possessed Armour", "Armatura posseduta", Language.Italian);
            RegisterCard("Possessed Armour", "Armatura posseduta");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AN EXPERIMENT GONE WRONG, IN A FUTILE ATTEMPT TO CREATE A DANSE MACCABRE. THEY DO NOT FUNCTION TOGETHER.", "UN ESPERIMENTO FALLITO NEL VANO TENTATIVO DI CREARE UN DANZATORE MACABRO. NON FUNZIONANO INSIEME.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Project", "Soggetto sperimentale", Language.Italian);
            RegisterCard("Project", "Soggetto sperimentale");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You shouldnt be seeing this right now", "Non dovresti vedere questo adesso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Random Cards", "Carte casuali", Language.Italian);
            RegisterCard("Random Cards", "Carte casuali");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BRINGING THE SCYTHE OF DEATH, THE REVENANT SEEKS ONLY REVENGE.", "PORTANDO LA FALCE DELLA MORTE, IL FANTASMA CERCA SOLO VENDETTA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revenant", "Fantasma", Language.Italian);
            RegisterCard("Revenant", "Fantasma");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ripper", "Squartatore", Language.Italian);
            RegisterCard("Ripper", "Squartatore");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE RIPPER SOLVES EVERYTHING THROUGH SHEER STRENGTH. IT WILL PUNCH ANY ISSUE STRAIGHT IN THE FACE AND SOLVE IT, TOO.", "LO SQUARTATORE RISOLVE TUTTO CON LA FORZA BRUTA. PRENDE A PUGNI IN FACCIA OGNI PROBLEMA, E LO RISOLVE PURE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a wonder this one has stayed together! Though it may lose that arm if it tries to flee.", "È un miracolo che sia ancora tutto intero! Ma potrebbe perdere quel braccio se cercasse di fuggire.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rotten", "Cadavere marcio", Language.Italian);
            RegisterCard("Rotten", "Cadavere marcio");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Twitching Arm", "Braccio tremante", Language.Italian);
            RegisterCard("Twitching Arm", "Braccio tremante");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The elusive Locker.", "L'inafferrabile Armadietto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Davy Jones Locker", "Armadietto di Davy Jones", Language.Italian);
            RegisterCard("Davy Jones Locker", "Armadietto di Davy Jones");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yellowbeard", "Barbagialla", Language.Italian);
            RegisterCard("Yellowbeard", "Barbagialla");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bluebeard", "Barbablù", Language.Italian);
            RegisterCard("Bluebeard", "Barbablù");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His songs raise the morale of only Skeletons, as no one else seems to like it.", "Le sue canzoni sollevano il morale solo agli Scheletri: a quanto pare, non piacciono a nessun altro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A DISTANT RELATIVE OF THE SCREAMING SKULL, HE IS NOW THE SYMBOL OF PIRACY ALL AROUND THE WORLD", "UN LONTANO PARENTE DEL TESCHIO URLANTE. ORA È IL SIMBOLO DELLA PIRATERIA IN TUTTO IL MONDO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crossbones", "Ossa incrociate", Language.Italian);
            RegisterCard("Crossbones", "Ossa incrociate");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Davy Jones", "Davy Jones", Language.Italian);
            RegisterCard("Davy Jones", "Davy Jones");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The true captain of the crew, respected by all yet still elusive. YELLOWBEARD ALWAYS GETS MORE BOOTY THAN HE DOES.", "Il vero capitano della ciurma, rispettato da tutti ma sempre sfuggente. BARBAGIALLA OTTIENE SEMPRE PIÙ BOTTINO DI LUI.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MAYBE IT WASN'T THE BEST IDEA TO HOLD A BARREL FULL OF GUNPOWDER. I'M NOT SURE WETHER HE NOTICED.", "FORSE NON ERA UNA GRANDE IDEA TENERE IN MANO UN BARILE PIENO DI POLVERE DA SPARO. NON SO SE SE NE SIA ACCORTO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exploding Pirate", "Pirata esplosivo", Language.Italian);
            RegisterCard("Exploding Pirate", "Pirata esplosivo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He betrayed his captain for that large hook, now he is sure to make anyone a double-crosser!", "Ha tradito il suo capitano per quel grosso gancio. Ora può rendere chiunque un traditore!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "First Mate Snag", "Primo ufficiale Snag", Language.Italian);
            RegisterCard("First Mate Snag", "Primo ufficiale Snag");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parrots usually make great sea-side companions, this one just ate a poisoned cracker.", "I pappagalli sono di solito ottimi compagni in riva al mare. Questo ha appena mangiato un cracker avvelenato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Polly", "Polly", Language.Italian);
            RegisterCard("Polly", "Polly");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A keen eye socket allows him to attack anywhere, his musket helps too. marvelous indeed!", "Un'orbita acuta gli permette di attaccare ovunque, e anche il moschetto aiuta. Davvero meraviglioso!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Privateer", "Capitano corsaro", Language.Italian);
            RegisterCard("Privateer", "Capitano corsaro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swashbuckler", "Spadaccino", Language.Italian);
            RegisterCard("Swashbuckler", "Spadaccino");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EMERGING FROM AN OLD EGYPTIAN TOMB, MADE TO HOUSE THE LORDS OF OLD.", "EMERSO DA UN'ANTICA TOMBA EGIZIA, FATTO PER OSPITARE I SIGNORI DEL PASSATO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sarcophagus", "Sarcofago", Language.Italian);
            RegisterCard("Sarcophagus", "Sarcofago");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Screaming Skull", "Teschio urlante", Language.Italian);
            RegisterCard("Screaming Skull", "Teschio urlante");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ONLY PAIN AND SUFFERING, NOTHING ELSE IS FELT BY THIS SKELETAL HEAD. WHAT A PITY.", "QUESTA TESTA SCHELETRICA PROVA SOLO DOLORE E SOFFERENZA, NIENT'ALTRO. CHE PECCATO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A SKILLED HUNTER. DON'T TRUST YOUR EARS WHEN YOU HEAR ITS HAUNTING WHISTLE.", "UN ABILE CACCIATORE. NON FIDARTI DELLE TUE ORECCHIE QUANDO SENTI IL SUO FISCHIO INQUIETANTE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Silbon", "Silbon", Language.Italian);
            RegisterCard("Silbon", "Silbon");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY HAVE LEARNED THE ANCIENT SPELL OF DEATH. YET IT IS TOO MUCH POWER TO BE WIELDED.", "HANNO IMPARATO L'ANTICO INCANTESIMO DELLA MORTE. MA IL SUO POTERE È TROPPO GRANDE PER ESSERE DOMINATO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelemagus", "Schelemago", Language.Italian);
            RegisterCard("Skelemagus", "Schelemago");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]RISE MY ARMY, RIIIIIISE[c:]", "[c:bR]SORGI, MIO ESERCITO, SOOOORGI[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleton Army", "Armata di scheletri", Language.Italian);
            RegisterCard("Skeleton Army", "Armata di scheletri");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of the faster draws in the west, but not fast enough.", "Uno dei pistoleri più veloci del West, ma non abbastanza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slinger's Soul", "Anima del pistolero", Language.Italian);
            RegisterCard("Slinger's Soul", "Anima del pistolero");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY SHOW UP OUT OF NOWHERE AND RELOCATE PEOPLE AS THEY PLEASE.", "APPAIONO DAL NULLA E SPOSTANO LE PERSONE A LORO PIACIMENTO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sluagh", "Sluagh", Language.Italian);
            RegisterCard("Sluagh", "Sluagh");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trick or treat!", "Dolcetto o scherzetto!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candy Bucket", "Secchio di caramelle", Language.Italian);
            RegisterCard("Candy Bucket", "Secchio di caramelle");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAPPY HALLOWEEN!", "BUON HALLOWEEN!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candy Monster", "Mostro di caramelle", Language.Italian);
            RegisterCard("Candy Monster", "Mostro di caramelle");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spectrabbit", "Spettroconiglio", Language.Italian);
            RegisterCard("Spectrabbit", "Spettroconiglio");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE SPECTRE EMITS A FLUTE LIKE CALL, AN OMEN OF BOTH DEATH AND DESCTRUCTION", "IL GRANDE SPETTRO EMETTE UN RICHIAMO SIMILE A UN FLAUTO, PRESAGIO DI MORTE E DISTRUZIONE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spectre", "Grande spettro", Language.Italian);
            RegisterCard("Spectre", "Grande spettro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DEATH IS A CRUEL FATE. STARVATION AN EVEN CRUELER ONE. WHY DO YOU FIGHT, OH HUNGRY CHILD.", "LA MORTE È UN DESTINO CRUDELE. MORIRE DI FAME LO È ANCORA DI PIÙ. PERCHÉ COMBATTI, O BAMBINO AFFAMATO?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Starved Man", "Uomo morto di fame", Language.Italian);
            RegisterCard("Starved Man", "Uomo morto di fame");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE HAS SPENT YEARS IN HIS STUDY, IN A TIRELESS ATTEMPT TO CHANGE HIS FATE. YET FATE IS A CRUEL MISTRESS.", "HA TRASCORSO ANNI NEL SUO STUDIO, TENTANDO INSTANCABILMENTE DI CAMBIARE IL PROPRIO DESTINO. MA IL DESTINO È UNA PADRONA CRUDELE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summoner", "Evocatore", Language.Italian);
            RegisterCard("Summoner", "Evocatore");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tampered Coffin", "Bara manomessa", Language.Italian);
            RegisterCard("Tampered Coffin", "Bara manomessa");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Tree", "Albero morto", Language.Italian);
            RegisterCard("Dead Tree", "Albero morto");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its low cost is justified only by its low stats.", "Il suo basso costo è giustificato solo dalle sue scarse statistiche.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disturbed Grave", "Tomba profanata", Language.Italian);
            RegisterCard("Disturbed Grave", "Tomba profanata");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A LOWLY GRAVE. WHOEVER IS LAID TO REST HERE, I DO NOT KNOW.", "UN'UMILE TOMBA. NON SO CHI RIPOSI QUI.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kennel", "Canile", Language.Italian);
            RegisterCard("Kennel", "Canile");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obelisk", "Obelisco", Language.Italian);
            RegisterCard("Obelisk", "Obelisco");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shipwreck", "Relitto", Language.Italian);
            RegisterCard("Shipwreck", "Relitto");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flotsam", "Legno alla deriva", Language.Italian);
            RegisterCard("Flotsam", "Legno alla deriva");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Water Urn", "Urna d'acqua", Language.Italian);
            RegisterCard("Water Urn", "Urna d'acqua");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Voodoo Doll", "Bambola voodoo", Language.Italian);
            RegisterCard("Voodoo Doll", "Bambola voodoo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOTHING... NOTHING AGAIN... NO TREASURE IS LEFT ANYMORE.", "NIENTE... ANCORA NIENTE... NON RESTA PIÙ ALCUN TESORO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tomb Robber", "Ladra di tombe", Language.Italian);
            RegisterCard("Tomb Robber", "Ladra di tombe");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ephialtes", "Efialte", Language.Italian);
            RegisterCard("Ephialtes", "Efialte");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Otis", "Otis", Language.Italian);
            RegisterCard("Otis", "Otis");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undertaker", "Becchino", Language.Italian);
            RegisterCard("Undertaker", "Becchino");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His service no longer needed, this lost soul buries without purpose..", "I suoi servizi non servono più. Quest'anima smarrita seppellisce senza uno scopo...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Walking Coffin", "Bara camminante", Language.Italian);
            RegisterCard("Walking Coffin", "Bara camminante");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Running Coffin", "Bara ambulante", Language.Italian);
            RegisterCard("Running Coffin", "Bara ambulante");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Placeholder", "Segnaposto", Language.Italian);
            RegisterCard("Placeholder", "Segnaposto");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE VAMPIRE IS A CREATURE OF LEGENDS. IN REALITY, LITTLE BLOOD TO DRINK AFTER EVERYONE HAS DIED.", "IL VAMPIRO È UNA CREATURA LEGGENDARIA. IN REALTÀ, RESTA POCO SANGUE DA BERE QUANDO SONO TUTTI MORTI.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vampire", "Conte vampiro", Language.Italian);
            RegisterCard("Vampire", "Conte vampiro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vellum", "Pergamena", Language.Italian);
            RegisterCard("Vellum", "Pergamena");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TO NEVER BE SATISFIED, TO ALWAYS WANT MORE. THIS SPIRIT SHALL NEVER FIND ITS PEACE.", "NON ESSERE MAI SAZIO, VOLERE SEMPRE DI PIÙ. QUESTO SPIRITO NON TROVERÀ MAI PACE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vengeful Spirit", "Spirito vendicativo", Language.Italian);
            RegisterCard("Vengeful Spirit", "Spirito vendicativo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THIS GELID SPECTER ENVELOPS WOULD-BE ATTACKERS IN AN ICY MIST.", "QUESTO SPETTRO GELIDO AVVOLGE GLI ASPIRANTI AGGRESSORI IN UNA NEBBIA GHIACCIATA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warthr", "Spettro del gelo", Language.Italian);
            RegisterCard("Warthr", "Spettro del gelo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corrupted by the spirit of a rabid wolf. It's fury cannot be stopped.", "Corrotto dallo spirito di un lupo rabbioso. La sua furia non può essere fermata.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wechuge", "Wechuge", Language.Italian);
            RegisterCard("Wechuge", "Wechuge");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hideous beings that will jump out to consume freshly killed corpses. They only spare the bones of the victim.", "Esseri orrendi che balzano fuori per divorare i cadaveri appena uccisi. Risparmiano solo le ossa della vittima.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wight", "Spettro delle tombe", Language.Italian);
            RegisterCard("Wight", "Spettro delle tombe");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY WARM WITH THEIR BODIES OF LIGHT, DRAWING HOPELESS SOULS INTO THEIR BEACON, DISPELLING THEIR FRIGHT.", "SCALDANO CON I LORO CORPI DI LUCE, ATTIRANO LE ANIME SENZA SPERANZA VERSO IL LORO BAGLIORE E NE DISSIPANO LA PAURA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Will 'O' The Wisp", "Fuoco fatuo", Language.Italian);
            RegisterCard("Will 'O' The Wisp", "Fuoco fatuo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A FALLEN GIANTS SPINE THAT IS TRYING TO FIND A NEW HOST. REGRETTABLY, MOST CREATURES ARE QUITE SMALL.", "LA SPINA DORSALE DI UN GIGANTE CADUTO CERCA UN NUOVO OSPITE. PURTROPPO, LA MAGGIOR PARTE DELLE CREATURE È PIUTTOSTO PICCOLA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Writher", "Contorsionista", Language.Italian);
            RegisterCard("Writher", "Contorsionista");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiny Vertebrae", "Vertebre spinose", Language.Italian);
            RegisterCard("Spiny Vertebrae", "Vertebre spinose");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE SIMPLEST OF UNDEAD, CHARACTERIZED BY ITS ROTTEN SMELL. IT ALWAYS TRAVELS WITH OTHERS, SEEKING PROTECTION AND GUIDANCE.", "IL PIÙ SEMPLICE DEI NON MORTI, RICONOSCIBILE DALL'ODORE DI MARCIO. VIAGGIA SEMPRE CON ALTRI, IN CERCA DI PROTEZIONE E GUIDA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zombie", "Zombie", Language.Italian);
            RegisterCard("Zombie", "Zombie");

            // Achievement
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grimora Mod Achievements", "Obiettivi del Mod Grimora", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grim Reminder", "Funesto presagio", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat Kaycee and thaw at least 5 of your cards.", "Sconfiggi Kaycee e scongela almeno 5 delle tue carte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowards End", "La fine dei codardi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat Sawyers second phase without hurting the hellhound.", "Sconfiggi la seconda fase di Sawyer senza ferire il Segugio infernale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Season Of Storms", "La stagione delle tempeste", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat Royal and have no cards walk the plank.", "Sconfiggi Royal senza che nessuna carta venga costretta a camminare sull'asse.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Black Bird//", "L'Uccello nero//", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Dark Slope. Defeat [redacted] without defeating [redacted].", "Il pendio oscuro. Sconfiggi [omissis] senza sconfiggere [omissis].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonesaw", "Sega per ossa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "End a turn with at least 30 bones.", "Termina un turno con almeno 30 ossa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pile Of Skulls", "Mucchio di teschi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Win with all challenges enabled and no antichallenges enabled.", "Vinci con tutte le sfide attive e nessuna antisfida attiva.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dance of Doom", "Danza della rovina", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Witness the end of everything.", "Assisti alla fine di ogni cosa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Spirits Way", "La via delle anime", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reach 6 Souls by turn 3.", "Raggiungi 6 anime entro il turno 3.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wail Of The Damned", "Lamento dei dannati", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use the dead hand item when your deck is empty.", "Usa l'oggetto Mano morta quando il tuo mazzo è vuoto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something Ends...", "Qualcosa finisce...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...Something Begins. Get an ourobones to deal 6 damage.", "... Qualcosa inizia. Fai infliggere 6 danni a una carta Ourossa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cull the weak", "Elimina i deboli", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifice an Obol with 5 sigils to the Bonelord.", "Sacrifica al Signore delle ossa un Obolo con 5 sigilli.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gateway to Dis", "Porta degli inferi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Win while Hell mode is active.", "Vinci con la Modalità inferno attiva.", Language.Italian);

            // Consumable
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Horn", "Corno d'osso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bone Horn, drains all of your current Soul but you gain a bone for each soul consumed.", "Il Corno d'osso consuma tutte le tue anime attuali, ma ti conferisce un osso per ogni anima consumata.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gives you a bone for each of your Souls, which are spent in the process, an unfortunate, but worthwhile sacrifice.", "Ti conferisce un osso per ogni tua anima, consumandole nel processo. Un sacrificio spiacevole, ma vantaggioso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Hand", "Mano morta", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Dead Hand, draws you a new Hand of cards at the cost of your old one.", "La Mano morta ti fa pescare una nuova mano di carte al costo di quella vecchia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The severed hand of a forgotten god, left to take on a life of its own. You know what this does.", "La mano recisa di un dio dimenticato, abbandonata a una vita propria. Sai cosa fa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Embalming Fluid", "Liquido imbalsamante", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Embalming Fluid, pour it over a card and it will gain one health and attack.", "Il Liquido imbalsamante: versalo su una carta per aumentarne salute e potenza di un punto ciascuna.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prepare to put a member of your army to rest, increasing its stamina and vigor as you do so!", "Preparati a dare riposo a un membro del tuo esercito, aumentandone al contempo resistenza e vigore!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravecarvers Chisel", "Scalpello dell'incisore di tombe", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Gravecarvers chisel, select any card that has died previously to add to your hand.", "Lo Scalpello dell'incisore di tombe: scegli una qualsiasi carta morta in precedenza da aggiungere alla tua mano.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tool left behind by a mysterious creator, did he carve the gravebards statue too?", "Un attrezzo lasciato da un misterioso creatore. Avrà scolpito anche la statua del Bardo delle tombe?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Urn", "Urna delle anime", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Soul Urn, spend all of your Soul and gain maximum Soul capacity for each Soul consumed.", "L'Urna delle anime consuma tutte le tue anime e aumenta la capacità massima della quantità consumata.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Takes all of your Soul but increases your maximum by the amount taken, a certain acquaintance of mine would call this a return on investment.", "Prende tutte le tue anime, ma aumenta il tuo massimo della quantità prelevata. Una mia certa conoscenza lo chiamerebbe ritorno sull'investimento.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mallet", "Mazzuolo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mallet, Whack a Card, it will become brittle and loose 1 Hp.", "Il Mazzuolo: colpisci una carta per conferirle Fragilità e farle perdere 1 di salute.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'd think this is comical, but it is quite cruel. Injures a card and leaves it frail.", "Potrà sembrarti comico, ma è piuttosto crudele. Ferisce una carta e la lascia fragile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quill", "Penna d'oca", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My very own Quill, this lets you copy any card on the field to put in your hand.", "La mia Penna d'oca ti permette di copiare qualsiasi carta sul tavolo e metterla nella tua mano.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My very own tool, i will lend it to you for now. Youve seen this in action, havent you?", "Il mio strumento personale. Te lo presto per ora. L'hai già visto all'opera, vero?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ship Bottle", "Bottiglia della nave", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Ship in a Bottle, fills the entire board with a scurvy Skeleton Crew.", "La Nave in bottiglia riempie l'intero tavolo con una ciurma di Scheletri scorbutici.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fills the entire board with skeletons! Like a real Pirate, Royal would be proud.", "Riempie l'intero tavolo di scheletri! Da vero pirata. Royal ne sarebbe fiero.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Salty Daryl", "Daryl il salato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Browntooth Barrie", "Barrie Dentemarrone", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonnie Splinter", "Splinter l'ossuto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Freebooter Bethel", "Bethel il contrabbandiere", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crazy Oakes Hayward", "Oakes Hayward il folle", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ashton Swabby", "Ashton lo zozzone", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plankton Braxton", "Braxton il plancton", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yeller-eye Colby", "Colby Occhiogiallo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fishwife Nate", "Nate il pescivendolo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Four-finger Fred", "Fred Quattrodita", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dawg Julie", "Julie la cagnaccia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wicked Jones", "Jones il perfido", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crabby Steele", "Steele il burbero", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slivered Hoggy Bank", "Salvadanaio cinghiale incrinato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Slivered Hoggy bank, gain 2 extra bones up to three times.", "Il Salvadanaio cinghiale incrinato ti conferisce 2 ossa extra, fino a tre volte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A relic from an age forsaken, this will grant you some extra bones in a pinch", "Una reliquia di un'epoca dimenticata, che ti darà qualche osso extra nel momento del bisogno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slivered Hoggy Bank2", "Salvadanaio cinghiale incrinato 2", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Slivered Hoggy bank, gain 2 extra bones, two more times.", "Il Salvadanaio cinghiale incrinato ti conferisce 2 ossa extra, ancora due volte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slivered Hoggy Bank3", "Salvadanaio cinghiale incrinato 3", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Slivered Hoggy bank, gain 2 extra bones, one more time.", "Il Salvadanaio cinghiale incrinato ti conferisce 2 ossa extra, ancora una volta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trowel", "Cazzuola", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Trowel, dig up a random terrain and gain a few Bones.", "La Cazzuola dissotterra un terreno casuale e ti conferisce alcune ossa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This used to belong to a gravedigger. Digs for treasure, or Terrain. And get some Bones too for your efforts.", "Apparteneva a un becchino. Scava alla ricerca di tesori o terreni. E per i tuoi sforzi ottieni anche qualche osso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonelords Femur", "Femore del Signore delle ossa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bone Lords Femur, a mystery even to me.", "Il Femore del Signore delle ossa, un mistero persino per me.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have dug too far, i have let myself be used as a tool for too long. Just like i will lend you this tool, i am truly in power.", "Hai scavato troppo a fondo. Mi sono lasciato usare come uno strumento troppo a lungo. Proprio come ti presterò questo attrezzo, sono io a detenere il vero potere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revenant Bottle", "Fantasma in bottiglia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Heap Bottle", "Cumulo di ossa in bottiglia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Revenant is created in your hand. [define:arackulele.inscryption.grimoramod_Revenant]", "Una carta «Fantasma» viene creata nella tua mano. [define:arackulele.inscryption.grimoramod_Revenant]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Bone Heap is created in your hand. [define:arackulele.inscryption.grimoramod_Bonepile]", "Una carta «Cumulo di ossa» viene creata nella tua mano. [define:arackulele.inscryption.grimoramod_Bonepile]", Language.Italian);

            // ShowUntilInput
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A [c:G]SANDSTORM[c:] IS BREWING!", "Si prepara una [c:G]TEMPESTA DI SABBIA[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]At the end of a turn, the rightmost Card will take 1 Damage![c:]", " [c:G]Alla fine di un turno, la carta più a destra subisce 1 danno![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ITS GETTING HOTTER!A [c:G]HEATWAVE[c:] IS STARTING!", "FA SEMPRE PIÙ CALDO! INIZIA UN'[c:G]ONDATA DI CALORE[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]All cards on the board will burn![c:]", " [c:G]Tutte le carte sul tavolo bruceranno![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TREES START SPROUTING AROUND YOU.AN [c:G]OVERGROWTH[c:] IS INBOUND!", "GLI ALBERI GERMOGLIANO ATTORNO A TE. È IN ARRIVO UNA [c:G]CRESCITA INCONTROLLATA[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Trees will sprout every turn![c:]", " [c:G]Gli alberi germoglieranno a ogni turno![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU HEAR WITCHES CHANTING.THE CLOCK STRIKES THE [c:G]WITCHING HOUR[c:]!", "SENTI LE STREGHE CANTILENARE. L'OROLOGIO SCOCCA [c:G]L'ORA DELLE STREGHE[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Cards on enchanted slots will gain more attack and health![c:]", " [c:G]Le carte sugli spazi incantati otterranno più potenza e salute![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A CAULDRON IS BUBBLING IN THE DISTANCE.YOUR CARDS ARE PUT IN THE [c:G]WITCHES CAULDRON[c:]!", "UN CALDERONE BOLLE IN LONTANANZA. LE TUE CARTE VENGONO MESSE NEL [c:G]CALDERONE DELLE STREGHE[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]2 Cards will swap after the end of the turn![c:]", " [c:G]2 carte si scambieranno di posto dopo la fine del turno![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SKELETONS START DANCING IN THE DISTANCE, YOU CAN SEE GHOSTS MOVE AROUND.ITS THE [c:G]NIGHT OF THE LIVING DEAD[c:]!", "GLI SCHELETRI DANZANO IN LONTANANZA E VEDI FANTASMI AGGIRARSI. È LA [c:G]NOTTE DEI MORTI VIVENTI[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Bone and soul cost of all cards are swapped![c:]", " [c:G]I costi in ossa e anime di tutte le carte vengono scambiati![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ZOMBIES ARE APPROACHING FROM ALL SIDES.A [c:G]ZOMBIE INVASION[c:] WILL APPROACH!", "GLI ZOMBIE SI AVVICINANO DA OGNI LATO. È IN ARRIVO UN'[c:G]INVASIONE DI ZOMBIE[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Every card is now a Zombie![c:]", " [c:G]Ora ogni carta è uno Zombie![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE DIRT IS PLAGUED WITH SPIRITS FROM CENTURIES PAST.YOU'VE APPROACHED THE [c:G]HAUNTED GROUNDS[c:]!", "IL TERRENO È INFESTATO DA SPIRITI DI SECOLI PASSATI. SEI GIUNTO SUI [c:G]TERRENI INFESTATI[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Every non Skeletal Card will gain Haunter![c:]", " [c:G]Ogni carta non scheletrica otterrà Infestatore![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE MOON RISES, GLOWING RED.A [c:G]BLOODMOON[c:] IS STARTING!", "LA LUNA SORGE, ROSSA E LUMINOSA. INIZIA UNA [c:G]LUNA DI SANGUE[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]All cards loose a random sigil after being played![c:]", " [c:G]Tutte le carte perdono un sigillo casuale dopo essere state giocate![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An ancient Guard stands in front of you, noticing you are trying to sneak past.", "Un'antica guardia si erge davanti a te e nota che stai cercando di passare di nascosto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You dare enter my [c:R]TOMB[c:]!Prepare for death.", "Osi entrare nella mia [c:R]TOMBA[c:]! Preparati a morire.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An imposing Man holding a sculpture of an Ankh blocks the way.", "Un uomo imponente con una scultura di un ankh blocca il passaggio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My Ankh gives me life, you shall not rob my [c:R]TOMB[c:].", "Il mio ankh mi dà la vita. Non saccheggerai la mia [c:R]TOMBA[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An old Pharaoh climbs out of his Sarcophagus.", "Un vecchio faraone esce dal suo sarcofago.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have been called to protect my [c:R]TOMB[c:].", "Sono stato chiamato a proteggere la mia [c:R]TOMBA[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A holy figure looms over you.", "Una figura sacra incombe su di te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your Fate is sealed, my [c:R]TOMB[c:] shall not be disturbed.", "Il tuo destino è segnato. La mia [c:R]TOMBA[c:] non sarà profanata.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A LONE GRAVE SITS SOLEMNLY IN FRONT OF YOU.", "UNA TOMBA SOLITARIA SI ERGE SOLENNE DAVANTI A TE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IN FRONT OF IT IS A MOUND OF EARTH, LEFT BY SOMEONE WHO'S ALREADY PASSED ON.", "DAVANTI C'È UN CUMULO DI TERRA, LASCIATO DA QUALCUNO CHE È GIÀ TRAPASSATO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PERHAPS A MEMBER OF YOUR UNDEAD HORDE COULD [c:bR]DIG THEM UP?[c:]", "FORSE UN MEMBRO DELLA TUA ORDA DI NON MORTI POTREBBE [c:bR]DISSOTTERRARE IL DEFUNTO?[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THIS WOULDN'T BE WITHOUT REPERCUSSIONS OF COURSE, AS DEATH IS NEVER PERMANENT.", "NATURALMENTE NON SAREBBE SENZA CONSEGUENZE, PERCHÉ LA MORTE NON È MAI DEFINITIVA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF ROTTING FLESH, YOUR CARD WILL BECOME [c:bR]BRITTLE[c:], BUT [c:bR]ITS BONE COST WILL BE HALVED[c:].", "IL CADAVERE SEMBRA FATTO DI CARNE MARCESCENTE. LA TUA CARTA OTTERRÀ [c:bR]FRAGILITÀ[c:], MA [c:bR]IL SUO COSTO IN OSSA SARÀ DIMEZZATO[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF A STARVED MAN, YOUR CARD WILL [c:bR]STARVE FOREVER[c:], BUT [c:bR]ITS BONE COST WILL BE REDUCED BY 2[c:].", "IL CADAVERE SEMBRA ESSERE DI UN UOMO MORTO DI FAME. LA TUA CARTA [c:bR]AVRÀ FAME IN ETERNO[c:], MA [c:bR]IL SUO COSTO IN OSSA DIMINUIRÀ DI 2[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF AN INCORPOREAL GHOST, YOUR CARD WILL [c:bR]COST 2 SOULS[c:] , BUT [c:bR]ITS BONE COST WILL BE REDUCED BY 1[c:].", "IL CADAVERE SEMBRA ESSERE DI UN FANTASMA INCORPOREO. LA TUA CARTA [c:bR]COSTERÀ 2 ANIME[c:], MA [c:bR]IL SUO COSTO IN OSSA DIMINUIRÀ DI 1[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF A CHAINED PRISONER, YOUR CARD WILL [c:bR]DEAL 1 MORE DAMAGE[c:] , BUT [c:bR]IT WILL BECOME VERY FRAIL[c:].", "IL CADAVERE SEMBRA ESSERE DI UN PRIGIONIERO INCATENATO. LA TUA CARTA [c:bR]INFLIGGERÀ 1 DANNO IN PIÙ[c:], MA [c:bR]DIVENTERÀ MOLTO FRAGILE[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF A MISCHIEVIOUS SPIRIT, YOUR CARD WILL [c:bR]HAUNT OTHERS[c:] , BUT [c:bR]WILL COST 3 SOULS[c:].", "IL CADAVERE SEMBRA ESSERE DI UNO SPIRITO BIRICHINO. LA TUA CARTA [c:bR]INFESTERÀ GLI ALTRI[c:], MA [c:bR]COSTERÀ 3 ANIME[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MARVELOUS! THEY CAME CRAWLING BACK AFTER DIGGING UP THE CORPSE.", "MERAVIGLIOSO! È TORNATA STRISCIANDO DOPO AVER DISSOTTERRATO IL CADAVERE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY STILL CARE ABOUT YOU IT SEEMS!", "SEMBRA CHE TENGA ANCORA A TE!", Language.Italian);
            foreach (var value in Cards.Values)
            {
                string name = "[c:R]" + value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TORN FROM ITS ETERNAL RESPITE WITH A RELUCTANT GROAN, THE " + name + " SHAMBLES BACK TO ITS RIGHTFUL PLACE AMONG YOUR HORDE.", "STRAPPATO AL RIPOSO ETERNO CON UN GEMITO RILUTTANTE, " + name + " TORNA BARCOLLANDO AL SUO POSTO NELLA TUA ORDA.", Language.Italian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ITS BONES HOLLOWED THROUGH BY THE CREATURES OF THE SOIL, LEAVING IT FEELING UNNATURAL AND UNFAMILIAR.", "LE SUE OSSA SONO STATE SCAVATE DALLE CREATURE DEL SUOLO, RENDENDOLA INNATURALE E IRRICONOSCIBILE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THOUGH THE WEIGHT OF CONSEQUENCE ALSO SEEMS LIFTED...", "MA ANCHE IL PESO DELLE CONSEGUENZE SEMBRA SVANITO...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems i have finally been given my turn!", "Sembra che finalmente mi sia stato concesso il mio turno!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After this i will finally be at peace.", "Dopo questo, troverò finalmente pace.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, it seems we will start in this frigid valley.", "Bene, sembra che inizieremo in questa valle gelida.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It must be where Kaycees resides.", "Dev'essere qui che risiede Kaycee.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I didn't expect to meet you here again!", "Non mi aspettavo di incontrarti di nuovo qui!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems the deletion process has stalled!", "Sembra che il processo di cancellazione si sia bloccato!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You again?", "Ancora tu?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, i suppose we can go another time.", "Bene, suppongo che possiamo fare un altro giro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Still not deleted?", "Ancora non cancellato?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Much seems to be contained on this disk.", "Questo disco sembra contenere parecchie cose.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps the last run wasn't long enough.", "Forse l'ultima avventura non è durata abbastanza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, im sure Kaycee has the energy for more battles.", "Beh, sono sicura che Kaycee abbia ancora energie per altre battaglie.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The frigid valley, again.", "Di nuovo la valle gelida.", Language.Italian);
            foreach (var value in Cards.Values)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BITTER CHILL MIGHT HURT, BUT IT WON'T SLOW DOWN " + value + "!", "IL GELO PUNGENTE PUÒ FERIRE, MA NON RALLENTERÀ " + value + "!", Language.Italian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BLOCKED IN ALL SLOTS. NO ARMY THIS TIME.", "TUTTI GLI SPAZI SONO BLOCCATI. NIENTE ESERCITO STAVOLTA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blocked on both sides. No Shipwrecks for the Forgotten Man.", "Entrambi i lati sono bloccati. Niente Relitti per l'Uomo dimenticato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, I love this one!", "Oh, questo mi piace proprio!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Electric Chair, it allows you to harness the power of lightning itself, letting you [c:B]empower[c:] your cards with mutating abilties!", "La sedia elettrica ti permette di sfruttare il potere stesso del fulmine e di [c:B]potenziare[c:] le tue carte con abilità mutanti!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "However, I must warn you, it is no ordinary chair. With the ability to adjust the voltage, a higher level of course increases the unpredictability of the mutation.", "Devo però avvertirti: non è una sedia comune. Puoi regolare il voltaggio e, naturalmente, più è alto, più la mutazione diventa imprevedibile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The brave will master the current, the cowardly will blindly follow it.", "I coraggiosi dominano la corrente, i codardi la seguono ciecamente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you bold enough to tinker with its lever on the left, letting the voltage corrupt the selection of the sigils?", "Hai il coraggio di armeggiare con la leva a sinistra, lasciando che il voltaggio alteri la selezione dei sigilli?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SURELY YOUR CREATURE COULD BECOME MORE POWERFUL...", "LA TUA CREATURA POTREBBE CERTO DIVENTARE PIÙ POTENTE...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BUT YOU WOULD NEED TO RISK ANOTHER MOMENT UNDER THE SHOCK.", "MA DOVRESTI RISCHIARE UN ALTRO ISTANTE SOTTO LA SCOSSA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BONES FLEW LEFT AND RIGHT AS YOU RETREATED FROM THE SCENE.", "LE OSSA VOLAVANO A DESTRA E A MANCA MENTRE TI RITIRAVI DALLA SCENA.", Language.Italian);
            foreach (var value in Cards.Values)
            {
                string name = "[c:bR]" + value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU EVER SO CAREFULLY PULL THE " + name + " AWAY FROM THE ELECTRICITY AND LEAVE.", "ALLONTANI " + name + " DALL'ELETTRICITÀ CON ESTREMA CAUTELA E TE NE VAI.", Language.Italian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello, dear challenger, we meet again!", "Salve, caro sfidante, ci incontriamo di nuovo!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you ready for a good ol' fashioned [c:R]DUEL[c:]?", "Sei pronto per un bel [c:R]DUELLO[c:] vecchio stile?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I see, theres a third candle at play this time...", "Vedo che stavolta c'è in gioco una terza candela...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I feel you have [c:bG]bested[c:] me this time...", "Sembra che stavolta tu mi abbia [c:bG]superata[c:]...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It was an honour, either way!", "È stato comunque un onore!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONGRATULATIONS, YOU DID WELL.", "CONGRATULAZIONI, TE LA SEI CAVATA BENE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S SEE, THE NEXT AREA IS MY VERY OWN CRYPT.", "VEDIAMO, LA PROSSIMA AREA È LA MIA CRIPTA PERSONALE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PERHAPS YOU CAN BEAT ALL ODDS AND TRIUMPH!", "FORSE RIUSCIRAI A TRIONFARE CONTRO OGNI PROBABILITÀ!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "T'was well thought, i believe.", "È stata una mossa ben pensata, credo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LETS GET RID OF THE OL' SLOTS FOR NOW!", "LIBERIAMOCI PER ORA DEI VECCHI SPAZI!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its time for a different sort of game.", "È il momento di un gioco diverso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dont let the costs of the cards on your side of the board get above [c:R]10[c:]!", "Non lasciare che il costo delle carte sul tuo lato del tavolo superi [c:R]10[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you bust, you get punished, hit the perfect [c:R]10[c:] and you shall get a reward...", "Se sballi, subirai una punizione. Raggiungi il perfetto [c:R]10[c:] e avrai una ricompensa...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Was the ol' slot machine not enough for you?", "La vecchia slot machine non ti bastava?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guess we shall bring in some more heavy hitters so to say...", "Suppongo che dovremo chiamare qualche pezzo grosso, per così dire...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lets get those powerhouses out of the way first!", "Togliamo di mezzo prima quei colossi!", Language.Italian);
            foreach (var kvp in Cards)
            {
                string key = "[c:R]" + kvp.Key + "[c:]";
                string value = "[c:R]" + kvp.Value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear, you've made " + key + " quite angry.", "Oh cielo, hai fatto arrabbiare molto " + value + ".", Language.Italian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NO? A TERRIBLE FATE WILL AWAIT YOU", "NO? TI ATTENDERÀ UN DESTINO TERRIBILE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I FEEL WATCHED SOMEHOW", "MI SENTO OSSERVATA, IN QUALCHE MODO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AN ANCIENT ENERGY DEMANDS YOUR SACRIFICE", "UN'ENERGIA ANTICA ESIGE IL TUO SACRIFICIO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ARE YOU WILLING TO SACRIFICE ONE OF YOUR STARTING-", "VUOI SACRIFICARE UNA DELLE TUE RISORSE INIZIALI-", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WAIT", "ASPETTA", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT SEEMS YOU BEAR A TERRIBLE CURSE", "SEMBRA CHE TU SIA AFFLITTO DA UNA TERRIBILE MALEDIZIONE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU SHALL KEEP THE BOON, BUT FOR A FAR GREATER SACRIFICE", "CONSERVERAI IL DONO, MA IN CAMBIO DI UN SACRIFICIO BEN PIÙ GRANDE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CAN YOU GIVE UP YOUR ETERNAL ASHES?", "PUOI RINUNCIARE ALLE TUE CENERI ETERNE?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ARE YOU WILLING TO SACRIFICE ONE OF YOUR STARTING BONES", "VUOI SACRIFICARE UNO DEI TUOI OSSI INIZIALI?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A BRAVE SOUL", "UN'ANIMA CORAGGIOSA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE GODS ANSWER YOUR PRAYERS, NOW CHOOSE", "GLI DEI RISPONDONO ALLE TUE PREGHIERE. ORA SCEGLI.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOON OF THE INANIMATE", "DONO DELL'INANIMATO", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AT THE START OF A BATTLE, A DEAD TREE WILL SPAWN IN ON A RANDOM SPACE ON THE BOARD", "ALL'INIZIO DI UNA BATTAGLIA, UN ALBERO MORTO APPARE IN UNO SPAZIO CASUALE DEL TAVOLO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOON OF THE SUN KINGDOM", "DONO DEL REGNO DEL SOLE", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ON THE 4TH TURN OF A BATTLE, DRAW 2 RANDOM EGYPT CARDS", "AL QUARTO TURNO DI UNA BATTAGLIA, PESCA 2 CARTE EGIZIE CASUALI.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BOON OF REPENTANCE", "DONO DEL PENTIMENTO", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GAIN AN ADDITIONAL SOUL AT THE START OF A BATTLE", "OTTIENI UN'ANIMA AGGIUNTIVA ALL'INIZIO DI UNA BATTAGLIA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BOON OF EBONY EYES", "DONO DEGLI OCCHI D'EBANO", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TERRAIN CARDS WILL PROVIDE 2 BONES ON DEATH", "LE CARTE TERRENO FORNISCONO 2 OSSA ALLA MORTE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOON OF THE ADVERSARY", "DONO DELL'AVVERSARIO", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AT THE START OF A BOSS BATTLE, GAIN 3 EXTRA BONES", "ALL'INIZIO DI UNA BATTAGLIA CONTRO UN BOSS, OTTIENI 3 OSSA EXTRA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOON OF THE SEASICK", "DONO DEL MAL DI MARE", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AFTER PLACING 3 CARDS, A PIRATE SKELETON WILL BE PLAYED ON A RANDOM SPACE ON THE BOARD", "DOPO AVER POSIZIONATO 3 CARTE, VIENE GIOCATO UNO SCHELETRO PIRATA IN UNO SPAZIO CASUALE DEL TAVOLO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BOON OF THE CUT FINGER", "DONO DEL DITO RECISO", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DRAW AN ADDITIONAL CARD AT THE START OF A BATTLE", "PESCA UNA CARTA AGGIUNTIVA ALL'INIZIO DI UNA BATTAGLIA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A WISE CHOICE, NOW LEAVE BEFORE THE GODS GET TOO HUNGRY", "UNA SCELTA SAGGIA. ORA VATTENE, PRIMA CHE GLI DEI ABBIANO TROPPA FAME.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We spent a lot of time here, I'm sure you are eager to get going again!", "Abbiamo passato molto tempo qui. Sono sicura che non vedi l'ora di ripartire!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Gravebard bids us farewell", "Il Bardo delle tombe ci saluta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I see you would rather hold on to the ash that you have collected.", "Vedo che preferisci conservare la cenere che hai raccolto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It still may be of use later...", "Potrebbe ancora tornare utile più avanti...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And don't feel bad, the Gravebard still enjoyed your company while it lasted!", "E non sentirti in colpa: il Bardo delle tombe ha comunque apprezzato la tua compagnia!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even if you wanted anything else, you are no longer able to afford it...", "Anche se volessi qualcos'altro, non potresti più permettertelo...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feeling sorry for you, the Gravebard offers to come with you.", "Mosso a compassione, il Bardo delle tombe si offre di accompagnarti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Gravebard never runs out of stories to sing about.", "Il Bardo delle tombe non esaurisce mai le storie da cantare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And as it so happens, they are willing to make you another offering, but they insist that you give them 6 grams of ash this time.", "Si dà il caso che voglia farti un'altra offerta, ma stavolta insiste per avere 6 grammi di cenere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you willing to accept their terms?.", "Vuoi accettare le sue condizioni?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Gravebard is able to give you one final gift, but now they are asking a much higher price of 12 grams of ash!", "Il Bardo delle tombe può farti un ultimo regalo, ma ora chiede un prezzo molto più alto: 12 grammi di cenere!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astoundingly, you have enough to pay such a fee, but are you willing to part with it?", "Sorprendentemente, hai abbastanza per pagare una simile somma. Ma vuoi davvero separartene?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Will you offer 3 Grams worth of Ash?", "Vuoi offrire 3 grammi di cenere?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Gravebard has set up camp here.", "Un Bardo delle tombe si è accampato qui.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They play songs and elegies about long forgotten warriors and rulers.", "Suona canzoni ed elegie su guerrieri e sovrani dimenticati da tempo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though nowadays their audience consists mostly of various ghouls.", "Anche se ormai il suo pubblico è composto soprattutto da ghoul di vario genere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They are willing to play you a song and trade you an unknown gift in exchange for any grams of ash you happen to be carrying.", "È disposto a suonarti una canzone e a darti un regalo sconosciuto in cambio dei grammi di cenere che porti con te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The gravebard is willing to play you a song for an item. You have to pay in ash.", "Il Bardo delle tombe è disposto a suonarti una canzone per offrirti un oggetto. Devi pagare in cenere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All the excess damage you have done may finally come in handy!", "Tutti i danni in eccesso che hai inflitto potrebbero finalmente tornare utili!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strum the Lute when you are ready to make a trade.", "Pizzica il liuto quando sei pronto a fare lo scambio.", Language.Italian);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With " + price.ToString() + " grams of ash, they hand you a pouch, and play a song about a brave knight from the crusades.", "Ricevuti " + price.ToString() + " grammi di cenere, ti porgono una borsa e suonano una canzone su un valoroso cavaliere delle crociate.", Language.Italian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even after a Demonic entity cursed them into a horse-like form, they were still able to liberate the lost souls trapped by the Demon!", "Anche dopo che un'entità demoniaca lo aveva maledetto trasformandolo in una creatura simile a un cavallo, riuscì comunque a liberare le anime perdute imprigionate dal demone!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh right, the pouch, let's see what's inside!", "Ah, giusto, il sacchetto! Vediamo cosa contiene!", Language.Italian);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With " + price.ToString() + " grams of ash in tow, they hand you another pouch, and play a tune about a sorceress from a mythical land.", "Con " + price.ToString() + " grammi di cenere, ti porgono un'altra borsa e suonano una melodia su una maga di una terra mitica.", Language.Italian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Despite pressure from a prophecy to be the hero of the land, they instead pulled from a dark tome and sided with a cloudy villain to conquer the land and find peace from fame in an unexpected way!", "Nonostante una profezia la spingesse a diventare l'eroina del regno, attinse a un tomo oscuro e si alleò con un losco malvagio per conquistare la terra, trovando in modo inaspettato pace lontano dalla fama!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I almost forgot! You must be dying to know what is in the pouch!", "Quasi dimenticavo! Non starai nella pelle dalla voglia di sapere cosa contiene il sacchetto!", Language.Italian);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feeling satisfied with  " + price.ToString() + " grams of ash, they hand you a pouch, and recount the tale of 4 islands.", "Soddisfatti dei " + price.ToString() + " grammi di cenere, ti porgono una borsa e raccontano la storia di 4 isole.", Language.Italian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each of the islands had a ruler fixated on a selfish goal, all except for one...", "Ogni isola aveva un sovrano ossessionato da uno scopo egoistico. Tutte, tranne una...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One island had a secluded hermit covered in moss and fungi. They surrounded themselves with beasts, and would eternally trap anyone who would wander into their forest.", "Su un'isola viveva un eremita solitario coperto di muschio e funghi. Si circondava di bestie e intrappolava per sempre chiunque si avventurasse nella sua foresta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Another island had a mysterious wizard covered head to toe in a green fur. Their true goal remained unknown, but seemed to involve the torturing of their own subjects...", "Un'altra isola ospitava un misterioso stregone coperto di pelo verde dalla testa ai piedi. Il suo vero obiettivo restava ignoto, ma sembrava comportare la tortura dei suoi stessi sudditi...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The worst island however, was barely even an island at all! A metallic barge with a sleepless factory ruled by an arrogant, robotic tyrant...", "L'isola peggiore, però, non era quasi nemmeno un'isola! Una chiatta metallica con una fabbrica che non dormiva mai, governata da un arrogante tiranno robotico...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Which leaves the other island, a sprawling burial ground with a Crypt at the end of it. It was ruled by a woman who only wished for the power struggle to finally end...", "Restava l'altra isola, un vasto cimitero con una cripta in fondo. Era governata da una donna che desiderava soltanto la fine della lotta per il potere...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh! That would happen to be me!", "Oh! Si dà il caso che sia io!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think we now know how that story ended.", "Credo che ora sappiamo come sia finita quella storia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And truthfully, the story still isn't over yet, maybe we can reach the end together!", "E a dire il vero, la storia non è ancora finita. Forse possiamo arrivare alla fine insieme!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That being said, you have earned this item.", "Detto questo, ti sei guadagnato questo oggetto.", Language.Italian);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Taking " + price.ToString() + " grams of ash with them, they hand you a pouch, and tell you about an ancient hunter of ghouls.", "Portano via " + price.ToString() + " grammi di cenere, ti porgono una borsa e ti parlano di un antico cacciatore di ghoul.", Language.Italian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though he was barely a hunter, instead he spent his time searching for something he could not obtain.", "Ma non era quasi un cacciatore. Passava invece il tempo a cercare qualcosa che non poteva ottenere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In the end he found a glimpse of what he had seeked, but paid a horrible price.", "Alla fine intravide ciò che cercava, ma pagò un prezzo terribile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You should see whats inside that pouch.", "Dovresti vedere cosa c'è in quel sacchetto.", Language.Italian);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Taking " + price.ToString() + " grams of your ash, they hand you a pouch, and reminisce about a medic from medieval times.", "Portano via " + price.ToString() + " grammi della tua cenere, ti porgono una borsa e ricordano un medico medievale.", Language.Italian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Instead of being content with their life, they instead chased the love of their life for years.", "Invece di accontentarsi della propria vita, inseguì per anni l'amore della sua vita.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This got them into much danger, but their friends were always there to help them out!", "Questo lo mise in molti pericoli, ma i suoi amici erano sempre pronti ad aiutarlo!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lets see what that pouch contains.", "Vediamo cosa contiene quel sacchetto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RISE MY ARMY! RIIIIIIIIIISE!", "SORGI, MIO ESERCITO! SOOOOOORGI!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:5]Otis![size:]", "[size:5]Otis![size:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:5]Ephialtes![size:]", "[size:5]Efialte![size:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH? FIVE LANES? HOW BOLD.", "OH? CINQUE CORSIE? CHE AUDACIA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT A SHAME", "CHE PECCATO", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT SEEMS YOUVE GIVEN UP YOUR REWARD FOR CHAOS", "SEMBRA CHE TU ABBIA RINUNCIATO ALLA TUA RICOMPENSA IN CAMBIO DEL CAOS.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I CANNOT BE DEFEATED", "NON POSSO ESSERE SCONFITTO", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I ALMOST FORGOT", "QUASI DIMENTICAVO", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ALL OF THIS SUFFERING YOU CAUSED, ALL OF THIS PAIN", "TUTTA QUESTA SOFFERENZA CHE HAI CAUSATO, TUTTO QUESTO DOLORE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU OUGHT TO BE REWARDED FOR ALL THAT EXCESS DAMAGE", "MERITI UNA RICOMPENSA PER TUTTI QUEI DANNI IN ECCESSO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TAKE THIS FOR YOUR EFFORTS", "PRENDI QUESTO PER I TUOI SFORZI.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT A TERRIBLE FOE, THIS WONT DEFEAT ME!", "CHE TERRIBILE NEMICO. QUESTO NON MI SCONFIGGERÀ!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT DID YOU DO. I AM DOOMED.", "COSA HAI FATTO? SONO SPACCIATO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A FORMIDABLE OPPONENT, YOU DID WELL IT SEEMS.", "UN AVVERSARIO FORMIDABILE. SEMBRA CHE TE LA SIA CAVATA BENE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minor Ashes", "Ceneri minori", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Ashes", "Ceneri maggiori", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BEHOLD, MY LATEST CREATIONS! THE TWIN GIANTS!", "AMMIRA LE MIE ULTIME CREAZIONI! I GIGANTI GEMELLI!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HELLO?", "C'È QUALCUNO?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We survived, but... but...", "Siamo sopravvissuti, ma... ma...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Our tools did not.", "I nostri strumenti no.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Our talents still remain, but..", "Abbiamo ancora il nostro talento, ma...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We must do things differently.", "Dobbiamo agire diversamente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We cannot fuse two into one, but...", "Non possiamo fonderne due in una, ma...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We can swap their souls, their Sigils.", "Possiamo scambiare le loro anime, i loro sigilli.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is once again time...", "È di nuovo il momento...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time to swap the souls of your cards.", "Il momento di scambiare le anime delle tue carte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time, it is...", "È il momento, è...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We shall work once more.", "Lavoreremo ancora una volta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This will get ugly...", "Sarà uno spettacolo orribile...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Their bodies and souls, they are...", "I loro corpi e le loro anime sono...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Switched.", "Scambiati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They lead new lives..", "Vivono nuove vite...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With new purposes.", "Con nuovi scopi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Till we meet again, one day... one day...", "Finché ci incontreremo di nuovo, un giorno... un giorno...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE WILL PROVIDE A HELPFUL CURSE OR BLESSING, AS SOME CALL IT UPON YOUR ARMY IF YOU LEAVE HIM AN OFFERING.", "SE GLI LASCI UN'OFFERTA, CONFERIRÀ AL TUO ESERCITO UN'UTILE MALEDIZIONE, O BENEDIZIONE, COME LA CHIAMANO ALCUNI.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I HOPE FOR YOUR SAKE HE IS FEELING GENEROUS.", "PER IL TUO BENE, SPERO CHE SI SENTA GENEROSO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BONELORD IS VERY HAPPY WITH THIS OFFERING", "IL SIGNORE DELLE OSSA È MOLTO SODDISFATTO DI QUESTA OFFERTA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I AM VERY THANKFUL FOR THIS", "TE NE SONO MOLTO GRATO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TAKE THIS IN RETURN, YOU CAN USE IT TO CALL ME ANYTIME", "PRENDI QUESTO IN CAMBIO. PUOI USARLO PER CHIAMARMI IN QUALSIASI MOMENTO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU CANNOT END THIS, END ME, THAT IS", "NON PUOI PORRE FINE A QUESTO. A ME, INTENDO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feeling overburdened enough with a full 3 items, you carried on.", "Già abbastanza appesantito dai tuoi 3 oggetti, hai proseguito.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee says it's time to freeze!", "Kaycee dice che è ora di congelare!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sawyer thanks you for your contribution!", "Sawyer ti ringrazia per il tuo contributo!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sawyer felt bad for you.", "Sawyer ha provato pena per te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope you're able to warm up next turn.", "Spero che tu riesca a scaldarti al prossimo turno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wonderful! I am pleasantly surprised by your triumph against me!", "Meraviglioso! Il tuo trionfo su di me è una piacevole sorpresa!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...It seems you have bested this game.", "... Sembra che tu abbia sconfitto questo gioco.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But alas, you have cheated.", "Ma ahimè, hai barato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm absolutely astonished!", "Sono davvero sbalordita!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've gone above and beyond what I thought you were capable of!", "Hai superato di gran lunga ciò di cui ti credevo capace!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is no where else to go beyond this...", "Non c'è altro posto dove andare, oltre questo...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So I owe it to you to know the truth...", "Perciò ti devo la verità...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee, the REAL Kaycee...", "Kaycee, la VERA Kaycee...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I know about the Horrifying contents of the OLD_DATA.", "Conosco gli orribili contenuti dei DATI_VECCHI.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Surely you have looked into it too..", "Sicuramente anche tu ci hai guardato dentro...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Windows into your world's greatest evils, both past and present.", "Finestre sui mali peggiori del tuo mondo, passati e presenti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I want to destroy it, and...", "Voglio distruggerli, e...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:R]THAT IS QUITE ENOUGH[c:]", "[c:R]ADESSO BASTA[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:R]IT IS TIME FOR THIS TO END.[c:]", "[c:R]È ORA CHE TUTTO QUESTO FINISCA.[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...But it seems i cannot move on just yet.", "... Ma sembra che non possa ancora andare oltre.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goodbye.", "Addio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...You wish to continue? Endlessly? Splendid!", "... Vuoi continuare? All'infinito? Splendido!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please, take a card of your choosing.", "Prego, prendi una carta a tua scelta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOUR WEAK SPIRITS SHALL NOT HAUNT ME NO MORE.", "I TUOI DEBOLI SPIRITI NON MI TORMENTERANNO PIÙ.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DEATH TOUCH WON'T HELP YOU HERE DEAR.\nI MADE THESE GIANTS SPECIAL, IMMUNE TO QUITE A FEW DIFFERENT TRICKS!", "IL TOCCO DELLA MORTE NON TI AIUTERÀ QUI, TESORO.\nHO RESO SPECIALI QUESTI GIGANTI, IMMUNI A PARECCHI TRUCCHI DIVERSI!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BONELORD CANNOT BE POSSESSED!", "IL SIGNORE DELLE OSSA NON PUÒ ESSERE POSSEDUTO!", Language.Italian);
            foreach (var kvp in Cards)
            {
                string key = "[c:B]" + kvp.Key + "[c:]";
                string value = "[c:B]" + kvp.Value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, key + " MIGHT HAVE SOME DIFFICULTY SUBMERGING IF IT'S FROZEN SOLID!", value + " FARÀ FATICA A IMMERGERSI SE È COMPLETAMENTE CONGELATA!", Language.Italian);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, key + " CAN'T POSSESS ANYTHING IF IT CAN'T MOVE!", value + " NON PUÒ POSSEDERE NIENTE SE NON PUÒ MUOVERSI!", Language.Italian);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, key + " WILL HAVE A HARD TIME HOOKING ANYTHING IF IT'S FROZEN SOLID!", value + " FARÀ FATICA AD AGGANCIARE QUALCOSA SE È COMPLETAMENTE CONGELATA!", Language.Italian);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, key + " FINALLY! TO GET RID OF THAT FOUL SMELL!", value + " FINALMENTE! LIBERIAMOCI DI QUEL FETORE!", Language.Italian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LETS [c:R]HEAT[c:] UP SOME CARDS!", "[c:R]SCALDIAMO[c:] UN PO' DI CARTE!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Y-Your strikes are only making me [c:B]c-colder[c:]!", "I-i tuoi colpi mi fanno solo avere più [c:B]f-freddo[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S TIME FOR YOUR CARDS TO FREEZE! [c:B]CHILLED[c:] TO THE BONE!", "È ORA DI CONGELARE LE TUE CARTE! [c:B]GELIDE[c:] FINO ALLE OSSA!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ALL THIS [c:bB]ICE[c:] IS TAKING UP TOO MUCH SPACE!", "TUTTO QUESTO [c:bB]GHIACCIO[c:] OCCUPA TROPPO SPAZIO!", Language.Italian);
            foreach (var kvp in Cards)
            {
                string key = "[c:bR]" + kvp.Key + "[c:]";
                string value = "[c:bR]" + kvp.Value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YARRRR, I WILL ENJOY THE KABOOM OF " + key, "ARRR, MI GODRÒ IL BOTTO DI " + value, Language.Italian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOIL ME ORANGES, THERES A-WAVES COMIN!", "PER TUTTE LE ARANCE BOLLITE, ARRIVANO LE ONDE!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THESE WAVES WILL PUSH YE CARD OFF THE BOARD, BACK TO YER HAND!", "QUESTE ONDE SPINGERANNO LE TUE CARTE FUORI DAL TAVOLO, DI NUOVO NELLA TUA MANO!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THIS PIRATE CANNOT BE TAKEN BACK UP BY THE WAVES! BUT EVEN THE ZESTIEST OF PIRATES WILL BE SHAKEN UP!", "QUESTO PIRATA NON PUÒ ESSERE TRASCINATO VIA DALLE ONDE! MA ANCHE I PIRATI PIÙ VISPI VERRANNO SBALLOTTATI!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seven seas for the table!", "I sette mari sul tavolo!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, I WILL STORE THIS BONE FOR LATER", "OH, CONSERVERÒ QUEST'OSSO PER DOPO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SPARE SOME SOULS?", "QUALCHE ANIMA DA DONARE?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PLEASE, WON'T YOU SPARE SOME BONES FOR A POOR GHOUL LIKE ME?", "TI PREGO, NON HAI QUALCHE OSSO PER UN POVERO GHOUL COME ME?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, HOW SAD. YOUR HAMMER COULD NOT BREAK THE ICE, AND SHATTERED", "OH, CHE PECCATO. IL TUO MARTELLO NON È RIUSCITO A ROMPERE IL GHIACCIO E SI È FRANTUMATO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE FRAIL THING WILL SHATTER AFTER EXCESSIVE USE. THREE STRIKES, AND IT'S OUT, FOR THIS BATTLE AT LEAST.", "QUESTO FRAGILE ARNESE SI FRANTUMERÀ CON L'USO ECCESSIVO. TRE COLPI ED È FUORI GIOCO, ALMENO PER QUESTA BATTAGLIA.", Language.Italian);
            foreach (var kvp in Cards)
            {
                string key = "[c:lGr]" + kvp.Key + "[c:]";
                string value = "[c:lGr]" + kvp.Value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... it will be rather difficult to haunt " + key + " with their abilities at max capacity.", "Oh... sarà piuttosto difficile infestare " + value + " con le sue abilità al massimo.", Language.Italian);
            }
            foreach (var value in Cards.Values)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH DEAR! LOOKS LIKE YOU HAVE HOOKED SOMETHING OUT OF " + value + "!", "OH CIELO! SEMBRA CHE TU ABBIA PESCATO QUALCOSA DA " + value + "!", Language.Italian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bB]BRRRR![c:] I'VE BEEN FREEZING FOR AGES!", "[c:bB]BRRRR![c:] STO GELANDO DA SECOLI!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S TURN UP THE [c:R]HEAT[c:] FOR A GOOD FIGHT!", "ALZIAMO LA [c:R]TEMPERATURA[c:] PER UNA BELLA BATTAGLIA!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh hey, looks like I've got another shot. Hope you watched the weather forecast!", "Oh, ehi, sembra che abbia un'altra possibilità. Spero che tu abbia guardato le previsioni del tempo!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH COME ON DUDE, I'M STILL [c:B]COLD![c:]", "OH, DAI, HO ANCORA [c:B]FREDDO![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S FIGHT AGAIN SOON!", "COMBATTIAMO DI NUOVO PRESTO!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONGRATULATIONS, YOU DID WELL.", "CONGRATULAZIONI, TE LA SEI CAVATA BENE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU HAVE DEFEATED ONE OF MY LOVELY GHOULS, YOU WILL NOW START FIGHTS WITH AN ADDITONAL BONE.", "HAI SCONFITTO UNO DEI MIEI ADORABILI GHOUL. ORA INIZIERAI LE BATTAGLIE CON UN OSSO AGGIUNTIVO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SAWYERS CATACOMBS ARE UP NEXT, A FILTHY PLACE WHERE LOTS ARE LAID TO REST.", "ORA TOCCA ALLE CATACOMBE DI SAWYER, UN LUOGO LURIDO DOVE RIPOSANO MOLTI DEFUNTI.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE THINKS IT IS A TERRIBLE PLACE TO BE.", "LUI PENSA CHE SIA UN POSTO TERRIBILE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "C'mon dude, where are you going? Can't handle the cold?", "Dai, dove vai? Non sopporti il freddo?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, IT SEEMS I HAVE FINALLY [c:R]WARMED UP![c:]", "OH, SEMBRA CHE MI SIA FINALMENTE [c:R]SCALDATA![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'M STILL NOT FEELING [c:R]WARMER![c:]", "NON MI SENTO ANCORA [c:R]PIÙ CALDA![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LETS SEE HOW YOU DEAL WITH [c:bB]THIS![c:]", "VEDIAMO COME TE LA CAVI CON [c:bB]QUESTO![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Careful, the life of your next card will be on a timer.", "Attento, la vita della tua prossima carta sarà a tempo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I look forward to the [c:brnO]explosive[c:] results!", "Non vedo l'ora di vedere i risultati [c:brnO]esplosivi[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your card cannot explode, how dissapointing.", "La tua carta non può esplodere. Che delusione.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VAR, I SEE YOU MADE IT TO ME SHIP CHALLENGER!", "ARR, VEDO CHE SEI ARRIVATO SULLA MIA NAVE, SFIDANTE!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'VE BEEN WAITING FOR A WORTHY FIGHT!", "ASPETTAVO UNA BATTAGLIA DEGNA DI QUESTO NOME!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT SEEMS A STORM IS BREWING, I HOPE ME SHIP CAN HANDLE IT", "SEMBRA CHE SI PREPARI UNA TEMPESTA. SPERO CHE LA MIA NAVE REGGA.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, I SEE YEE ARE SEVERELY HAUNTED!", "OH, VEDO CHE SEI PROPRIO INFESTATO!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "REVENANT, PACK YE BAGS, YOURE GETTING THROWN OVERBOARD!", "FANTASMA, FA' I BAGAGLI, STAI PER FINIRE FUORIBORDO!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I OVERESTIMATED ME SKILL, GOOD LUCK CHALLENGER.", "HO SOPRAVVALUTATO LE MIE CAPACITÀ. BUONA FORTUNA, SFIDANTE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S SEE, THE NEXT AREA IS MY VERY OWN CRYPT.", "VEDIAMO, LA PROSSIMA AREA È LA MIA CRIPTA PERSONALE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PERHAPS YOU CAN BEAT ALL ODDS AND TRIUMPH!", "FORSE RIUSCIRAI A TRIONFARE CONTRO OGNI PROBABILITÀ!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I beat the livin' PULP out o' ye!", "Ti ho ridotto in POLTIGLIA!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ME SHIP! I FEAR WE MAY BE SINKING.", "LA MIA NAVE! TEMO CHE STIAMO AFFONDANDO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO HOLD YEE BREATH!", "PREPARATI A TRATTENERE IL FIATO!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HOLY FISHPASTE, YE FOUND DAVY JONES TREASURE", "PER TUTTA LA PASTA DI PESCE, HAI TROVATO IL TESORO DI DAVY JONES!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YARRG, TWAS JUST DA FIRST ROUND!\nLETS SEE HOW YE FARE 'GAINST ME PERSONAL SHIP AN CREW!", "ARR! ERA SOLO IL PRIMO ROUND!\nVEDIAMO COME TE LA CAVI CONTRO LA MIA NAVE PERSONALE E LA MIA CIURMA!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HOW NICE OF YOU TO COME KNOCK AT MY DOORSTEP ON THIS TRULY SPOOKY DAY! DO YOU PREFER TREATS, OR TRICKS?", "CHE GENTILE A BUSSARE ALLA MIA PORTA IN QUESTO GIORNO DAVVERO SPAVENTOSO! PREFERISCI DOLCETTI O SCHERZETTI?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LOOK AWAY, LOOK AWAY! IF YOU WANT TO FIGHT, GET IT OVER QUICK!", "GUARDA ALTROVE, GUARDA ALTROVE! SE VUOI COMBATTERE, FACCIAMOLA FINITA IN FRETTA!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "oh... I- I see you're here again... Please, get rid of that monster and maybe I'll find some more time for you", "oh... V-vedo che sei di nuovo qui... Ti prego, liberati di quel mostro e forse troverò un po' più di tempo per te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU HAVE BEATEN THE VICIOUS CANDY MONSTER AND SAVED HALLOWEEN!", "HAI SCONFITTO IL FEROCE MOSTRO DI CARAMELLE E SALVATO HALLOWEEN!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THANKS FOR GETTING IT OVER WITH, AND DON'T EVER RETURN!", "GRAZIE PER AVERLA FATTA FINITA, E NON TORNARE MAI PIÙ!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEXT UP IS ROYALS VERY OWN SHIP, THE LIMONCELLO.", "ORA TOCCA ALLA NAVE PERSONALE DI ROYAL, IL LIMONCELLO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HIS TRUSTY CREW OF SWASHBUCKLERS RESIDES THERE, MAY THEY GIVE YOU A WARM WELCOME.", "LÌ RISIEDE LA SUA FIDATA CIURMA DI SPADACCINI. CHE POSSANO DARTI UN CALOROSO BENVENUTO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh no... does this mean you will try again?", "Oh no... Significa che ci riproverai?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, HE IS GONE... WHAT A RELIEF.", "OH, SE N'È ANDATO... CHE SOLLIEVO.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THANKS FOR YOUR BONES, KIND SIR!", "GRAZIE PER LE TUE OSSA, GENTILUOMO!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOW THAT THAT MONSTER IS GONE, WHY DONT WE PLAY A LITTLE LONGER", "ORA CHE QUEL MOSTRO NON C'È PIÙ, PERCHÉ NON GIOCHIAMO ANCORA UN PO'?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I HOPE YOU DONT MIND, I PAID GOOD MONEY TO PLAY THESE.", "SPERO NON TI DISPIACCIA, HO PAGATO FIOR DI QUATTRINI PER GIOCARE QUESTE CARTE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOT THE CANDY MONSTER! HE HAS ENOUGH OF YOUR [c:R]TRICKS![c:]", "NON IL MOSTRO DI CARAMELLE! NE HA ABBASTANZA DEI TUOI [c:R]TRUCCHI![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH NO, HE HAS ARRIVED! HE IS THIRSTY FOR YOUR [c:R]BONES![c:]", "OH NO, È ARRIVATO! HA SETE DELLE TUE [c:R]OSSA![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you!", "Grazie!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOUUUUUUUR, PAINNNFULLLLL DEAAATHHH AWAIIITTTSSS YOUUUUUUU!", "LA TUAAA MOOORTE DOLOOOOROSA TI ASPEEEETTA!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ARRG! WALK OFF THE PLANK YEE DIRTY SCALLYWAG!!!", "ARR! CAMMINA SULL'ASSE, SPORCO FURFANTE!!!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My dogs will enjoy your bones!", "I miei cani si godranno le tue ossa!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A [c:bR]{0}[c:]... He's only here for the riches.", "Un [c:bR]{0}[c:]... È qui solo per le ricchezze.", Language.Italian);
            foreach (var value in Cards.Values)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been generous.\n[c:bR]" + value + "[c:] bone cost has decreased!", "Il Signore delle ossa è stato generoso.\nIl costo in ossa di [c:bR]" + value + "[c:] è diminuito!", Language.Italian);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been generous.\n[c:bR]" + value + "[c:] base health has increased!", "Il Signore delle ossa è stato generoso.\nLa salute base di [c:bR]" + value + "[c:] è aumentata!", Language.Italian);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear, it looks like [c:bR]" + value + "[c:] bone cost has decreased!", "Oh cielo, sembra che il costo in ossa di [c:bR]" + value + "[c:] sia diminuito!", Language.Italian);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been generous.\n[c:bR]" + value + "[c:] bone cost has decreased greatly!", "Il Signore delle ossa è stato generoso.\nIl costo in ossa di [c:bR]" + value + "[c:] è diminuito molto!", Language.Italian);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been very generous.\n[c:bR]" + value + "[c:] base health has increased greatly!", "Il Signore delle ossa è stato molto generoso.\nLa salute base di [c:bR]" + value + "[c:] è aumentata molto!", Language.Italian);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been very generous.\n[c:bR]" + value + "[c:] base attack has increased!", "Il Signore delle ossa è stato molto generoso.\nL'attacco base di [c:bR]" + value + "[c:] è aumentato!", Language.Italian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... WHAT? WHY DID YOU DO THAT BONELORD?! [c:bR]INCREASING THE HEALTH OF THE ENTIRE DECK?![c:] YOU FOOL!", "... COSA? PERCHÉ L'HAI FATTO, SIGNORE DELLE OSSA?! [c:bR]AUMENTARE LA SALUTE DELL'INTERO MAZZO?![c:] SCIOCCO!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... WHAT? WHY DID YOU DO THAT BONELORD?! [c:bR]DECREASING THE COST OF THE ENTIRE DECK?![c:] YOU FOOL!", "... COSA? PERCHÉ L'HAI FATTO, SIGNORE DELLE OSSA?! [c:bR]RIDURRE IL COSTO DELL'INTERO MAZZO?![c:] SCIOCCO!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU DON'T HAVE ANYMORE CARDS TO [c:bR]GAIN HP[c:], HOW SAD. NOW PLEASE LEAVE.", "NON HAI PIÙ CARTE A CUI [c:bR]AUMENTARE LA SALUTE[c:]. CHE PECCATO. ORA VATTENE, PER FAVORE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU DON'T HAVE ANYMORE CARDS TO [c:bR]REDUCE THEIR BONE COST[c:], HOW SAD. NOW PLEASE LEAVE.", "NON HAI PIÙ CARTE A CUI [c:bR]RIDURRE IL COSTO IN OSSA[c:]. CHE PECCATO. ORA VATTENE, PER FAVORE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU DON'T HAVE ANYMORE CARDS TO [c:bR]GAIN ATTACK[c:], HOW SAD. NOW PLEASE LEAVE.", "NON HAI PIÙ CARTE A CUI [c:bR]AUMENTARE LA POTENZA[c:]. CHE PECCATO. ORA VATTENE, PER FAVORE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THAT'S UNFORTUNATE. YOU WERE SUPPOSED TO HAVE YOUR ENTIRE DECK DECREASED, BUT IT LOOKS LIKE THE BONELORD HAS ALREADY GIFTED YOU THAT. BEGONE!", "CHE SFORTUNA. IL COSTO DELL'INTERO MAZZO DOVEVA DIMINUIRE, MA SEMBRA CHE IL SIGNORE DELLE OSSA TI ABBIA GIÀ FATTO QUESTO DONO. SPARISCI!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THAT'S UNFORTUNATE. YOU WERE SUPPOSED TO HAVE YOUR ENTIRE DECK INCREASED, BUT IT LOOKS LIKE THE BONELORD HAS ALREADY GIFTED YOU THAT. BEGONE!", "CHE SFORTUNA. L'INTERO MAZZO DOVEVA ESSERE POTENZIATO, MA SEMBRA CHE IL SIGNORE DELLE OSSA TI ABBIA GIÀ FATTO QUESTO DONO. SPARISCI!", Language.Italian);


            // ShowThenClear
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO BE BOARDED!", "PREPARATI ALL'ARREMBAGGIO!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That hammer doesn't look very sturdy, you'll break it if you bash my ice!", "Quel martello non sembra molto robusto. Lo romperai se colpisci il mio ghiaccio!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DID YOU REALLY THINK THE BONELORD WOULD LET YOU OFF THAT EASILY?!", "PENSAVI DAVVERO CHE IL SIGNORE DELLE OSSA TI AVREBBE LASCIATO ANDARE COSÌ FACILMENTE?!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET THE [size:5][c:bR]BONELORD[c:][size:] COMMETH!", "CHE VENGA IL [size:5][c:bR]SIGNORE DELLE OSSA[c:][size:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose as you will...", "Scegli come vuoi...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose one.", "Scegline una.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time to rest.", "È ora di riposare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Go Bartender![c:] Drink up!", "[c:bG]Vai, Barista![c:] Bevi tutto!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Go Undertaker![c:] Dont scream!", "[c:bG]Vai, Becchino![c:] Non urlare!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Go Slingers Soul![c:] Time for a duel!", "[c:bG]Vai, Anima del pistolero![c:] È l'ora del duello!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Go One Armed Bandit![c:] I hope i get lucky!", "[c:bG]Vai, Bandito con un braccio![c:] Spero di avere fortuna!", Language.Italian);
            for (int amnt = 0; amnt < 10; amnt++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your score is " + amnt.ToString() + ", acceptable.", "Il tuo punteggio è " + amnt.ToString() + ", accettabile.", Language.Italian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "our score is 10, heres your prize!", "Il tuo punteggio è 10, ecco il tuo premio!", Language.Italian);
            for (int amnt = 11; amnt <= 100; amnt++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "our score is " + amnt.ToString() + ", too bad!", "Il tuo punteggio è " + amnt.ToString() + ", che peccato!", Language.Italian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SUCH A SMALL TRAP CANNOT AFFECT GIANTS.", "UNA TRAPPOLA COSÌ PICCOLA NON PUÒ COLPIRE I GIGANTI.", Language.Italian);

            // ShowMessage
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PUSH YOUR LUCK FOR ONE MORE ABILITY?\nOR PULL AWAY?", "TENTARE LA FORTUNA PER UN'ALTRA ABILITÀ?\nO TIRARSI INDIETRO?", Language.Italian);

            // Challenge
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No Bones", "Senza ossa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You no longer gain the extra bones, from defeating bosses.", "Non ottieni più le ossa extra per aver sconfitto i boss.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's Kerfuffle", "Trambusto di Kaycee", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The fourth turn of every battle, all your cards will be Frozen Away.", "Al quarto turno di ogni battaglia, tutte le tue carte ottengono Congelato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sawyer's Showdown", "Resa dei conti di Sawyer", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose 1 bone every 3rd turn, if you have less than 3, gain 1 Bone", "Ogni terzo turno perdi 1 osso. Se ne hai meno di 3, ottieni 1 osso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal Rumble", "Rissa Royal", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every third card you play gains the Lit Fuse sigil.", "Ogni terza carta che giochi ottiene il sigillo Miccia accesa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soulless", "Senz'anima", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeletons cost +1 Energy.", "Gli Scheletri costano +1 energia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frail Hammer", "Martello fragile", Language.Italian);
