    public class MagnificusMod
    {
        public static Dictionary<string, string> Cards = new();
        public static Dictionary<string, List<KeyValuePair<string, string>>> CardsDescription = new();

        public static Dictionary<string, string> Abilities = new();

        public static void RegisterCard(string en, string zh, string desen, string deszh)
        {
            if (!Cards.ContainsKey(en))
            {
                Cards.Add(en, zh);
            }
            if (!CardsDescription.ContainsKey(en))
            {
                CardsDescription[en] = new List<KeyValuePair<string, string>>();
            }
            CardsDescription[en].Add(new KeyValuePair<string, string>(desen, deszh));
        }

        public static void RegisterAbility(string en, string zh)
        {
            Abilities.Add(en, zh);
        }

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Magnificus Mod");
            // SetText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "New Magnificus Run", "NUOVA SESSIONE CON MAGNIFICUS", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEW MAGNIFICUS RUN", "NUOVA SESSIONE CON MAGNIFICUS", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "View Deck", "Visualizza mazzo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TOWER OF MAGICKS", "TORRE DELLE MAGIE", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GOO DUNGEON", "SOTTERRANEO DI MELMA", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LAVA DUNGEON", "SOTTERRANEO DI LAVA", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VOID DUNGEON", "SOTTERRANEO DEL VUOTO", Language.Italian);

            // Config
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Automatically unlocks every challenge and starter deck in Magnificus' Kaycees Mod. This does NOT change your magnificus challenge point value. If you have a change of heart and decide to unlock the challenges fairly, your challenge points will remain the same.", "Sblocca automaticamente tutte le sfide e i mazzi iniziali nel Mod di Kaycee di Magnificus. NON modifica i tuoi punti sfida di Magnificus. Se cambi idea e decidi di sbloccare le sfide lealmente, i tuoi punti sfida rimarranno gli stessi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Base wizard cards from act 2 will keep their original statlines.", "Le carte base degli stregoni dell'atto 2 mantengono le loro statistiche originali.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use the old 2D flat card designs instead of the new 3D models.", "Usa i vecchi modelli piatti delle carte in 2D al posto dei nuovi modelli in 3D.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Add paint splashes to the background of every card (like in the original magnificus finale).", "Aggiunge schizzi di vernice allo sfondo di ogni carta, come nel finale originale di Magnificus.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Third person perspective for magnificus' game. Disable if you want the classic first person experience.", "Visuale in terza persona per il gioco di Magnificus. Disattivala se vuoi l'esperienza classica in prima persona.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Show a grid around the player in tabletop mode.", "Mostra una griglia attorno al giocatore in modalità da tavolo.", Language.Italian);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blank Mox", "Mox vuoto", Language.Italian);
            RegisterAbility("Blank Mox", "Mox vuoto");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is drawn, it will materialize into a random Mox Crystal. \n When on another card, the card will generate a random Mox Crystal.", "Quando si pesca una carta che possiede questo sigillo, si materializza in un cristallo Mox casuale. \n Su un'altra carta, questo sigillo fa generare alla carta un cristallo Mox casuale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undecided Mox", "Mox indeciso", Language.Italian);
            RegisterAbility("Undecided Mox", "Mox indeciso");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, select a mox type for this card to provide.", "Quando si gioca una carta che possiede questo sigillo, scegli un tipo di Mox che la carta fornirà.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Heart", "Cuor di rubino", Language.Italian);
            RegisterAbility("Ruby Heart", "Cuor di rubino");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Ruby Mox in its place.", "Quando una carta che possiede questo sigillo muore, crea un Mox rubino al suo posto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Heart", "Cuore di zaffiro", Language.Italian);
            RegisterAbility("Sapphire Heart", "Cuore di zaffiro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Sapphire Mox in its place.", "Quando una carta che possiede questo sigillo muore, crea un Mox zaffiro al suo posto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Marrow", "Midollo osseo", Language.Italian);
            RegisterAbility("Bone Marrow", "Midollo osseo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When one of your non-gem cards perishes, a card bearing this sigil gains 1 power, maxing out at 5.", "Quando una delle tue carte non gemma muore, una carta che possiede questo sigillo ottiene 1 di potenza, fino a un massimo di 5.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimulation", "Stimolazione", Language.Italian);
            RegisterAbility("Stimulation", "Stimolazione");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigil gains 1 power, maxing out at 4.", "Alla fine di ogni turno, una carta che possiede questo sigillo ottiene 1 di potenza, fino a un massimo di 4.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimulation (Health)", "Stimolazione della salute", Language.Italian);
            RegisterAbility("Stimulation (Health)", "Stimolazione della salute");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigil gains 2 health, maxes out at 10.", "Alla fine di ogni turno, una carta che possiede questo sigillo ottiene 2 di salute, fino a un massimo di 10.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Draw", "Pesca funebre", Language.Italian);
            RegisterAbility("Dead Draw", "Pesca funebre");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-gem card dies, draw a card from your deck.", "Quando muore una carta non gemma, pesca una carta dal tuo mazzo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Heart", "Cuore di smeraldo", Language.Italian);
            RegisterAbility("Emerald Heart", "Cuore di smeraldo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates an Emerald Mox in its place.", "Quando una carta che possiede questo sigillo muore, crea un Mox smeraldo al suo posto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gooey", "Melmoso", Language.Italian);
            RegisterAbility("Gooey", "Melmoso");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, the striker loses 1 attack.", "Quando una carta che possiede questo sigillo viene colpita, l'attaccante perde 1 di potenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mental Gemnastics", "Gemmastica mentale", Language.Italian);
            RegisterAbility("Mental Gemnastics", "Gemmastica mentale");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw cards from your deck based on how many Gems are on the board.", "Quando si gioca una carta che possiede questo sigillo, pesca dal tuo mazzo tante carte quante sono le gemme sul tavolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loot", "Saccheggiatore", Language.Italian);
            RegisterAbility("Loot", "Saccheggiatore");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals direct damage, draw cards from your deck based on how much damage was dealt.", "Quando una carta che possiede questo sigillo infligge danni diretti, pesca dal tuo mazzo tante carte quanti sono i danni inflitti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life Steal", "Furto vitale", Language.Italian);
            RegisterAbility("Life Steal", "Furto vitale");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals direct damage, the amount dealt will be healed to the owner of this card.", "Quando una carta che possiede questo sigillo infligge danni diretti, il suo proprietario recupera salute pari ai danni inflitti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knockback Hit", "Colpo respingente", Language.Italian);
            RegisterAbility("Knockback Hit", "Colpo respingente");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil hits an opposing card, the opposing card will be kicked in the direction inscrybed in the sigil.", "Quando una carta che possiede questo sigillo colpisce una carta avversaria, la carta colpita viene respinta nella direzione indicata dal sigillo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Impaled", "Impalamento", Language.Italian);
            RegisterAbility("Impaled", "Impalamento");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Spear in its placed. A spear is defined as Sharp, 0 power, 3 health.", "Quando una carta che possiede questo sigillo muore, crea una Lancia al suo posto. Una Lancia possiede Aculei taglienti, 0 di potenza e 3 di salute.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magnus Mox", "Mox magno", Language.Italian);
            RegisterAbility("Magnus Mox", "Mox magno");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, it provides an orange gem, a blue gem and a green gem to its owner.", "Finché una carta che possiede questo sigillo è sul tavolo, fornisce al suo proprietario una gemma arancione, una blu e una verde.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resurrection", "Resurrezione", Language.Italian);
            RegisterAbility("Resurrection", "Resurrezione");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-gem card perishes, the dead card will be brought back to life, but this card loses 3 health.", "Quando muore una carta non gemma, la carta morta torna in vita, ma la carta che possiede questo sigillo perde 3 di salute.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rerolls", "Rilanci dei dadi", Language.Italian);
            RegisterAbility("Rerolls", "Rilanci dei dadi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigils' base power will be increased by a random value between 0 and 3.", "Alla fine di ogni turno, la potenza base di una carta che possiede questo sigillo viene impostata a un valore casuale compreso tra 0 e 3.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Steel Trap", "Trappola d'acciaio", Language.Italian);
            RegisterAbility("Steel Trap", "Trappola d'acciaio");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the opposing card also perishes.", "Quando una carta che possiede questo sigillo muore, muore anche la carta di fronte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Shield", "Scudo di gemme", Language.Italian);
            RegisterAbility("Gem Shield", "Scudo di gemme");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all gems on the board gain a shield.", "Quando si gioca una carta che possiede questo sigillo, tutte le gemme sul tavolo ottengono uno scudo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plating Work", "Lavoro di placcatura", Language.Italian);
            RegisterAbility("Plating Work", "Lavoro di placcatura");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, all gems on your side of the board gain the Sharp Quills sigil, and 2 health.", "Finché una carta che possiede questo sigillo è sul tavolo, tutte le gemme sul tuo lato del tavolo ottengono il sigillo Aculei taglienti e 2 di salute.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animator", "Burattinaio", Language.Italian);
            RegisterAbility("Animator", "Burattinaio");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, all non-mox cards with 0 power gain 2 power", "Finché una carta che possiede questo sigillo è sul tavolo, tutte le carte non Mox con 0 di potenza ottengono 2 di potenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Absorber", "Assorbitore di gemme", Language.Italian);
            RegisterAbility("Gem Absorber", "Assorbitore di gemme");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all gems on your side of the board will perish. For each gem absorbed, gain 1 power and 2 health.", "Quando si gioca una carta che possiede questo sigillo, tutte le gemme sul tuo lato del tavolo muoiono. Per ogni gemma assorbita, questa carta ottiene 1 di potenza e 2 di salute.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Submerge", "Immersione", Language.Italian);
            RegisterAbility("Submerge", "Immersione");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, a card bearing this sigil will submerge. Upon resubmerging, this card will become a random Tentacle Card.", "Alla fine del turno, una carta che possiede questo sigillo si immerge. Quando riemerge, diventa una carta Tentacolo casuale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Familiar", "Famiglio", Language.Italian);
            RegisterAbility("Familiar", "Famiglio");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will perish if there are no non-gem cards on the board.", "Una carta che possiede questo sigillo muore se non ci sono carte non gemma sul tavolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fading", "Dissolvenza", Language.Italian);
            RegisterAbility("Fading", "Dissolvenza");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will perish at the end of the turn.", "Una carta che possiede questo sigillo muore alla fine del turno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Morph", "Metamorfosi", Language.Italian);
            RegisterAbility("Morph", "Metamorfosi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will mimic the card opposing it. If there is no card opposing it, this card will perish.", "Quando si gioca una carta che possiede questo sigillo, imita la carta di fronte. Se non c'è una carta di fronte, muore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiplication", "Moltiplicazione matriciale", Language.Italian);
            RegisterAbility("Multiplication", "Moltiplicazione matriciale");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw another of this card, but with a different gem cost.", "Quando si gioca una carta che possiede questo sigillo, pesca un'altra copia della stessa carta, ma con un costo in gemme diverso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Cycle", "Ciclo dei Mox", Language.Italian);
            RegisterAbility("Mox Cycle", "Ciclo dei Mox");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, all the mox on the board will cycle into different gems.", "Alla fine di ogni turno, tutti i Mox sul tavolo passano ciclicamente ad altri tipi di gemma.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Strafe", "Scia di Mox", Language.Italian);
            RegisterAbility("Mox Strafe", "Scia di Mox");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, this card will move to the direction inscrybed on the sigil, and leave behind a mox.", "Alla fine del turno, questa carta si muove nella direzione indicata dal sigillo e lascia un Mox al suo posto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purist", "Purismo", Language.Italian);
            RegisterAbility("Purist", "Purismo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any card directly opposing this one will have all it's sigils removed.", "Qualsiasi carta direttamente di fronte a questa perde tutti i suoi sigilli.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brewery", "Birrificio", Language.Italian);
            RegisterAbility("Brewery", "Birrificio");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, you automatically draw a mox card from your side deck.", "Alla fine di ogni turno, peschi automaticamente una carta Mox dal tuo mazzo secondario.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignite", "Appiccare", Language.Italian);
            RegisterAbility("Ignite", "Appiccare");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, every empty opposing slot will be filled with flames. A flame is defined as a 0/1, Annoying.", "Quando si gioca una carta che possiede questo sigillo, ogni spazio avversario vuoto viene riempito di fiamme magiche. Una Fiamma magica è una carta 0/1 con Irritante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Projection", "Proiezione stellare", Language.Italian);
            RegisterAbility("Projection", "Proiezione stellare");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is stuck, it will move and leave behind an astral projection of itself.", "Quando una carta che possiede questo sigillo viene colpita, si sposta e lascia una proiezione astrale di sé al suo posto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell Book", "Libro degli incantesimi", Language.Italian);
            RegisterAbility("Spell Book", "Libro degli incantesimi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random spell card.", "Quando si gioca una carta che possiede questo sigillo, pesca una carta incantesimo casuale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scholar", "Studioso di incantesimi", Language.Italian);
            RegisterAbility("Scholar", "Studioso di incantesimi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random one of Bleene's Books.", "Quando si gioca una carta che possiede questo sigillo, pesca un libro casuale di Blerde.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Midas' Touch", "Tocco di Mida", Language.Italian);
            RegisterAbility("Midas' Touch", "Tocco di Mida");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil attacks another card, the attacked card will lose all of it's attack and turn to gold.", "Quando una carta che possiede questo sigillo attacca un'altra carta, la carta attaccata perde tutta la sua potenza e si trasforma in oro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Made of Gold", "Corpo d'oro", Language.Italian);
            RegisterAbility("Made of Gold", "Corpo d'oro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the killer will gain 2 crystals.", "Quando una carta che possiede questo sigillo muore, chi la uccide ottiene 2 cristalli.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Runes", "Rune d'evocazione", Language.Italian);
            RegisterAbility("Summon Runes", "Rune d'evocazione");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will summon two runes beside it. A rune is defined as 0 power, 1 health, Detonator.", "Quando si gioca una carta che possiede questo sigillo, evoca due rune accanto a sé. Una Runa possiede 0 di potenza, 1 di salute e Detonatore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Health", "Incantesimo di salute", Language.Italian);
            RegisterAbility("Spell of Health", "Incantesimo di salute");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board gain +2 health.", "Quando si gioca un incantesimo che possiede questo sigillo, tutte le carte sul tuo lato del tavolo ottengono +2 di salute.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Attack", "Incantesimo d'attacco", Language.Italian);
            RegisterAbility("Spell of Attack", "Incantesimo d'attacco");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board gain +1 attack.", "Quando si gioca un incantesimo che possiede questo sigillo, tutte le carte sul tuo lato del tavolo ottengono +1 di potenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Spell", "Incantesimo del gelo", Language.Italian);
            RegisterAbility("Frost Spell", "Incantesimo del gelo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards belonging to the opponent will have their attack set to 0, but given +2 health.", "Quando si gioca un incantesimo che possiede questo sigillo, la potenza di tutte le carte dell'avversario viene impostata a 0, ma ottengono +2 di salute.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Wind", "Incantesimo di vento", Language.Italian);
            RegisterAbility("Spell of Wind", "Incantesimo di vento");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board will become airborne.", "Quando si gioca un incantesimo che possiede questo sigillo, tutte le carte sul tuo lato del tavolo ottengono Volante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruckus", "Scompiglio orario", Language.Italian);
            RegisterAbility("Ruckus", "Scompiglio orario");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all cards on the board will move clockwise.", "Quando si gioca una carta che possiede questo sigillo, tutte le carte sul tavolo si muovono in senso orario.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Water", "Incantesimo d'acqua", Language.Italian);
            RegisterAbility("Spell of Water", "Incantesimo d'acqua");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, every card on the board will have their sigils erased.", "Quando si gioca un incantesimo che possiede questo sigillo, vengono cancellati i sigilli di ogni carta sul tavolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Flame", "Incantesimo di fiamma", Language.Italian);
            RegisterAbility("Spell of Flame", "Incantesimo di fiamma");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a side of the board, every card on that side will lose 2 health (without perishing) and have their attack increased by 1.", "Scegli un lato del tavolo. Ogni carta su quel lato perde 2 di salute senza morire e ottiene 1 di potenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Set Ablaze", "Dare fuoco", Language.Italian);
            RegisterAbility("Set Ablaze", "Dare fuoco");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every card on the opposite side will lose 2 health (without perishing) and have their attack increased by 1.", "Ogni carta sul lato opposto perde 2 di salute senza morire e ottiene 1 di potenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Time Spell", "Incantesimo monouso", Language.Italian);
            RegisterAbility("One Time Spell", "Incantesimo monouso");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the turn ends, a spell bearing this sigil will perish and be removed from your deck.", "Alla fine del turno, un incantesimo che possiede questo sigillo muore e viene rimosso dal tuo mazzo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vase of Greed", "Vaso dell'avidità", Language.Italian);
            RegisterAbility("Vase of Greed", "Vaso dell'avidità");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, discard your current hand and draw 4 new cards.", "Quando si gioca un incantesimo che possiede questo sigillo, scarta la tua mano attuale, poi pesca 4 nuove carte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gnomification", "Gnomificazione", Language.Italian);
            RegisterAbility("Gnomification", "Gnomificazione");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a slot to summon a Gnome card in.", "Scegli uno spazio in cui evocare una carta Gnomo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed", "Maledetto", Language.Italian);
            RegisterAbility("Cursed", "Maledetto");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, it will immediately perish.", "Quando si gioca un incantesimo che possiede questo sigillo, muore immediatamente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inspiration", "Ispirazione", Language.Italian);
            RegisterAbility("Inspiration", "Ispirazione");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to give Airborne + Looter for 1 turn.", "Scegli una carta a cui conferire Volante + Saccheggiatore per 1 turno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calculus", "Calcolo infinitesimale", Language.Italian);
            RegisterAbility("Calculus", "Calcolo infinitesimale");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to swap stats.", "Scegli una carta di cui scambiare le statistiche.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rage", "Furia", Language.Italian);
            RegisterAbility("Rage", "Furia");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to kill. The opponent of the card will recieve damage equal to the amount of health the card had.", "Scegli una carta da uccidere. L'avversario di quella carta subisce danni pari alla salute che aveva la carta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fireball", "Palla di fuoco", Language.Italian);
            RegisterAbility("Fireball", "Palla di fuoco");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to take 2 damage.", "Scegli una carta che subisca 2 danni.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cold to the Touch", "Tocco gelido", Language.Italian);
            RegisterAbility("Cold to the Touch", "Tocco gelido");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigils attack another card, that card will lose 1 attack.", "Quando una carta che possiede questo sigillo attacca un'altra carta, quest'ultima perde 1 di potenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frozen", "Congelato", Language.Italian);
            RegisterAbility("Frozen", "Congelato");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, this card will lose its frozen health. When all frozen health is depleted, or this card is struck, it will defrost.", "Alla fine di ogni turno, questa carta perde la sua salute congelata. Quando tutta la salute congelata si esaurisce, o se la carta viene colpita, si scongela.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strong Pull", "Trazione potente", Language.Italian);
            RegisterAbility("Strong Pull", "Trazione potente");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every opposing card will be inclined to hit this card instead of any other.", "Ogni carta avversaria tenderà a colpire questa carta invece di qualsiasi altra.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Displacement", "Spostamento", Language.Italian);
            RegisterAbility("Displacement", "Spostamento");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is drawn, another of this card will be added randomly into your deck", "Quando si pesca una carta che possiede questo sigillo, un'altra copia di questa carta viene aggiunta in una posizione casuale del tuo mazzo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Reckoning", "Resa dei conti delle gemme", Language.Italian);
            RegisterAbility("Gem Reckoning", "Resa dei conti delle gemme");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, if the owner of this card does not control any gems, the leftmost card in your hand is discarded.", "Alla fine di ogni turno, se il proprietario di questa carta non controlla gemme, la carta più a sinistra nella tua mano viene scartata.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Power", "Potenza dei Mox", Language.Italian);
            RegisterAbility("Mox Power", "Potenza dei Mox");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Mox Cards that the owner has on their side of the table.", "Il valore di questo sigillo equivale al numero di carte Mox che il proprietario ha sul proprio lato del tavolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Health", "Salute dei Mox", Language.Italian);
            RegisterAbility("Mox Health", "Salute dei Mox");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Mox Cards that the owner has on their side of the table.", "Il valore di questo sigillo equivale al numero di carte Mox che il proprietario ha sul proprio lato del tavolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candle Proximity", "Vicinanza della candela", Language.Italian);
            RegisterAbility("Candle Proximity", "Vicinanza della candela");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to how close this card is to the Candle on the table.", "Il valore di questo sigillo dipende da quanto questa carta è vicina alla candela sul tavolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Murder Power", "Potenza omicida", Language.Italian);
            RegisterAbility("Murder Power", "Potenza omicida");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal the total amount of power on the opponents board.", "Il valore di questo sigillo equivale alla potenza totale sul lato avversario del tavolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to half the total amount of power on your board.", "Il valore di questo sigillo equivale alla metà della potenza totale sul tuo lato del tavolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell Power", "Potenza degli incantesimi", Language.Italian);
            RegisterAbility("Spell Power", "Potenza degli incantesimi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to total amount of spells played during this current dungeon.", "Il valore di questo sigillo equivale al numero totale di incantesimi giocati nel sotterraneo attuale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to total amount of spells played during the battle.", "Il valore di questo sigillo equivale al numero totale di incantesimi giocati durante la battaglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Counterbattery Power", "Potenza di controbatteria", Language.Italian);
            RegisterAbility("Counterbattery Power", "Potenza di controbatteria");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the amount of damage taken by you this battle, divided by two.", "Il valore di questo sigillo equivale ai danni che hai subito in questa battaglia, divisi per due.", Language.Italian);
            foreach (Ability ability in Enum.GetValues(typeof(Ability)))
            {
                var info = AbilitiesUtil.GetInfo(ability);
                if (info == null || info.rulebookName == null || Abilities.ContainsKey(info.rulebookName))
                {
                    Debug.LogWarning($"Ability {ability} 没有有效的info，已跳过。");
                    continue;
                }
                if (info.rulebookName == null || Abilities.ContainsKey(info.rulebookName))
                {
                    Debug.LogWarning($"Ability {ability} 没有有效的rulebookName，或本身已注册，已跳过。");
                    continue;
                }
                RegisterAbility(info.rulebookName, ItalianLanguagePack.Localize(info.rulebookName));
            }

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox", "Mox", Language.Italian);
            RegisterCard("Mox", "Mox", "its a me moxio", "Sono io, Moxio!");
            RegisterCard("Ruby Mox", "Mox rubino", "its a me moxio", "Sono io, Moxio!");
            RegisterCard("Emerald Mox", "Mox smeraldo", "its a me moxio", "Sono io, Moxio!");
            RegisterCard("Sapphire Mox", "Mox zaffiro", "its a me moxio", "Sono io, Moxio!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "its a me moxio", "Sono io, Moxio!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spear", "Lancia", Language.Italian);
            RegisterCard("Spear", "Lancia", "ayo", "ehi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ayo", "ehi", Language.Italian);
            RegisterCard("Mage Pupil", "Apprendista strega", "Though weak, it can always be useful in the right situation.", "Pur essendo debole, può sempre essere utile nella situazione giusta.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though weak, it can always be useful in the right situation.", "Pur essendo debole, può sempre essere utile nella situazione giusta.", Language.Italian);
            RegisterCard("Junior Sage", "Giovane saggio", "Although simple, it can prove itself to be useful.", "Pur essendo semplice, può dimostrarsi utile.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Although simple, it can prove itself to be useful.", "Pur essendo semplice, può dimostrarsi utile.", Language.Italian);
