            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just look at what you've done..", "Guarda un po' cos'hai fatto...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chained Legs", "Gambe incatenate", Language.Italian);
            RegisterCard("Chained Legs", "Gambe incatenate", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sealed Body", "Corpo sigillato", Language.Italian);
            RegisterCard("Sealed Body", "Corpo sigillato", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bound Arms", "Braccia legate", Language.Italian);
            RegisterCard("Bound Arms", "Braccia legate", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Imprisoned Tyrant", "Tiranno imprigionato", Language.Italian);
            RegisterCard("Imprisoned Tyrant", "Tiranno imprigionato", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiplication mage", "Mago delle matrici", Language.Italian);
            RegisterCard("Multiplication mage", "Mago delle matrici", "This cycle can go on forever..", "Questo ciclo può continuare per sempre...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cycle can go on forever..", "Questo ciclo può continuare per sempre...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Invisible mage", "Mago invisibile", Language.Italian);
            RegisterCard("Invisible mage", "Mago invisibile", "It drank the wrong potion and ended up invisible. How clumsy.", "Ha bevuto la pozione sbagliata ed è diventato invisibile. Che goffaggine.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It drank the wrong potion and ended up invisible. How clumsy.", "Ha bevuto la pozione sbagliata ed è diventato invisibile. Che goffaggine.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Sage", "Saggio di cristallo", Language.Italian);
            RegisterCard("Crystal Sage", "Saggio di cristallo", "A young scholar, profoundly studying mana crystals.", "Un giovane studioso che si dedica a fondo ai cristalli di mana.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A young scholar, profoundly studying mana crystals.", "Un giovane studioso che si dedica a fondo ai cristalli di mana.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Guardian", "Guardiano delle gemme", Language.Italian);
            RegisterCard("Gem Guardian", "Guardiano delle gemme", "The inverse of the Gem Detonator, this one seeks to protect all mox.", "L'opposto del Detonatore di gemme: questo cerca di proteggere tutti i Mox.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The inverse of the Gem Detonator, this one seeks to protect all mox.", "L'opposto del Detonatore di gemme: questo cerca di proteggere tutti i Mox.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gembound Ripper", "Squarta-Gemme", Language.Italian);
            RegisterCard("Gembound Ripper", "Squarta-Gemme", "It is unstable, but such is the price for unending power.", "È instabile, ma questo è il prezzo di un potere senza fine.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is unstable, but such is the price for unending power.", "È instabile, ma questo è il prezzo di un potere senza fine.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Absorber", "Divoratore di gemme", Language.Italian);
            RegisterCard("Gem Absorber", "Divoratore di gemme", "It seeks out to consume all mana within Mox to grow stronger.", "Cerca di consumare tutto il mana nei Mox per diventare più forte.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seeks out to consume all mana within Mox to grow stronger.", "Cerca di consumare tutto il mana nei Mox per diventare più forte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelemagus", "Schelemago", Language.Italian);
            RegisterCard("Skelemagus", "Schelemago", "Great power for a few, fleeting moments..", "Un grande potere per pochi, fugaci istanti...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great power for a few, fleeting moments..", "Un grande potere per pochi, fugaci istanti...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelesage", "Saggio scheletrico", Language.Italian);
            RegisterCard("Skelesage", "Saggio scheletrico", "One of my own Junior Sages, lost and revived.", "Uno dei miei Giovani saggi, perduto e riportato in vita.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of my own Junior Sages, lost and revived.", "Uno dei miei Giovani saggi, perduto e riportato in vita.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Erratic Scholar", "Studioso irrequieto", Language.Italian);
            RegisterCard("Erratic Scholar", "Studioso irrequieto", "A panicked scholar.. Always running from its problems..", "Uno studioso in preda al panico... Fugge sempre dai suoi problemi...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A panicked scholar.. Always running from its problems..", "Uno studioso in preda al panico... Fugge sempre dai suoi problemi...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Mage", "Mago dei Mox", Language.Italian);
            RegisterCard("Mox Mage", "Mago dei Mox", "A Mox disguised as a mage.. It's not going to fool anyone.", "Un Mox travestito da mago... Non ingannerà nessuno.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Mox disguised as a mage.. It's not going to fool anyone.", "Un Mox travestito da mago... Non ingannerà nessuno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aurumtact", "Trasmutatore d'oro", Language.Italian);
            RegisterCard("Aurumtact", "Trasmutatore d'oro", "An elder scholar, cursed for his greed, entombing anything he touches in pure gold.", "Un anziano studioso, maledetto per la sua avidità, che imprigiona nell'oro puro tutto ciò che tocca.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An elder scholar, cursed for his greed, entombing anything he touches in pure gold.", "Un anziano studioso, maledetto per la sua avidità, che imprigiona nell'oro puro tutto ciò che tocca.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chained Mox", "Mox incatenato", Language.Italian);
            RegisterCard("Chained Mox", "Mox incatenato", "A collection of 3 moxen, tangled together, combining their mana energy.", "Un insieme di 3 Mox intrecciati che combinano la loro energia di mana.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of 3 moxen, tangled together, combining their mana energy.", "Un insieme di 3 Mox intrecciati che combinano la loro energia di mana.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maux", "Maux", Language.Italian);
            RegisterCard("Maux", "Maux", "In all my years, I have NEVER seen an imitation cruder than this.", "In tutti i miei anni, non ho MAI visto un'imitazione più rozza di questa.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In all my years, I have NEVER seen an imitation cruder than this.", "In tutti i miei anni, non ho MAI visto un'imitazione più rozza di questa.", Language.Italian);
            RegisterCard("Stim Mage", "Mago stimolatore", "It strives to grow stronger, disregarding its own wellbeing..", "Cerca di diventare più forte, incurante del proprio benessere...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It strives to grow stronger, disregarding its own wellbeing..", "Cerca di diventare più forte, incurante del proprio benessere...", Language.Italian);
            RegisterCard("Gourmage", "Strega del midollo", "A gluttonous mage who devours the corpses of your fallen to grow stroner.. Disgusting.", "Una maga ingorda che divora i cadaveri dei tuoi caduti per diventare più forte... Disgustoso.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A gluttonous mage who devours the corpses of your fallen to grow stroner.. Disgusting.", "Una maga ingorda che divora i cadaveri dei tuoi caduti per diventare più forte... Disgustoso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dunce", "Mago somaro", Language.Italian);
            RegisterCard("Dunce", "Mago somaro", "This one can never seem to hit its target..", "Questo non sembra mai riuscire a colpire il bersaglio...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one can never seem to hit its target..", "Questo non sembra mai riuscire a colpire il bersaglio...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grootslang", "Grootslang", Language.Italian);
            RegisterCard("Grootslang", "Grootslang", "The mere graze of its fangs is enough to kill any creature. No matter the size.", "Basta che le sue zanne sfiorino una creatura per ucciderla, qualunque sia la sua taglia.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mere graze of its fangs is enough to kill any creature. No matter the size.", "Basta che le sue zanne sfiorino una creatura per ucciderla, qualunque sia la sua taglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bookworm", "Topo di biblioteca", Language.Italian);
            RegisterCard("Bookworm", "Topo di biblioteca", "A rare kind of insect that absorbs knowledge out of books.", "Un raro tipo di insetto che assorbe conoscenza dai libri.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A rare kind of insect that absorbs knowledge out of books.", "Un raro tipo di insetto che assorbe conoscenza dai libri.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alchemist", "Alchimista", Language.Italian);
            RegisterCard("Alchemist", "Alchimista", "A supporting one. It brews potions to empower your cards.", "Un'unità di supporto. Prepara pozioni per potenziare le tue carte.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A supporting one. It brews potions to empower your cards.", "Un'unità di supporto. Prepara pozioni per potenziare le tue carte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chime Mage", "Mago delle campane", Language.Italian);
            RegisterCard("Chime Mage", "Mago delle campane", "Its chime can prove to be quite annoying..", "Il suo scampanellio può essere piuttosto irritante...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its chime can prove to be quite annoying..", "Il suo scampanellio può essere piuttosto irritante...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revivor", "Risorto", Language.Italian);
            RegisterCard("Revivor", "Risorto", "It brings a mage back from the dead, at the cost of its own health.", "Riporta in vita un mago al costo della propria salute.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It brings a mage back from the dead, at the cost of its own health.", "Riporta in vita un mago al costo della propria salute.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rune Mage", "Mago delle rune", Language.Italian);
            RegisterCard("Rune Mage", "Mago delle rune", "It conjures explosive runes alongside it when summoned. Not a good idea, I must say.", "Quando viene evocato, crea rune esplosive accanto a sé. Non una buona idea, devo dire.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It conjures explosive runes alongside it when summoned. Not a good idea, I must say.", "Quando viene evocato, crea rune esplosive accanto a sé. Non una buona idea, devo dire.", Language.Italian);
            RegisterCard("--~~--~~--", "--~~--~~--", "So it arrives.", "Dunque arriva.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So it arrives.", "Dunque arriva.", Language.Italian);
            RegisterCard("~-~-~-~-~-~", "~-~-~-~-~-~", "I foresaw its arrival.", "Avevo previsto il suo arrivo.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I foresaw its arrival.", "Avevo previsto il suo arrivo.", Language.Italian);
            RegisterCard("~~--~~--~~", "~~--~~--~~", "At last, it is here.", "Finalmente è qui.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At last, it is here.", "Finalmente è qui.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sniper Sage", "Saggio cecchino", Language.Italian);
            RegisterCard("Sniper Sage", "Saggio cecchino", "A mage whose training allows it to cast spells from afar.", "Un mago il cui addestramento gli permette di lanciare incantesimi da lontano.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage whose training allows it to cast spells from afar.", "Un mago il cui addestramento gli permette di lanciare incantesimi da lontano.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rune", "Runa", Language.Italian);
            RegisterCard("Rune", "Runa", "This is the last call, for alcohol.", "È l'ultima chiamata per gli alcolici.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "È l'ultima chiamata per gli alcolici.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flame", "Fiamma magica", Language.Italian);
            RegisterCard("Flame", "Fiamma magica", "This is the last call, for alcohol.", "È l'ultima chiamata per gli alcolici.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "È l'ultima chiamata per gli alcolici.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rabbit", "Coniglio", Language.Italian);
            RegisterCard("Rabbit", "Coniglio", "This is the last call, for alcohol.", "È l'ultima chiamata per gli alcolici.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "È l'ultima chiamata per gli alcolici.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for booze.", "Ultima chiamata per la sbronza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for ale.", "Ultima chiamata per la birra.", Language.Italian);
            RegisterCard("Master Goranj", "Maestro Verdancio", "The towering Master Goranj. Not only a caster of fearsome Magicks, but possessed of a sturdy poise as well.", "L'imponente Maestro Verdancio. Non solo lancia magie temibili, ma possiede anche una postura salda.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The towering Master Goranj. Not only a caster of fearsome Magicks, but possessed of a sturdy poise as well.", "L'imponente Maestro Verdancio. Non solo lancia magie temibili, ma possiede anche una postura salda.", Language.Italian);
            RegisterCard("Master Bleene", "Maestro Blerde", "The selfless Master Bleene. It shall help you in times of dire need… At the cost of its own ability to defend itself. Admirable.", "L'altruista Maestro Blerde. Ti aiuterà nei momenti di estremo bisogno... Al costo della propria capacità di difendersi. Ammirevole.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The selfless Master Bleene. It shall help you in times of dire need… At the cost of its own ability to defend itself. Admirable.", "L'altruista Maestro Blerde. Ti aiuterà nei momenti di estremo bisogno... Al costo della propria capacità di difendersi. Ammirevole.", Language.Italian);
            RegisterCard("Master Orlu", "Maestro Aranblu", "The great Master Orlu, soaring on pale wings, it attacks from above and draws in cards from below..", "Il grande Maestro Aranblu vola su ali pallide, attacca dall'alto e attira carte dal basso...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The great Master Orlu, soaring on pale wings, it attacks from above and draws in cards from below..", "Il grande Maestro Aranblu vola su ali pallide, attacca dall'alto e attira carte dal basso...", Language.Italian);
            RegisterCard("Master Magnus", "Maestro supremo", "my name is.. Shake-Zula! The Mic rula! The Old Schoola! You want a trip? I'll bring it to ya...", "Mi chiamo... Shake-Zula! Il re del microfono! Quello della vecchia scuola! Vuoi sballare? Ci penso io...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "my name is.. Shake-Zula! The Mic rula! The Old Schoola! You want a trip? I'll bring it to ya...", "Mi chiamo... Shake-Zula! Il re del microfono! Quello della vecchia scuola! Vuoi sballare? Ci penso io...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Magnus", "Maestro supremo", Language.Italian);
            RegisterCard("Master Magnus", "Maestro supremo", "Frylock yeah Im on top rock you like a cop, meatwad you're up next with your knock knock!", "Frylock, sì, sono al top, ti scuoto come uno sbirro. Meatwad, ora tocca a te con il tuo toc toc!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frylock yeah Im on top rock you like a cop, meatwad you're up next with your knock knock!", "Frylock, sì, sono al top, ti scuoto come uno sbirro. Meatwad, ora tocca a te con il tuo toc toc!", Language.Italian);
            RegisterCard("Master Magnus", "Maestro supremo", "Meatwad get the money, see. Meatwad get the honeys, G. ", "Meatwad prende i soldi, capisci. Meatwad conquista le ragazze, fratello. ");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meatwad get the money, see. Meatwad get the honeys, G. ", "Meatwad prende i soldi, capisci. Meatwad conquista le ragazze, fratello. ", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phoenix", "Fenice", Language.Italian);
            RegisterCard("Phoenix", "Fenice", "Majestic avian, rumoured to have been an accomplice to Master Orlu...", "Un uccello maestoso, che si dice sia stato complice del Maestro Aranblu...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Majestic avian, rumoured to have been an accomplice to Master Orlu...", "Un uccello maestoso, che si dice sia stato complice del Maestro Aranblu...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleenehound", "Segugio di Blerde", Language.Italian);
            RegisterCard("Bleenehound", "Segugio di Blerde", "Loyalist canine, rumoured to have been Master Bleene's loyal companion.", "Un canide leale, che si dice sia stato il fedele compagno del Maestro Blerde.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loyalist canine, rumoured to have been Master Bleene's loyal companion.", "Un canide leale, che si dice sia stato il fedele compagno del Maestro Blerde.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alchemy 101", "Introduzione all'alchimia", Language.Italian);
            RegisterCard("Alchemy 101", "Introduzione all'alchimia", "[c:g2]Alchemy 101[c:]\n[c:g3]I[c:] [c:g1]never[c:] [c:g3]was[c:] [c:g1]that[c:] [c:g3]great[c:] [c:g1]at[c:] [c:g3]alchemy..[c:]", "[c:g2]Introduzione all'alchimia[c:]\n[c:g3]Io[c:] [c:g1]non[c:] [c:g3]sono[c:] [c:g1]mai[c:] [c:g3]stato bravo[c:] [c:g1]in[c:] [c:g3]alchimia...[c:]");
