            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of anger will ignite flames in the opposite battlefield.", "La strega che domina l'ira appicca le fiamme sul campo avversario.", Language.Italian);
