            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch who mastered the power of arrogance appeared with the demon.", "La strega che padroneggia il potere della superbia appare accompagnata da un demone.", Language.Italian);
