            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lust Witch", "Strega lussuriosa", Language.Italian);
            MagnificusMod.RegisterCard("Lust Witch", "Strega lussuriosa", "The witch in charge of lust, don't look into her eyes.", "La strega che domina la lussuria… Non guardarla negli occhi.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of lust, don't look into her eyes.", "La strega che domina la lussuria… Non guardarla negli occhi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nine Color Deer", "Cervo dai nove colori", Language.Italian);
            MagnificusMod.RegisterCard("Nine Color Deer", "Cervo dai nove colori", "The colorful nine color deer has precious value.", "Il variopinto cervo dai nove colori ha un valore inestimabile.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The colorful nine color deer has precious value.", "Il variopinto cervo dai nove colori ha un valore inestimabile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stinky MagiChiking", "Pollo magico puzzolente", Language.Italian);
            MagnificusMod.RegisterCard("Stinky MagiChiking", "Pollo magico puzzolente", "Hatched by magic eggs.", "Nato da un uovo magico.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hatched by magic eggs.", "Nato da un uovo magico.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb Maniac", "Maniaco delle bombe", Language.Italian);
            MagnificusMod.RegisterCard("Bomb Maniac", "Maniaco delle bombe", "Even if it detonates itself, it never surrenders to others.", "Anche a costo di farsi esplodere, non si arrenderà mai.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even if it detonates itself, it never surrenders to others.", "Anche a costo di farsi esplodere, non si arrenderà mai.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Earl Bunny", "Conte Coniglio", Language.Italian);
            MagnificusMod.RegisterCard("Earl Bunny", "Conte Coniglio", "The versatile Earl Bunny, not everyone can comprehend this art.", "Il versatile Conte Coniglio… Non tutti sanno comprendere quest'arte.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The versatile Earl Bunny, not everyone can comprehend this art.", "Il versatile Conte Coniglio… Non tutti sanno comprendere quest'arte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chinese Loong", "Drago cinese", Language.Italian);
            MagnificusMod.RegisterCard("Chinese Loong", "Drago cinese", "Diving into the abyss will bring peace to the four seas, flying will protect all things and bring peace, and the dragon's journey of thousands of miles is a sign of good fortune.", "Quando il drago si immerge negli abissi, porta pace ai quattro mari; quando si alza in volo, protegge ogni cosa. Il suo viaggio di migliaia di miglia è ovunque presagio di buona sorte.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diving into the abyss will bring peace to the four seas, flying will protect all things and bring peace, and the dragon's journey of thousands of miles is a sign of good fortune.", "Quando il drago si immerge negli abissi, porta pace ai quattro mari; quando si alza in volo, protegge ogni cosa. Il suo viaggio di migliaia di miglia è ovunque presagio di buona sorte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheese Wizard", "Mago del formaggio", Language.Italian);
            MagnificusMod.RegisterCard("Cheese Wizard", "Mago del formaggio", "A humorous wizard who is proficient in cooking, his cheese has magical power.", "Uno stregone spiritoso ed esperto di cucina, il cui formaggio possiede poteri magici.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A humorous wizard who is proficient in cooking, his cheese has magical power.", "Uno stregone spiritoso ed esperto di cucina, il cui formaggio possiede poteri magici.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Golem", "Golem del gelo", Language.Italian);
            MagnificusMod.RegisterCard("Frost Golem", "Golem del gelo", "Once on the field, there is a strong sense of oppression.", "Non appena entra in campo, si avverte la sua presenza opprimente.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once on the field, there is a strong sense of oppression.", "Non appena entra in campo, si avverte la sua presenza opprimente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baseball Mage", "Mago del baseball", Language.Italian);
            MagnificusMod.RegisterCard("Baseball Mage", "Mago del baseball", "His soul is bound under sportswear and can never be liberated.", "La sua anima è imprigionata negli abiti sportivi e non potrà mai liberarsi.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His soul is bound under sportswear and can never be liberated.", "La sua anima è imprigionata negli abiti sportivi e non potrà mai liberarsi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raid Mage", "Mago d'assalto", Language.Italian);
            MagnificusMod.RegisterCard("Raid Mage", "Mago d'assalto", "You will understand how terrifying it is for a robber to master magic.", "Capirai quanto possa essere terrificante un predone che padroneggia la magia.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will understand how terrifying it is for a robber to master magic.", "Capirai quanto possa essere terrificante un predone che padroneggia la magia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jade Turtle", "Tartaruga di giada", Language.Italian);
            MagnificusMod.RegisterCard("Jade Turtle", "Tartaruga di giada", "A turtle draped in emeralds from head to toe—I can't help but marvel that such a painting even exists.", "Una tartaruga ricoperta di smeraldi dalla testa ai piedi… Non posso che meravigliarmi che esista un dipinto simile.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A turtle draped in emeralds from head to toe—I can't help but marvel that such a painting even exists.", "Una tartaruga ricoperta di smeraldi dalla testa ai piedi… Non posso che meravigliarmi che esista un dipinto simile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Cheese", "Formaggio magico", Language.Italian);
            MagnificusMod.RegisterCard("Magic Cheese", "Formaggio magico", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scarlet Cuckoo", "Cuculo scarlatto", Language.Italian);
            MagnificusMod.RegisterCard("Scarlet Cuckoo", "Cuculo scarlatto", "The success or failure of the angry magic bird often depends on its face.", "Con questo uccello magico arrabbiato, il tuo successo o fallimento dipende spesso dal suo umore.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The success or failure of the angry magic bird often depends on its face.", "Con questo uccello magico arrabbiato, il tuo successo o fallimento dipende spesso dal suo umore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spear Apprentice", "Apprendista lanciere", Language.Italian);
            MagnificusMod.RegisterCard("Spear Apprentice", "Apprendista lanciere", "Apprentices of Spear Mages, wise people will leave behind their backs to prepare.", "Gli apprendisti dei maghi lancieri… I più saggi tengono sempre pronto un piano di riserva.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apprentices of Spear Mages, wise people will leave behind their backs to prepare.", "Gli apprendisti dei maghi lancieri… I più saggi tengono sempre pronto un piano di riserva.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Eye of Darkness", "L'Occhio dell'oscurità", Language.Italian);
            MagnificusMod.RegisterCard("The Eye of Darkness", "L'Occhio dell'oscurità", "This precious pearl was once the devil's eye.", "Questa preziosa perla un tempo era l'occhio del diavolo.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This precious pearl was once the devil's eye.", "Questa preziosa perla un tempo era l'occhio del diavolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forest Spell", "Incantesimo della foresta", Language.Italian);
            MagnificusMod.RegisterCard("Forest Spell", "Incantesimo della foresta", "The forest spell obtained from Leshy can provide the most primitive defense.", "L'incantesimo della foresta ottenuto da Leshy offre la forma più primitiva di difesa.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The forest spell obtained from Leshy can provide the most primitive defense.", "L'incantesimo della foresta ottenuto da Leshy offre la forma più primitiva di difesa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MoxShield", "Scudo Mox", Language.Italian);
            MagnificusMod.RegisterCard("MoxShield", "Scudo Mox", "A magic shield inlaid with gemstones always provides a sense of security with its presence.", "La sola presenza di questo scudo magico incastonato di gemme infonde sempre sicurezza.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A magic shield inlaid with gemstones always provides a sense of security with its presence.", "La sola presenza di questo scudo magico incastonato di gemme infonde sempre sicurezza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nebula Storm", "Tempesta nebulare", Language.Italian);
            MagnificusMod.RegisterCard("Nebula Storm", "Tempesta nebulare", "This cruel storm can directly take away an enemy.", "Questa tempesta spietata può spazzare via un nemico all'istante.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cruel storm can directly take away an enemy.", "Questa tempesta spietata può spazzare via un nemico all'istante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Contract", "Contratto dell'anima", Language.Italian);
            MagnificusMod.RegisterCard("Soul Contract", "Contratto dell'anima", "Perhaps you need more card assistance, and a soul contract is a great choice.", "Forse hai bisogno dell'aiuto di altre carte. Un contratto dell'anima sarebbe un'ottima scelta.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps you need more card assistance, and a soul contract is a great choice.", "Forse hai bisogno dell'aiuto di altre carte. Un contratto dell'anima sarebbe un'ottima scelta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wailing Wall", "Muro del pianto", Language.Italian);
            MagnificusMod.RegisterCard("Wailing Wall", "Muro del pianto", "Such perseverance even moves the thorny walls to weep.", "Una simile perseveranza commuove persino i muri di spine, facendoli piangere.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such perseverance even moves the thorny walls to weep.", "Una simile perseveranza commuove persino i muri di spine, facendoli piangere.", Language.Italian);
            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coffee Time", "Pausa caffè", Language.Italian);
            MagnificusMod.RegisterAbility("Coffee Time", "Pausa caffè");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] receives the first damage, it gains 2 strength.", "La prima volta che [creature] subisce danni, ottiene 2 di potenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death of Arrogance", "Morte della superbia", Language.Italian);
            MagnificusMod.RegisterAbility("Death of Arrogance", "Morte della superbia");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 2 power.", "Quando [creature] muore, le carte adiacenti ottengono 2 di potenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death of Greed", "Morte dell'avidità", Language.Italian);
            MagnificusMod.RegisterAbility("Death of Greed", "Morte dell'avidità");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 3 health.", "Quando [creature] muore, le carte adiacenti ottengono 3 di salute.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Made", "Creazione divina", Language.Italian);
            MagnificusMod.RegisterAbility("God Made", "Creazione divina");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Homunculus is created on each empty adjacent space. The Homunculus has : 1 power, 1 health, Familiar.", "Quando si gioca [creature], si crea un Omuncolo in ogni spazio adiacente vuoto. L'Omuncolo ha: 1 di potenza, 1 di salute, Famiglio.", Language.Italian);
            MagnificusMod.RegisterAbility("Fir Caller", "Richiamo degli abeti");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the empty slot on the cardholder's side is filled with Great Firs. Great Fir has: 0 Power, 3 Health, Mighty Leap.", "Quando [creature] muore, gli spazi vuoti dalla parte del proprietario vengono riempiti di Grandi abeti. Il Grande abete ha: 0 di potenza, 3 di salute, Balzo potente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering Taste", "Gusto persistente", Language.Italian);
            MagnificusMod.RegisterAbility("Lingering Taste", "Gusto persistente");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 1 health.", "Quando [creature] muore, le carte adiacenti ottengono 1 di salute.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Love of Cheese", "Amore per il formaggio", Language.Italian);
            MagnificusMod.RegisterAbility("Love of Cheese", "Amore per il formaggio");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, draw a cheese card, cheese has: 0 power, 2 health,Lingering Taste.", "Quando si gioca [creature], pesca una carta Formaggio magico. Il Formaggio magico ha: 0 di potenza, 2 di salute, Gusto persistente.", Language.Italian);
            // Other
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Expansion", "Espansione magica", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here comes the card of the fantasy world! More content will be added in the future!", "Arrivano le carte del mondo fantastico! In futuro verranno aggiunti altri contenuti!", Language.Italian);
        }
    }
