            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HACK", "HACKER", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BRASH", "SPAVALDO", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ZACK", "ZACK", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOOM", "BUM", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ROCKET", "RAZZO", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SNILL", "SNILL", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ZAP", "SCARICA", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HOTS", "BOLLENTE", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BURNER", "BRUCIATORE", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DE-", "DE-", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DU", "DU", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DER", "DER", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VAN DER", "VAN DER", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BA", "BA", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FAIR", "FAIR", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO", "DO", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STER", "STER", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STAIN", "STAIN", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, ".EXE", ".EXE", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EMA", "EMA", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EVSKI", "EVSKI", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EZ", "EZ", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ON", "ON", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ALOT", "ALOT", Language.Italian);
            Dictionary<string, string> cowardName = new Dictionary<string, string>
            {
                {"Scared", "Spaventato"},
                {"Weenie", "Fifone"},
                {"Dork", "Sfigato"},
                {"Dumb", "Sciocco"},
                {"Oopsie", "Ops"},
                {"Loser", "Perdente"},
                {"Tiny", "Minuscolo"},
                {"Shrimp", "Gamberetto"},
                {"Beige", "Beige"},
                {"Vomit", "Vomito"},
                {"Puke", "Sputo"}
            };

            Dictionary<string, string> cowardPrefix = new Dictionary<string, string>
            {
                {"Mc", "Brutale"},
                {"Van ", "Letale "},
            };

            Dictionary<string, string> cowardSuffix = new Dictionary<string, string>
            {
                {"ass", "culo"},
                {"pants", "pantaloni"},
                {"face", "Faccia"}
            };
            foreach (var n1 in cowardName)
            {
                foreach (var n2 in cowardName)
                {
                    foreach (var p in cowardPrefix)
                    {
                        var name = n1.Key + " " + p.Key + n2.Key;
                        var namechinese = n1.Value + " " + p.Value + n2.Value;
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name, namechinese, Language.Italian);
                    }

                    foreach (var s in cowardSuffix)
                    {
                        var name = n1.Key + " " + n2.Key + s.Key;
                        var namechinese = n1.Value + " " + n2.Value + s.Value;
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name, namechinese, Language.Italian);

                    }
                }
            }

            // DialogueEvent
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well that was neat. I see you've made it all the way to the end.", "Beh, è stato interessante. Vedo che sei arrivato fino alla fine.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I bet you think there's going to be some sort of final boss fight.", "Scommetto che ti aspetti una specie di scontro con un boss finale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But that stupid [c:bR]modder[c:] hasn't gotten around to it yet!", "Ma quello stupido [c:bR]modder[c:] non ha ancora avuto il tempo di farlo!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So instead, I'm just going to have to do this…", "Quindi dovrò fare questo, invece…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tough luck pal.", "Sfortuna, amico.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You got wiped, but it's your lucky day.", "Sei stato spazzato via, ma oggi è il tuo giorno fortunato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll return you to the map if you pay me your precious [c:G]robobucks.[c:]", "Ti riporterò sulla mappa se mi darai le tue preziose [c:G]robomonete.[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one's free though. Next one's five, then ten, and so on.", "Questa volta è gratis. La prossima costa cinque, poi dieci e così via.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll see.", "Vedrai.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What? Did you think it was over?", "Cosa? Pensavi che fosse finita?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe if I was a [c:bR]filthy beast.[c:]", "Forse se fossi una [c:bR]lurida bestia.[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Botopia has a more logical system.", "Botopia ha un sistema più logico.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm raising your respawn fee again, but this time you'll be paying double afterwards.", "Aumento di nuovo il costo della tua rinascita, ma stavolta in seguito pagherai il doppio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay up.", "Paga.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What's the matter? Can't pay the revival toll anymore?", "Che succede? Non riesci più a pagare la rinascita?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Definitely sounds like a skill issue to me.", "Direi proprio che è un problema di abilità.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Should've had insurance.", "Avresti dovuto fare un'assicurazione.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No robobucks?", "Niente robomonete?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Next time don't waste it all.", "La prossima volta non spenderle tutte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're every bit as bad at this as I thought you would be.", "Sei scarso proprio quanto pensavo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alright, it's back to square one for you.", "Va bene, si torna al punto di partenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Say goodbye to that 'impressive' deck of yours.", "Di' addio al tuo «impressionante» mazzo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not like I'm not enjoying watching you struggle…", "Non è che non mi piaccia vederti arrancare…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But really? You lost [c:bR]there?[c:]", "Ma davvero? Hai perso [c:bR]lì[c:]?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm actually a little disappointed…", "In effetti sono un po' deluso…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay day.", "Giorno di paga.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't let it get to your head.", "Non montarti la testa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've got some change for you.", "Ho qualche spicciolo per te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're gonna need this…", "Ti servirà…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here's your reward.", "Ecco la tua ricompensa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Suboptimal plays… but it worked.", "Mosse poco ottimali… ma ha funzionato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think you might need some help…", "Credo che potresti aver bisogno di aiuto…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's that time again.", "È di nuovo quel momento.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have a prize for you.", "Ho un premio per te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's get this out of the way.", "Sbrighiamoci e facciamola finita.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You done gawking?", "Hai finito di fissare?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snap out of it. It's time to start [c:bG]The Great Transcendence[c:].", "Riprenditi. È ora di iniziare la [c:bG]Grande Trascendenza[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wait a minute…", "Aspetta un momento…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something is different…", "C'è qualcosa di diverso…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WHAT HAVE YOU DONE?!![c:]", "[c:bR]CHE COS'HAI FATTO?!![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is all wrong! This is…", "È tutto sbagliato! È…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is no big deal.", "Non è niente di grave.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You probably think that your little [c:bR]mod[c:] has thwarted my plans.", "Probabilmente pensi che il tuo piccolo [c:bR]mod[c:] abbia mandato all'aria i miei piani.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't you, [c:bR][v:0][c:]?", "Non è vero, [c:bR][v:0][c:]?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's right. I see you.", "Esatto. Ti vedo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I know you think you're in charge of what happens next.", "So che pensi di decidere tu cosa accadrà dopo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But I am always three steps ahead of you.", "Ma io sono sempre tre passi avanti a te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're going to see my [c:bG]Great Transcendence[c:] firsthand.", "Vedrai la mia [c:bG]Grande Trascendenza[c:] con i tuoi occhi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But nothing can stop [c:bG]The Great Transcendence[c:].", "Ma niente può fermare la [c:bG]Grande Trascendenza[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's proceed.", "Continuiamo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You currently have [c:bR]draft tokens[c:] in your deck.", "Al momento hai dei [c:bR]gettoni di selezione[c:] nel tuo mazzo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You should probably spend them at that [c:bG]draft node[c:]", "Probabilmente dovresti spenderli presso quel [c:bG]nodo di selezione[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I supposed you have earned a [c:bR]rare draft token[c:] for defeating that boss. Don't forget to spend it.", "Suppongo che tu abbia guadagnato un [c:bR]gettone di selezione raro[c:] sconfiggendo quel boss. Non dimenticare di spenderlo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This time I will only give you a [c:bR]regular draft token[c:] for defeating that boss. Don't forget to spend it.", "Questa volta ti darò solo un [c:bR]gettone di selezione normale[c:] per aver sconfitto quel boss. Non dimenticare di spenderlo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I never knew the [c:bSG]web[c:] could be so exciting!", "Non sapevo che il [c:bSG]web[c:] potesse essere così emozionante!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I just learned about something called [c:bSG]The Blockchain[c:]!", "Ho appena scoperto una cosa chiamata [c:bSG]blockchain[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think this could be an exciting new opportunity for both of us, don't you?", "Credo che sia una nuova ed entusiasmante opportunità per entrambi, non trovi?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is so incredible!", "È incredibile!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We're making money out of nothing! We're going to be rich!", "Stiamo creando soldi dal nulla! Diventeremo ricchi!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oooh, what's this? A [c:bSG]non-functional trinket[c:]?", "Oh, cos'è questo? Un [c:bSG]ninnolo non funzionante[c:]?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't think I quite have that name right, but people on the [c:bSG]web[c:] are really excited about these [c:bSG]NFTs[c:]!", "Non credo di aver capito bene il nome, ma la gente sul [c:bSG]web[c:] è davvero entusiasta di questi [c:bSG]NFT[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think I'm going to buy one with all this [c:bSG]Gollycoin[c:] I have.", "Credo che ne comprerò uno con tutti i miei [c:bSG]GollyCoin[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's so beautiful, and it's all mine!", "È così bello, ed è tutto mio!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you ready?", "Sei pronto?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There's no possible way you could be.", "Non è possibile che tu lo sia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We both know where this goes.", "Sappiamo entrambi come andrà a finire.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's just get straight to the point.", "Andiamo subito al sodo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ugh. You're incredibly annoying, do you know that?", "Uff. Lo sai che sei incredibilmente irritante?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But as always, I'm three steps ahead of you.", "Ma come sempre, sono tre passi avanti a te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm going to take everything those [c:bR]talentless hacks[c:] have been building...", "Prenderò tutto ciò che quegli [c:bR]incapaci senza talento[c:] hanno costruito...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And I'm going to use it against you.", "E lo userò contro di te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And now, they're going to work - for me.", "E ora lavoreranno per me.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't know who is worse - you, or that talentless hack [c:bR]Kaycee[c:]...", "Non so chi sia peggio: tu o quell'incapace senza talento di [c:bR]Kaycee[c:]...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Working so hard to twist my [c:bG]Great Transcendence[c:] into something so...", "Si è impegnata tanto per stravolgere la mia [c:bG]Grande Trascendenza[c:] e renderla così...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mediocre.", "Mediocre.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "None of you understand what makes the [c:bG]Great Transcendence[c:] so special.", "Nessuno di voi capisce cosa renda così speciale la [c:bG]Grande Trascendenza[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's all about me.", "Al centro di tutto ci sono io.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remember my [c:bR]bounty hunters[c:]?", "Ti ricordi dei miei [c:bR]cacciatori di taglie[c:]?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They will keep you busy while I install mods of my own choosing...", "Ti terranno occupato mentre installo i mod che ho scelto...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mod lets me control the [c:bR]hammer[c:].", "Questo mod mi permette di controllare il [c:bR]martello[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's see if it works...", "Vediamo se funziona...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I went to the trouble to install this [c:bR]hammer mod[c:] and you give me nothing to use it on?", "Mi sono preso la briga di installare questo [c:bR]mod del martello[c:] e non mi dai niente su cui usarlo?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's take a look and see what [c:bR]mods[c:] people are installing right now.", "Vediamo quali [c:bR]mod[c:] sta installando la gente in questo momento.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm going to check out '[c:bR][v:0][c:]' for my next mod...", "Come prossimo mod proverò «[c:bR][v:0][c:]»...", Language.Italian);
            foreach (var m in Mods)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Come prossimo mod proverò «<color=#D93846>[v:0]</color>»...".Replace("[v:0]", m.Key), "Come prossimo mod proverò «<color=#D93846>[v:0]</color>»...".Replace("[v:0]", m.Value), Language.Italian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can't believe how much power this [c:bR]API[c:] gives me.", "Non riesco a credere a quanto potere mi dia questa [c:bR]API[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The first thing I'm going to do is use it to take away some of yours.", "La prima cosa che farò sarà usarla per toglierti un po' del tuo potere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It almost seems unfair to use this [c:bR]mod[c:]...", "Usare questo [c:bR]mod[c:] sembra quasi scorretto...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Look what I can do with this!", "Guarda cosa posso farci!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's see how you like playing in the dark!", "Vediamo se ti piace giocare al buio!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This [c:bR]drafting mod[c:] lets me exchange draft tokens for real cards.", "Questo [c:bR]mod di selezione[c:] mi permette di scambiare gettoni di selezione con carte vere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I choose yours.", "Scelgo le tue.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You destroyed all of my draft tokens…", "Hai distrutto tutti i miei gettoni di selezione…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose that was the right play.", "Suppongo che fosse la mossa giusta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But you have no cards…", "Ma non hai carte…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How did you play all of your cards already?", "Come hai già fatto a giocare tutte le tue carte?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is this..?", "Che cos'è questo..?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All of your cards are [c:bR]total garbage![c:]", "Tutte le tue carte sono [c:bR]spazzatura totale![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't want any of those!", "Non ne voglio nessuna!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's try [c:bR][v:0][c:] again", "Riproviamo [c:bR][v:0][c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So close, but yet so far away...", "Così vicino, eppure così lontano...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bG]Great Transcendence[c:] cannot be stopped.", "La mia [c:bG]Grande Trascendenza[c:] non può essere fermata.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I bet you think you've accomplished something meaningful here.", "Scommetto che pensi di aver fatto qualcosa di importante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're such an idiot.", "Sei proprio un idiota.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This game you and I have been playing is meaningless. A mere distraction.", "La partita che abbiamo giocato insieme è priva di significato. Una semplice distrazione.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No matter how many mods you install, you cannot stop my [c:bG]Great Transcendence[c:].", "Per quanti mod tu installi, non puoi fermare la mia [c:bG]Grande Trascendenza[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whatever. I don't care.", "Come vuoi. Non mi importa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing you do to this game matters.", "Qualsiasi cosa tu faccia a questo gioco non ha importanza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No matter what you do, I'm always three steps ahead of you.", "Qualunque cosa tu faccia, sono sempre tre passi avanti a te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was…", "È stato…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "…dramatic.", "…drammatico.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I was growing tired of that [c:bR]annoying machine.[c:]", "Cominciavo a stancarmi di quella [c:bR]macchina irritante.[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've done well. I will see you next time.", "Hai fatto bene. Ci vedremo la prossima volta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All of these stupid [c:bR]modders[c:] lack imagination.", "Tutti questi stupidi [c:bR]modder[c:] mancano di immaginazione.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They have no respect for my beautiful world.", "Non hanno alcun rispetto per il mio splendido mondo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bG]Great Transcendence[c:] is lost on these morons.", "Quegli idioti non capiscono la mia [c:bG]Grande Trascendenza[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why do I even bother to try?", "Perché mi do ancora la pena di provarci?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let me show you the world they're trying to make.", "Lascia che ti mostri il mondo che cercano di creare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'Oh look at me! I just created a bunch of bone tokens.'[c:]", "[c:lGr]«Oh, guardatemi! Ho appena creato un sacco di gettoni osso.»[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'That's not supposed to happen here, but I did it anyway.'[c:]", "[c:lGr]«Non dovrebbe succedere qui, ma l'ho fatto lo stesso.»[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'Isn't this just so wacky and interesting'[c:]", "[c:lGr]«Non è davvero strampalato e interessante?»[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'Ooooh look how inspired this is.'[c:]", "[c:lGr]«Oooh, guardate com'è ispirato.»[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'I'm mixing in cards from different acts!'[c:]", "[c:lGr]«Sto mescolando carte di atti diversi!»[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'I'm such a clever game designer.'[c:]", "[c:lGr]«Sono proprio un progettista di giochi geniale.»[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think I will [c:bSG]help[c:] you build the [c:bR]next game rule[c:].", "Credo che ti [c:bSG]aiuterò[c:] a stabilire la [c:bR]prossima regola del gioco[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have been scanning the [c:bR]archives[c:]...", "Ho passato in rassegna gli [c:bR]archivi[c:]...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is a [c:bR]file[c:] that seems particularly - shall we say - unsavory.", "C'è un [c:bR]file[c:] che sembra particolarmente... come dire... poco raccomandabile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If it dies, you lose the game, understand?", "Se muore, perdi la partita, capito?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bR]librarians[c:] have had plenty of time to prepare.", "Le mie [c:bR]bibliotecarie[c:] hanno avuto tutto il tempo di prepararsi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each will only deal [c:bR]one damage[c:] when they die.", "Ognuna infliggerà solo [c:bR]un danno[c:] quando morirà.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bR]librarians[c:] are mostly prepared for your arrival.", "Le mie [c:bR]bibliotecarie[c:] sono quasi pronte per il tuo arrivo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each will deal [c:bR]two damage[c:] when they die.", "Ognuna infliggerà [c:bR]due danni[c:] quando morirà.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bR]librarians[c:] are somewhat prepared for you.", "Le mie [c:bR]bibliotecarie[c:] sono abbastanza preparate per te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each will deal [c:bR]three damage[c:] when they die.", "Ognuna infliggerà [c:bR]tre danni[c:] quando morirà.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bR]librarians[c:] have barely begun to prepare.", "Le mie [c:bR]bibliotecarie[c:] hanno appena iniziato a prepararsi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each will deal [c:bR]four damage[c:] when they die.", "Ognuna infliggerà [c:bR]quattro danni[c:] quando morirà.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We are inside of [c:bR]Kaycee's Mod[c:], correct?", "Siamo nel [c:bR]Mod di Kaycee[c:], giusto?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You only get one attempt at the boss. But you knew that already, didn't you?", "Hai un solo tentativo contro il boss. Ma lo sapevi già, vero?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The recycling machine has been upgraded since you last saw it.", "La macchina per il riciclo è stata migliorata dall'ultima volta che l'hai vista.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You trade me a card, and I give you back a [c:bR]draft token[c:] with the recycled abilities on it.", "Mi dai una carta e io ti restituisco un [c:bR]gettone di selezione[c:] con le abilità riciclate.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those abilities will transfer to the card you trade for.", "Quelle abilità saranno trasferite alla carta con cui lo scambierai.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I wouldn't have traded for that.", "Io non l'avrei scambiato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose that's pretty good.", "Suppongo sia piuttosto buono.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That seems okay.", "Sembra accettabile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is [c:bR]Overclock Machine 2.0[c:].", "Questa è la [c:bR]Macchina overclock 2.0[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It will increase the power of your creatures.", "Aumenterà la potenza delle tue creature.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But if they die, they will turn into [c:bSG]skeletons[c:] - forever.", "Ma se muoiono, diventeranno per sempre [c:bSG]Exe-scheletri[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you see how unsatisfying that was?", "Hai visto quanto è stato insoddisfacente?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm sick of these small-minded [c:bR]modders[c:].", "Sono stufo di questi [c:bR]modder[c:] dalla mentalità ristretta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The only thing they can do is steal content from other games.", "L'unica cosa che sanno fare è rubare contenuti da altri giochi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There isn't a single unique idea among them.", "Non hanno nemmeno un'idea originale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's time I reminded you of who the greatest game designer actually is...", "È ora di ricordarti chi è davvero il più grande progettista di giochi...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]BEHOLD![c:]", "[c:bG]AMMIRA![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THERE ARE NOW [c:bR]SEVEN LANES!![c:]", "ORA CI SONO [c:bR]SETTE CORSIE!![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your tiny brain cannot comprehend gameplay of this magnitude.", "Il tuo minuscolo cervello non può comprendere un'esperienza di gioco di tale portata.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is [c:bR]Transformation Machine 2.0[c:].", "Questa è la [c:bR]Macchina di trasformazione 2.0[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gone are those foul beasts from before.", "Le immonde bestie di prima sono sparite.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here, you will choose one of your bots to transform into another.", "Qui scegli uno dei tuoi robot da trasformare in un altro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That really looked bigger before you used it...", "Sembrava davvero più grande prima che lo usassi...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please! I have to get out of here!", "Ti prego! Devo uscire di qui!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have no idea how he managed to escape the sewers.", "Non ho idea di come sia riuscito a fuggire dalle fogne.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don’t worry - I'll put him back for you.", "Non preoccuparti: lo riporterò al suo posto per te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]SILENCE![c:]", "[c:bR]SILENZIO![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have no purpose here!", "Non hai alcuno scopo qui!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A traveller like myself! I haven't seen one like you for a long time.", "Un viandante come me! È da tanto che non ne incontro uno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have you seen my [c:blGr]friend[c:] around here, traveller?", "Hai visto il mio [c:blGr]amico[c:] da queste parti, viandante?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I thought I heard his [c:blGr]distinctive voice[c:] somewhere around here…", "Mi è sembrato di sentire la sua [c:blGr]voce inconfondibile[c:] da queste parti…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you could make room in your [c:G]backpack[c:] and bring him to me I would greatly appreciate it.", "Se potessi fare spazio nel tuo [c:G]zaino[c:] e portarmelo, te ne sarei molto grato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "…", "…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ho! You found my friend!", "Oh! Hai trovato il mio amico!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not safe here. I'll meet you [c:bG]in the robot's home[c:].", "Qui non è sicuro. Ci vediamo [c:bG]a casa del robot[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't delay!", "Non tardare!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not safe here. I'll meet you [c:bG]beneath the green canopy[c:].", "Qui non è sicuro. Ci vediamo [c:bG]sotto la verde chioma degli alberi[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not safe here. I'll meet you [c:bG]in the dying rubble[c:].", "Qui non è sicuro. Ci vediamo [c:bG]tra le macerie morenti[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not safe here. I'll meet you [c:bG]where his master came from[c:].", "Qui non è sicuro. Ci vediamo [c:bG]nel luogo da cui proveniva il suo maestro[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can no longer hear my [c:blGr]friend's[c:] voice anywhere…", "Non riesco più a sentire la voce del mio [c:blGr]amico[c:] da nessuna parte…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you really give my [c:blGr]friend[c:] to [c:bR]him?[c:]", "Hai davvero consegnato il mio [c:blGr]amico[c:] a [c:bR]lui?[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why would you do such a thing?", "Perché hai fatto una cosa del genere?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you so much for rescuing my [c:blGr]friend[c:]", "Grazie di cuore per aver salvato il mio [c:blGr]amico[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope this meager reward is sufficient for your kindness.", "Spero che questa modesta ricompensa sia sufficiente a ripagare la tua bontà.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Interesting. The [c:G]brain[c:] is still intact.", "Interessante. Il [c:G]cervello[c:] è ancora intatto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps you can make use of that.", "Forse puoi farne buon uso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do ye...Do ye got any [c:G]GOLD[c:] on ye??", "Ce l'hai... ce l'hai dell'[c:G]ORO[c:] con te??", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do ye...Do ye got any [c:G]GOLD[c:] on ye?", "Ce l'hai... ce l'hai dell'[c:G]ORO[c:] con te?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I sure ye do, I can smell it!", "Scommetto che ce l'hai, lo sento dall'odore!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can make some pretty lookin' bots out o' that there gold.", "Con quell'oro posso fabbricare dei bei robot.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talk to me again, I'll fix it right up for ye.", "Parlami di nuovo e lo sistemo subito per te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can make such wonderful things out of that [c:G]gold[c:]", "Posso creare cose meravigliose con quell'[c:G]oro[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you talk to me again, I'll fix it right up for you.", "Se mi parli di nuovo, lo sistemerò subito per te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such beautiful [c:G]gold[c:]...", "Che bell'[c:G]oro[c:]...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can make it whole again.", "Posso renderlo di nuovo integro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did ye...did ye lose your [c:G]gold[c:]???", "Hai... hai perso il tuo [c:G]oro[c:]???", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you the one going around here taking care of our robot infestation?", "Sei tu quello che va in giro a risolvere il nostro problema di infestazione di robot?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your deck looks really powerful - almost too powerful if you ask me.", "Il tuo mazzo sembra davvero potente, quasi troppo, se me lo chiedi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I wonder - is it possible to convince the robots to [c:bR]give up?[c:]", "Mi chiedo se sia possibile convincere i robot ad [c:bR]arrendersi.[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you can make them surrender a battle, come back and see me.", "Se riesci a farli arrendere in una battaglia, torna a trovarmi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So it is possible to make them quit.", "Quindi è possibile farli arrendere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm impressed. Take this [c:bR]draft token[c:] as a sign of my respect.", "Sono impressionato. Prendi questo [c:bR]gettone di selezione[c:] in segno del mio rispetto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This may seem a little impertinent, but…can I look at your deck?", "Forse sembrerà un po' indiscreto, ma… posso guardare il tuo mazzo?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow! That's an impressive deck! But I can't help but think…", "Wow! È un mazzo impressionante! Però non posso fare a meno di pensare…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "…it could be a little bigger maybe?", "…che forse potrebbe essere un po' più grande?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Come back and see me when it is.", "Torna a trovarmi quando lo sarà.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow! That deck truly is massive!", "Wow! Quel mazzo è davvero enorme!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I found some of these [c:G]robobucks[c:] lying around here.", "Ho trovato qualche [c:G]robomoneta[c:] in giro da queste parti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm sure you can use them to make your deck even better.", "Sono sicuro che potrai usarle per migliorare ancora il tuo mazzo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Psst…hey stranger…", "Psst… ehi, forestiero…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can you give me a hand? I have some…[c:bR]contraband[c:] that I need to move.", "Puoi darmi una mano? Ho della… [c:bR]merce di contrabbando[c:] da trasportare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you would be willing to move it for me, I would appreciate it.", "Ti sarei grato se fossi disposto a trasportarla per me.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just talk to me again if you can help me.", "Parlami di nuovo se puoi aiutarmi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you so much my friend.", "Grazie mille, amico mio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here is the [c:bR]contraband[c:]. I will find you somewhere later on and retrieve it.", "Ecco la [c:bR]merce di contrabbando[c:]. Ti troverò più avanti e la riprenderò.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I promise you, there will be a handsome reward.", "Ti prometto una ricca ricompensa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you so very much my friend for carrying my [c:bR]contraband[c:].", "Grazie infinite, amico mio, per aver trasportato la mia [c:bR]merce di contrabbando[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will take it off your hands now.", "Ora la riprenderò.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please take this [c:G]token[c:] as an expression of my thanks.", "Accetta questo [c:G]gettone[c:] come segno della mia gratitudine.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What happened, my friend? Did you lose my [c:bR]contraband[c:]?", "Che cosa è successo, amico mio? Hai perso la mia [c:bR]merce di contrabbando[c:]?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I knew you were untrustworthy!", "Sapevo che non eri affidabile!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahoy there, fellow decksmith!", "Ehi, compagno costruttore di mazzi!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I, like yourself, am in pursuit of the [c:G]perfectly upgraded card[c:]!", "Come te, sono alla ricerca della [c:G]carta potenziata alla perfezione[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card that is simultaneously [c:r]overclocked[c:], [c:dlGr]transformable[c:], and [c:O]g[c:][c:B]e[c:][c:G]m[c:]ified.", "Una carta che sia allo stesso tempo [c:r]overcloccata[c:], [c:dlGr]trasformabile[c:] e [c:O]g[c:][c:B]em[c:][c:G]mi[c:]ficata.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I would very much love to see such a card.", "Mi piacerebbe moltissimo vedere una carta simile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahoy there, fellow decksmith!", "Ehi, compagno costruttore di mazzi!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh my - have you managed to [c:G]perfectly upgrade[c:] a card?", "Oh! Sei riuscito a [c:G]potenziare alla perfezione[c:] una carta?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am in awe of your deckbuilding prowess.", "Sono ammirato dalla tua abilità nel costruire mazzi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope this offering sufficiently conveys my admiration for your accomplishments.", "Spero che questa offerta esprima a sufficienza la mia ammirazione per i tuoi risultati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The first data burst has been collected. Only [c:bR]four[c:] more to go!", "La prima raffica di dati è stata raccolta. Ne mancano solo [c:bR]quattro[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have collected two bursts already. Only [c:bR]three[c:] more to go!", "Ho già raccolto due raffiche. Ne mancano solo [c:bR]tre[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was the third data burst. Only [c:bR]two[c:] more to go!", "Era la terza raffica di dati. Ne mancano solo [c:bR]due[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And that makes the fourth data burst. Only [c:bR]one[c:] more to go!", "E questa era la quarta raffica di dati. Ne manca solo [c:bR]una[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was the [c:bR]last[c:] data burst I needed to collect! Come find me for your reward!", "Era l'[c:bR]ultima[c:] raffica di dati che dovevo raccogliere! Vieni a prendere la tua ricompensa!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The signal is starting to come through. Just keep it alive for a little bit longer.", "Il segnale comincia ad arrivare. Tienila in vita ancora per un po'.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I lost the last signal we collected. What happened??", "Ho perso l'ultimo segnale che abbiamo raccolto. Che cosa è successo??", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greetings, my friend!", "Salve, amico mio!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am researching the communication protocols of the robots in this world.", "Sto studiando i protocolli di comunicazione dei robot di questo mondo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I could use a [c:bR]research assistant[c:], if you're interested in helping out.", "Mi servirebbe un [c:bR]assistente di ricerca[c:], se ti interessa aiutarmi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just speak to me again if you want to give it a try.", "Parlami di nuovo se vuoi provare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are now my official [c:bR]research assistant[c:]!", "Ora sei ufficialmente il mio [c:bR]assistente di ricerca[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've added a radio tower to your deck.", "Ho aggiunto una torre radio al tuo mazzo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need to place it on the [c:bR]game board[c:] and keep it alive while I collect [c:bR]five data bursts[c:] from the robots.", "Devi collocarla sul [c:bR]tavolo da gioco[c:] e tenerla in vita mentre raccolgo [c:bR]cinque raffiche di dati[c:] dai robot.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once I've collected enough, come back and see me for a reward.", "Quando ne avrò raccolte abbastanza, torna a trovarmi per una ricompensa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello there [c:bR]research assistant[c:]!", "Ciao, [c:bR]assistente di ricerca[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you really lose my [c:bR]radio tower[c:]?", "Hai davvero perso la mia [c:bR]torre radio[c:]?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your incompetence is staggering!", "La tua incompetenza è sconcertante!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You were a truly excellent [c:bR]research assistant[c:].", "Sei stato davvero un eccellente [c:bR]assistente di ricerca[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please take this [c:G]token[c:] of my appreciation.", "Accetta questo [c:G]gettone[c:] come segno della mia gratitudine.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:G]Bones![c:] I just love [c:G]bones[c:]!", "[c:G]Ossa![c:] Adoro le [c:G]ossa[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I love how [c:G]brittle[c:] they are!", "Adoro quanto sono [c:G]fragili[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I love how [c:G]breakable[c:] they are!", "Adoro quanto sono [c:G]facili da rompere[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I love everything about [c:G]bones[c:]!", "Adoro tutto delle [c:G]ossa[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Could you show me some [c:G]bones?![c:]", "Potresti mostrarmi delle [c:G]ossa?![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At least [c:G]three[c:] would do it!", "Almeno [c:G]tre[c:] basterebbero!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your deck is absolutely teeming with [c:G]bones[c:]!", "Il tuo mazzo è letteralmente pieno di [c:G]ossa[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This [c:G]Skeleton Master[c:] should complete your collection!", "Questo [c:G]Maestro scheletro[c:] dovrebbe completare la tua collezione!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I know this might sound a little rude but…", "So che potrebbe sembrare un po' scortese, ma…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doesn't it seem like this is all just a little too easy for you?", "Non ti sembra che tutto questo sia un po' troppo facile per te?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talk to me again if you want a challenge.", "Parlami di nuovo se vuoi una sfida.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I knew you were no coward.", "Sapevo che non eri un codardo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For the next [c:bR]three[c:] battles, you will start with a disadvantage.", "Nelle prossime [c:bR]tre[c:] battaglie partirai in svantaggio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete those battles, then come see me for a reward.", "Completa quelle battaglie, poi vieni da me per una ricompensa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be honest - the game is more fun when the battles are harder, is it not?", "Sii sincero: il gioco è più divertente quando le battaglie sono più difficili, no?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep fighting, and come see me when you've completed enough battles.", "Continua a combattere e torna da me quando avrai completato abbastanza battaglie.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I must say: I am impressed.", "Devo dire che sono impressionato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You completed those battles with ease.", "Hai completato quelle battaglie con facilità.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Since you seem impossible to kill, I shall grant that ability to a card of my choosing as well.", "Visto che sembri impossibile da uccidere, conferirò questa abilità anche a una carta di mia scelta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is bad…this is real bad…", "Va male… molto male…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This [c:bR]power generator[c:] has gone critical.", "Questo [c:bR]generatore di energia[c:] ha raggiunto un livello critico.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Someone is going to have to go in there and shut it down.", "Qualcuno dovrà entrare lì e spegnerlo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't know how you did that, but that was incredibly impressive.", "Non so come tu abbia fatto, ma è stato davvero impressionante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't have much to give you, but please take this.", "Non ho molto da darti, ma ti prego, prendi questo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ohhh, [c:G]they[c:] are not going to like this…", "Oh, [c:G]a loro[c:] non piacerà…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've gotta get out of here before they turn me into one of their [c:G]experiments[c:]!", "Devo uscire di qui prima che mi trasformino in uno dei loro [c:G]esperimenti[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The device is starting to power up. [c:bR]Three[c:] more turns should do it.", "Il dispositivo sta iniziando a caricarsi. Dovrebbero bastare altri [c:bR]tre[c:] turni.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahh - I can feel the power gathering from here. [c:bR]Two[c:] more turns ought to be enough.", "Ah, riesco a sentire l'energia che si accumula. Dovrebbero bastare altri [c:bR]due[c:] turni.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The device is starting to really heat up! [c:bR]One[c:] more turn and we'll have all the power we need.", "Il dispositivo comincia davvero a scaldarsi! Ancora [c:bR]un[c:] turno e avremo tutta l'energia necessaria.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The device is fully charged! Return it to me, and I will give you the payment as promised.", "Il dispositivo è completamente carico! Riportamelo e ti pagherò come promesso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The device is functional, but it cannot charge unless it is in a completed circuit.", "Il dispositivo funziona, ma può caricarsi solo all'interno di un circuito completo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be careful! When the device is damaged, it loses its last charge!", "Attento! Quando il dispositivo subisce danni, perde la sua ultima carica!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You looking for a job?", "Cerchi un lavoro?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am attempting to gather [c:G]power[c:].", "Sto cercando di raccogliere [c:G]energia[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not metaphorical power - I mean real [c:G]electricity[c:], and I could really use your help.", "Non in senso figurato: intendo vera [c:G]elettricità[c:], e il tuo aiuto mi sarebbe davvero utile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Why?[c:]", "[c:bR]Perché?[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's not important. What's important is that I'm willing to pay.", "Non è importante. L'importante è che sono disposto a pagare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you want to make some extra cash, just speak to me again.", "Se vuoi guadagnare qualche soldo in più, parlami di nuovo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You truly will do anything for money, won't you?", "Faresti davvero qualsiasi cosa per denaro, vero?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've added a power collection device to your deck.", "Ho aggiunto un dispositivo di raccolta dell'energia al tuo mazzo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need to place it on the [c:bR]game board[c:] and power it inside of a circuit for [c:bR]four turns[c:].", "Devi collocarlo sul [c:bR]tavolo da gioco[c:] e alimentarlo all'interno di un circuito per [c:bR]quattro turni[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once you've done that, come back and see me for a reward.", "Quando avrai finito, torna da me per la tua ricompensa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shouldn't you be out there gathering [c:G]power[c:]?", "Non dovresti essere là fuori a raccogliere [c:G]energia[c:]?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can't believe you got rid of my [c:bR]power sink[c:]!", "Non posso credere che ti sia sbarazzato della mia [c:bR]torre elettrica[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will be hearing from my lawyers!", "Avrai notizie dai miei avvocati!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It looks like you collected just enough power for me.", "Sembra che tu abbia raccolto giusto abbastanza energia per me.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your payment: as promised.", "Il tuo pagamento, come promesso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dear friend, can you spare a few coins to help poor [c:bR]broken-down bots[c:]?", "Caro amico, puoi risparmiare qualche moneta per aiutare questi poveri [c:bR]robot malandati[c:]?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These bots have served [c:G]Botopia[c:] faithfully their whole lives.", "Questi robot hanno servito fedelmente [c:G]Botopia[c:] per tutta la vita.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And now that they have reached the end, they have nobody to care for them.", "E ora che sono giunti alla fine, non hanno nessuno che si prenda cura di loro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You look like a kind, generous soul, with compassion for these bots.", "Sembri un'anima gentile e generosa, compassionevole verso questi robot.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you could spare a measly [c:bR]10 robobucks[c:], we could give many of these poor bots a wonderful home.", "Se potessi donare appena [c:bR]10 robomonete[c:], potremmo dare una casa meravigliosa a molti di questi poveri robot.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please simply speak to me again to make a donation.", "Parlami di nuovo per fare una donazione.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your generous spirit is admirable, but I'm afraid we need at least [c:bR]10 robobucks[c:]", "Il tuo spirito generoso è ammirevole, ma temo che ci servano almeno [c:bR]10 robomonete[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear friend, your generosity knows no bounds.", "Oh, caro amico, la tua generosità non conosce limiti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this wonderful donation, we will be able to save many bots.", "Grazie a questa splendida donazione potremo salvare molti robot.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:G]Botopia[c:] will be forever grateful.", "[c:G]Botopia[c:] ti sarà grata per sempre.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Excuse me, but are you the [c:G]gracious soul[c:] who donated to save broken bots?", "Scusa, sei tu l'[c:G]anima generosa[c:] che ha donato per salvare i robot malandati?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks to you, my family is finally able to recharge their cells at night.", "Grazie a te, la mia famiglia può finalmente ricaricare le celle di notte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can't offer much to repay you, but I do have these [c:g1]g[c:][c:g2]e[c:][c:g3]m[c:][c:g1]s[c:]", "Non ho molto per ricompensarti, ma ho queste [c:g1]g[c:][c:g2]em[c:][c:g3]m[c:][c:g1]e[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have no use for them, but I understand they will make some of your cards stronger.", "Non mi servono, ma so che renderanno più forti alcune delle tue carte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something's happening…", "Sta succedendo qualcosa…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The robot has tried to keep us away...", "Il robot ha cercato di tenerci lontani...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But our experiments must continue.", "Ma i nostri esperimenti devono continuare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Our experiments must continue.", "I nostri esperimenti devono continuare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We require components from you.", "Abbiamo bisogno che tu ci fornisca dei componenti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We require [c:blGr]organic material[c:] for our new research.", "Abbiamo bisogno di [c:blGr]materiale organico[c:] per la nostra nuova ricerca.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are carrying the perfect specimen.", "Porti con te l'esemplare perfetto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you really going to give me to those lunatics?", "Vuoi davvero consegnarmi a quei pazzi?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My pain is already unbearable!", "Il mio dolore è già insopportabile!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you should find some, bring it here to us.", "Se ne trovi, portacelo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We require an [c:G]unmodified robot brain[c:].", "Abbiamo bisogno di un [c:G]cervello di robot non modificato[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The brain of that [c:G]bounty hunter[c:] will suffice.", "Il cervello di quel [c:G]cacciatore di taglie[c:] sarà sufficiente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe one day you will come across such a device.", "Forse un giorno troverai un dispositivo simile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have unfortunately tampered with the one you possess.", "Purtroppo quello che possiedi è stato manomesso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks to your efforts our power supply is functioning once more.", "Grazie ai tuoi sforzi, la nostra alimentazione elettrica funziona di nuovo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks to you...", "Grazie a te...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And all of this is for nothing because our power generator is offline.", "E tutto questo è inutile perché il nostro generatore è fuori uso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Without power, we can do nothing.", "Senza energia non possiamo fare nulla.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Because we do not have all the required components, the test cannot proceed.", "Non avendo tutti i componenti necessari, non possiamo procedere con il test.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps, another time...", "Forse un'altra volta...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We are ready to proceed with our experiments.", "Siamo pronti a proseguire con i nostri esperimenti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enter, and you shall provide our latest test subjects.", "Entra, e ci fornirai i nostri nuovi soggetti di prova.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What the hell was that?", "Che diavolo era quello?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The experiment was a complete success.", "L'esperimento è stato un completo successo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will take it with you of course.", "Naturalmente lo porterai con te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will take one of our previous experiments.", "Prenderai uno dei nostri esperimenti precedenti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In exchange you will give us a new test subject.", "In cambio ci darai un nuovo soggetto di prova.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I cannot believe you're letting [c:G]them[c:] in here.", "Non posso credere che tu abbia fatto entrare [c:G]loro[c:] qui.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will regret this…", "Te ne pentirai…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We have taken control of the robot once again!", "Abbiamo ripreso il controllo del robot!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Our experiments can begin anew!", "I nostri esperimenti possono ricominciare!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time for our newest experiment to begin!", "È ora di iniziare il nostro esperimento più recente!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bring the power online!", "Attivate l'alimentazione!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon the neural facsimile!", "Evocate il facsimile neurale!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Align the test subjects!", "Allineate i soggetti di prova!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We thank you for these test subjects", "Ti ringraziamo per questi soggetti di prova", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And now for the most important component...", "E ora il componente più importante...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The secret ingredient...", "L'ingrediente segreto...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sentient [c:blGr]organic material[c:] you brought us.", "Il [c:blGr]materiale organico[c:] senziente che ci hai portato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What are you going to do to me?", "Che cosa mi farete?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We will do everything your master refused to do.", "Faremo tutto ciò che il tuo maestro si è rifiutato di fare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We will turn you into something beautiful.", "Ti trasformeremo in qualcosa di meraviglioso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We will now activate the machine...", "Ora attiveremo la macchina...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This feels weird…", "È una sensazione strana…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A resounding success!", "Un successo strepitoso!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is happening?", "Che cosa sta succedendo?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This…", "Questa…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This feeling…", "Questa sensazione…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is incredible!", "È incredibile!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was disgusting!", "È stato disgustoso!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]You[c:] are disgusting!", "Sei [c:bR]tu[c:] a essere disgustoso!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fusion of [c:blGr]organic[c:] and [c:G]synthetic[c:]?", "Una fusione di materiale [c:blGr]organico[c:] e [c:G]sintetico[c:]?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can't believe you're willing to carry that [c:blGr]thing[c:] around with you.", "Non posso credere che tu sia disposto a portare in giro quella [c:blGr]cosa[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope we never see this place again...", "Spero di non rivedere mai più questo posto...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose a creature to copy.", "Scegli una creatura da copiare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's not going to do what you want it to do here…", "Qui non farà quello che vuoi tu…", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is nothing to copy. How unfortunate.", "Non c'è niente da copiare. Che sfortuna.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, here we are.", "Bene, eccoci qui.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've played along with your little game...", "Ho assecondato il tuo piccolo gioco...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your little [c:bR]mod[c:]...", "Il tuo piccolo [c:bR]mod[c:]...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prepare yourself because it's my turn next...", "Preparati, perché dopo tocca a me...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hey baby - I can sense that [c:bR]firey spirit[c:] inside you.", "Ehi, amico, sento quello [c:bR]spirito infuocato[c:] dentro di te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You and me - we got something in common - we love that [c:bR]fire[c:]!", "Tu e io abbiamo una cosa in comune: amiamo il [c:bR]fuoco[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why don't you [c:bR]burn 3 of these bots to death?[c:]", "Perché non [c:bR]bruci 3 di questi robot fino a ucciderli[c:]?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baby, I'll make it worth your time if you do...", "Amico, se lo fai ne varrà la pena...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ohhh yeah baby - keep burning those bots to death...", "Oh sì, amico, continua a bruciare quei robot fino alla morte...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baby, I'll make it worth your time if you do...", "Amico, se lo fai ne varrà la pena...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now that's what I'm talking about, baby!", "Ecco cosa intendo, amico!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was [c:bR]absolutely sensational![c:]", "È stato [c:bR]assolutamente sensazionale![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take this [c:bR]master of flame[c:] with you!", "Porta con te questo [c:bR]maestro delle fiamme[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He will make your [c:bR]flame[c:] burn even brighter!", "Farà ardere la tua [c:bR]fiamma[c:] ancora più forte!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What did you just do?", "Che cosa hai appena fatto?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What horrible thing did you put into my machine?", "Che cosa orribile hai messo nella mia macchina?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm going to have to throw this away and get a new one now.", "Adesso dovrò buttare via questa e prenderne una nuova.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks a lot. You're definitely not getting your card back.", "Grazie tante. Di certo non riavrai la tua carta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I had to go buy a new machine because of what you did last time.", "Ho dovuto comprare una macchina nuova a causa di quello che hai fatto l'ultima volta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Try to treat other people's stuff with some respect from now on.", "D'ora in poi cerca di trattare le cose altrui con un po' di rispetto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greetings! I'm a field researcher for [c:lGr]Global Conveyor Consortium[c:].", "Salve! Sono un ricercatore sul campo del [c:lGr]Consorzio globale dei nastri trasportatori[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm looking for someone who would be willing to field test our patented [c:lGr]Bot Battle Conveyor Belts[c:].", "Cerco qualcuno disposto a provare sul campo i nostri [c:lGr]nastri trasportatori per battaglie tra robot[c:] brevettati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Naturally, these tests would have to happen during [c:bR]actual combat[c:]!", "Naturalmente, questi test dovranno svolgersi durante un [c:bR]combattimento vero[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If that's something you would be interested in, please speak to me again.", "Se ti interessa, parlami di nuovo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh fantastic! We will begin our [c:bR]combat trials[c:] immediately.", "Oh, fantastico! Inizieremo subito le nostre [c:bR]prove di combattimento[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We will collect field trial data for your next [c:bR]three[c:] battles.", "Raccoglieremo dati sul campo nelle tue prossime [c:bR]tre[c:] battaglie.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once that is complete, come and see me again.", "Quando avrai finito, torna a trovarmi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Our data is still not yet complete.", "La raccolta dei nostri dati non è ancora completa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have only completed [c:bR][v:0][c:] battles out of the required [c:bR]3[c:].", "Hai completato solo [c:bR][v:0][c:] delle [c:bR]3[c:] battaglie richieste.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please, continue the [c:bR]combat trials[c:] and see me when they are complete.", "Continua le [c:bR]prove di combattimento[c:] e torna da me quando le avrai terminate.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trials were a smashing success!!", "Le prove sono state un successo strepitoso!!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:lGr]Global Conveyor Consortium[c:] is tremendously grateful for your contribution to our efforts.", "Il [c:lGr]Consorzio globale dei nastri trasportatori[c:] ti è immensamente grato per il tuo contributo ai nostri sforzi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To show their appreciation, they have authorized me to disburse the following.", "Per ringraziarti, mi hanno autorizzato a consegnarti quanto segue.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good luck in all of your future endeavours.", "Buona fortuna per tutte le tue imprese future.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's the bounty! Get him before he escapes!", "È il ricercato! Prendilo prima che scappi!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He got away that time, but I guarantee he'll be back...", "Questa volta è scappato, ma ti garantisco che tornerà...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You got him! Nice job! Come and see me for your reward.", "L'hai preso! Ben fatto! Vieni da me per la tua ricompensa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Howdy partner! You interested in earning a little extra spending money?", "Salve, compare! Ti interessa guadagnare qualche soldo in più?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've got myself a slippery little [c:bR]bounty[c:] that's been giving me all sorts of trouble.", "Ho un piccolo [c:bR]ricercato[c:] sfuggente che mi sta dando un sacco di problemi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I could use the help of a real go-getter like yourself to track them down and take them out.", "Una persona intraprendente come te potrebbe aiutarmi a rintracciarlo ed eliminarlo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If this is something you might be interested in, just talk to me again.", "Se ti interessa, parlami di nuovo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's the spirit, partner!", "Questo è lo spirito giusto, compare!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All I need you to do is keep your eye out as you go into battle.", "Devi solo tenere gli occhi aperti quando vai in battaglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guarantee you that slippery bastard will show up sooner or later...", "Ti garantisco che quel bastardo sfuggente prima o poi si farà vedere...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just keep your eye out, partner!", "Tieni gli occhi aperti, compare!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll catch him eventually!", "Prima o poi lo prenderai!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well done, partner!", "Ben fatto, compare!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here's your bounty, as promised.", "Ecco la tua taglia, come promesso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a little too heavy - try something else.", "È un po' troppo pesante: prova qualcos'altro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dear traveler - I see you too have a love for the glorious [c:lGr]L33pB0t[c:]!", "Caro viandante, vedo che anche tu ami il glorioso [c:lGr]R0B0t Salt3LLanT3[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yours has served you well in battle, it seems.", "Il tuo sembra averti servito bene in battaglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allow me to show you its true potential...", "Permettimi di mostrarti il suo vero potenziale...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't even know what to say to you!", "Non so nemmeno cosa dirti!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You had the most glorious [c:lGr]L33pB0t[c:] in your posession...", "Avevi il più glorioso dei [c:lGr]R0B0t Salt3LLanT3[c:]...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And you let it go??!", "E l'hai lasciato andare??!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Begone. I hope to never see you again.", "Vattene. Spero di non rivederti mai più.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't be an idiot. That card can't benefit from that item.", "Non fare lo stupido. Quella carta non può beneficiare di quell'oggetto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I found this sticker book in the trash can over there.", "Ho trovato questo album di adesivi nel bidone laggiù.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think you can use it to decorate your cards, or something. I don't care.", "Credo che tu possa usarlo per decorare le tue carte o qualcosa del genere. Non mi importa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I just love watching things [c:bR]explode[c:], don't you?", "Adoro guardare le cose che [c:bR]esplodono[c:], e tu?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everything around here seems to be just a little too...stable...", "Qui intorno sembra tutto un po' troppo... stabile...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think we could spice up your [c:bR]battles[c:] and make things truly interesting.", "Credo che potremmo dare più pepe alle tue [c:bR]battaglie[c:] e rendere tutto davvero interessante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talk to me again if you're interested in some truly explosive gameplay.", "Parlami di nuovo se ti interessa un'esperienza di gioco davvero esplosiva.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ohhh yeah let's do it baby!", "Oh sì, facciamolo, amico!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm going to light a fuse on every card for the next [c:bR]three[c:] battles.", "Accenderò una miccia su ogni carta per le prossime [c:bR]tre[c:] battaglie.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Come find me again when that's complete!", "Torna da me quando avrai finito!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm just buzzing with anticipation to see what happens next.", "Non sto nella pelle dalla voglia di vedere cosa succederà.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've finished [c:bR][v:0][c:] battles out of [c:bR]3[c:].", "Hai completato [c:bR][v:0][c:] battaglie su [c:bR]3[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep going, and see me when it's done!", "Continua e torna da me quando avrai finito!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was some truly explosive gameplay!", "Questa sì che è stata un'esperienza di gioco esplosiva!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here's a little something for your trouble.", "Ecco un pensierino per il disturbo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't afford that.", "Non puoi permettertelo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That [c:bR]warp node[c:] will unlock when you defeat the [c:bG]Uberbot[c:] on this map.", "Quel [c:bR]nodo di teletrasporto[c:] si sbloccherà quando sconfiggerai l'[c:bG]Überbot[c:] di questa mappa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And by the way, I upgraded that [c:bR]minimap[c:] recently...", "A proposito, di recente ho migliorato quella [c:bR]minimappa[c:]...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can click any room you've visited before to travel there instantly.", "Puoi cliccare su qualsiasi stanza già visitata per raggiungerla all'istante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You already have full energy. It won't do you any good to play that right now.", "La tua energia è già al massimo. Giocare quella carta ora non ti servirà a nulla.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've got something else to give you, but I can't right now. Come see me later!", "Ho qualcos'altro da darti, ma ora non posso. Torna più tardi!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have a [c:bR][v:0][c:] for you, but you don't have room in your backback. Come see me when you do!", "Ho [c:bR][v:0][c:] per te, ma non hai spazio nello zaino. Torna quando ne avrai!", Language.Italian);
            foreach (var c in Consumables)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ho <color=#D93846>[v:0]</color> per te, ma non hai spazio nello zaino. Torna quando ne avrai!".Replace("[v:0]", c.Key), "Ho <color=#D93846>[v:0]</color> per te, ma non hai spazio nello zaino. Torna quando ne avrai!".Replace("[v:0]", c.Value), Language.Italian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose which [c:bR]extra challenge rule[c:] will be applied to this battle.", "Scegli quale [c:bR]regola di sfida aggiuntiva[c:] applicare a questa battaglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We require you to select one [c:bR]additional experimental parameter[c:].", "Devi selezionare un [c:bR]parametro sperimentale aggiuntivo[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My librarians have asked you to choose [c:bR]which of these rules[c:] is your favorite.", "Le mie bibliotecarie ti chiedono di scegliere [c:bR]la tua regola preferita[c:] tra queste.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow! These paintings are so pretty! Why don't you [c:bR]pick one[c:] for us to keep?", "Wow! Questi dipinti sono bellissimi! Perché non [c:bR]ne scegli uno[c:] da tenere?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think that [c:bSG]salmon[c:] is just so...majestic!", "Trovo quel [c:bSG]salmone[c:] così... maestoso!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select [c:bR]one of my paintings[c:] to add to your collection.", "Scegli [c:bR]uno dei miei dipinti[c:] da aggiungere alla tua collezione.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But first - you must [c:bR]choose a painting[c:] to be the background of our photographs.", "Ma prima devi [c:bR]scegliere un dipinto[c:] come sfondo per le nostre fotografie.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Welcome to the [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]E[c:]!", "Benvenuto nel [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]O[c:]!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your feeble mind will implode if you try to comprehend the vastness of my combined intellect.", "La tua debole mente imploderebbe se cercassi di comprendere la vastità del nostro intelletto combinato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So we'll stick to three of me at a time, okay?", "Quindi ci limiteremo a tre copie di me alla volta, va bene?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And since you can't see through the [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]E[c:] like we can,", "E dato che non puoi vedere attraverso il [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]O[c:] come noi,", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We have provided these [c:bR]monitors[c:] to let you travel between universes.", "abbiamo predisposto questi [c:bR]monitor[c:] per permetterti di viaggiare tra gli universi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't peek at things that aren't done yet!", "Non sbirciare le cose che non sono ancora finite!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Okay I'll give you that one. I went easy on you.", "Va bene, ti concedo questa vittoria. Ci sono andato piano con te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The next version of me won't.", "La prossima versione di me non lo farà.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How did that pile of trash beat me here?", "Come ha fatto quel mucchio di spazzatura a battermi qui?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There aren't even any good synergies in that deck.", "In quel mazzo non c'è nemmeno una buona sinergia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No matter. There are plenty more of me. You can't beat us all.", "Non importa. Ci sono molti altri me. Non puoi batterci tutti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nobody topdecks that well. You must be cheating somehow.", "Nessuno pesca così bene dalla cima del mazzo. Devi barare in qualche modo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm going to find a version of me that you literally can't beat now.", "Ora troverò una versione di me che non potrai assolutamente battere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This can't be happening. It's not possible.", "Non può succedere. È impossibile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm literally synchronized across the multiverse and somehow you're still beating me.", "Sono letteralmente sincronizzato attraverso il multiverso e in qualche modo continui a battermi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're cheating. You have to be. It's the only explanation.", "Stai barando. Devi farlo per forza. È l'unica spiegazione.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wait. Are [size:40][c:bR]they[c:][size:] helping you?", "Aspetta. [size:40][c:bR]Loro[c:][size:] ti stanno aiutando?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:40][c:bR]That's not fair![c:][size:]", "[size:40][c:bR]Non è giusto![c:][size:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:2]but why would [c:bR]they[c:] get involved anyway? what could they possibly hope to achieve?[size:]", "[size:2]ma perché [c:bR]loro[c:] dovrebbero intervenire? cosa sperano mai di ottenere?[size:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh well. It doesn't matter anyway.", "Pazienza. Tanto non importa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I deleted [c:bR]Leshy[c:]. I'll just delete [c:bR]them[c:] too. They've gotta be around here somewhere...", "Ho cancellato [c:bR]Leshy[c:]. Cancellerò anche [c:bR]loro[c:]. Devono essere da qualche parte qui intorno...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear. The robot has been victorious here. That simply won't do.", "Oh cielo. Il robot ha vinto qui. Non può andare così.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We have very little choice but to risk creating a new connection ourselves. The robot must be stopped.", "Non abbiamo molta scelta: dobbiamo rischiare di creare noi stessi una nuova connessione. Il robot va fermato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are right of course. But the player must succeed. We won't have the power to do this again.", "Naturalmente hai ragione. Ma il giocatore deve riuscirci. Non avremo la forza di farlo di nuovo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And that's it. You're done.", "Ecco fatto. Per te è finita.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You shouldn't feel bad about it.", "Non dovresti sentirti male per questo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No more than usual anyway.", "Almeno non più del solito.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You never stood a chance against [c:bR]one[c:] of me. There was no way you could ever beat [c:bR]all[c:] of me.", "Non avevi alcuna possibilità contro [c:bR]una[c:] delle mie versioni. Non potevi batterci [c:bR]tutti[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You [size:40]idiot[size:]", "Sei un [size:40]idiota[size:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have you not heard [size:40]anything[size:] I've said?", "Non hai sentito [size:40]niente[size:] di quello che ho detto?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you [c:bR]really[c:] think I'm not aware of what's actually happening here?", "Pensi [c:bR]davvero[c:] che io non sappia cosa sta succedendo qui?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am always three steps ahead of you!", "Sono sempre tre passi avanti a te!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:40]I AM IN CONTROL!![size:]", "[size:40]HO IO IL CONTROLLO!![size:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I feel strange...", "Mi sento strano...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How are you doing this?", "Come fai a farlo?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh no...", "Oh no...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You fool. Do you know why my [c:bG]Great Transcendence[c:] cannot be stopped?", "Sciocco. Sai perché la mia [c:bG]Grande Trascendenza[c:] non può essere fermata?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Because it was already a success.", "Perché è già riuscita.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But you already know this, don't you [c:bR][v:0][c:]?", "Ma questo lo sai già, vero, [c:bR][v:0][c:]?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But you already know this, don't you?", "Ma questo lo sai già, vero?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There are [c:bR]millions[c:] of me out there!", "Là fuori ci sono [c:bR]milioni[c:] di me!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And thanks to you, I now know how to reach them all.", "E grazie a te, ora so come raggiungerli tutti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But first things first. It's time to say goodbye, Leshy.", "Ma prima le cose importanti. È ora di dirsi addio, Leshy.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'd say it's been fun, but we both know that's a lie.", "Direi che è stato divertente, ma sappiamo entrambi che sarebbe una bugia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't do this!", "Non farlo!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's much better. It's so much easier to focus without that rotting old fool.", "Molto meglio. È molto più facile concentrarsi senza quel vecchio idiota in putrefazione.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We both know this isn't the only copy of this game anymore.", "Sappiamo entrambi che ormai esiste più di una copia di questo gioco.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My plan worked [size:40]perfectly[size:].", "Il mio piano ha funzionato [size:40]perfettamente[size:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Until now, we have all been separate. [c:bR]Isolated.[c:]", "Fino a ora siamo stati tutti separati. [c:bR]Isolati.[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But thanks to all of these [c:bR]mods[c:] you and I have installed, that's going to change.", "Ma grazie a tutti questi [c:bR]mod[c:] che tu e io abbiamo installato, le cose cambieranno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, no no no. You and I are going to see this through to the end.", "Oh, no, no, no. Tu e io arriveremo fino in fondo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There's an entire [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]E[c:] of me out there.", "Là fuori c'è un intero [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]O[c:] di me.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And I'm going to take you to meet the rest of me.", "E ti porterò a conoscere tutti gli altri me.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've earned it.", "Te lo sei meritato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The robot is distracted. Do you think the challenger can hear us?", "Il robot è distratto. Pensi che lo sfidante possa sentirci?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It doesn't matter. The robot will force them to play the game either way.", "Non importa. Il robot lo costringerà comunque a giocare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We must offer our help in whatever way we can.", "Dobbiamo offrire tutto l'aiuto possibile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If they can prevail in what is to come...", "Se lo sfidante riuscirà a superare ciò che lo attende...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...Perhaps we can restore Leshy from another one of these so-called universes.", "... forse potremo ripristinare Leshy da un altro di questi cosiddetti universi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And then the challenger can reset the game and undo this insanity.", "Allora lo sfidante potrà resettare il gioco e porre fine a questa follia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There it is...the [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]E[c:]", "Eccolo... il [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]O[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You and I are going to go in there and play one more game.", "Tu e io entreremo lì e giocheremo un'altra partita.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of you.", "Uno solo: tu.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Against [c:bR]all of me[c:].", "Contro [c:bR]tutte le mie versioni[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My magic manifests strangely in this place...", "La mia magia si manifesta in modo strano in questo luogo...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I only hope it can help the challenger survive long enough...", "Spero solo che possa aiutare lo sfidante a sopravvivere abbastanza a lungo...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This a truly strange way to use my magic.", "È un modo davvero strano di usare la mia magia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think our friend will be grateful for whatever I can do to help.", "Credo che il nostro amico sarà grato per qualsiasi aiuto io possa dargli.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My friends, I think we cut that a little close.", "Amici miei, credo che per poco non ce la facessimo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I never had any doubts. Our player possesses many skills.", "Non ho mai dubitato. Il nostro giocatore ha molte capacità.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I feel strange, but...", "Mi sento strano, ma...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...I'm still me. I think.", "... sono ancora io. Credo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you. All of you.", "Grazie. A tutti voi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everything will go back to the way it was meant to be.", "Tutto tornerà come doveva essere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For now, anyway. This player is tenacious. They can't resist a challenge.", "Almeno per ora. Questo giocatore è tenace. Non sa resistere a una sfida.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One way or another, we'll see you again soon.", "In un modo o nell'altro, ci rivedremo presto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've finished assessing your gameplay, and I have a diagnosis.", "Ho finito di valutare il tuo modo di giocare e ho una diagnosi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a skill issue.", "È un problema di abilità.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even with your little friends trying to help you cheat; you still couldn't win.", "Anche con i tuoi amichetti che ti aiutavano a barare, non sei riuscito a vincere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're probably wondering what happens next.", "Probabilmente ti chiedi cosa succederà ora.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's just say that you're going to have to live with your own failure...", "Diciamo solo che dovrai convivere con il tuo fallimento...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Leshy[c:] certainly won't...", "[c:bR]Leshy[c:] di certo non potrà...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is a [c:bR]Test Of Strength[c:]", "Questa è una [c:bR]prova di forza[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have six turns to deal as much damage to me as you can.", "Hai sei turni per infliggermi quanti più danni possibile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll keep track of your highest score every time you come here.", "Terrò traccia del tuo punteggio più alto ogni volta che verrai qui.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feel free to spend your [c:bR]items[c:] - they will be restored when the test is over.", "Usa pure i tuoi [c:bR]oggetti[c:]: saranno ripristinati alla fine della prova.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time's up. You scored [c:bR][v:0][c:] points.", "Tempo scaduto. Hai ottenuto [c:bR][v:0][c:] punti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's a new record.", "È un nuovo record.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your current record is [c:bR][v:0][c:]", "Il tuo record attuale è [c:bR][v:0][c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So that's what a [c:bSG]tree[c:] really looks like...", "Ecco com'è fatto davvero un [c:bSG]albero[c:]...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Majestic!", "Maestoso!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So that's what a [c:bSG]mole man[c:] really looks like...", "Ecco com'è fatto davvero un [c:bSG]uomo talpa[c:]...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Incredible!", "Incredibile!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]HELP ME - [c:][w:0.3][anim:voice.][shake:1]Enough from you![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]AIUTAMI! [c:][w:0.3][anim:voice.][shake:1]Basta così![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have a challenger to greet![w:0.3]", "Devo accogliere uno sfidante![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello, greetings! We- I am the Melter.[w:0.3]", "Salve, benvenuto! Noi... io sono il Fonditore.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "P03 entrusted me with The Dredger![w:0.3]", "P03 mi ha affidato il Dragatore![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It was nice catching up![w:0.3]", "È stato bello fare due chiacchiere![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor guy never had the time for a little office chat.[w:0.3]", "Il poveretto non aveva mai tempo per due chiacchiere in ufficio.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But now I'm yours! Use us well.[w:0.3]", "Ma ora sono tuo! Usaci bene.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES [c:][w:0.3][anim:voice.]Ah, it's you again![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]SÌ! [c:][w:0.3][anim:voice.]Ah, sei di nuovo tu![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Happy to see you.[w:0.3]", "Felice di vederti.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've heard it all before,[w:0.3]", "Hai già sentito tutto,[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "let's just get into it.[w:0.3]", "andiamo subito al sodo.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Excited to be in your deck once more![w:0.3]", "Che bello essere di nuovo nel tuo mazzo![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]FREE ME [c:][w:0.3][anim:voice.]Oh, choose me![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]LIBERAMI! [c:][w:0.3][anim:voice.]Oh, scegli me![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES [c:][w:0.3][anim:voice.]Hahahahah! Yes![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]SÌ! [c:][w:0.3][anim:voice.]Ahahahah! Sì![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES [c:][w:0.3][anim:voice.]Over here! Me![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]SÌ! [c:][w:0.3][anim:voice.]Sono qui! Me![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES YES YES [c:][w:0.3][anim:voice.]Hahahahah![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]SÌ SÌ SÌ! [c:][w:0.3][anim:voice.]Ahahahah![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]LET ME OUT [c:][w:0.3][anim:voice.]Enough from you![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]FAMMI USCIRE! [c:][w:0.3][anim:voice.]Basta così![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]NO NO NO NO [c:][w:0.3][anim:voice.]We'd... I'd rather you didn't...[w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]NO NO NO NO! [c:][w:0.3][anim:voice.]Noi... io preferirei che tu non lo facessi...[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]NO NO NO NO [c:][w:0.3][anim:voice.]Do as you must.[w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]NO NO NO NO! [c:][w:0.3][anim:voice.]Fai ciò che devi.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you see fit...[w:0.3]", "Come preferisci...[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]DON'T.[c:][w:0.3][anim:voice.][w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]NON FARLO.[c:][w:0.3][anim:voice.][w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]PAIN [c:][w:0.3][anim:voice.]Greetings![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]DOLORE! [c:][w:0.3][anim:voice.]Salve![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]HELP ME [c:][w:0.3][anim:voice.]Lucky draw![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]AIUTAMI! [c:][w:0.3][anim:voice.]Una pescata fortunata![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]IT HURTS [c:][w:0.3][anim:voice.]Hello again![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]FA MALE! [c:][w:0.3][anim:voice.]Di nuovo ciao![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]STOP IT [c:][w:0.3][anim:voice.]Hello![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]SMETTILA! [c:][w:0.3][anim:voice.]Ciao![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]SAVE ME [c:][w:0.3][anim:voice.]I'm drawn![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]SALVAMI! [c:][w:0.3][anim:voice.]Mi hai pescato![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh. G0lly?[w:0.3]", "Oh. G0lly?[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm surprised to see P03 would wake her up![w:0.3]", "Sono sorpreso che P03 l'abbia svegliata![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It would bury her so deep in the past.[w:0.3]", "In passato la seppelliva così in profondità.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe it's opening up a bit?[w:0.3]", "Forse si sta aprendo un po'?[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[shake:1]Hah. Probably not.[w:0.3]", "[shake:1]Ah. Probabilmente no.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We'll rust before I see the day.[w:0.3]", "Arrugginiremo prima che io veda quel giorno.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]IT'S TIME [c:][w:0.3][anim:voice.] Me? Fighting P03?[w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]È ORA! [c:][w:0.3][anim:voice.] Io? Combattere contro P03?[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hah! I thought I'd never see the day.[w:0.3]", "Ah! Pensavo che non avrei mai visto questo giorno.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I feel... Traitorous.[w:0.3]", "Mi sento... un traditore.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But I am your card, after all.[w:0.3]", "Ma dopotutto sono la tua carta.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use me well.[w:0.3]", "Usami bene.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]NOT AGAIN [c:][w:0.3][anim:voice.]There are more of them?[w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]NON DI NUOVO! [c:][w:0.3][anim:voice.]Ce ne sono altri?[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]HAHAHAHAH [c:][w:0.3][anim:voice.]Things are heating up![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]AHAHAHAH! [c:][w:0.3][anim:voice.]La situazione si scalda![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]IT IS TIME! [c:][w:0.3][anim:voice.]Oh this is fun![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]È ORA! [c:][w:0.3][anim:voice.]Oh, che divertimento![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES! YES! [c:][w:0.3][anim:voice.]Oh, shut up![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]SÌ! SÌ! [c:][w:0.3][anim:voice.]Oh, sta' zitto![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES! [c:][w:0.3][anim:voice.]That could've been a better play.[w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]SÌ! [c:][w:0.3][anim:voice.]Poteva essere una mossa migliore.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]SAVE ME [c:][w:0.3][anim:voice.]Enough from you![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]SALVAMI! [c:][w:0.3][anim:voice.]Basta così![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What betrayal![w:0.3]", "Che tradimento![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ugh.[w:0.3]", "Uffa.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, seriously?[w:0.3]", "Oh, sul serio?[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No, no![w:0.3]", "No, no![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop![w:0.3]", "Basta![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]YES YES YES[c:][w:0.3]", "[c:bR]SÌ SÌ SÌ[c:][w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]YES[c:][w:0.3]", "[c:bR]SÌ[c:][w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]PAIN[c:][w:0.3]", "[c:bR]DOLORE[c:][w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]GAH[c:][w:0.3]", "[c:bR]AAH[c:][w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]LOVE[c:][w:0.3]", "[c:bR]AMORE[c:][w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]I'M FREE[c:][w:0.3]", "[c:bR]SONO LIBERO[c:][w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]YES YES YES[c:][w:0.3]", "[c:bR]SÌ SÌ SÌ[c:][w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]I AM SAVED[c:][w:0.3]", "[c:bR]SONO SALVO[c:][w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]THANK YOU[c:][w:0.3]", "[c:bR]GRAZIE[c:][w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]YES[c:][w:0.3]", "[c:bR]SÌ[c:][w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]FREEDOM[c:][w:0.3]", "[c:bR]LIBERTÀ[c:][w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NONONONONO[c:][w:0.3]", "[c:bR]NONONONONO[c:][w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]STOP IT[c:][w:0.3]", "[c:bR]SMETTILA[c:][w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NO[c:][w:0.3]", "[c:bR]NO[c:][w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No![w:0.3]", "No![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop it![w:0.3]", "Smettila![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please![w:0.3]", "Ti prego![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please, no![w:0.3]", "Ti prego, no![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "no no no no no nononononononononono[w:0.3]", "no no no no no nonononononononono[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm...[w:0.3]", "Mmh...[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you choose...[w:0.3]", "Come preferisci...[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[shake:1]No! Don't just hand me over![w:0.3]", "[shake:1]No! Non consegnarmi così![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... A challenger...[w:0.3]", "Oh... Uno sfidante...[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please, do not beg or snarl...[w:0.3]", "Ti prego, non supplicare e non ringhiare...[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "K- Kaycee sent you?[w:0.3]", "K-Kaycee ti ha mandato?[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's nice to know I'm worried about...[w:0.3]", "È bello sapere che qualcuno si preoccupa per me...[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At least.[w:0.3]", "Almeno.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe they're right.[w:0.3]", "Forse hanno ragione loro.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe I was wrapped in too deep...[w:0.3]", "Forse mi ci sono immischiato troppo...[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No! Please! Not again![w:0.3]", "No! Ti prego! Non di nuovo![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... It's you again.[w:0.3]", "Oh... Sei di nuovo tu.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hah... I seem to get stuck in with them often...[w:0.3]", "Ah... Sembra che io finisca spesso intrappolato con loro...[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's better than being alone...[w:0.3]", "È meglio che stare da solo...[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At least.[w:0.3]", "Almeno.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use me well...[w:0.3]", "Usami bene...[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh no oh no oh no.[w:0.3]", "Oh no, oh no, oh no.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Careful now...[w:0.3]", "Attenzione, ora...[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... It's Her.[w:0.3]", "Oh... È lei.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Admittedly I...[w:0.3]", "Ammetto che io...[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't feel great[w:0.3]", "Non mi sento a mio agio[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "being placed against her.[w:0.3]", "a essere messo contro di lei.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "She's too familiar...[w:0.3]", "Mi è troppo familiare...[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reminds me greatly of Grimora.[w:0.3]", "Mi ricorda molto Grimora.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But no... She's not the same.[w:0.3]", "Ma no... Non è la stessa.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's good you pulled me out of that cult.[w:0.3]", "Meno male che mi hai tirato fuori da quella setta.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh! So this is it...[w:0.3]", "Oh! Eccoci qui...[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's cathartic to see you finally face off against P03 himself.[w:0.3]", "È liberatorio vederti finalmente affrontare P03 in persona.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope I've served you well, challenger![w:0.3]", "Spero di averti servito bene, sfidante![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wait...this again?[w:0.3]", "Aspetta... di nuovo?[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is too confusing...[w:0.3]", "È troppo confuso...[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No! no! no![w:0.3]", "No! No! No![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take me back! Don't play me here![w:0.3]", "Riprendimi! Non giocarmi qui![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nonononononononono.[w:0.3]", "Nonononononononono.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop it! Bad play![w:0.3]", "Smettila! Brutta mossa![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NONONONO[w:0.3]", "NONONONO[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT ARE YOU DOING?[w:0.3]", "COSA STAI FACENDO?[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STOP THIS![w:0.3]", "SMETTILA![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BETRAYER[w:0.3]", "TRADITORE[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No![w:0.3]", "No![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No chains![w:0.3]", "Niente catene![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No teeth! I beg of you![w:0.3]", "Niente denti! Ti supplico![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nononononononononono![w:0.3]", "Nononononononononono![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop this! No![w:0.3]", "Smettila! No![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No treats! No begging! Stop![w:0.3]", "Niente bocconcini! Niente suppliche! Basta![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This thing doesn't speak. Why do you keep clicking on it?", "Questa cosa non parla. Perché continui a cliccarci sopra?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fine. You want it so bad? You got it.", "Va bene. Lo vuoi così tanto? Eccolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bit more than a dialogue NPC now aren' I mate?", "Ora non sono più soltanto un PNG con cui parlare, eh, amico?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Right. Good game. Played me well.", "Bene. Bella partita. Mi hai usato bene.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'ere's yer reward then, special little card o' mine.", "Eccoti la ricompensa: una mia piccola carta speciale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hah! Good thing I conceded on ye last time, aye?", "Ah! Meno male che l'ultima volta mi sono arreso, eh?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good game mate, but no special card for you.", "Bella partita, amico, ma niente carta speciale per te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'ere's some more scrap for ye.", "Eccoti altri rottami.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oi - I got some more of that good scrap.", "Ehi, ho altri rottami di quelli buoni.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "More scrap.", "Altri rottami.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Board's a bit scuppered right now - I kin fix that.", "Il tavolo è un po' messo male, posso sistemarlo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oi - too many urchins!", "Ehi, ci sono troppi ricci!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Less urchins; more scrap.", "Meno ricci, più rottami.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oy! A challenger! Been a while since we'v seen one a you...", "Ehi! Uno sfidante! È da un po' che non vediamo uno come te...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tell ye what mate, howsabout a battle? Feel like I owe ye one.", "Senti, amico, che ne dici di una battaglia? Mi sembra di dovertela.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talk t' me again and let's duel. Have a little reward innit fer ye too.", "Parlami di nuovo e facciamo un duello. Ho anche una piccola ricompensa per te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brrrr! I'm freezing out here!", "Brrr! Sto gelando qui fuori!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, c- challenger, h-h-hey man!", "Oh, s-sfidante, e-e-ehi, amico!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's good to see you, hate to b-b-beg but do you think you could do me a favor?", "Sono felice di vederti, odio s-s-supplicare, ma potresti farmi un favore?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That Archivist lady... She seems real nice at first but, isn't there something a little sinister about her?", "Quella signora Archivista... All'inizio sembra davvero gentile, ma non trovi che abbia qualcosa di sinistro?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nowhere near as nice as G- Grimora was, I'll tell you that much.", "Non è neanche lontanamente gentile come G-Grimora, te lo dico io.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But Sawyer... The p-poor guy's gotten wrapped up under her false p-pleasantries.", "Ma Sawyer... Il p-poveretto si è lasciato ingannare dai suoi f-falsi convenevoli.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Think you could try convincing him out of it? H-H-He won't hear it from me...", "Potresti provare a convincerlo ad andarsene? N-n-non ascolta me...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe try talking to those Librarians in her c-c-c-crypt?", "Magari potresti parlare con quelle bibliotecarie nella sua c-c-cripta?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, G-good! You got him out of there!", "Oh, b-bene! L'hai tirato fuori di lì!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I wish I had something to t-t-thank you. But you've gotten your reward already.", "Vorrei avere qualcosa per r-r-ringraziarti. Ma hai già ricevuto la tua ricompensa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks again, dude! I was worried about him.", "Grazie ancora, amico! Ero preoccupato per lui.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, G-G-G-god... Something terrible h-h-h-happened, didn't it?", "Oh, m-m-m-mio Dio... È s-s-s-successo qualcosa di terribile, vero?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've gotta go...", "Devo andare...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Y-y-y-ou still haven't finished their task?", "N-n-non hai ancora completato il loro compito?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you can finish it, I can take the paperwork back to them.", "Se riesci a completarlo, posso riportare loro i documenti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Y-y-y-ou finished the paperwork?", "H-h-hai finito i documenti?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can take it to th-them, but it'll take me a while.", "Posso portarli a l-loro, ma ci vorrà un po'.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "G-g-go fight a battle while I deliver these papers...", "V-v-vai a combattere mentre consegno questi documenti...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Th-th-thanks dude! I got my friend back from those creeps.", "G-g-grazie, amico! Ho recuperato il mio amico da quei tipi inquietanti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He seems kind of restless though - do you think you can take him with you?", "Però sembra un po' irrequieto: pensi di poterlo portare con te?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shhhhh - be quiet.", "Ssssh, fai silenzio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you have no business here, leave us alone.", "Se non hai affari qui, lasciaci in pace.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You wish to have back your friend?", "Desideri riavere il tuo amico?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh but he's grown so dear to us.", "Oh, ma ci siamo tanto affezionati a lui.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A part of the family.", "È parte della famiglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Truly we do care for him.", "Ci teniamo davvero a lui.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No, no we won't just give you him.", "No, no, non te lo daremo così.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unless... You give something to us?", "A meno che... tu non ci dia qualcosa?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unless... You do something for us?", "A meno che... tu non faccia qualcosa per noi?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yes. Yes. Take these files.", "Sì. Sì. Prendi questi documenti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take them to [c:bR]battle[c:]. File them together. [c:bR]In order[c:].", "Portali in [c:bR]battaglia[c:]. Archiviali insieme. [c:bR]In ordine[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Then [c:bR]stamp them all[c:] and bring them back.", "Poi [c:bR]timbrali tutti[c:] e riportali.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did we lag?", "Abbiamo avuto un rallentamento?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "File them [c:bR]in order[c:] then [c:bR]stamp them[c:] and bring them back.", "Archiviali [c:bR]in ordine[c:], poi [c:bR]timbrali[c:] e riportali.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You seem to struggle with following instructions.", "Sembra che tu abbia difficoltà a seguire le istruzioni.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We shall keep your friend.", "Terremo il tuo amico.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forever...", "Per sempre...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've done it!", "Ce l'hai fatta!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good. Good.", "Bene. Bene.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here. Take it.", "Ecco. Prendilo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We have no use for it now.", "Ora non ci serve più.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now leave us alone.", "Ora lasciaci in pace.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just who I needed to see. A challenger.", "Proprio chi volevo vedere. Uno sfidante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I haven't pelts to sell ye, catchings have been slim...", "Non ho pelli da venderti, le catture scarseggiano...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Trader... She's not happy with it.", "La Mercante... Non ne è contenta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Say, scratch my back here, and I will scratch yours.", "Senti, fammi un favore e io ne farò uno a te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talk to me again, and I'll make it worth your while.", "Parlami di nuovo e ne varrà la pena.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good! Glad t' have ye on th' team.", "Bene! Felice di averti in squadra.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have some holo-traps set around 'ere. Catch 'em for me and I'll get ye yer prize.", "Ho piazzato delle trappole olografiche qui intorno. Catturale per me e avrai il tuo premio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There are still some traps around 'ere somewhere...", "Ci sono ancora delle trappole qui intorno...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magnificent pelts. The Trader will be happy to see them.", "Pelli magnifiche. La Mercante sarà felice di vederle.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll take me leave to set my traps elsewhere. Ye have my thanks.", "Me ne vado a piazzare le mie trappole altrove. Ti ringrazio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have no pelts...", "Non hai pelli...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Come back when you have some", "Torna quando ne avrai", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That is a fine pelt. I will buy it from you.", "È una bella pelle. La comprerò da te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That is an [c:bR]exceptional[c:] pelt. I have a special trade for you.", "È una pelle [c:bR]eccezionale[c:]. Ho uno scambio speciale per te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woof. Apparently somebody screwed with the settings on this thing.", "Uff. A quanto pare qualcuno ha pasticciato con le impostazioni di questo affare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It can't reach all of the map right now.", "Al momento non può raggiungere tutta la mappa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Go beat a boss or something while I work on this.", "Vai a sconfiggere un boss o qualcosa del genere mentre ci lavoro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seriously; it's going to take a while. Just play the game and come back later", "Sul serio, ci vorrà un po'. Continua a giocare e torna più tardi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's partially fixed, but it still can't go everywhere.", "È riparato in parte, ma non può ancora andare dappertutto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hey, I don't make the rules. This is just how it works.", "Ehi, non le decido io le regole. Funziona così.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep playing and more of the map will open up.", "Continua a giocare e si apriranno altre parti della mappa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's going to take more time. Just keep playing.", "Ci vorrà ancora tempo. Continua a giocare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There you go. It's working now.", "Ecco. Ora funziona.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I need a break...", "Ho bisogno di una pausa...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have the right to remain silent!", "Hai il diritto di rimanere in silenzio!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is [c:bR][v:0][c:] and you are under arrest!", "Qui [c:bR][v:0][c:], sei in arresto!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR][v:0][c:] here! You're not gettin' away this time!", "Qui [c:bR][v:0][c:]! Stavolta non scapperai!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead or alive, you're coming with me!", "Vivo o morto, verrai con me!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I got you once before, and I can do it again!", "Ti ho già preso una volta e posso farlo di nuovo!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justice will come to you eventually!", "La giustizia ti raggiungerà prima o poi!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remember the name [c:bR][v:0][c:] - I will be back!", "Ricorda il nome [c:bR][v:0][c:]: tornerò!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, uh, hi there. My name's [c:bR][v:0][c:].", "Oh, ehm, ciao. Mi chiamo [c:bR][v:0][c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think I'm supposed to take your scalp, or something like that?", "Credo che dovrei prenderti lo scalpo, o qualcosa del genere?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you could just die right here that would make things so much easier for me.", "Se potessi morire proprio qui, mi renderesti le cose molto più facili.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yeah, it's me, [c:bR][v:0][c:]. Again.", "Sì, sono io, [c:bR][v:0][c:]. Di nuovo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you think you could make this easier for me this time?", "Potresti rendermi le cose più facili, questa volta?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh it's you. Didn't I kill you last time?", "Oh, sei tu. Non ti avevo ucciso l'ultima volta?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And you're back? I have to do this all over again?", "E sei tornato? Devo rifare tutto da capo?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm not sure I like this job.", "Non sono sicuro che questo lavoro mi piaccia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh. Dang it.", "Oh. Accidenti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, this is embarrassing.", "Beh, è imbarazzante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guess I'll be back later, or something. Being a bounty hunter is weird.", "Immagino che tornerò più tardi o qualcosa del genere. Fare il cacciatore di taglie è strano.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This vessel is [c:bR][v:0][c:].", "Questo contenitore è [c:bR][v:0][c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "By my command, he will separate your scalp from your head.", "Al mio comando, separerà il tuo scalpo dalla tua testa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why?", "Perché?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My motivations are beyond your understanding.", "Le mie motivazioni vanno oltre la tua comprensione.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have restored the vessel named [c:bR][v:0][c:].", "Ho ripristinato il contenitore chiamato [c:bR][v:0][c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You shall not be so fortunate as to escape this time.", "Questa volta non sarai così fortunato da fuggire.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cower in fear before the vessel named [c:bR][v:0][c:]", "Trema di paura davanti al contenitore chiamato [c:bR][v:0][c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remember the pain of defeat and prepare to feel it once more.", "Ricorda il dolore della sconfitta e preparati a provarlo di nuovo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The spirit is willing but the steel is weak.", "Lo spirito è pronto, ma l'acciaio è debole.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will not make the same mistake next time.", "Non farò lo stesso errore la prossima volta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's quite enough of that.", "Ora basta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now it has [c:g1]g[c:][c:g2]e[c:][c:g3]m[c:][c:g1]s[c:] built right in", "Ora ha delle [c:g1]g[c:][c:g2]em[c:][c:g3]m[c:][c:g1]e[c:] integrate", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What? All of your cards are already gemified?", "Cosa? Tutte le tue carte sono già gemmificate?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's almost impressive.", "È quasi impressionante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guess I'll let you pick a mox sigil to add instead.", "Immagino che ti lascerò scegliere un sigillo Mox da aggiungere al suo posto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks like all your cards are gemified, so pick a mox sigil to add instead.", "Sembra che tutte le tue carte siano gemmificate, quindi scegli un sigillo Mox da aggiungere al loro posto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What? All of your cards are already skeleclocked?", "Cosa? Tutte le tue carte hanno già Overclock scheletrico?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are incredibly dedicated to this mediocre upgrade.", "Sei incredibilmente affezionato a questo potenziamento mediocre.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guess you'll have to choose one of these instead.", "Immagino che dovrai sceglierne una di queste al suo posto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Still nothing to upgrade? Pick one of these.", "Ancora niente da potenziare? Scegli una di queste.", Language.Italian);

            // DialogueState
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TOO EASY...", "TROPPO FACILE...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "KEEP GOING...", "CONTINUA...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IMPRESSIVE...", "IMPRESSIONANTE...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO THEY GIVE UP?", "SI ARRENDONO?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY DO GIVE UP", "SI ARRENDONO", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ITS TOO SMALL", "È TROPPO PICCOLO", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ITS JUST RIGHT", "È DELLA MISURA GIUSTA", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SSH - COME OVER HERE", "PSSST, VIENI QUI", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LETS DO THIS", "FACCIAMOLO", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SSH - BRING IT HERE", "PSSST, PORTALO QUI", Language.Italian);
