            foreach (var value in P03InKayceesModMod.Cards)
            {
                string name;
                string nameLoc;
                if (value.Key != null && value.Key.ToLowerInvariant().Contains("skel-e"))
                {
                    name = "Skel-E-" + value.Key.Replace(" ", "-");
                    nameLoc = value.Value + " (scheletro)";
                }
                else
                {
                    name = "Skele " + value.Key;
                    nameLoc = value.Value + " (esoscheletro)";
                }
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name, nameLoc, Language.Italian);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beta " + value.Key, value.Value + " (beta)", Language.Italian);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lesser " + value.Key, value.Value + " (forma giovane)", Language.Italian);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elder " + value.Key, value.Value + " (forma anziana)", Language.Italian);
                for (int score = 0; score <= 100; score++)
                {
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, value.Key + " " + score.ToString() + ".0", value.Value + " " + score.ToString() + ".0", Language.Italian);
                }
                //string[] array = value.Key.Split(new char[] { ' ', '-' });
                //Debug.Log(((array.Length > 1) ? (array[0].ToLowerInvariant().Contains("gem") ? array[1] : array[0]) : (value.Key.Contains("bot") ? value.Key.Replace("bot", "") : value.Key)) + ", " + value.Key + ", " + value.Value);
            }

            // DialogueEvent
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glug glug glug", "Glu glu glu", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We seem to have a [c:bR]tentacle[c:] problem", "Sembra che abbiamo un problema di [c:bR]tentacoli[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you want to help out, talk to me again.", "Se vuoi aiutarci, parlami di nuovo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you for your help", "Grazie per il tuo aiuto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There are [c:bR]3[c:] tentacles that need to be destroyed.", "Ci sono [c:bR]3[c:] tentacoli da distruggere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once you've done that, come talk to me again.", "Quando avrai finito, torna a parlarmi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glug glug glug", "Glu glu glu", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have killed [c:bR][v:0][c:] tentacles.", "Hai ucciso [c:bR][v:0][c:] tentacoli.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "See me once you've killed them all.", "Torna da me quando li avrai uccisi tutti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glug glug glug", "Glu glu glu", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The scourge of the tentacles has been erased", "Il flagello dei tentacoli è stato eliminato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please take this as a token of my gratitude.", "Accetta questo come segno della mia gratitudine.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WARNING! WARNING![c:]", "[c:bR]ATTENZIONE! ATTENZIONE![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Unidentified flying objects[c:] have been spotted in the area", "Nella zona sono stati avvistati [c:bR]oggetti volanti non identificati[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You should leave [c:bR]immediately[c:] before they return.", "Dovresti andartene [c:bR]subito[c:] prima che tornino.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WARNING! WARNING![c:]", "[c:bR]ATTENZIONE! ATTENZIONE![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:bR]UFOs[c:] are arriving!", "Gli [c:bR]UFO[c:] stanno arrivando!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]CONGRATULATIONS![c:]", "[c:bR]CONGRATULAZIONI![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:bR]UFOs[c:] have been defeated!", "Gli [c:bR]UFO[c:] sono stati sconfitti!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And they event left one behind!", "E ne hanno persino lasciato uno indietro!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]DISASTER! DISASTER![c:]", "[c:bR]DISASTRO! DISASTRO![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:bR]UFOs[c:] were victorious!", "Gli [c:bR]UFO[c:] hanno vinto!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We may never recover from this failure!", "Forse non ci riprenderemo mai da questo fallimento!", Language.Italian);

            // DialogueState
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GLUG GLUG GLUG", "GLU GLU GLU", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FIGHT THE TENTACLES", "COMBATTI I TENTACOLI", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FIGHT THE TENTACLES", "COMBATTI I TENTACOLI", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DEATH TO THE TENTACLES", "MORTE AI TENTACOLI", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WARNING!!!", "ATTENZIONE!!!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HERE THEY COME!!!", "STANNO ARRIVANDO!!!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONGRATULATIONS!!!", "CONGRATULAZIONI!!!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DISASTER!!!", "DISASTRO!!!", Language.Italian);
        }
    }
