            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You entered the [c:bR]card creation[c:] mode.", "Sei entrato nella modalità di [c:bR]creazione delle carte[c:].", Language.Italian);
