    public class LegendsFromTheDarknessMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for LegendsFromTheDarkness Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Legends From The Darkness", "Leggende dalle tenebre", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of around [count] cards consisting of a random assortment of animals, myths and urban legends.", "Una raccolta di circa [count] carte con un assortimento casuale di animali, miti e leggende metropolitane.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mako Shark", "Squalo mako", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The swift Mako, an agile sea predator.", "Il veloce squalo mako, un agile predatore marino.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The robust Puma, a fierce creature.", "Il robusto Puma, una creatura feroce.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hideous offspring of a voracious creature.", "La ripugnante progenie di una creatura vorace.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahuizotl", "Ahuizotl", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiar creature. I wonder if that tail is special.", "Una creatura particolare. Mi chiedo se la sua coda abbia qualcosa di speciale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahuizotl Tail", "Coda di Ahuizotl", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hiding in dismal waters, the ferocious alligator approaches those who dare get close.", "Nascosto in acque cupe, il feroce alligatore si avvicina a chi osa farsi vicino.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Angler Fish", "Rana pescatrice", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't let that glamorous shine decieve you.", "Non lasciarti ingannare da quello splendore seducente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antlion", "Formicaleone", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Automaton", "Automa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The rusted machine's exposed wires shock any would-be aggressor", "I fili scoperti della macchina arrugginita danno una scossa a chiunque tenti di aggredirla.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the regenerative sea predator, what would happen if the eternal juvenile were to reach maturity?", "Il predatore marino rigenerante: cosa accadrebbe se questo eterno giovane raggiungesse la maturità?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beetle", "Coleottero", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unsurpassable strength of the beetle knocks creatures away.", "La forza insuperabile del coleottero respinge le creature.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloater", "Gonfio", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An unfortunate demise to this particular being.", "Una fine sfortunata per questo particolare essere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boa", "Boa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The constricting Boa ensnares its prey and won't let go.", "Il Boa costrittore avvolge la preda e non la lascia andare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bombardier", "Bombardiere", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Armed with a noxious spray, this odd beetle retaliates against its aggressors.", "Armato di uno spruzzo nocivo, questo strano coleottero reagisce agli aggressori.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Braxie", "Braxie", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wandering Braxie's horrid stench weakens any threat it encounters.", "Il terribile fetore del vagabondo Braxie indebolisce ogni minaccia che incontra.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cape Buffalo", "Bufalo del Capo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Vengeful Buffalo, attacking it is a woeful decision.", "Il Bufalo vendicativo: attaccarlo è una decisione sciagurata.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bush Dog", "Speoto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thought to be extinct, the Illusive Bush Dog is normally found in packs.", "Un tempo ritenuto estinto, l'elusivo Speoto si trova di solito in branco.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cadejo", "Cadejo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bound to chance, your guardian will be either benign or maleficent.", "Affidato al caso, il tuo guardiano sarà benevolo oppure malvagio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camazotz", "Camazotz", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A servant to the lords of the underworld, associated with darkness, death... and 'sacrifice'.", "Un servitore dei signori degli inferi, associato all'oscurità, alla morte... e al «sacrificio».", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The \"spit\" of the camel is enough to blind most aggressors.", "Lo «sputo» del cammello basta ad accecare la maggior parte degli aggressori.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carpenter Moth", "Falena carpentiera", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The resourceful carpenter, able to draw blood from stone.", "L'intraprendente carpentiere, capace di cavare sangue da una pietra.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "few are able to catch the nimble cheetah.", "Pochi riescono a raggiungere l'agile ghepardo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The humble chicken, its meat is nourishing for most creatures.", "L'umile gallina, la cui carne è nutriente per la maggior parte delle creature.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chupacabra", "Chupacabra", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the horrid chupacabra. It hungers for your livestock.", "L'orribile Chupacabra. Ha fame del tuo bestiame.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ever-bothersome cicada, using its loud buzzing to summon its kin.", "La sempre fastidiosa cicala richiama i suoi simili con un forte frinire.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cloth", "Tessuto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the mystifying Clouded Leopard. The missing link between the cat family.", "L'enigmatico Leopardo nebuloso. L'anello mancante della famiglia dei felini.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cookiecutter", "Squalo stampo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crab", "Granchio", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "an armored crustacean. The crab's carapace covers it from fatal blows.", "Un crostaceo corazzato. Il carapace del granchio lo protegge dai colpi mortali.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dart Frog", "Rana freccia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is Ill-advised to attack this creature.", "Non è saggio attaccare questa creatura.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dirt Pile", "Mucchio di terra", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dobhar-chu", "Dobhar-chu", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the king of the otters. The Dobhar-chu requires sustenance to grow.", "Il re delle lontre. Il Dobhar-chu deve nutrirsi per crescere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The onerous eagle, a keen guard of the sky. ", "L'aquila imponente, vigile guardiana del cielo. ", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How did such a creature learn to use electricity as a weapon?", "Come ha imparato una simile creatura a usare l'elettricità come arma?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerging Zombie", "Zombie emergente", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sprightly falcon, eager to attack in a breakneck pace", "Il vivace falco pellegrino, impaziente di attaccare a velocità vertiginosa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The arboreal Fisher Cat", "Il Pekan arboricolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fisher Cat", "Pekan", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The red fox, born with a deceitful nature.", "La volpe rossa, nata con un'indole ingannevole.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gargoyle", "Gargolla", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A horrid man-made beast, does humanity know no limit?", "Un'orribile bestia creata dall'uomo. L'umanità non conosce limiti?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The towering culmination of spirits of fallen soldiers, risen from pure hatred in their souls.", "Un'imponente fusione degli spiriti dei soldati caduti, sorta dal puro odio delle loro anime.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Genet", "Genetta", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The slender Genet can sneak past airborne creatures.", "L'esile Genetta può sgattaiolare oltre le creature volanti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Lobster", "Astice gigante", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An eternal lifespan can lead to dire changes in a creature.", "Una vita eterna può portare a terribili cambiamenti in una creatura.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goblin", "Goblin", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ever-hungry imp of greed. He shall give you an item... But not without a cost.", "Il diavoletto dell'avidità, sempre affamato. Ti darà un oggetto... ma non senza un prezzo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goose", "Oca", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The phoney goose. Rarely will a creature call its bluff.", "L'oca impostora. Raramente una creatura osa smascherare il suo bluff.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haggard", "Emaciato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the abominable Haggard, a wretched hulking beast.", "L'abominevole Emaciato, una miserabile e massiccia bestia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hammerhead", "Squalo martello", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The perceptive Hammerhead, able to retaliate against those that tread into its waters", "Il percettivo Squalo martello può reagire a chi si avventura nelle sue acque.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hawk Wasp", "Vespa cacciatrice", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The threatening Hawk Wasp. An intelligent hunter.", "La minacciosa Vespa cacciatrice. Una cacciatrice intelligente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hellhound", "Segugio infernale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It spreads misery to those its near, making them suffer its pain", "Diffonde miseria a chi gli sta vicino, facendogli patire il suo dolore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heron", "Airone cenerino", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The keen-eyed heron is able to perforate through aquatic creatures.", "L'airone cenerino dall'occhio acuto può trafiggere le creature acquatiche.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Highland Cow", "Mucca delle Highlands", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The tranquil highland cow, able to shrug off assaults by grazing the land", "La tranquilla Mucca delle Highlands riesce a sopportare gli assalti mentre pascola.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Horde", "Orda", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Hunter", "Il Cacciatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "\"It's all about the sport\" he claims, though his true intentions still remain a mystery.", "«È tutta una questione di sport», sostiene, ma le sue vere intenzioni restano un mistero.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Hunter's Bible", "La Bibbia del cacciatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iguana", "Iguana", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The battered iguana, its power weakens without its tail.", "L'iguana malconcia: senza la coda la sua potenza diminuisce.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Isopod", "Isopode gigante", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stricken with gigantism, the giant isopod can resist most forms of harm.", "Colpito da gigantismo, l'Isopode gigante resiste alla maggior parte delle forme di danno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jaguar", "Giaguaro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beware the efficacy of a Jaguar's hunt.", "Attento all'efficacia della caccia del giaguaro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jellyfish", "Medusa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A simple invertebrate, with barbed tentacles capable of paralyzing the biggest of creatures.", "Un semplice invertebrato con tentacoli uncinati capaci di paralizzare le creature più grandi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jerboa", "Gerboa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A meager rodent, the jumpy Jerboa will carelessly leap throughout the board.", "Un esile roditore: il vivace Gerboa salta senza cautela per tutto il tavolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jiangshi", "Jiangshi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This ghastly cadaver steals life energy from unfortunate souls.", "Questo cadavere spaventoso ruba l'energia vitale alle anime sfortunate.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kappa", "Kappa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A direful spirit of the sea, it will take those who dare tread its waters.", "Un terribile spirito marino che porta via chi osa entrare nelle sue acque.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "King Cobra", "Cobra reale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The prestigious King Cobra, its venom slowly cripples any aggressor.", "Il prestigioso Cobra reale: il suo veleno indebolisce lentamente qualsiasi aggressore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Komodo Dragon", "Drago di Komodo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The baneful Komodo, with a bite so caustic, it's victim is guaranteed a painful death.", "Il nefasto drago di Komodo: il suo morso è così corrosivo che la vittima è destinata a una morte dolorosa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Krampus", "Krampus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "emerging from the winter forests, the hateful krampus marches through, carrying unfortunate souls in his sack.", "Emergendo dalle foreste invernali, l'odioso Krampus avanza portando anime sfortunate nel suo sacco.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kuchisake-onna", "Kuchisake-onna", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is she hiding behind that mask?", "Cosa nasconde dietro quella maschera?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antlion Larva", "Larva di formicaleone", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the antlion larva is a proficient hunter, though with such dwindling youth.", "La larva di formicaleone è un'abile cacciatrice, sebbene la sua giovinezza stia volgendo al termine.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ferocious leopard. Born with an insatiable hunger.", "Il feroce leopardo. Nato con una fame insaziabile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lethargic Dragon", "Drago letargico", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The proud lion, a courageous soul able to empower its kin.", "Il fiero leone, un'anima coraggiosa capace di rafforzare i suoi simili.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lobster Claw", "Chela di astice", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The solitary Lynx attacks with its sharp claws and teeth.", "La lince solitaria attacca con artigli e denti affilati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mako Pup", "Cucciolo di squalo mako", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The juvenile Mako pup, its no less crafty in it's childlike state.", "Il giovane cucciolo di squalo mako non è meno astuto nonostante la sua età.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mandrill", "Mandrillo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mandrill, an aggressive and hefty old-world monkey.", "Il Mandrillo, una scimmia del Vecchio Mondo aggressiva e robusta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nessie", "Nessie", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A remorseless creature, born from a long-forgotten era.", "Una creatura spietata nata in un'epoca dimenticata da tempo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightcrawlers", "Vagabondi notturni", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such weird creatures they are, acting as one.", "Che strane creature, agiscono come una sola.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not Jerma", "Non Jerma", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I... Don't really know what to say about this one.", "Io... non so davvero cosa dire di questo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Old Golem", "Vecchio golem", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a long deactivated protector, born with sentience but no heartbeat.", "Un protettore disattivato da tempo, nato senziente ma senza battito cardiaco.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Osprey", "Falco pescatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Piscivorous Osprey, with claws tailored to catch its prey in the water.", "Il Falco pescatore piscivoro, con artigli adatti a catturare prede nell'acqua.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Owl", "Gufo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The predatory Owl grows vicious against other birds, cutting their wings.", "Il Gufo predatore diventa feroce contro gli altri uccelli, tagliando loro le ali.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasite", "Parassita", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Penguin", "Pinguino", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the flightless penguin. An agile swimmer.", "Il Pinguino incapace di volare. Un agile nuotatore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom", "Spettro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "\"The dead shall never rest\" is a statement that rings true for the phantom.", "«I morti non riposeranno mai»: questa frase è vera per lo spettro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raging Dragon", "Drago furioso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He has risen.", "Si è risvegliato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raging King Dragon", "Re drago furioso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scavenger", "Avvoltoio", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the resourceful scavenger, what little consciousness is left is spent on bone collecting.", "L'intraprendente Avvoltoio dedica la poca coscienza rimasta alla raccolta di ossa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scorpion", "Scorpione", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The rancorous Scorpion. With a potent venom capable of slaying most prey.", "Lo Scorpione rancoroso, con un potente veleno capace di uccidere la maggior parte delle prede.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shark Fin", "Pinna di squalo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shrike", "Averla", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The gruesome Shrike uses spiked branches to its advantage.", "La macabra Averla sfrutta a proprio vantaggio i rami spinosi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Siguanaba", "Siguanaba", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sorrowful spirit that wanders near lakes, luring unwary souls to their demise.", "Uno spirito addolorato che vaga vicino ai laghi, attirando le anime imprudenti verso la morte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "El Silbon", "Il Silbon", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A greedy miscreant. I wonder which bones are from his ascendant?", "Un malfattore avido. Mi chiedo quali ossa appartengano al suo antenato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skinwalker", "Mutapelle", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the malevolent shapeshifter, able to take form of any animal it kills.", "Il mutaforma malvagio può assumere la forma di qualsiasi animale che uccide.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sleeping Dragon", "Drago addormentato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "May the gods have mercy on any sorrowful soul who wakes it.", "Che gli dèi abbiano pietà di ogni anima sventurata che lo sveglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disturbed Dragon", "Drago disturbato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sloth Bear", "Orso labiato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The docile sloth bear, it swipes wildly when it feels threatened.", "L'Orso labiato docile sferra colpi selvaggi quando si sente minacciato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiked Branches", "Rami spinosi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stalker", "Inseguitore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a husk of a human, doomed to an infernal punishment.", "Un guscio umano vuoto, condannato a una punizione infernale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strigoi", "Strigoi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Blood-hungry beast of hell, the Strigoi is evil incarnate.", "Una bestia infernale assetata di sangue: lo Strigoi è il male incarnato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "superstar", "superstar", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "he gets a lot of money, and drives fancy cars.", "Guadagna un sacco di soldi e guida auto di lusso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thorny Dragon", "Drago spinoso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Thorny Dragon uses its spikes to deterr predators.", "Il Drago spinoso usa le spine per scoraggiare i predatori.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thresher Shark", "Squalo volpe", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The crafty Thresher, it uses its tail to attack prey.", "L'astuto squalo volpe usa la coda per attaccare le prede.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thunderbird", "Uccello del tuono", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "born from the mad skies, This Terrorbird dwarves the largest of known creatures.", "Nato dai cieli impazziti, questo uccello del terrore fa impallidire le più grandi creature conosciute.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiger", "Tigre", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Frightful apex predator, the tiger attacks the weak first.", "Un terrificante superpredatore: la tigre attacca per primi i deboli.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tuna", "Tonno", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fish that is a lot larger than you may believe.", "Un pesce molto più grande di quanto si possa pensare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the solitary vampire works best when alone.", "Il vampiro solitario dà il meglio di sé quando è solo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warthog", "Facocero", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the savage warthog, it's attack style is unpredictable.", "Il selvaggio facocero: il suo stile d'attacco è imprevedibile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wendigoon", "Wendigoon", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this... is not one of my deathcards...", "Questa... non è una delle mie carte della morte...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hey there. ", "Ehi. ", Language.Italian);
