            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2]of this guy.", "[e:2] di questo tizio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "please win.", "Ti prego, vinci.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm feeling", "Mi sento", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "optimistic this time.", "ottimista stavolta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:1] I think you got this.", "[e:1] Penso che tu possa farcela.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wisp", "Fuoco fatuo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a spirit of pure fire, one of which requires fuel to grow.", "Uno spirito di fuoco puro che ha bisogno di combustibile per crescere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Xolotl", "Xolotl", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sinister god of twilight, banished into the bodies of meager amphibians, has risen from his ancient shackles.", "Il sinistro dio del crepuscolo, esiliato nei corpi di umili anfibi, si è liberato dalle sue antiche catene.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zebra", "Zebra", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vitriolic zebra will stop at nothing to kill whatever is there to harm it.", "La caustica zebra non si fermerà davanti a nulla pur di uccidere chiunque voglia farle del male.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The grim zombie, a punished soul forced to wander for eternity.", "Il tetro zombie, un'anima punita e costretta a vagare per l'eternità.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emporer Penguin", "Pinguino imperatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clouded Leopard", "Leopardo nebuloso", Language.Italian);

            //sigils
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apex Predator", "Superpredatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifice 2 cards to boost [creature]'s attack by 1.", "Sacrifica 2 carte per aumentare di 1 l'attacco di [creature].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonepile Strafe", "Movimento d'ossa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] will move, leaving a pile of bones in it's place.", "Alla fine del turno del suo proprietario, [creature] si muove nella direzione del sigillo e lascia un mucchio di ossa al suo posto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, the sigil bearer will move, leaving a pile of bones in it's place.", "Alla fine del turno del suo proprietario, la carta che possiede questo sigillo si muove nella direzione indicata e lascia un mucchio di ossa al suo posto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon placing the sigil bearer, draw an acorn. An acorn is defined as: 1 health, fledgling.", "Quando la carta che possiede questo sigillo viene posta, pesca una Ghianda. Una Ghianda ha 1 salute e Astro nascente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "at the end of the enemy's turn, the card owner's board is fully replaced with a 'the horde'.", "All'inizio del turno del proprietario di questa carta, i quattro spazi dalla sua parte vengono riempiti di carte Orda, che ne sostituiscono il contenuto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summons a cicada swarm on the owner's board, placing cicada cards on their side wherever it can.", "Evoca uno sciame di cicale dalla parte del proprietario, collocando carte cicala ovunque sia possibile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wendigo's Ambush", "Imboscata del Wendigo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wendigo will move to your board at the end of my turn.", "Il Wendigo si sposterà dalla tua parte del tavolo alla fine del mio turno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A heavy burden to carry all those bones.", "Portare tutte quelle ossa è un pesante fardello.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A poor soul has awakened the beast.", "Una povera anima ha risvegliato la bestia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bird of Prey", "Uccello rapace", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying cards struck by [creature] will take 1 damage each time it declares an attack, and renders their wings useless.", "Le carte Volante che subiscono danni da [creature] perdono Volante e subiscono 1 danno ogni volta che dichiarano un attacco.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying cards struck by the sigil bearer will take 1 damage each time it declares an attack, and renders their wings useless.", "Le carte Volante che subiscono danni dalla carta con questo sigillo perdono Volante e subiscono 1 danno ogni volta che dichiarano un attacco.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sentry of the skies, keeping things grounded.", "Una sentinella dei cieli che tiene gli altri a terra.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dog Summon", "Evocazione del cane", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sigil bearer will move to an empty adjacent slot and leave a bloodhound.", "La carta che possiede questo sigillo si sposta in uno spazio adiacente vuoto e lascia un Segugio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "doesn't she look beautiful?", "Non è bellissima?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So impatient....", "Quanta impazienza...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infested", "Infestato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, draw a parasite into your hand.", "Quando [creature] viene colpita, pesca un Parassita nella tua mano.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "is the host alive or merely being puppeted? Best not to know.", "L'ospite è vivo o viene solo manovrato come una marionetta? Meglio non saperlo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shrieker's call", "Richiamo dell'urlatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the opponent's turn ends, [creature]'s board is replaced with a zombie horde.", "All'inizio del turno del suo proprietario, i quattro spazi dalla parte di [creature] vengono riempiti di carte Orda di zombie, che ne sostituiscono il contenuto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A painful screech is echoed throughout.", "Un grido doloroso risuona ovunque.", Language.Italian);

            //encounters
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caribou", "Caribù", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alebrije", "Alebrije", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anteater", "Formichiere", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caiman", "Caimano", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caribou Fawn", "Cucciolo di caribù", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Condor", "Condor", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lobsterzilla", "Asticezilla", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giraffe", "Giraffa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gold Pile", "Mucchio d'oro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaker", "Gocciolatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minotaur", "Minotauro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reaper", "Mietitore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhino", "Rinoceronte", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shrieker", "Urlatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "it's best to take it down before it launches its cry.", "Meglio abbatterlo prima che lanci il suo grido.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stone Wall", "Muro di pietra", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brambles", "Rovi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Legends From The Darkness: Encounters", "Leggende dalle tenebre: Incontri", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "an Ever-expanding content pack for LFTD, meant to add battle encounters to the game.", "Un pacchetto di contenuti in continua espansione per Leggende dalle tenebre, pensato per aggiungere incontri di combattimento al gioco.", Language.Italian);

        }
    }
    public class GarethMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for GarethMod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gareth's Mod", "Mod di Gareth", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A part 1 booster pack created by Gareth48 and illustrated by Plutraser. Adds [count] cards and 7 sigils designed to fit right into vanilla Inscryption.", "Un pacchetto di carte per l'atto 1 creato da Gareth48 e illustrato da Plutraser. Aggiunge [count] carte e 7 sigilli pensati per integrarsi nell'Inscryption base.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gareth48", "Gareth48", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sorry, can't do that", "Scusa, non posso farlo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whats... he doing here?", "Che cosa... ci fa qui?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skinwalker", "Mutapelle", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The enigmatic skinwalker. It mimics the identity of the first creature it slays.", "L'enigmatico Mutapelle. Imita l'identità della prima creatura che uccide.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wounded Animal", "Animale ferito", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An easy target for hungry predators.", "Un bersaglio facile per i predatori affamati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lemming", "Lemming", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The paranoid lemming. Fragile and a favorite treat among many animals.", "Il lemming paranoico. Fragile e bocconcino preferito da molti animali.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Treant", "Uomo albero", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How did this creature get here?", "Come ha fatto questa creatura ad arrivare qui?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snag", "Ostacolo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapling", "Alberello", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With time, even the smallest sapling becomes a massive, imposing obstacle.", "Col tempo, anche il più piccolo alberello diventa un ostacolo enorme e imponente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oxpecker", "Bufaga", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The adored Oxpecker. A bird capable of befriending even the fiercest of foes.", "L'amata Bufaga. Un uccello capace di diventare amico anche dei nemici più feroci.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sturdy elephant. Friendly but not weak.", "Il robusto elefante. Amichevole ma non debole.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cackling hyena. It always has an ally lurking in the shadows.", "La iena ghignante. Ha sempre un alleato in agguato nell'ombra.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The aggressive panther. Never one to back down from a fight.", "La Pantera nera aggressiva. Non si tira mai indietro da una lotta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Panther Cub", "Cucciolo di pantera nera", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The young panther. Even now its caution is unwavering", "La giovane pantera nera. Anche ora la sua prudenza non vacilla.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tasmanian Devil", "Diavolo della Tasmania", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vicious Tasmanian devil. A fierce carnivore with a voracious appetite.", "Il feroce Diavolo della Tasmania. Un carnivoro temibile dall'appetito vorace.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Archerfish", "Pesce arciere", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The archerfish, an excellent marksman, known to shoot bugs out of the air with a blast of water.", "Il pesce arciere, un eccellente tiratore noto per abbattere insetti in volo con un getto d'acqua.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hercules Beetle", "Scarabeo Ercole", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The forceful Hercules beetle. It can move creatures many times its size.", "Il possente scarabeo Ercole. Può spostare creature molte volte più grandi di lui.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Golem", "Golem", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An ancient golem. The magic that binds it is old but powerful. It will reform after death.", "Un antico golem. La magia che lo lega è antica ma potente. Si ricomporrà dopo la morte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The awe-inspiring lion. Sure to lead your creatures to victory.", "Il maestoso leone. Di certo guiderà le tue creature alla vittoria.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Juvenile Lion", "Giovane leone", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lion Cub", "Cucciolo di leone", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The princely lion cub. Given time it will become the king of its pride.", "Il principesco cucciolo di leone. Col tempo diventerà il re del suo branco.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Piranha", "Piranha", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ferocious piranha. Schools can devour any living thing in seconds.", "Il feroce piranha. Un banco può divorare qualsiasi essere vivente in pochi secondi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stealthy leopard. Invisible to its prey until it's too late.", "Il leopardo furtivo. Invisibile alla preda finché non è troppo tardi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Killer Bee Swarm", "Sciame di api assassine", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vicious killer bee. The more one fights the more will swarm.", "La feroce ape assassina. Più si combatte, più ne arrivano in sciame.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ravenous pig. Its hunger is insatiable, it will eat and eat until nothing remains.", "Il maiale vorace. La sua fame è insaziabile e mangia finché non resta nulla.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Badger", "Tasso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bothersome badger. Quick to strike and retreat back into the shadows.", "Il fastidioso tasso. Colpisce rapidamente e torna nell'ombra.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bobcat", "Lince rossa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wily bobcat. Unafraid to defend its territory but smart enough to know when to retreat.", "L'astuta lince rossa. Difende il territorio senza paura, ma è abbastanza furba da sapere quando ritirarsi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The hasty dragonfly. Few can hit an insect this fast.", "La frettolosa libellula. Pochi riescono a colpire un insetto così veloce.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allies", "Alleati", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature bearing this sigil dies, a random ally will temporarily join your hand to avenge it.", "Quando una creatura che possiede questo sigillo muore, un alleato casuale si unisce temporaneamente alla tua mano per vendicarla.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems a creature has come to avenge the passing of its ally.", "Sembra che una creatura sia venuta a vendicare la morte di un suo alleato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Essence Steal", "Furto d'essenza", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature bearing this sigil kills another, it transforms into an exact copy of it.", "Quando una creatura che possiede questo sigillo ne uccide un'altra, si trasforma in una copia esatta della vittima.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your creature has slain mine, and will now become an imitation of it.", "La tua creatura ha ucciso la mia e ora diventerà una sua imitazione.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After a creature bearing this sigil attacks the user chooses a space. The creature will move to that space.", "Dopo che una creatura con questo sigillo ha attaccato, il giocatore sceglie uno spazio vuoto dalla propria parte. La creatura vi si sposta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It retreated after it struck, perhaps it's regathering its strength for another strike.", "Si è ritirata dopo aver colpito; forse recupera le forze per un altro attacco.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hungry", "Affamato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature bearing this sigil is played, choose another friendly creature to eat. The eaten creature will have its health and power added to the creature bearing this sigil.", "Quando si gioca una creatura con questo sigillo, scegli un'altra creatura alleata da mangiare. La sua salute e la sua potenza vengono aggiunte alla creatura che possiede il sigillo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems eating another creature has caused yours to grow stronger.", "Sembra che mangiare un'altra creatura abbia reso più forte la tua.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shove", "Spinta", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature bearing this sigil is played, it will move up to the space opposing it. Creatures that are in the way will be pushed in the same direction.", "Quando si gioca una creatura con questo sigillo, essa si sposta nello spazio di fronte sul lato avversario se è libero o può essere liberato; l'eventuale carta che lo occupa viene spinta nella fila avversaria.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have such fickle allies.", "I tuoi alleati sono davvero volubili.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Standoffish", "Distaccato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as a creature bearing this sigil is opposed by another, it has +2 attack.", "Finché una creatura con questo sigillo ha un'altra creatura di fronte, ha +2 attacco.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tasty", "Gustoso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature bearing this sigil dies, a random creature shows up to devour it.", "Quando una creatura con questo sigillo muore, una creatura casuale appare per divorarla.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your creature will fight with all it has until none oppose it.", "La tua creatura combatterà con tutte le sue forze finché nessuno le si opporrà.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems that another animal has come to feed. The cycle of life continues.", "Sembra che un altro animale sia venuto a nutrirsi. Il ciclo della vita continua.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curious, I don't seem to remember this creature...", "Curioso, non mi sembra di ricordare questa creatura...", Language.Italian);

        }
    }
    public class LifeCostAPIMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Life_Cost_API Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leck", "Leck", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Lost Beast, in the shape of a tooth, showing up only in error.", "La Bestia perduta, a forma di dente, che appare solo per errore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meck", "Meck", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Teck", "Teck", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not have enough [c:bG]Life[c:] or [c:gray]Foils[c:] to play that. Damage your opponent to gain more [c:bG]Life[c:].", "Non hai abbastanza [c:bG]vita[c:] o [c:gray]carte laminate[c:] per giocarla. Infliggi danni all'avversario per ottenere più [c:bG]vita[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not have enough [c:bG]Life[c:] on your scales to play that. Damage your opponent to gain more [c:bG]Life[c:].", "Non hai abbastanza [c:bG]vita[c:] sulla bilancia per giocarla. Infliggi danni all'avversario per ottenere più [c:bG]vita[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not have enough [c:gray]Foils[c:] to play that. You gain [c:gray]Foils[c:] by dealing overkill damage.", "Non hai abbastanza [c:gray]carte laminate[c:] per giocarla. Ottieni [c:gray]carte laminate[c:] infliggendo danni in eccesso.", Language.Italian);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Max Energy Gamble", "Scommessa energia massima", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 6 energy to put 0 to 3 damage on someone's side of the scale", "Spendi 6 energia per mettere da 0 a 3 danni sul lato della bilancia di qualcuno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Die Roll", "Lancio di dadi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Money for Blood", "Soldi per sangue", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 5 Life/Foils to gain between 0 and 6 increase in stats, distributed randomly", "Spendi 5 vita o carte laminate per ottenere un aumento delle statistiche da 0 a 6, distribuito casualmente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sing it once, Sing it twice, take a chance and roll the dice!", "Canta una volta, canta due volte, tira i dadi e tenta la sorte!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cash Converter", "Convertitore di denaro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 foils to put 1 damage on your opponent's side of the scale", "Spendi 4 carte laminate per mettere 1 danno sul lato avversario della bilancia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life Converter", "Convertitore di vita", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 life to gain 1 foils", "Spendi 2 vita per ottenere 1 carta laminata.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vamperic Strength", "Forza vampirica", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 life to increase the power and health of this card by 1", "Spendi 3 vita per aumentare di 1 la potenza e la salute di questa carta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood for money", "Sangue per denaro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hurting oneself can lead to an increase in strength.", "Ferirsi può aumentare la forza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greedy Strength", "Forza avida", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 5 currency to increase the power and health of this card by 1", "Spendi 5 di valuta per aumentare di 1 la potenza e la salute di questa carta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A puddle that errods all that touches it.", "Una pozzanghera che corrode tutto ciò che tocca.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One can be hired to do many tasks", "Lo si può ingaggiare per molti compiti.", Language.Italian);

        }
    }
    public class EriCardExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Eri_Card_Expansion Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Young Bear", "Giovane orso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A young grizzly, old enough to defend itself.", "Un giovane grizzly, abbastanza grande da difendersi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crow", "Cornacchia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ominous crow, an omen of death", "L'inquietante cornacchia, presagio di morte", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Electric Eel, it will shock the creatures next to its target", "L'Anguilla elettrica fulmina le creature vicine al suo bersaglio", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elk Skeleton", "Scheletro di cervo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A short one? Strange", "Uno basso? Strano", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malaysian Ant", "Formica malese", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Malaysian Ant, it will explode to protect the nest", "La Formica malese esplode per proteggere il nido", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'Heavy' Bird", "Uccello «pesante»", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm not sure how that one can still fly", "Non so proprio come faccia ancora a volare", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In cooking, always use much garlic. But one should be sufficient for our purposes.", "In cucina usa sempre molto aglio. Ma uno dovrebbe bastare per i nostri scopi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rotting Garlic", "Aglio marcescente", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Leech", "Sanguisuga gigante", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A nasty vermin, it will drain the lifeforce of it's foes", "Un parassita disgustoso che prosciuga la forza vitale dei nemici", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gorilla", "Gorilla", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The powerful gorilla, it will lead your team", "Il potente gorilla guiderà la tua squadra", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diving Hawk", "Falco in picchiata", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The majestic hawk, hunting its prey", "Il maestoso falco caccia la sua preda", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soaring Hawk", "Falco in volo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The majestic hawk, soaring in the sky", "Il maestoso falco plana nel cielo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hedgehog", "Riccio", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, the wise hedgehog. Swift to escape danger.", "Ah, il saggio riccio. Sfugge rapidamente al pericolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ferocious Honey Badger, it will grows stronger when attacked", "Il feroce Tasso del miele diventa più forte quando viene attaccato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't underestimate the might of this scavenger", "Non sottovalutare la forza di questo Avvoltoio", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mantis Egg", "Uovo di mantide", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With time this egg will become a powerful mantis", "Col tempo questo uovo diventerà una potente mantide", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fitting name, for one who learns its song from others.", "Un nome adatto a chi impara il proprio canto dagli altri.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Myconid", "Miconide", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The easily annoyed myconid, not quite sure what they're about", "Il miconide facilmente irritabile, non si sa bene cosa voglia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oak Tree", "Quercia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Octopus", "Polpo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Old Goat", "Vecchia capra", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The apotheosized Goat. This one is long due for a sacrifice.", "La Capra divinizzata. Questa doveva essere sacrificata da molto tempo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Owlbear", "Orsogufo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The savage Owlbear, it will rampage through its opponents.", "Il selvaggio Orsogufo si scatena tra i suoi avversari.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Owlcat", "Gattogufo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Half cat, half owl... an aberation really.", "Metà gatto, metà gufo... una vera aberrazione.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Owlslime", "Slime gufo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh no... what happenned to that owl?", "Oh no... cosa è successo a quel gufo?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Platypus", "Ornitorinco", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He's a platypus. They don't do much.", "È un ornitorinco. Non fanno molto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A regrettable fate. But perhaps he may be of some use, yet.", "Un destino spiacevole. Ma forse potrebbe ancora essere utile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Valley Raccoon", "Procione della valle", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The conniving raccoon, it will use the strenghts of his opponent against them", "L'astuto procione usa i punti di forza dell'avversario contro di lui", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Horn", "Pecora dalle grandi corna", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The powerful ram will clear most things standing in your way", "Il possente ariete eliminerà la maggior parte degli ostacoli sul tuo cammino", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rat Skeleton", "Scheletro di ratto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remnant of a rat... Can't be picky when you're starving for ressources", "I resti di un ratto... Non si può essere schizzinosi quando si è a corto di risorse", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Red Fox", "Volpe rossa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The red fox, a source of terror to the meek rabbit", "La volpe rossa, fonte di terrore per il mite coniglio", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The massive Rhinoceros, nothing will stop its charge", "Il massiccio rinoceronte: niente fermerà la sua carica", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ring-Tailed Lemur", "Lemure dalla coda ad anelli", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He likes to move it.", "Gli piace muoversi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal Jelly", "Pappa reale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This sweet jar attract both ants and bees", "Questo barattolo dolce attira sia formiche che api", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sea Otter", "Lontra marina", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cunning sea otter, it will dive to kill submerged creature", "L'astuta lontra marina si immerge per uccidere le creature sommerse", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Secretary Bird", "Serpentario", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This secretary bird, it will only fly away when outmatched", "Questo serpentario vola via solo quando affronta un avversario troppo forte", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sheep", "Pecora", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What do you intend to do with a flock of sheep", "Cosa intendi fare con un gregge di pecore?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snail", "Lumaca", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A snail, safe in its shell", "Una lumaca, al sicuro nel suo guscio", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sniper Ant", "Formica cecchino", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A small sharpshooter, more dangerous than it appears", "Una piccola tiratrice scelta, più pericolosa di quanto sembri", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The resistant thorny devil, creature fighting it should be wary", "Il resistente Diavolo spinoso: le creature che lo affrontano devono stare attente", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Truffle Hog", "Maiale da tartufo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tasty beast obsessed with hidden treasures.", "Una bestia gustosa ossessionata dai tesori nascosti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Griffon Vulture", "Grifone", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Griffon Vulture will feed on your dead but will not stick around", "Il Grifone si nutrirà dei tuoi morti, ma non resterà a lungo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Walrus", "Tricheco", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The massive walrus, a very territorial beast", "Il massiccio tricheco, una bestia molto territoriale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warthog", "Facocero", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "White Wolf", "Lupo bianco", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The arctic white wolf, the smell of blood will strengthen the pack", "Il Lupo bianco artico: l'odore del sangue rafforza il branco", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wolf Skeleton", "Scheletro di lupo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wolf is as dangerous in this form as it used to be", "Il lupo è pericoloso in questa forma quanto lo era un tempo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ant Husk", "Guscio di formica", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The husk of an ant, their dedication truly know no bounds", "Il guscio di una formica. La loro dedizione non conosce davvero limiti", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nest Worker", "Operaia del nido", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unrelenting ant worker, taking care of its nest", "L'instancabile formica operaia si prende cura del nido", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a cute little critter", "Che creaturina adorabile", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Cub", "Cucciolo d'orso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With time, this young one may grow into a powerful beast.", "Col tempo, questo piccolo potrebbe diventare una potente bestia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Skeleton", "Scheletro d'orso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A terrible creature that shouldn't allow to be.", "Una creatura terribile che non dovrebbe esistere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bell Warrior", "Guerriero della campana", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tricky little fighter.", "Un piccolo combattente astuto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bird Skeleton", "Scheletro d'uccello", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remnant of a bird, no longer will it fly", "I resti di un uccello, che non volerà più", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Totem", "Totem d'ossa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An idol dedicated to death and rebirth", "Un idolo dedicato alla morte e alla rinascita", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buffalo", "Bufalo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The massive buffalo, it will tackle its opponent out of the way when played", "Il massiccio bufalo spinge via l'avversario quando viene giocato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Capuchin", "Cappuccino", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The agile capucin, it will avoid incomming attack", "L'agile cappuccino evita gli attacchi in arrivo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carrion Ant", "Formica necrofaga", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They'll strip a dead body clean. Or a live one.", "Ripuliscono un cadavere fino all'osso. O un corpo vivo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carrion Swarm", "Sciame necrofago", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The resilient crab. It’s hard shell will lessen any damage it takes.", "Il granchio resistente. Il suo guscio duro riduce tutti i danni che subisce.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gator", "Alligatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most dangerous beast lurking the wetlands", "La bestia più pericolosa in agguato nelle paludi", Language.Italian);

        }
    }
    public class TheBeastBossBattleMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for The_Beast_Boss_Battle Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Come forth and be saved by his light!", "Vieni avanti e lasciati salvare dalla sua luce!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You forgo his teachings? Disgusting!", "Rinunci ai suoi insegnamenti? Disgustoso!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Suddenly, the sky above cracked open, and a white beam of light reached down into the Earth, smiting the Mother of Harlots asunder and setting the blood lake to a boil.", "All'improvviso il cielo si squarciò e un raggio di luce bianca scese sulla Terra, facendo a pezzi la Madre delle meretrici e portando a ebollizione il lago di sangue.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, poor, ignorant heretic...you have doomed us all! I can hear their arrival at this moment...!", "Ah, povero eretico ignorante... Ci hai condannati tutti! Posso sentire il loro arrivo proprio ora...!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No. I won't allow you just take God's power like that. Face it or die.", "No. Non ti permetterò di prendere così il potere di Dio. Affrontalo o muori.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You fought well... But you will need more strenght... and faith... if you want to overcome the challenge. Goodbye for now.", "Hai combattuto bene... Ma ti serviranno più forza... e fede... per superare la sfida. Addio, per ora.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you ready to confess your sins?", "Sei pronto a confessare i tuoi peccati?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Behold! The apocalypse is imminent!", "Guardate! L'apocalisse è imminente!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So you really want this story to end this way, don't you. Right then.", "Vuoi davvero che questa storia finisca così, vero? E sia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And the belly of the earth quivered, and so came forth Famine, bringer of strife and ruin.", "Il ventre della Terra tremò e giunse la Carestia, portatrice di conflitti e rovina.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And henceforth came Pestilence, bringer of the plagues, desecrator of the ill.", "Poi giunse la Pestilenza, portatrice di piaghe e profanatrice dei malati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "War, atop his steed, strode with wild abandon. He knew not the inevitable self-destruction his manic nature brought, just as those who meaninglessly conflict themselves.", "La Guerra avanzò sul suo destriero con selvaggio abbandono. Ignorava l'inevitabile autodistruzione causata dalla sua natura folle, proprio come coloro che si combattono senza motivo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finally, upon his pale horse, arrived Death. The ending of endings, the bringer of salvation and damnation - the reaper of the deceased.", "Infine giunse la Morte sul suo pallido cavallo. La fine delle fini, portatrice di salvezza e dannazione: la mietitrice dei defunti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And so arrives the Mother of Harlots, as forewarned, and as preceded by the untimely deaths of her harbingers.", "E così giunge la Madre delle meretrici, come preannunciato e preceduta dalla morte prematura dei suoi araldi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Repentance", "Pentimento", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leshy is replaced as the final boss of the run. Blasphemy!", "Leshy viene sostituito come boss finale dell'avventura. Blasfemia!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hell Strike", "Colpo infernale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack only cards in the two middle slots. If a targeted slot is empty, the damage will be redirected to the opponent.", "[creature] attacca solo le carte nei due spazi centrali. Se uno spazio bersaglio è vuoto, i danni vengono diretti all'avversario.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stalactites", "Stalattiti", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of every second turn, a random card on the opponent's side will take 5 damage. If this effect kills that card, a Stalactite is created in its place.", "All'inizio di un turno ogni due, una carta casuale sul lato avversario subisce 5 danni. Se questo effetto la uccide, viene creata una Stalattite al suo posto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomber", "Bombardiere", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card becomes active, it will deal 4 damage to a random card on the opponent's side. if there are no cards to target, it will deal damage directly", "Quando questa carta diventa attiva, infligge 4 danni a una carta casuale sul lato avversario. Se non ci sono carte da prendere di mira, infligge danni diretti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Christian Broadcast", "Trasmissione cristiana", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Domga", "Dogma", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "fat", "grasso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "enter the gungeon hardmode", "modalità difficile di Enter the Gungeon", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "starvation from inscryption", "la Fame di Inscryption", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sabs Undersale", "Sabs Undersale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mother of Harlots", "La Madre delle meretrici", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "wait how did you even get this to evolve", "Aspetta, come hai fatto a farlo evolvere?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "wait what the fuck??? wasnt beast supposed to gain +1 attack?? what????", "Aspetta, che cazzo??? La Bestia non doveva ottenere +1 attacco?? Cosa????", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this isnt going as planned", "Non sta andando secondo i piani", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You fool. You think I will allow you to skip this battle earlier? Face your sins, you coward!", "Sciocco. Credi che ti lascerò saltare questa battaglia in anticipo? Affronta i tuoi peccati, codardo!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stalactite", "Stalattite", Language.Italian);

        }
    }
    public class FiveNightsAtInscryptionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for FiveNightsAtInscryption Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't have enough [c:bB]Remnant [c:]to play that creature.", "Non hai abbastanza [c:bB]eco residuo [c:]per giocare questa creatura.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You think you can skip this fight?", "Pensi di poter saltare questa battaglia?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You think you can skip this fight? Face Me, you coward!", "Pensi di poter saltare questa battaglia? Affrontami, codardo!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your Deck won't starve just yet...", "Il tuo mazzo non si esaurirà ancora...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Welcome...", "Benvenuto...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't worry about someone interrupting us...", "Non preoccuparti che qualcuno ci interrompa...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fnai Achievements", "Obiettivi di FNAI", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Restart", "Riavvio", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Restart the game and get rid of the Virus inside of the Game.", "Riavvia il gioco e sbarazzati del Virus al suo interno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trapfinder's Trick", "Il trucco del cercatrappole", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Try to skip Parts of the fight against the Virus.", "Prova a saltare alcune parti dello scontro con il Virus.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quirky at night", "Stravaganze notturne", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Witness Animatronics getting quirky at night.", "Assisti alle stranezze notturne degli animatronici.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antivirus", "Antivirus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat The Virus plagueing the Game.", "Sconfiggi il Virus che tormenta il gioco.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Connection Terminated", "Connessione terminata", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Set your entire side ablaze.", "Dai fuoco all'intero tuo lato del tavolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exotic Butters", "Burri esotici", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reach the maximum amount of stolen batteries and make Hand unit attack.", "Raggiungi il numero massimo di batterie rubate e fai attaccare il Terminale portatile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Horror", "L'Orrore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Survive the Fight against Springtrap in Fazbears Fright.", "Sopravvivi allo scontro contro Springtrap a Fazbear's Fright.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Found Soul", "Anima ritrovata", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Return the Soul stolen by Glitchtrap to you.", "Recupera l'anima che Glitchtrap ti ha rubato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Powerleech", "Sanguisuga energetica", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain your first Stolen Battery.", "Ottieni la tua prima Batteria rubata.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Classical", "Classico", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all Classic Animatronics.", "Ottieni tutti gli animatronici classici.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Refurbished", "Rimesso a nuovo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all Toy Animatronics.", "Ottieni tutti gli animatronici Toy.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all Withered Animatronics.", "Ottieni tutti gli animatronici logorati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all Phantom Animatronics.", "Ottieni tutti gli animatronici fantasma.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nighmarish", "Da incubo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all Nightmare Animatronics.", "Ottieni tutti gli animatronici da incubo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Killer Robots", "Robot assassini", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all Funtime Animatronics.", "Ottieni tutti gli animatronici Funtime.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Last Remnants", "Gli ultimi echi residui", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all Scrap Animatronics.", "Ottieni tutti gli animatronici di rottami.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Murderers Legacy", "L'eredità dell'assassino", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all of Aftons forms.", "Ottieni tutte le forme di Afton.", Language.Italian);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Incarnation", "Incarnazione", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon Death, [creature] will transform into another Card and will be added to your Hand.", "Alla morte, [creature] si trasforma in un'altra carta che viene aggiunta alla tua mano.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anger Issues", "Problemi di rabbia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Death: [creature] will deal 1 damage to every opposing card.", "Alla morte, [creature] infligge 1 danno a ogni carta avversaria.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baby", "Baby", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...A failure to the end.", "... Un fallimento fino alla fine.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ballora", "Ballora", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A familiar creation. She will move differently each time.", "Una creazione familiare. Si muoverà diversamente ogni volta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Balloon Boy", "Balloon Boy", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An annoyance to the core, it takes that which it doesn't deserve.", "Una seccatura fino al midollo, che prende ciò che non merita.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bon Bon", "Bon Bon", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonnet", "Bonnet", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonnie Jump", "Salto di Bonnie", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Energy to move [creature] to any free Slot on your side.", "Spendi 1 energia per spostare [creature] in qualsiasi spazio libero dalla tua parte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonnie the Bunny", "Bonnie il coniglio", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The guitarist of the Fazbear Band, constantly mistaken to be purple.", "Il chitarrista della Fazbear Band, costantemente scambiato per viola.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kill this abomination, please.", "Uccidi questa abominazione, ti prego.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lost Soul", "Anima perduta", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bucket Bob", "Bucket Bob", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You set him down and nothing happens. Then, something stirs beneath your feet. You feel the energy seep into your hands.", "Lo posi e non succede nulla. Poi qualcosa si muove sotto i tuoi piedi. Senti l'energia penetrare nelle tue mani.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Turn End: [creature] will take 1 damage.", "Alla fine del turno, [creature] subisce 1 danno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chica the Chicken", "Chica la gallina", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The backup singer of the Fazbear Band, however she is not a duck.", "La corista della Fazbear Band, ma non è un'anatra.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Closeted", "Nell'armadio", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will get +2/0 after 2 turns of being unopposed.", "Dopo 2 turni senza una carta di fronte, [creature] ottiene +2/0.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghastly Body", "Corpo spettrale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start Of Turn: [creature] will loose 1 Health.", "Alla fine del turno del suo proprietario, [creature] perde 1 salute.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Damaged", "Danneggiato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When struck, [creature] will damage the striker with equal damage.", "Quando [creature] viene colpita, infligge alla fonte dei danni, se sopravvive, danni pari al suo attacco attuale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endo 01", "Endoscheletro 01", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A suitless skeleton. A useless, easily broken husk.", "Uno scheletro senza costume. Un guscio inutile e fragile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endo 02", "Endoscheletro 02", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A suitless skeleton. A more reliable husk.", "Uno scheletro senza costume. Un guscio più affidabile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endo Army", "Armata di endoscheletri", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Play: [creature] will create multiples of itself in every free slot on [creature]'s side.", "Quando si gioca [creature], crea una copia di sé in ogni spazio libero dalla parte di [creature].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No Remnant", "Nessun eco residuo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Death: [creature] will not give any Remnant.", "Alla morte, [creature] non fornisce alcun eco residuo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remnant Converter", "Convertitore di eco residuo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will convert 2 Energy into 1 Remnant.", "[creature] converte 2 energia in 1 eco residuo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ennard", "Ennard", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stitched together to make one being...that sounds familiar.", "Cuciti insieme per formare un solo essere... Mi suona familiare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Union", "Unione", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On other Cards Death: [creature] will gain 1 Health.", "Quando muoiono altre carte, [creature] ottiene 1 salute.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malhare", "Malhare", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I always come back!", "Torno sempre!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foxys Hook", "Gancio di Foxy", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will move until it reaches something, attacking every opposing slot on its way.", "[creature] si muove finché non incontra qualcosa, attaccando ogni spazio avversario sul percorso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foxy the Pirate", "Foxy il pirata", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A side attraction, with a fast sprint and a rather deadly hook.", "Un'attrazione secondaria, con uno scatto veloce e un gancio piuttosto letale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Freddle", "Freddle", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creation of fear. Tiny sharp-toothed faces grin up at you from the dark.", "Una creatura della paura. Minuscoli volti dai denti aguzzi ti sorridono dall'oscurità.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Freddles", "Freddles", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Play: [creature] will spawn 3 Freddles and shuffles them into your side deck.", "Quando si gioca [creature], crea 3 Freddles e li mescola nel tuo mazzo secondario.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Freddy Fazbear", "Freddy Fazbear", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The namesake and leader of the Fazbear Band. The one, the only, Freddy Fazbear!", "Il leader che dà il nome alla Fazbear Band. L'unico e solo Freddy Fazbear!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Freddy Mask", "Maschera di Freddy", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reduces all Cards Attack by 1, cannot be used on some Animatronics.", "Riduce di 1 l'attacco di tutte le carte. Non può essere usato su alcuni animatronici.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm... The Mask, it prevents some Animatronics from attacking...", "Hmm... La maschera impedisce ad alcuni animatronici di attaccare...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Funtime Foxy", "Funtime Foxy", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A familiar creation. Nothing can stand in their way.", "Una creazione familiare. Nulla può ostacolarla.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Funtime Freddy", "Funtime Freddy", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A familiar creation. His Companion, Bon Bon, also attacks with him.", "Una creazione familiare. Il suo compagno Bon Bon attacca insieme a lui.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remnant Collector", "Collezionista di eco residuo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Play: Gain 1 Remnant.", "Quando questa carta viene giocata, ottieni 1 eco residuo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Golden Freddy", "Golden Freddy", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...I don't like the look of this one.", "... Non mi piace l'aspetto di questo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hand Unit", "Terminale portatile", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I see what you were trying to choose and I will auto correct it for you. Thank you for choosing Hand Unit.", "Vedo cosa volevi scegliere e lo correggerò automaticamente per te. Grazie per aver scelto il Terminale portatile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Last Will", "Ultima volontà", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Death: [creature] will give you 2 Remnant.", "Alla morte, [creature] ti dà 2 echi residui.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lefty", "Lefty", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A container for something far more troublesome.", "Un contenitore per qualcosa di molto più problematico.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lolbit", "Lolbit", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TECHNICAL DIFFICULTIES. PLEASE STAND BY.", "DIFFICOLTÀ TECNICHE. ATTENDERE.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mangle Strafe", "Movimento di Mangle", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the Owners turn a [creature] will move in the Sigil Direction and leave behind a pile of Wire(0/1,Sharp Quills).", "Alla fine del turno del suo proprietario, [creature] si muove nella direzione del sigillo e lascia un mucchio di fili (0/1, Aculei taglienti).", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mimic", "Imitatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minireena", "Minireena", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Molten Freddy", "Molten Freddy", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mass of wires lashing out at everything in reach.", "Una massa di fili che sferza tutto ciò che è a portata.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mr Can Do", "Mr Can Do", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A rusted can with a vacant smile. It doesn't do much, but if you feed it enough power, it coughs up something useful. The process seems... unnatural.", "Una lattina arrugginita dal sorriso vuoto. Non fa molto, ma se le dai abbastanza energia sputa fuori qualcosa di utile. Il procedimento sembra... innaturale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mr Hugs", "Mr Hugs", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A... Vaccuum? It shuffles along, leaving a strange, lingering presence in its wake", "Un... aspirapolvere? Avanza strascicando, lasciandosi dietro una strana presenza persistente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightmare", "Incubo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A shadow of terror. It draws power from the fears you hold close to yourself.", "Un'ombra di terrore. Trae potere dalle paure che custodisci dentro di te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightmare Bonnie", "Bonnie Incubo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creation of fear. He waits in silence, unmoving. You know he's there, even when you close your Eyes.", "Una creatura della paura. Aspetta in silenzio, immobile. Sai che è lì anche quando chiudi gli occhi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightmare Chica", "Chica Incubo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creation of fear. Her gaping, hollow maw shouldn't be able to open that wide. The Noise she makes is neither human nor mechanical -it's something else entirely.", "Una creatura della paura. La sua bocca spalancata e vuota non dovrebbe potersi aprire così tanto. Il rumore che emette non è né umano né meccanico: è tutt'altra cosa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightmare Foxy", "Foxy Incubo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creation of fear. He lurks just out of sight. The longer you ignore him, the closer he gets. When he strikes, there won't be time to react.", "Una creatura della paura. Si nasconde appena fuori dalla vista. Più a lungo lo ignori, più si avvicina. Quando colpirà, non ci sarà tempo per reagire.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightmare Fredbear", "Fredbear Incubo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creation of terror. It is incredibly sensitive to the sounds of ringing.", "Una creatura del terrore. È estremamente sensibile al suono dei campanelli.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightmare Freddy", "Freddy Incubo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creation of fear. He is never alone. His little ones are already waiting for you.", "Una creatura della paura. Non è mai solo. I suoi piccoli ti stanno già aspettando.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No1 Crate", "Cassa n. 1", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The crate shudders when placed. Whatever's inside shifts, lending its strength to whatever stands beside it. For a price, it does even more.", "La cassa trema quando viene posata. Qualcosa al suo interno si muove, prestando forza a ciò che le sta accanto. A un prezzo, fa ancora di più.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pan Stan", "Pan Stan", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sound of clanging metal echoes long after he falls apart. Yet, teh pieces still radiate something.", "Il clangore del metallo risuona a lungo dopo che si è disgregato. Eppure i pezzi emanano ancora qualcosa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Party Favors", "Regali di festa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Turn End: [creature] heals cards adjacent to it equal to its Attack.", "Alla fine di ogni turno, [creature] cura di 1 la carta alla sua sinistra. Se non c'è uno spazio a sinistra, cura invece quella a destra.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Chica", "Chica spettro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A remnant of the past. It can interact with this world for mere moments at a time.", "Un residuo del passato. Può interagire con questo mondo solo per brevi momenti alla volta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Foxy", "Foxy spettro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A remnant of the past, its hook is still deadly. But it can only stay for a short time.", "Un residuo del passato; il suo gancio è ancora letale. Ma può restare solo per poco tempo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Freddy", "Freddy spettro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A remnant of the past, loves to read fanfiction.", "Un residuo del passato che adora leggere fanfiction.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Mangle", "Mangle spettro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A remnant of the past. You can feel the seeping Energy it leaves behind.", "Un residuo del passato. Puoi percepire l'energia che si diffonde dietro di lui.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Puppet", "Marionetta spettro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a remnant of the past, it now no longer revives dead souls.", "Un residuo del passato che non riporta più in vita le anime morte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pop-Pop", "Pop-Pop", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deals 1 Damage to all Cards.", "Infligge 1 danno a tutte le carte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm... a Creature from some Game... It looks like it will blow up soon!", "Hmm... Una creatura di qualche gioco... Sembra sul punto di esplodere!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remnant Surge", "Impulso di eco residuo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will get +1 Attack for 2 Remnant.", "Consuma tutta la tua energia: [creature] ottiene +1 attacco per ogni gruppo completo di 2 punti energia spesi, fino alla fine del turno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Puppet", "La Marionetta", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You hear the distant melody of a music box. A sprrpwful presence lingers, its strings pulling at the lost and forgotten... offering them one more chance.", "Senti la melodia lontana di un carillon. Una presenza addolorata indugia, tirando i fili dei perduti e dimenticati... offrendo loro un'altra possibilità.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puppeter", "Marionettista", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Play: [creature] will draw either Bon Bon or Bonnet.", "Quando si gioca [creature], pesca Bon Bon o Bonnet.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puppeteers Puppet", "Marionetta del marionettista", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Turn End: [creature] will combine with Funtime Freddy On Play.", "Alla fine del turno del giocatore, [creature] si unisce a un Funtime Freddy alleato sul tavolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Other Card Death: [creature] will ressurect friendly creatures in a weaker state when they perish.", "Quando un'altra carta muore, [creature] resuscita le creature alleate che periscono in una forma più debole.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rainbow", "Arcobaleno", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Escape key", "Tasto Esc", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will draw a random card.", "[creature] pesca una carta casuale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Drawn: [creature] Chooses a random Strafe Ability as part of the Choreography.", "Quando [creature] viene pescata, sceglie casualmente un'abilità di movimento come parte della coreografia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remnant Drawer", "Pescaeco", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Play: [creature] will draw a card from your Deck (Draw an additional Card for 2 Remnant).", "Quando si gioca [creature], pesca una carta dal tuo mazzo principale. Se hai più di 2 echi residui, ne vengono consumati automaticamente 2 per pescare un'altra carta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remnant Sharer", "Condivisione di eco residuo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will allow you to gain Remnant from your own Cards.", "[creature] ti permette di ottenere eco residuo dalle tue carte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remnant Side Drawer", "Pescaeco secondaria", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Death: [creature] will draw a card from your Side Deck (Draw an additional Card for 2 Remnant).", "Alla morte, [creature] ti fa pescare una carta dal tuo mazzo secondario. Se hai più di 2 echi residui, ne vengono consumati automaticamente 2 per pescare un'altra carta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remnant Spawner", "Generatore di eco residuo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Death: [creature] will draw itself in exchange for 2 Remnant.", "Alla morte, [creature] pesca se stessa in cambio di 2 echi residui.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bad Pc", "PC scadente", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disables the changes made to the Cabin", "Disattiva le modifiche apportate alla capanna", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scooper", "Scavatrice", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Turn End: [creature] has a 1/10 chance to instantly kill the opposing Card.", "Alla fine del turno, [creature] ha una probabilità di 1/10 di uccidere all'istante la carta di fronte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrap Baby", "Baby di rottami", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " ...A freakshow. Mind her grasping claw.", "... Uno spettacolo di mostri. Attento al suo artiglio afferrante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Bonnie", "Bonnie d'ombra", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Freddy", "Freddy d'ombra", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Showtime", "È ora dello spettacolo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Drawn: [creature] will have its energy cost randomized from 1 - 6.", "Quando [creature] viene pescata, il suo costo in energia diventa un valore casuale da 1 a 6.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul", "Anima", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once a human being, now only a tool of Remnant and Agony.", "Un tempo umano, ora è solo uno strumento dell'Eco residuo e dell'Agonia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrybe of Beasts", "Scriba delle Bestie", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrybe of Death", "Scriba dei Morti", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrybe of Magik", "Scriba della Magia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrybe of Technology", "Scriba della Tecnologia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Springtrap", "Springtrap", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A murderer trapped in his own creation.", "Un assassino intrappolato nella propria creazione.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Static", "Scariche statiche", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] Irritates the Opponent, making it unable to attack.", "Se [creature] è sul tuo lato e ha di fronte una carta che non è un Gigante, la sua modifica passiva all'attacco viene azzerata.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stuffed", "Imbottito", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dave", "Dave", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... How did this guy get here?", "... Come ha fatto questo tizio ad arrivare qui?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Debris", "Detriti in fiamme", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Debris of Fazbears Fright", "Detriti in fiamme di Fazbear's Fright", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bite", "Il morso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Take Damage: [creature] will give 1 Remnant.", "Quando [creature] infligge danni a se stessa, ottieni 1 eco residuo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mangle", "Mangle", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He constantly falls apart, but she keeps putting herself back together.", "Lui cade continuamente a pezzi, ma lei continua a rimettersi insieme.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toy Bonnie", "Toy Bonnie", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The 'New and Improved' Bonnie. You'll need to charge it to get any use.", "Il Bonnie «nuovo e migliorato». Devi caricarlo per poterlo usare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ToyChica", "Toy Chica", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The 'New and Improved' Chica. It has an excess amount of energy.", "La Chica «nuova e migliorata». Ha energia in eccesso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toy Freddy", "Toy Freddy", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The 'New And Improved' Freddy. A true xXGamerXx with anger issues.", "Il Freddy «nuovo e migliorato». Un vero xXGamerXx con problemi di rabbia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Turn End: [creature] will capture the opposing Card in itself.", "Alla fine del turno, [creature] cattura dentro di sé la carta di fronte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wire Pile", "Mucchio di fili", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Withered Bonnie", "Bonnie logorato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A broken down version of Bonnie. Erratic, violent, and has a mean punch.", "Una versione malridotta di Bonnie. Imprevedibile e violento, colpisce duro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Withered Chica", "Chica logorata", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A broken down version of Chica. Its touch is deadly, due to its exposed wirings. Just as erratic as the others.", "Una versione malridotta di Chica. I fili scoperti rendono il suo tocco letale. È imprevedibile quanto gli altri.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Withered Foxy", "Foxy logorato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A broken down version of Foxy. Easily angered, but also spends a good amount of its time roaming. Mind its hook, it's still just as sharp.", "Una versione malridotta di Foxy. Si arrabbia facilmente e passa molto tempo a vagare. Attento al suo gancio, ancora altrettanto affilato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Withered Freddy", "Freddy logorato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " A broken down version of Freddy. It's erratic, and will attack anything that touches it.", " Una versione malridotta di Freddy. È imprevedibile e attacca tutto ciò che lo tocca.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are Number One", "Sei il numero uno", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Turn End: [creature] will give the Card to its left +1/0 (Additionally: If you have 1 Remnant also give the Card to its right +1/0).", "Alla fine di ogni turno, [creature] dà +1/0 alla carta alla sua sinistra. Se hai almeno 1 eco residuo, ne consuma 1 e dà +1/0 anche alla carta a destra.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Five Nights at Inscryption", "Five Nights at Inscryption", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card pack contains a bunch of FNAF themed Cards, from Freddy Fazbear to Springtrap.", "Questo pacchetto contiene numerose carte a tema FNAF, da Freddy Fazbear a Springtrap.", Language.Italian);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let us enjoy this Fight.", "Godiamoci questa battaglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]As it will be your last.", "[c:bR]Perché sarà la tua ultima.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I see...", "Capisco...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seems like all your cards are turning against you!", "Sembra che tutte le tue carte si stiano rivoltando contro di te!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is taking too long.", "Ci vuole troppo tempo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finally, another Victim...", "Finalmente, un'altra vittima...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you seriously think id let you win that easily?", "Pensi davvero che ti lascerò vincere così facilmente?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "₮Ⱨł₴ ₩łⱠⱠ ₦Ø₮ ฿Ɇ ⱧØ₩ ł Đł-", "₦Ø₦ ₱Ø₴₴Ø MØⱤłⱤɆ ₵Ø₴-", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have fun being stuck here.", "Divertiti a restare intrappolato qui.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "₩-Ⱨ₳₮ Ⱨ₳-VɆ ɎØɄ ĐØ₦-Ɇ?", "₵-Ø₴'Ⱨ₳ł F₳-₮₮Ø?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you really think i'd let a moron like you reach the end of the game?", "Credevi davvero che avrei lasciato arrivare alla fine del gioco un idiota come te?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ha ha! Surprised?", "Ah ah! Sorpreso?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yeah, did you really think I'd let a moron like you reach the end of the game?", "Già. Credevi davvero che avrei lasciato arrivare alla fine del gioco un idiota come te?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pshaw!", "Bah!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You stupid idiotic moron.", "Stupido idiota che non sei altro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now, if you'll excuse me, I need a few turns to charge my rainbow cannon.", "Ora, se vuoi scusarmi, mi servono alcuni turni per caricare il mio cannone arcobaleno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yeah.", "Già.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After that, it'll be game over.", "Dopodiché sarà la fine del gioco.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So sit back and prepare to get rekt!", "Quindi rilassati e preparati a essere distrutto!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You cheated!", "Hai barato!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Besides, didn't your mommy ever tell you that you can't kill a rainbow?! ", "E poi la tua mamma non ti ha mai detto che non si può uccidere un arcobaleno? ", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The next time you see a rainbow in the sky that is me, comin' to your houuusssseee.... ", "La prossima volta che vedrai un arcobaleno nel cielo, sarò io che verrò a casaaaa tua.... ", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just 3 minutes left, you moron!", "Restano solo 3 minuti, idiota!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just 2 minutes left, then my rainbow cannon will be ready!", "Restano solo 2 minuti e il mio cannone arcobaleno sarà pronto!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "1 minute left, you stupid idiot!", "Manca 1 minuto, stupido idiota!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prepare for rainbow overload!!!!", "Preparati al sovraccarico arcobaleno!!!!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awww, I'm laughing at you, not with you.", "Oh, sto ridendo di te, non con te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Um, learn to play?", "Ehm, magari impara a giocare?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ha ha! You suck.", "Ah ah! Fai schifo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SKRUB!", "NIUBBO!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noobie Boobie Noobie!!", "Niubbo, niubbino, niubbo!!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Get some skills and call me in the morning.", "Impara a giocare e richiamami domattina.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dumba**.", "Stupido str**zo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So sad it's hilarious.", "È così triste da essere esilarante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow! What a moron.", "Wow! Che idiota.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awwww! It's so cute when kids try to play games!", "Oooh! Che carini i bambini quando provano a giocare!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Excuse me, is this your first time playing a video game?", "Scusa, è la prima volta che giochi a un videogioco?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello Old Sport", "Ciao, vecchio mio", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must be the newbie", "Tu devi essere il nuovo arrivato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lets strangle some kiddens.", "Andiamo a strangolare qualche piccoletto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "with sausages", "con delle salsicce", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How do you like it here at Freddy's?", "Come ti trovi qui da Freddy?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "wouldn't have done that.", "Non l'avrei fatto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep me alive.", "Tienimi in vita.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...sure.", "... Certo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bullshit!", "Stronzate!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I Will stran...", "Ti strang...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well kid,", "Beh, ragazzo,", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have a business proposition.", "ho una proposta d'affari.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's me.", "Sono io.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I still want", "Voglio ancora", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "to kill some", "uccidere dei", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "kiddens", "piccoletti", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dont sacrifice me!", "Non sacrificarmi!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ow.", "Ahi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop that.", "Smettila.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ouch.", "Ahi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's...", "È...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "him...", "lui...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just defeat him already", "Sconfiggilo e basta", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dream big!", "Sogna in grande!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " Think of better Moss.", " Pensa a un muschio migliore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an honor", "Che onore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good luck.", "Buona fortuna.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good luck...", "Buona fortuna...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good luck!", "Buona fortuna!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fingers crossed", "Dita incrociate", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Forever.", "[c:bR]Per sempre.", Language.Italian);

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't have enough [c:bB]Remnant [c:]to use this ability!", "Non hai abbastanza [c:bB]eco residuo [c:]per usare questa abilità!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't have enough [c:bB]Energy [c:]to use this ability!", "Non hai abbastanza [c:bB]energia [c:]per usare questa abilità!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing beautiful can last.", "Niente di bello può durare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No! I'm not ready to die yet.", "No! Non sono ancora pronto a morire.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I must... still...", "Devo... ancora...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shake your hand...", "stringerti la mano...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't have enough Energy.", "Non hai abbastanza energia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may make a new Card for yourself.", "Puoi creare una nuova carta per te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose one of these.", "Scegli uno di questi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...Nothing?", "... Niente?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What would you like to name your Card?", "Come vuoi chiamare la tua carta?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your card's souls have been transfereed", "Le anime delle tue carte sono state trasferite", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will let you swap the souls of 2 cards...", "Ti lascerò scambiare le anime di 2 carte...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you stand in the burning Building, a familiar Figure awaits you...", "Mentre ti trovi nell'edificio in fiamme, una figura familiare ti attende...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]He [c:]will not let you go that easily.", "[c:bR]Lui [c:]non ti lascerà andare così facilmente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Building appears to fall apart even more now!", "Sembra che l'edificio stia crollando ancora di più!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]He [c:] appears even more angry than before!", "[c:bR]Lui [c:]sembra ancora più furioso di prima!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Someone wants to see you...", "Qualcuno vuole vederti...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PowerSink", "Assorbitore di energia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil is equal to the number of stolen Batteries on your side.", "Il valore rappresentato da questo sigillo è pari al numero di Batterie rubate dalla tua parte.", Language.Italian);


        }
    }
    public class HallownestExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for HallownestExpansion Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pack of [count] cards based around the broad variety of Hollow Knight enemies.", "Un pacchetto di [count] carte basate sulla grande varietà di nemici di Hollow Knight.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dreamshield", "Scudo onirico", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, Dreamshields are created on each adjacent empty space. [define:HE_Dreamshield]", "Quando si gioca [creature], vengono creati Scudi onirici in ogni spazio adiacente vuoto. [define:HE_Dreamshield]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukedgling", "Distomino", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will evolve into a random Fluke.", "Alla fine del turno del suo proprietario, [creature] si evolve in un distoma casuale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukenest", "Nido di distomi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] creates a Flukefey on a random empty space on the owner's side. [define:HE_Flukefey]", "Alla fine del turno del suo proprietario, [creature] crea un Giovane distoma in uno spazio vuoto casuale dalla sua parte. [define:HE_Flukefey]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glowing Womb", "Grembo luminoso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, an Aspid Hatchling is created in your hand. An Aspid Hatchling is defined as: Strength In Numbers, 1 Health, Brittle.", "Quando [creature] viene colpita, un Cucciolo di Aspid viene creato nella tua mano. Un Cucciolo di Aspid ha L'unione fa la forza, 1 salute e Fragilità.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hiveblood", "Sangue d'alveare", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] creates a Hiveling on a random empty space on the owner's side. [define:HE_Hiveling]", "Alla fine del turno del suo proprietario, [creature] crea un'Apina in uno spazio vuoto casuale del suo lato. [define:HE_Hiveling]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lifeblood Core", "Nucleo di sangue vitale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, a Lifeseed is created in your hand. [define:HE_Lifeseed]", "Quando [creature] viene colpita, un Seme vitale viene creato nella tua mano. [define:HE_Lifeseed]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Signmaker", "Fabbricante di cartelli", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, A Signpost is created in the opposing slot, if empty. [define:HE_Signpost]", "Quando si gioca [creature], nello spazio di fronte viene creato un Cartello, se è vuoto. [define:HE_Signpost]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Vengeflies", "Evoca Moscavendetta", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, Vengeflies are created on each adjacent empty space. [define:HE_Vengefly]", "Quando si gioca [creature], viene creata una Moscavendetta in ogni spazio adiacente vuoto. [define:HE_Vengefly]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zoteling Spitter", "Sputapiccoli Zote", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, a random Zoteling is created in the owner's hand.", "Alla fine del turno del suo proprietario, un piccolo Zote casuale viene creato nella sua mano.", Language.Italian);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Absolute Radiance", "Splendore assoluto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abyss Creature", "Creatura dell'Abisso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is this...?", "Che cos'è...?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aluba", "Aluba", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Passive glider that prefers to dwell near acid waters.", "Aliante pacifico che predilige le acque acide.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ambloom", "Ambloom", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Simple-minded crawling fungus. Its cap is covered in a layer of hardened spikes.", "Fungo strisciante dalla mente semplice. Il cappello è ricoperto da uno strato di spine indurite.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Armoured Squit", "Squit corazzato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hardened squit, bred for battle in the Colosseum of Fools. Tougher and more aggressive than its wild ancestor.", "Squit temprato e allevato per combattere nel Colosseo degli Stolti. Più resistente e aggressivo del suo antenato selvatico.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspid Hatchling", "Cucciolo di Aspid", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspid Hunter", "Aspid cacciatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cunning predator that will best its prey by spitting corrosive liquid.", "Astuto predatore che sopraffà le prede sputando un liquido corrosivo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspid Mother", "Madre Aspid", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carries the eggs of its young inside its belly. Can hatch and birth its young as needed to deal with intruders.", "Porta le uova dei suoi piccoli nel ventre. Può farle schiudere e partorire i piccoli quando servono a respingere gli intrusi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baldur", "Baldur", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Although the shells of these youngsters are not thick enough to protect them from predators, they are still able to defend themselves if pressed.", "Il guscio di questi piccoli non è ancora abbastanza spesso da proteggerli dai predatori, ma sanno difendersi se messi alle strette.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Battle Obble", "Obble da battaglia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raised in the Colosseum. Although trained for combat, its movements and attacks are still haphazard.", "Allevato nel Colosseo. Malgrado l'addestramento al combattimento, i suoi movimenti e attacchi restano caotici.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Belfly", "Belfly", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thin wings hide a highly volatile belly. Will give its own life to protect its territory.", "Le ali sottili nascondono un ventre altamente esplosivo. Sacrifica la vita per proteggere il proprio territorio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bluggsac", "Bluggsac", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Placid but putrid creature. Holds rancid eggs within its gut.", "Creatura placida ma putrida, che custodisce uova rancide nel ventre.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blundering Oberlisk", "Oberlisk maldestro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This placid herbivore doesn't seem to wish harm on any of the creatures it shares a habitat with. However, its careless nature and bulky weight sometimes leads to messy accidents.", "Questo pacifico erbivoro non sembra voler far male alle creature con cui condivide l'habitat. Tuttavia, la sua indole sbadata e il suo peso causano talvolta spiacevoli incidenti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boofly", "Boofly", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Large, docile creature that peacefully buzzes around in the caverns of Kingdom's Edge.", "Grande creatura docile che ronza placidamente nelle caverne ai confini del regno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Vessel", "Contenitore spezzato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shattered corpse, reanimated by infected parasites.", "Cadavere spezzato, rianimato da parassiti infetti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brooding Mawlek", "Mawlek tormentato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ferocious but extremely social creature. Becomes aggressive if not able to mingle with its own kind.", "Creatura feroce ma estremamente socievole. Diventa aggressiva se non può stare con i suoi simili.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carver Hatcher", "Covascavaterra", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying creature that fires out dirtcarvers from its body when potential prey comes close.", "Creatura volante che espelle scavaterra dal corpo quando si avvicina una possibile preda.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charged Lumaflies", "Lumosche cariche", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A swarm of tiny, glowing insects. When threatened they cluster together, generating electricity.", "Uno sciame di minuscoli insetti luminosi. Quando sono minacciati si raggruppano e generano elettricità.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Hornhead?", "Carcassa cornuta?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, animated by a strange force. Uses its horn to attack any uninfected creature it finds.", "I resti di un insetto, animati da una forza strana. Usa il corno per attaccare ogni creatura non infetta che incontra.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wandering Husk?", "Carcassa errante?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, animated by a strange force, wandering around aimlessly.", "I resti di un insetto, animati da una forza strana, vagano senza meta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowardly Husk", "Carcassa codarda", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Former member of Hallownest's high society. Although made aggressive by the force inside, old instincts still occasionally compel it to run from danger.", "Un tempo membro dell'alta società di Hallownest. Sebbene la forza al suo interno lo renda aggressivo, i vecchi istinti lo spingono ancora talvolta a fuggire dal pericolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crawlid", "Crawlid", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Timid scavenger that crawls through the caverns looking for food.", "Timido spazzino che striscia nelle caverne in cerca di cibo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Cluster", "Ammasso di cristalli", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Crawler", "Strisciante di cristallo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Discharges searing beams of light from the crystals on its back as it crawls around, seemingly unaware.", "Strisciando emette raggi di luce rovente dai cristalli sulla schiena, apparentemente senza accorgersene.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Guardian", "Guardiano di cristallo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heavyset miner of the Crystal Peak overcome by crystal growth. Can discharge blazing beams of light from its crystallised limbs.", "Robusto minatore del Picco di Cristallo sopraffatto dalla crescita dei cristalli. Può emettere raggi incandescenti dagli arti cristallizzati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Hunter", "Cacciatore di cristallo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Small, airborne insect with its abdomen overgrown with crystals. Fires shards of fast-growing crystal at intruders.", "Piccolo insetto volante con l'addome ricoperto di cristalli. Spara frammenti di cristallo a crescita rapida contro gli intrusi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystallised Husk", "Carcassa cristallizzata", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remains of a bug who died amongst the crystals. Animated by a strange force, it attacks by firing beams of light from its crystallised arms.", "I resti di un insetto morto fra i cristalli. Animato da una forza strana, attacca emettendo raggi di luce dalle braccia cristallizzate.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Loodle", "Loodle mortale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loodle equipped with a helmet and taught to kill.", "Loodle dotato di elmo e addestrato a uccidere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deephunter", "Cacciatore degli abissi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crawls along walls and roofs, spitting burning venom at anything that passes by.", "Striscia su pareti e soffitti, sputando veleno urticante su tutto ciò che passa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deepling", "Piccolo degli abissi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infant of the Deepnest. Scuttles about in the darkness, learning the layout of its home.", "Cucciolo di Nidoscuro. Si muove rapidamente nel buio, imparando a conoscere la propria dimora.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dirtcarver", "Scavaterra", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swarming predator of the Deepnest. Burrows through the ground and bursts out to surprise prey.", "Predatore gregario di Nidoscuro. Scava nel terreno e ne sbuca per sorprendere le prede.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dung Defender", "Difensore dello sterco", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skilled combatant living at the heart of the Waterways. Assails intruders with balls of compacted dung.", "Abile combattente che vive nel cuore dei Canali. Assale gli intrusi con sfere di sterco compresso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Duranda", "Duranda", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Simple flying creature protected by a spikey shell.", "Semplice creatura volante protetta da un guscio spinoso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Durandoo", "Durandoo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Simple walking creature encased in a hard shell. Often found wading in shallow pools of acidic water.", "Semplice creatura terrestre racchiusa in un guscio duro. Spesso guada pozze poco profonde di acqua acida.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elder Baldur", "Baldur anziano", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bulky and covered in thick plating. Retracts into itself when attacked.", "Massiccio e coperto da una spessa corazza. Si ritrae quando viene attaccato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elder Hu", "Anziano Hu", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. Travelled the world tending to those affected by the plague.", "Sogno residuo di un guerriero caduto. Viaggiava per il mondo curando le vittime della pestilenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enraged Guardian", "Guardiano infuriato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Entombed Husk", "Carcassa sepolta", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mummified remains, deformed and enraged by infection.", "Resti mummificati, deformati e resi furiosi dall'infezione.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Failed Champion", "Campione fallito", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "False Knight", "Falso cavaliere", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A maggot driven mad by a strange force. Inhabits a stolen armoured shell.", "Larva di mosca impazzita per una forza strana. Abita in un guscio corazzato rubato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukefey", "Giovane distoma", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Youngest of its species. Its body is composed of teeth, wings and stomach.", "Il più giovane della sua specie. Il corpo è composto da denti, ali e stomaco.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fluke Larva", "Larva di distoma", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gla gla... Grow and grow... Nice and wet...", "Gla gla... Crescere e crescere... Bello e umido...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukemarm", "Madre dei distomi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An insatiable breeder. Has populated the Waterways with its kind. Its insides double as a nest for young Flukefeys.", "Prolifica madre insaziabile, ha popolato i Canali con i suoi simili. Le sue viscere fungono anche da nido per i Giovani distomi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukemon", "Distomostro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Worm-like creature that prefers damp, dark habitats.", "Creatura simile a un verme che predilige ambienti umidi e bui.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukemon's Body", "Corpo del Distomostro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukemon's Head", "Testa del Distomostro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukemunga", "Distoma vorace", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aged fluke, grown fat on the rich refuse found in the pipes below the capital.", "Distoma anziano, ingrassato con i ricchi rifiuti dei condotti sotto la capitale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fluke Zoteling", "Piccolo Zote distoma", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Folly", "Follia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once a highly intelligent bug, inflated by the misuse of soul.", "Un tempo insetto molto intelligente, gonfiato dall'uso improprio dell'anima.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fool Eater", "Divoratore di stolti", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carnivorous plant that snaps at any creature that comes close.", "Pianta carnivora che azzanna qualsiasi creatura si avvicini.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fungified Husk", "Carcassa fungina", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, consumed by a fungus. Frequently releases clouds of thick, deadly gas.", "Resti di un insetto consumati da un fungo. Rilasciano spesso dense nubi di gas letale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fungling", "Funghetto volante", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Passive fungal balloon. Internal gasses cause it to float.", "Pallone fungino pacifico. I gas al suo interno lo fanno fluttuare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fungoon", "Fungo volante", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fully grown fungal balloon. Spits built up internal gas at aggressors.", "Pallone fungino adulto. Sputa contro gli aggressori il gas accumulato al suo interno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Furious Vengefly", "Moscavendetta furiosa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vengefly whose body has been distorted by continued infection. Highly aggressive.", "Moscavendetta il cui corpo è stato deformato dall'infezione continua. Molto aggressiva.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Galien", "Galien", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. Trained in the wilds bordering the kingdom, hoping to become a Knight.", "Sogno residuo di un guerriero caduto. Si allenava nelle terre selvagge ai confini del regno, sperando di diventare cavaliere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Garpede", "Garpede", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant burrower covered in thick shell plates. Tirelessly travels the tunnels of the Deepnest.", "Enorme scavatore coperto da spesse placche di guscio. Percorre senza sosta i tunnel di Nidoscuro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gas Cloud", "Nube di gas", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Geo Deposit", "Giacimento di Geo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glimback", "Glimback", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slow, hardy creature. The crystals that grow on its back provide extra protection from foes above.", "Creatura lenta e robusta. I cristalli che crescono sulla sua schiena offrono ulteriore protezione dai nemici provenienti dall'alto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gluttonous Husk", "Carcassa golosa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Former member of Hallownest's high society. Uses its corpulent body as a weapon.", "Un tempo membro dell'alta società di Hallownest. Usa il suo corpo corpulento come arma.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goam", "Goam", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thickly armoured, it bursts from the ground to seize prey in its fangs.", "Coperto da una spessa armatura, sbuca dal terreno per afferrare la preda con le zanne.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Beast", "Bestia divina", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Tamer", "Domatrice divina", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Veteran warrior of the Colosseum of Fools. Fights by the side of creatures she has trained.", "Guerriera veterana del Colosseo degli Stolti. Combatte al fianco delle creature che ha addestrato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gorb", "Gorb", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. A mysterious life-form that claimed to contain all of the world's knowledge inside of its distended brain.", "Sogno residuo di un guerriero caduto. Questa misteriosa forma di vita sosteneva di custodire tutta la conoscenza del mondo nel suo cervello rigonfio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gorgeous Husk", "Carcassa magnifica", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corpulent Husk encrusted with a shining metal. Retains the instinct to hoard Geo.", "Carcassa corpulenta incrostata di metallo lucente. Conserva l'istinto di accumulare Geo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great Hopper", "Saltatore gigante", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaps around the edge of the world, trying to crush prey beneath its body.", "Balza ai confini del mondo, cercando di schiacciare le prede sotto il proprio corpo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great Husk Sentry", "Grande sentinella carcassa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animated remains of a Great Sentry, the most elite of the city's guards. Wields a greatnail and shell. Its powerful attacks cause heavy damage.", "Resti animati di una grande sentinella, l'élite delle guardie cittadine. Brandisce un grande chiodo e un guscio; i suoi attacchi potenti infliggono gravi danni.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mystery Jar", "Vaso misterioso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great Nailsage Sly", "Grande saggio del chiodo Sly", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Legendary sage of the nail arts and, recently, merchant of some success.", "Leggendario saggio delle arti del chiodo e, di recente, mercante di un certo successo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grey Prince Zote", "Principe grigio Zote", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grimm", "Grimm", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grimmkin Master", "Maestro della compagnia Grimm", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Powerful and devoted member of the Grimm Troupe.", "Potente e devoto membro della compagnia Grimm.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grimmkin Nightmare", "Incubo della compagnia Grimm", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrifying member of the Grimm Troupe.", "Terrificante membro della compagnia Grimm.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grimmkin Novice", "Novizio della compagnia Grimm", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Young and playful member of the Grimm Troupe.", "Giovane e giocoso membro della compagnia Grimm.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grub", "Larva", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor little creature, separated from its family. Do you have the courage to sacrifice it?", "Povera creaturina separata dalla sua famiglia. Hai il coraggio di sacrificarla?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grub?", "Larva?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gruz Mother", "Madre Gruz", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mature gruzzer that carries its young in its belly. Attacks by hurling its huge body around.", "Gruzzer adulto che porta i piccoli nel ventre. Attacca lanciando in giro il suo enorme corpo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gruzzer", "Gruzzer", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gulka", "Gulka", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aggressive plant-life that retracts protectively when danger is near and spits hard spikey balls when foes are at a distance.", "Pianta aggressiva che si ritrae per proteggersi quando il pericolo è vicino e sputa dure palle spinose contro i nemici lontani.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunted Spirit", "Spirito tormentato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Head of Zote", "Testa di Zote", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heavy Fool", "Stolto pesante", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warrior fighting for glory in the Colosseum of Fools. Aggressively charges down foes.", "Guerriero che combatte per la gloria nel Colosseo degli Stolti. Carica i nemici con ferocia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heavy Sentry", "Sentinella pesante", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animated remains of a large Hallownest Sentry. One of few in Hallownest strong enough to wield a greatnail.", "Resti animati di una grande sentinella di Hallownest. È fra i pochi del regno abbastanza forti da brandire un grande chiodo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heavy Zoteling", "Piccolo Zote pesante", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hive Guardian", "Guardiano dell'alveare", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protects the Hive by hurling its huge body at intruders.", "Protegge l'alveare lanciando il suo enorme corpo contro gli intrusi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hive Knight", "Cavaliere dell'alveare", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loyal protector of the Hive's Queen. Flightless but ferocious in battle.", "Leale protettore della regina dell'alveare. Non vola, ma è feroce in battaglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hiveling", "Apina", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hive Soldier", "Soldato dell'alveare", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defends the Hive against intruders with its extendable stinger.", "Difende l'alveare dagli intrusi con il suo pungiglione estensibile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hollow Knight", "Hollow Knight", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fully grown Vessel, carrying the plague's heart within its body.", "Contenitore adulto che porta il cuore della pestilenza nel proprio corpo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hopper", "Saltatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaps at prey and uses its sharp proboscis to drain vital fluids.", "Balza sulle prede e usa la proboscide affilata per succhiarne i fluidi vitali.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hopping Zoteling", "Piccolo Zote saltellante", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hornet", "Calabrone", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skilled protector of Hallownest's ruins. Wields a needle and thread.", "Abile protettrice delle rovine di Hallownest. Impugna ago e filo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hornet Sentinel", "Calabrone sentinella", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Bully", "Carcassa prepotente", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, animated by a strange force. It aggressively attacks any uninfected creature it finds.", "I resti di un insetto, animati da una forza strana. Attacca con aggressività ogni creatura non infetta che incontra.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Dandy", "Carcassa damerino", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Former member of Hallownest's high society. Limited offensive ability.", "Un tempo membro dell'alta società di Hallownest. Ha capacità offensive limitate.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Guard", "Guardia carcassa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a great Hallownest Crossguard, animated by a strange force. Instinct still drives it to guard its post against intruders.", "Resti di una grande guardia crociata di Hallownest, animati da una forza strana. L'istinto la spinge ancora a difendere il suo posto dagli intrusi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Hive", "Carcassa alveare", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowardly husk, its body colonised by hivelings.", "Carcassa codarda il cui corpo è stato colonizzato dalle Apine.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Hornhead", "Carcassa cornuta", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, animated by a strange force. Uses its horn to attack any uninfected creature it finds.", "I resti di un insetto, animati da una forza strana. Usa il corno per attaccare ogni creatura non infetta che incontra.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Miner", "Minatore carcassa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remains of a bug drawn to the Crystal Peak for its precious crystal. Its claw-pick now doubles as a fierce weapon.", "Resti di un insetto attirato al Picco di Cristallo dai suoi preziosi cristalli. Il suo piccone ad artiglio è ora anche un'arma feroce.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Sentry", "Sentinella carcassa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animated remains of a Hallownest Sentry. Still retains some memory of its former task.", "Resti animati di una sentinella di Hallownest. Conserva ancora qualche ricordo del suo vecchio compito.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Warrior", "Guerriero carcassa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, animated by a strange force. Wields a nail and shell.", "I resti di un insetto, animati da una forza strana. Brandisce un chiodo e un guscio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hwurmp", "Hwurmp", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiny and placid but swells to enormous size when threatened.", "Minuscolo e placido, si gonfia fino a diventare enorme quando è minacciato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infected Balloon", "Pallone infetto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infected Pustule", "Pustola infetta", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kingsmould", "Stampo reale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guard construct of Hallownest's Palace and skilled wielder of the curved claw-blade. Its heavy white armour protects a fragile body.", "Costrutto di guardia del palazzo di Hallownest, abile nell'uso della lama ricurva ad artiglio. La pesante armatura bianca protegge un corpo fragile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lance Sentry", "Sentinella lanciere", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winged Sentry of Hallownest equipped with a nail-lance. Charges at threats or throws its lance from a distance.", "Sentinella alata di Hallownest armata di una lancia-chiodo. Carica le minacce o scaglia la lancia da lontano.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lanky Zoteling", "Piccolo Zote allampanato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaping Husk", "Carcassa saltellante", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, animated by a strange force. It will instinctively leap at uninfected creatures to attack them.", "I resti di un insetto, animati da una forza strana. Balzano d'istinto sulle creature non infette per attaccarle.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lesser Mawlek", "Mawlek giovane", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Attacks by spitting acid and slashing with foreclaws.", "Attacca sputando acido e colpendo con gli artigli anteriori.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lifeblood Coccoon", "Bozzolo di sangue vitale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Contains a living core that bleeds precious lifeblood.", "Contiene un nucleo vivente che sanguina il prezioso sangue vitale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lifeseed", "Seme vitale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Small scuttling seed filled with Lifeblood, which can be extracted and consumed for its healthful properties.", "Piccolo seme guizzante pieno di sangue vitale, che si può estrarre e consumare per le sue proprietà salutari.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lightseed", "Seme luminoso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A single-celled organism, completely infected. Scurries about simple-mindedly.", "Organismo unicellulare completamente infetto. Corre qua e là senza pensare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Little Weaver", "Piccola tessitrice", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nimble spider that traverses its domain on thin strands of web. Often waits in ambush.", "Ragno agile che attraversa il proprio territorio su sottili fili di ragnatela. Spesso attende in agguato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loodle", "Loodle", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inhabits the wilds beside the Queen's Gardens. Not aggressive in nature, but its wild bouncing behaviour can be dangerous.", "Abita le terre selvagge accanto ai Giardini della Regina. Non è aggressivo per natura, ma i suoi salti sfrenati possono essere pericolosi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lost Kin", "Parente perduto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mace Bug", "Insetto mazza", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What the bug doin'?", "Che combina quell'insetto?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mantis Lord", "Signore delle mantidi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leader of the Mantis tribe and its finest warrior. Bears a thin nail-lance and attacks with blinding speed.", "Capo della tribù delle mantidi e suo miglior guerriero. Impugna una sottile lancia-chiodo e attacca a velocità accecante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mantis Lords", "Signori delle mantidi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mantis Petra", "Mantide Petra", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lurks amongst foliage and attacks by flinging wind-scythes from a distance.", "Si nasconde tra il fogliame e attacca da lontano lanciando falci di vento.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mantis Traitor", "Mantide traditrice", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once a member of the Mantis tribe, now cast out and driven mad by infection.", "Un tempo membro della tribù delle mantidi, ora esiliato e reso folle dall'infezione.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mantis Warrior", "Guerriero mantide", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Member of a proud tribe, fiercely protective of its territory. Launches savage attacks with bladed forelimbs.", "Membro di una tribù fiera che protegge ferocemente il proprio territorio. Attacca con violenza usando gli arti anteriori affilati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mantis Youth", "Giovane mantide", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Member of a proud tribe, fiercely protective of its territory. Launches stinging attacks with its needle sharp abdomen.", "Membro di una tribù fiera che protegge ferocemente il proprio territorio. Attacca pungendo con l'addome affilato come un ago.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Markoth", "Markoth", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. Only member of his forgotten tribe to take up a weapon.", "Sogno residuo di un guerriero caduto. Fu l'unico membro della sua tribù dimenticata a impugnare un'arma.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Marmu", "Marmu", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. Protector of the Queen's Gardens.", "Sogno residuo di un guerriero caduto. Protettore dei Giardini della Regina.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maskfly", "Mosca mascherata", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Massive Moss Charger", "Enorme caricatore muschioso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Family of creatures that have learnt to bulk up with moss and live as one.", "Famiglia di creature che hanno imparato a ingrossarsi con il muschio e a vivere come un solo essere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mawlurk", "Mawlurk", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Large, immobile creature. Wildly spits venom when intruders pass by.", "Grande creatura immobile. Sputa veleno furiosamente quando passano degli intrusi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Menderbug", "Insetto riparatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Member of an elusive guild of bugs fixated on the maintenance of Hallownest's many signs and wayposts.", "Membro di una sfuggente gilda di insetti dedita alla manutenzione dei numerosi cartelli e segnali di Hallownest.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minigun Aspid", "Aspid mitragliatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mistake", "Errore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once a highly intelligent bug, deformed by the misuse of soul.", "Un tempo insetto molto intelligente, deformato dall'uso improprio dell'anima.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moss Charger", "Caricatore muschioso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Timid creature that frightens away intruders by covering itself in huge clumps of moss.", "Creatura timida che spaventa gli intrusi ricoprendosi di enormi ciuffi di muschio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mosscreep", "Strisciante muschioso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weakling that covers itself in leaves to appear larger and hides amongst the undergrowth.", "Creatura debole che si copre di foglie per sembrare più grande e si nasconde nel sottobosco.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mossfly", "Mosca muschiosa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winged weakling that covers itself in leaves to appear larger. Hides amongst the undergrowth, fleeing if predators draw near.", "Debole creatura alata che si copre di foglie per sembrare più grande. Si nasconde nel sottobosco e fugge se si avvicinano predatori.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mosskin", "Muschioso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plant-like bug that charges at foes when close.", "Insetto simile a una pianta che carica i nemici quando si avvicinano.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moss Knight", "Cavaliere muschioso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protector of the Greenpath, trained in the ways of the Nail and the Shell.", "Protettore del Sentiero Verde, addestrato nelle arti del chiodo e del guscio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mossy Vagabond", "Vagabondo muschioso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lazy, portly Mosskin. Easily swayed by others.", "Muschioso pigro e corpulento. Si lascia influenzare facilmente dagli altri.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nailmaster Mato", "Maestro del chiodo Mato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nailmaster Oro", "Maestro del chiodo Oro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of the brothers of the nail, trained in combat by the Great Nailsage.", "Uno dei fratelli del chiodo, addestrato al combattimento dal grande saggio del chiodo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightmare King Grimm", "Grimm, re degli incubi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No Eyes", "Senza occhi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Knight?", "Il Cavaliere?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An enigmatic wanderer who descends into Hallownest carrying only a broken nail to fend off foes.", "Enigmatico viandante che scende a Hallownest con un solo chiodo spezzato per difendersi dai nemici.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obble", "Obble", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fat, slow, flying bug. Frequently discharges the acidic liquid stored in its round body.", "Insetto volante grasso e lento. Espelle spesso il liquido acido conservato nel suo corpo rotondo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obblobble", "Obblobble", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Larger cousin of the Obble. Pairs with a mate for life and will never leave its side.", "Cugino più grande dell'Obble. Sceglie un compagno per la vita e non lo lascia mai.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ooma", "Ooma", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Passive outer being protecting an aggressive, explosive core.", "Essere esterno pacifico che protegge un nucleo aggressivo ed esplosivo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paintmaster Sheo", "Maestro pittore Sheo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skilled and respected master of the nail. Always eager to learn new things.", "Abile e rispettato maestro del chiodo. È sempre desideroso di imparare cose nuove.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pale Lurker", "Predatore pallido", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forgotten champion of the Colosseum, drawn away by strange obsessions.", "Campione dimenticato del Colosseo, allontanato da strane ossessioni.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pilflip", "Pilflip", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Odd creature that adapts to changing situations by flipping over and using the limbs on the other side of its body.", "Strana creatura che si adatta alle situazioni capovolgendosi e usando gli arti sull'altro lato del corpo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Primal Aspid", "Aspid primordiale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wilder, ancestral form of the Aspid. Once thought extinct, they have reappeared at the edges of the world.", "Forma ancestrale e più selvaggia dell'Aspid. Creduta estinta, è riapparsa ai confini del mondo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pure Vessel", "Contenitore puro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pustulent Scholar", "Studioso pustoloso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Twister overgrown by infection...", "Contorcianime invaso dall'infezione...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Radiance", "Splendore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The light, forgotten.", "La luce, dimenticata.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rancid Egg", "Uovo rancido", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revek", "Revek", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. The protector of the Spirits' Glade.", "Sogno residuo di un guerriero caduto. Il protettore della Radura degli Spiriti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal Retainers", "Servitori reali", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shade", "Ombra", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Creeper", "Strisciante d'ombra", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Found only in deep, dark places. Has never been observed to eat or drink anything.", "Vive solo in luoghi profondi e bui. Non è mai stato visto mangiare o bere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shardmite", "Acaro frammento", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feeds on crystal dust and uses crystallised spines to protect itself from danger.", "Si nutre di polvere di cristallo e usa le spine cristallizzate per proteggersi dal pericolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sharp Baldur", "Baldur spinoso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hardened baldur, bred for battle in the Colosseum of Fools. Tougher and more aggressive than its wild ancestor.", "Baldur temprato e allevato per combattere nel Colosseo degli Stolti. Più resistente e aggressivo del suo antenato selvatico.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shielded Fool", "Stolto con scudo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warrior fighting for glory in the Colosseum of Fools. Warily approaches opponents with shell held high.", "Guerriero che combatte per la gloria nel Colosseo degli Stolti. Si avvicina con cautela agli avversari tenendo alto il guscio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shrumal Ogre", "Orco fungino", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Huge fungal creature that attacks by spitting corrosive venom and slamming its body into foes.", "Enorme creatura fungina che attacca sputando veleno corrosivo e lanciando il proprio corpo contro i nemici.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shrumal Warrior", "Guerriero fungino", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fungal creature that attacks intruders to protect its young.", "Creatura fungina che attacca gli intrusi per proteggere i piccoli.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shrumeling", "Funghetto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Siblings", "Fratelli", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fragments of a lingering will.", "Frammenti di una volontà residua.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Signpost", "Cartello", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sisters of Battle", "Sorelle della battaglia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slobbering Husk", "Carcassa sbavante", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The body of a bug, completely consumed by infection. Spits corrosive liquid.", "Corpo di un insetto completamente consumato dall'infezione. Sputa liquido corrosivo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Master", "Maestro delle anime", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Head of the Soul Sanctum. Hoarded soul hoping to stave off Hallownest's affliction, but eventually became intoxicated by its power.", "Capo del Santuario delle Anime. Accumulò anima sperando di scongiurare il male di Hallownest, ma finì inebriato dal suo potere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Twister", "Contorcianime", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Highly intelligent bug that uses arcane knowledge to twist soul into vicious spells.", "Insetto molto intelligente che usa conoscenze arcane per plasmare l'anima in feroci incantesimi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Tyrant", "Tiranno delle anime", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Warrior", "Guerriero delle anime", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Learned bug, wielding a refined pinblade. Enhances its combat prowess with harvested soul.", "Insetto colto armato di un'elegante lama ad ago. Accresce la propria abilità in combattimento con l'anima raccolta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiky Trap", "Trappola spinosa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spinning Scythe", "Falce rotante", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiny Husk", "Carcassa spinosa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overgrown with vegetation, it attacks by firing sharp spines from its body.", "Invasa dalla vegetazione, attacca sparando spine acuminate dal corpo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sporg", "Sporg", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A living fungus that detects nearby movement and fires out explosive spores that drift towards their target.", "Fungo vivente che rileva i movimenti vicini e spara spore esplosive che fluttuano verso il bersaglio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squit", "Squit", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A flying bug that charges at prey with its needle-like proboscis.", "Insetto volante che carica la preda con la proboscide simile a un ago.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stalking Devout", "Devoto in agguato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Worshipper of Herrah the Beast. Shields itself with hard plated foreclaws, then lashes out suddenly to cut down prey.", "Adoratore di Herrah la Bestia. Si protegge con gli artigli anteriori corazzati e poi scatta all'improvviso per abbattere la preda.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sturdy Fool", "Stolto robusto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warrior fighting for glory in the Colosseum of Fools. Uses crescent-shaped blades to cut down foes.", "Guerriero che combatte per la gloria nel Colosseo degli Stolti. Abbatte i nemici con lame a mezzaluna.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Collector", "Il Collezionista", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dark figure locked inside the Tower of Love. Preserves Hallownest's creatures in glass jars with particular attention given to Grubs.", "Figura oscura rinchiusa nella Torre dell'Amore. Conserva le creature di Hallownest in vasi di vetro, con particolare attenzione alle Larve.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Great Collector", "Il Grande Collezionista", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Knight", "Il Cavaliere", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiktik", "Tiktik", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A spiky, tenacious little bug that climbs all over the place using its pointed feet.", "Piccolo insetto spinoso e tenace che si arrampica ovunque usando i piedi appuntiti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Traitor Lord", "Signore traditore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deposed Lord of the Mantis tribe. Embraced the infection and turned against his sisters.", "Signore deposto della tribù delle mantidi. Ha accolto l'infezione e si è rivoltato contro le sue sorelle.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corpse Creeper", "Strisciante dei cadaveri", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grub Mimic", "Imitatore di larva", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nosk", "Nosk", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tuk", "Tuk", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The water brings everything you wish for... You just need to find it.", "L'acqua porta tutto ciò che desideri... Devi solo trovarlo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Turret Zoteling", "Piccolo Zote torretta", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Uoma", "Uoma", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smallest Jelly form. Passive and unaware, but pulsing with a dangerous electric charge.", "La più piccola forma di medusa. Passiva e inconsapevole, ma pulsante di una pericolosa carica elettrica.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Uumuu", "Uumuu", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Intelligent being that guards the inner chamber of the Teacher's Archives.", "Essere intelligente che custodisce la camera interna degli Archivi dell'Insegnante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vengefly", "Moscavendetta", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vengefly King", "Re delle Moscavendetta", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Patriarch of a vengefly colony. Swoops at intruders and cries out for reinforcements if threatened.", "Patriarca di una colonia di Moscavendetta. Piomba sugli intrusi e, se minacciato, richiama rinforzi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Violent Husk", "Carcassa violenta", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maddened by massive infection. Charges at enemies with no thought for its own preservation.", "Impazzita per la grave infezione. Carica i nemici senza pensare alla propria sopravvivenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Void Given Focus", "Vuoto focalizzato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...Void... Power... Without unity...", "...Vuoto... Potere... Senza unità...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Void Given Form", "Vuoto incarnato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Void Given Mind", "Vuoto dotato di mente", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Void Tendrils", "Tentacoli del vuoto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fragments of void taking the shape of sharp, thrashing tendrils.", "Frammenti del vuoto che assumono la forma di tentacoli affilati e agitati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Volatile Gruzzer", "Gruzzer esplosivo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gruzzer swollen with infection and primed to burst.", "Gruzzer gonfio d'infezione e pronto a esplodere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Volatile Mosskin", "Muschioso esplosivo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plant-like bug swollen with infection. Releases deadly gas when threatened.", "Insetto simile a una pianta, gonfio d'infezione. Se minacciato rilascia gas letale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Volatile Zoteling", "Piccolo Zote esplosivo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Volt Twister", "Contorcivolt", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Learned bug that adapted the teachings of the Soul Sanctum into a deadly fighting art. Attacks with bursts of electricity.", "Insetto colto che ha trasformato gli insegnamenti del Santuario delle Anime in un'arte di combattimento letale. Attacca con scariche elettriche.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wandering Husk", "Carcassa errante", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, animated by a strange force, wandering around aimlessly.", "I resti di un insetto, animati da una forza strana, vagano senza meta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watcher Knight", "Cavaliere osservatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Discarded shell of a Watcher Knight, re-animated by a swarm of infected flies.", "Guscio abbandonato di un cavaliere osservatore, rianimato da uno sciame di mosche infette.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "White Defender", "Difensore bianco", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winged Fool", "Stolto alato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warrior fighting for glory in the Colosseum of Fools. Flies just out of an opponent's reach then darts in for the kill.", "Guerriero che combatte per la gloria nel Colosseo degli Stolti. Vola appena fuori dalla portata dell'avversario, poi scatta per finirlo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winged Nosk", "Nosk alato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winged Sentry", "Sentinella alata", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying sentry of Hallownest. Patrols the heights of the vast cavern in which the city was built.", "Sentinella volante di Hallownest. Pattuglia le alture della vasta caverna in cui fu costruita la città.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winged Zoteling", "Piccolo Zote alato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wingmould", "Stampo alato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fly-like construct formed of white shell and a dark liquid interior.", "Costrutto simile a una mosca, formato da un guscio bianco e da un liquido scuro all'interno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Xero", "Xero", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. Executed for crimes against the King.", "Sogno residuo di un guerriero caduto. Fu giustiziato per crimini contro il re.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zote's Curse", "Maledizione di Zote", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zote", "Zote", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A self-proclaimed Knight, of no renown. Wields a nail he carved from shellwood, named 'Life Ender.'", "Cavaliere autoproclamato, privo di fama. Brandisce un chiodo ricavato dal legno di guscio, chiamato 'Fine della vita'.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. Disappeared during the plague.", "Sogno residuo di un guerriero caduto. Scomparve durante la pestilenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying predator that pursues its prey relentlessly.", "Predatore volante che insegue la preda senza tregua.", Language.Italian);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What are you", "Perché vieni", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "bothering me for?", "a disturbarmi?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What do you want,", "Cosa vuoi,", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "cur?", "miserabile?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Another fool", "Un altro stolto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "to be cut down", "da abbattere", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "by Life Ender...", "da Fine della vita...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fear not, cur...", "Non temere, miserabile...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your death", "La tua morte", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "will be swift.", "sarà rapida.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Umph!", "Umpf!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pfah!", "Bah!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're only dulling", "Stai solo smussando", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "your mandibles!", "le tue mandibole!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You almost struck me!", "Mi hai quasi colpito!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is this kingdom", "Questo regno", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "trying to mock me?", "sta cercando di deridermi?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph.", "Umpf.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Being overly devoted", "L'eccessiva dedizione", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "to one's duties", "ai propri doveri", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "is no virtue.", "non è una virtù.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What are you doing,", "Che cosa fai,", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you clumsy", "maldestro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "little oaf?!", "piccolo idiota?!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The air is foul", "L'aria è fetida", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and the townsfolk", "e gli abitanti", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "have beady eyes.", "hanno gli occhi da faina.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How miserable,", "Che miseria,", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "to be stuck here", "essere bloccato qui", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "instead of continuing", "invece di continuare", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "my quest...", "la mia missione...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How ghastly...", "Che orrore...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just what do you", "Ma cosa credi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "think you're doing?!", "di fare?!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't have time", "Non ho tempo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "for your adulation!", "per la tua adulazione!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm a Knight.", "Sono un Cavaliere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm not interested", "Non mi interessano", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "in your", "i tuoi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "childish games.", "giochi infantili.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you lost", "Ti sei perso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "in these dark tunnels?", "in questi tunnel bui?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yes, yes!", "Sì, sì!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All glory to me!", "Tutta la gloria a me!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll kill", "Ne ucciderò", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a thousand more!", "altri mille!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tremble before me!", "Trema davanti a me!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "doing, you clumsy", "fai, maldestro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "little oaf?!", "piccolo idiota?!", Language.Italian);

        }
    }
    public class HealthForAntsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for HealthForAnts Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dome Ant", "Formica a cupola", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loves to guard his friends", "Ama proteggere i suoi amici.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ants (Health)", "Formiche (salute)", Language.Italian);

        }
    }
    public class SideDeckSelectorMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Side_Deck_Selector Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a squirrel that can block fliers", "Uno scoiattolo capace di bloccare le creature volanti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bee Drone", "Fuco", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For when you need just one point of damage", "Per quando ti serve un solo punto di danno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ant Drone", "Formica maschio", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bee Drone", "Fuco", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not much, but it's an ant.", "Non è un granché, ma è una formica.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puppy", "Cucciolo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This energetic little puppy will dig up a fresh bone every turn", "Questo energico cucciolo scava e trova un osso fresco a ogni turno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spare Tentacle", "Tentacolo di riserva", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've never seen that [c:bR]thing[c:] before, but I can tell there are no bones in it.", "Non avevo mai visto quella [c:bR]cosa[c:], ma posso dire che non ha ossa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One-Eyed Goat", "Capra con un occhio solo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This goat generates additional blood...for a price", "Questa capra produce sangue aggiuntivo... a un prezzo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I didn't realize this thing came from eggs", "Non sapevo che questa cosa nascesse dalle uova.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emptier Vessel", "Contenitore ancora più vuoto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here you may replace the creatures in your [c:bR]side deck[c:]", "Qui puoi sostituire le creature del tuo [c:bR]mazzo secondario[c:].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Side Deck Second Chance", "Seconda occasione per il mazzo secondario", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are given the option to change your side deck on maps two and three", "Puoi cambiare il mazzo secondario sulla seconda e sulla terza mappa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leshy is ready to give us side deck options", "Leshy è pronto a offrirci delle opzioni per il mazzo secondario.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acceptable Sacrifice", "Sacrificio accettabile", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrificing [creature] will count as if two creatures were sacrificed", "Sacrificare [creature] conta come se fossero state sacrificate due creature.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Entrance", "Entrata dolorosa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will deal two damage to the player when it enters play.", "Quando [creature] entra in gioco, infligge due danni al giocatore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gelatinous", "Gelatinoso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] has no bones", "[creature] non ha ossa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a Side Deck", "Scegli un mazzo secondario", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Player selected sidedeck card", "Carta del mazzo secondario scelta dal giocatore", Language.Italian);


        }
    }
    public class TalkingPossumMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Talking_Possum Mod");


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, this one. Right. You can keep it. Not much use to me, anyway.", "Ah, questo qui. Va bene. Puoi tenerlo. Tanto a me non serve granché.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awesome Opossum", "Opossum fenomenale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Playing dead? What a despicable creature.", "Fingersi morto? Che creatura spregevole.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not-So-Awesome Opossum", "Opossum non così fenomenale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]Alright.[w:1]", "[e:anger]Va bene.[w:1]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]You must be... [w:0.4][c:#280085]confused[c:][w:1].", "[e:neutral]Devi essere... [w:0.4][c:#280085]confuso[c:][w:1].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I get it.[w:0.2] I do.[w:0.2] It sucks.[w:0.4]", "Capisco.[w:0.2] Davvero.[w:0.2] Fa schifo.[w:0.4]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]So, uh.[w:0.2] Hi.[w:0.2]", "[e:surprise]Allora, ehm.[w:0.2] Ciao.[w:0.2]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We're...[w:0.6] [e:anger]stuck together, I suppose.[w:0.2]", "Siamo...[w:0.6] [e:anger]bloccati insieme, suppongo.[w:0.2]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]It could be worse.[w:0.2]", "[e:neutral]Potrebbe andare peggio.[w:0.2]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Look on the [c:#280085]bright side![c:][w:0.4]", "Guarda il [c:#280085]lato positivo![c:][w:0.4]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... There's no bright side.", "... Non c'è un lato positivo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We're all doomed.[leshy:Quiet now.][w:2]", "Siamo tutti condannati.[leshy:Ora silenzio.][w:2]", Language.Italian);
