            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Now not so much.[w:1]", "[e:surprise]Ora non più tanto.[w:1]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]Cameras are ruined too.[w:2]", "[e:anger]Anche le macchine fotografiche sono rovinate per me.[w:2]", Language.Italian);
