            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Why are you[w:0.2]", "[e:quiet]Perché mi[w:0.2]", Language.Italian);
