            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]... If you must.[w:1]", "[e:surprise]... Se proprio devi.[w:1]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise][c:#1e0040]Lamb to the slaughter.[c:][w:1]", "[e:surprise][c:#1e0040]Un agnello al macello.[c:][w:1]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]This sounds...[w:0.6]", "[e:anger]Sembra...[w:0.6]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]... [c:#1e0040]acceptable.[c:][w:1]", "[e:surprise]... [c:#1e0040]accettabile.[c:][w:1]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Is it...[w:0.4] gonna...[w:0.4]", "[e:quiet]Farà...[w:0.4] mi farà...[w:0.4]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is it gonna hurt?[w:1]", "Farà male?[w:1]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]This is...[w:0.6] [e:quiet]fine.[w:1]", "[e:surprise]Va...[w:0.6] [e:quiet]bene.[w:1]", Language.Italian);
