            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'they fough amongst themselves to feed'", "«Combattevano tra loro per nutrirsi.»", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "apocalypse, the horrid amalgamation of the defenders of the forest. a shame how it ended for them", "L'Uccello dell'Apocalisse, orribile fusione dei difensori della foresta. Che triste fine per loro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Aspiration, it loves seeing the battlefield", "L'Aspirazione ama osservare il campo di battaglia.", Language.Italian);
