            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "emerald noon, expresseing only despair and ire", "Il mezzogiorno smeraldo esprime solo disperazione e ira.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the flesh idol, worshiped by those who are truly insane", "L'idolo di carne, venerato da chi è davvero folle.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Great Sap, usefull past the card", "La grande linfa è utile anche fuori dalla carta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "hod, the training meltdown", "Hod, il collasso dell'addestramento.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malkuth, The meltdown of annoying me", "Malkuth, il collasso che mi irrita.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the mirror of adjustment, some say it leads to another world", "Lo Specchio dell'adattamento. Alcuni dicono che conduca a un altro mondo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "netzach, the safety meltdown", "Netzach, il collasso della sicurezza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slime, heard he trying hard to make this mod good", "Slime, a quanto pare si impegna per rendere buona questa mod.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the band, popular amongst teens", "La band è popolare tra gli adolescenti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orchestra", "Orchestra", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the bear, it waits to show its true self", "L'orso aspetta di mostrare la sua vera natura.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the bloody, seems the blood never ends", "La sanguinosa: il sangue sembra non finire mai.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the box, dont stare into the keyhole for to long", "La scatola. Non guardare troppo a lungo nel buco della serratura.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The clockwork, the humming of its motors arent the only annoyance it makes", "Il meccanismo: il ronzio dei motori non è l'unico fastidio che provoca.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Current, an experiment that has never seen the real world", "La corrente, un esperimento che non ha mai visto il mondo reale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the cute, its looks can melt even the coldest hearts", "La tenera: il suo aspetto può sciogliere anche i cuori più freddi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this one is no longer cute", "Questa non è più carina.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the dream, a peaceful ram that loves to sleep", "Il sogno, un ariete pacifico che ama dormire.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "guess its dream came true", "Sembra che il suo sogno si sia avverato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the exposed, taking the direct approach", "L'esposta sceglie l'approccio diretto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The flower, living and walking on sunshine", "Il fiore vive e cammina alla luce del sole.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the fragment, the poor creature experimented on into its form", "Il frammento, una povera creatura ridotta così dagli esperimenti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Happy, calm yet in a state of excietment", "La felice è calma, ma eccitata.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the hatefull, innocent mind for what she hides underneath", "L'odiosa: sotto ciò che nasconde c'è una mente innocente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the helper, it just wants to help you out", "L'aiutante vuole solo darti una mano.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the judge, decider of the good and the bad", "Il giudice decide il bene e il male.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the killer, made with intent", "L'assassino è stato creato con uno scopo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the lady, no one knows what she truly looks like", "La signora: nessuno sa che aspetto abbia davvero.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The little red, hunting the wolf in a game of cat and mouse", "Il piccolo cappuccetto rosso dà la caccia al lupo in un gioco del gatto col topo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mad, its given up on playing nice", "La folle ha smesso di fare la brava.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Many, Containing all the fun of 5 in 1", "La molteplice racchiude il divertimento di 5 in 1.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the masiyah, the prophet that speaks past death", "Il messia, il profeta che parla oltre la morte.", Language.Italian);
