            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Moral, It Tries but fails to keep balance", "La morale tenta invano di mantenere l'equilibrio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yin and Yang", "Yin e Yang", Language.Italian);
