            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the phoenix, its ashes keep it forever alive", "La fenice, le cui ceneri la mantengono in vita per sempre.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Plague, its only the beginning", "La peste, è solo l'inizio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the poisoned, this apple keeps everyone away", "L'avvelenata: questa mela tiene tutti lontani.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the reindeer, dragging christmas fun all over the world", "La renna trascina l'allegria natalizia in tutto il mondo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Sad, its destined to never see the light", "La triste è destinata a non vedere mai la luce.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Today's Sad Look", "Espressione triste di oggi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the sniper, one shot is all it needs", "Al cecchino basta un colpo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the star, the center of both attention and fashion", "La star, al centro dell'attenzione e della moda.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the swan, its song sound similar to those of the band", "Il canto del cigno somiglia a quello della band.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The train, best not walk in its way", "Il Treno: meglio non mettersi sulla sua strada.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the tree, spreading its roots to help its allies", "L'albero estende le radici per aiutare gli alleati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the true hatred, seems she let out what she had inside", "Il vero odio sembra aver liberato ciò che aveva dentro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the wolf, seems cute on first glance", "Il lupo sembra carino a prima vista.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the woodsman, sweeping the forest with its axe", "Il boscaiolo spazza la foresta con l'ascia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Army, they never seem to end", "L'esercito sembra non finire mai.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've never seen this one here", "Non l'ho mai visto qui.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The CherryTree, Contains the bodies of thousands", "Il ciliegio contiene i corpi di migliaia di persone.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Fruit, its ripe for the picking.", "Il frutto è maturo, pronto per essere raccolto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Galaxy, a blessing, and a curse.", "La galassia, una benedizione e una maledizione.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The greedfull, carefull not to touch it.", "L'avida: attento a non toccarla.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Hive, The true ruler of the hive", "L'alveare, il suo vero sovrano.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Innocent, Ignorant in everything besides pain", "L'innocente non conosce altro che il dolore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mountain, it smiles upon you ", "La montagna ti sorride.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Nest, its presence is unsettling  ", "Il nido: la sua presenza è inquietante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Nothing...", "Il nulla...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Silent, Performing the best orchestra around.", "La Silente, che dirige la migliore orchestra in circolazione.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Silent", "La Silente", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Swarm, he dresses for the occasion", "Lo sciame si è vestito per l'occasione.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Trap, So Cute yet so deadly", "La trappola, così carina eppure letale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiphereth, the command meltdown", "Tiphereth, il collasso del comando.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Violet Dawn", "Alba violetta", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "violet dawn, radiating the field", "L'alba violetta irradia il campo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "violet Midnight", "Mezzanotte violetta", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "we tried to accept it,we wanted to understand them", "Abbiamo cercato di accettarlo, volevamo capirli.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Violet noon", "Mezzogiorno violetto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "violet noon, enscrybing the words of their gods", "Il mezzogiorno violetto incide le parole dei loro dèi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So that explains the chills", "Questo spiega i brividi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the white night, the true end of the world", "La notte bianca, la vera fine del mondo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yesod, the concealing meltdown", "Yesod, il collasso dell'occultamento.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Claw", "L'Artiglio", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps you can survive this white midnight.", "Forse sopravviverai a questa mezzanotte bianca.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You definitely won't press the button, right?", "Non premerai il pulsante, vero?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If it's not voluntary, does anyone really need to be 'fixed'?", "Se non è volontario, qualcuno ha davvero bisogno di essere «riparato»?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No one wants to know what truly protects them.", "Nessuno vuole sapere cosa li protegge davvero.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is currently unclear why such a painting would exist.", "Al momento non è chiaro perché esista un simile dipinto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gloomy Seahorse", "Cavalluccio marino cupo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Play the fatal movement.", "Suona il movimento fatale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why does the mysterious ray appear within the facility?", "Perché la misteriosa razza appare nella struttura?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stingray", "Razza", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What sorrow.", "Che tristezza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Intangible creation.", "Una creazione intangibile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A scarecrow soaked in fresh blood.", "Uno spaventapasseri intriso di sangue fresco.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you yearn for blessings?", "Desideri benedizioni?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps, she can protect no one.", "Forse non può proteggere nessuno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mechanical creations, restoring peace and health", "Creazioni meccaniche che riportano pace e salute.", Language.Italian);

        }
    }
    public class NevernamedsBestiaryMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Nevernameds_Bestiary Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ace Lord", "Signore degli assi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aderyn Y corph", "Aderyn Y corph", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The corpse bird. It's appearance portends the end.", "L'uccello dei cadaveri. La sua comparsa annuncia la fine.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adipocere", "Adipocera", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor little corpse wax, it can be molded into any shape you can think of.", "Povera piccola adipocera, può essere modellata in qualsiasi forma immaginabile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It lurks below the water, until the time is ripe to rend the land for prey.", "Si nasconde sott'acqua finché non arriva il momento di squarciare la terra in cerca di prede.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahuizotl", "Ahuizotl", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Albatross", "Albatro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The noble albatross. It's vast wingspan creates an impressive downdraft.", "Il nobile albatro. La sua enorme apertura alare crea una notevole corrente discendente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Albatross Chick", "Pulcino di albatro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The young of the immense albatross, it seems almost lost inside of it's own down.", "Il piccolo dell'enorme albatro sembra quasi perdersi nel proprio piumino.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gar Roe", "Uova di luccio alligatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toxic gar roe, will kill anything that swallows it.", "Le uova tossiche uccidono chiunque le ingoi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alligator Gar", "Luccio alligatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ferocious Alligator Gar. It squirts out it's toxic eggs when frightened.", "Il feroce luccio alligatore spruzza le sue uova tossiche quando si spaventa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amorphous Shame", "Vergogna amorfa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...such a shame...", "... che vergogna...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anaconda", "Anaconda", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't... don't say it. I have heard it all before, and it is not funny.", "Non... non dirlo. Ho già sentito tutto e non fa ridere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anansi", "Anansi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anansi, the many legged trickster. He attacks multiple times per turn, in flagrant disregard for the rules.", "Anansi, l'imbroglione dalle molte zampe. Attacca più volte per turno, ignorando sfacciatamente le regole.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anchimayen", "Anchimayen", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anemone", "Anemone", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The soft, unassuming anemone- it seems to have remarkable potential for propagation, but no means as of yet...", "La morbida e modesta anemone sembra avere un notevole potenziale di propagazione, ma per ora non ne ha i mezzi...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Angel Shark", "Squalo angelo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Despite the name, it is far from divine.", "Nonostante il nome, è tutt'altro che divino.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That irritating canine...", "Quel fastidioso canide...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anteater", "Formichiere", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The slothly anteater only attacks with vigour when presented with a meal.", "Il pigro formichiere attacca con vigore solo quando gli viene offerto un pasto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antingaw", "Antingaw", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiar mollusk. It gathers sustenance from burrowing into barren rock...", "Uno strano mollusco. Si nutre scavando nella roccia sterile...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So small... so fragile...", "Così piccolo... così fragile...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The larvae of the antlion. It's skill for trapping knows no match... in the insect world.", "La larva del formicaleone. La sua abilità nel tendere trappole non ha eguali... nel mondo degli insetti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ararach", "Ararach", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The infinilegged crawler, the Ararach never settles on a definitive strategy of attack for long...", "Ararach, il strisciante dalle infinite zampe, non mantiene mai a lungo una strategia d'attacco...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The archerfish is quick to retaliate to any confrontation with a precise jet of water.", "Il pesce arciere risponde subito a ogni minaccia con un preciso getto d'acqua.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Areion", "Areion", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The eternally running Areion. It loyally moves wherever it's owner demands it in the blink of an eye.", "Areion corre senza sosta. Si sposta fedelmente in un battito di ciglia dove il proprietario desidera.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Artful Magister", "Magister astuto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspidochelone", "Aspidochelone", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That ruthless spiny turtle... it shares it's spines with it's comrades..", "Quella spietata tartaruga spinosa... condivide le sue spine con i compagni.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Automamox", "Automamox", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Axehandle Hound", "Segugio dal manico d'ascia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The peculiar axehandle hound. It uses it's sharp, bladed nose to cut clean through it's foes with the cold precision of a lumberjack...", "Lo strano segugio dal manico d'ascia. Con il naso affilato come una lama taglia i nemici con la fredda precisione di un boscaiolo...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Axe Murderer", "Assassino con l'ascia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Through night he hunts, in blackened brush, the bite of an axe heralds a blood red stream.", "Caccia di notte tra i cespugli anneriti; il morso di un'ascia annuncia un fiume rosso sangue.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Babai", "Babai", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baboon", "Babbuino", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Far more vicious than its name and appearance would betray- it needs only a reason to strike.", "Molto più feroce di quanto suggeriscano nome e aspetto: gli basta una ragione per colpire.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bakunawa", "Bakunawa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The lengthy Bakunawa, terror of the sea and skies.", "Il lungo Bakunawa, terrore dei mari e dei cieli.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Balaur", "Balaur", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The three-headed Balaur dragon. It lashes out with each of it's maws when threatened.", "Balaur, il drago a tre teste. Se minacciato, attacca con ognuna delle sue fauci.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bald Eagle", "Aquila di mare testabianca", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Truly the most patriotic of birds.", "Il più patriottico degli uccelli, senza dubbio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ball Droid", "Droide sferico", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Balloondroid", "Droide palloncino", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bandito", "Bandito", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiar deathcard- no matter how many times I tear it to pieces, I always find it back in my deck...", "Una strana carta della morte. Per quante volte la faccia a pezzi, la ritrovo sempre nel mio mazzo...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bannana", "Banana", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a small, sweet spider... It couldn't hurt a fl- ...oh", "Un ragnetto così piccolo e dolce... Non farebbe male a una mo... oh.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Barnacle", "Balano", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unimpressive barnacle. Anything that strikes it will be torn to shreds on it's rough shell.", "L'insignificante balano. Chiunque lo colpisca sarà fatto a pezzi dal suo guscio ruvido.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Basilisk", "Basilisco", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The grim basilisk. Life withers and dies under it's mere gaze.", "Il tetro basilisco. La vita appassisce e muore al suo solo sguardo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Bat", "Pipistrello in fiamme", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The first... and last time one of my... associates attempted to use living organisms to it's own advantage.", "La prima... e ultima volta che uno dei miei... soci ha tentato di sfruttare organismi viventi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Batfly", "Mosca pipistrello", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The perturbing batfly. It clings to airborne creatures for a free ride.", "L'inquietante mosca pipistrello. Si aggrappa alle creature volanti per viaggiare gratis.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bat Tery", "Pipistrello batteria", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beached Whale", "Balena spiaggiata", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The poor thing, completely out of it's element... it bursts upon death.", "Poverina, completamente fuori dal suo elemento... Esplode quando muore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beast Of Exmoor", "Bestia di Exmoor", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The illusory exmoor cat... hard to catch, harder to kill.", "L'illusorio gatto di Exmoor... difficile da catturare, ancora più da uccidere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Belladin", "Campaladino", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bellbird", "Uccello campana", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Their cry is melodic, like the ringing of a great chime.", "Il loro verso è melodioso, come il suono di una grande campana.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bellbot", "Bot campana", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bhoot", "Bhoot", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How she floats above the holy earth... I wonder what form she will take next!", "Come fluttua sopra la terra sacra... Chissà quale forma assumerà poi!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bind Warden", "Custode dei vincoli", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Biscione", "Biscione", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vicious biscione, it is insatiable in it's lust for flesh.", "Il feroce Biscione, insaziabile nella sua fame di carne.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bishop", "Vescovo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bison", "Bisonte", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trampling Bison. It destroys anything in it's path, and becomes more enraged as it becomes more soaked with blood...", "Il bisonte travolgente distrugge tutto sul suo cammino e si infuria sempre più man mano che si copre di sangue...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Dog", "Cane nero", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The grim black dog, haunter of graveyards... omen incarnate.", "Il tetro cane nero infesta i cimiteri... un presagio incarnato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Egg", "Uovo nero", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something pulses dimly, below the surface...", "Qualcosa pulsa debolmente sotto la superficie...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Giant Squirrel", "Scoiattolo gigante nero", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The shadowy Black Giant Squirrel. It hits hard and is easily deployed, but perishes with no brothers or sisters by it's side...", "L'oscuro scoiattolo gigante nero colpisce forte ed è facile da giocare, ma muore senza fratelli o sorelle accanto...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Kite", "Nibbio bruno", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It carries the flames of a previous inferno to drive prey from cover...", "Trasporta le fiamme di un incendio passato per stanare le prede...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Widow", "Vedova nera", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The black widow spider. It's infamous bite kills swiftly.", "La vedova nera. Il suo famigerato morso uccide rapidamente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blank Obelisk", "Obelisco vuoto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A blank obelisk. Unremarkable.", "Un obelisco vuoto. Nulla di notevole.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blast Termite", "Termite esplosiva", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disgusting blasting termite. It explodes it's foes upon death.", "La ripugnante termite esplosiva fa esplodere i nemici alla sua morte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blind Mouse", "Topo cieco", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those blind mice... always travelling in a group. See how they run...", "Quei topi ciechi... sempre in gruppo. Guardali correre...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blind Scorpion", "Scorpione cieco", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The poor blinded scorpion. It's venom is immaculate, but it's aim?... less so.", "Il povero scorpione cieco. Il suo veleno è impeccabile, ma la sua mira... un po' meno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloated Leech", "Sanguisuga gonfia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disquieting leech. It has reached full maturity.", "L'inquietante sanguisuga è giunta a piena maturità.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blockhead", "Testa di blocco", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A comically frontheavy insect.", "Un insetto dalla parte anteriore comicamente pesante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodbag", "Sacca di sangue", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Cell", "Cellula sanguigna", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Knight", "Cavaliere di sangue", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Red Dog", "Cane rosso sangue", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The infamous blood red dog, nothing can stop it's lust for combat. We'll have tea in hell today...", "Il famigerato cane rosso sangue: nulla può fermare la sua sete di battaglia. Oggi prenderemo il tè all'inferno...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodstopper", "Ferma sangue", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Witch", "Strega del sangue", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bloodstarved beast. It will wither and die if it does not taste violence each turn.", "La bestia assetata di sangue appassisce e muore se non assapora violenza a ogni turno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloody Sack", "Sacco insanguinato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blowfly", "Moscone", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disgusting.", "Disgustoso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bluebottle", "Moscone blu", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bluebottle... what secrets lie beyond it's squishy facade?", "Il moscone blu... quali segreti nasconde il suo aspetto molle?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue-Ringed", "Polpo dagli anelli blu", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Blue-Ringed Octopus. It's venom is one of the most potent in the world...", "Il polpo dagli anelli blu. Il suo veleno è tra i più potenti al mondo...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Whale", "Balenottera azzurra", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The greatest mortal beast ever to roam the seas... but not the greatest immortal one.", "La più grande bestia mortale che abbia mai solcato i mari... ma non la più grande immortale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BoardWipe", "Pulizia del tavolo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bobbit Worm", "Verme Bobbit", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The terrifying bobbit worm. It leaps from it's aquatic burrow to attack with it's razor sharp jaws.", "Il terrificante verme Bobbit balza fuori dalla tana acquatica e attacca con mascelle affilate come rasoi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bobcat", "Lince rossa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Often underestimated, the Bobcat will strike the moment it is played.", "Spesso sottovalutata, la lince rossa colpisce appena viene giocata.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Body Snatcher", "Ladro di corpi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boil", "Foruncolo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A festering little blotch.", "Una piccola macchia infetta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bolotnik", "Bolotnik", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bloated swampman. It drags others down to hades- returning for more.", "L'uomo di palude gonfio trascina gli altri negli inferi e torna a prenderne altri.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bombardier Beetle", "Coleottero bombardiere", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The incandescant bombardier beetle. It's boiling hot secretions scald it's prey.", "L'incandescente coleottero bombardiere. Le sue secrezioni bollenti scottano le prede.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Cell", "Cellula ossea", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Clutter", "Mucchio d'ossa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boneworm", "Verme d'ossa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The morbid boneworm. It excells in bringing remains to the surface of the churning soil...", "Il macabro verme d'ossa eccelle nel portare i resti sulla superficie del terreno smosso...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Booting Bot", "Bot avviatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bot Printer", "Stampante di bot", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bowerbird", "Uccello giardiniere", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The crafty bowerbird, master of manipulating materials around itself.", "L'astuto uccello giardiniere è maestro nel manipolare i materiali che lo circondano.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Box Jelly", "Cubomedusa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Small, but possessing of a crippling set of stingers.", "Piccola, ma dotata di pungiglioni paralizzanti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Proceed", "Procedi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brazen Bull", "Toro di bronzo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The horrific brazen bull. A true metric of human depravity.", "L'orribile toro di bronzo. Una vera misura della depravazione umana.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's go!", "Andiamo!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Play me properly", "Giocami come si deve", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAAH, YES!", "HAHAHAHA, SÌ!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YES, YES!", "SÌ, SÌ!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S MAKE A RING", "FACCIAMO UN CERCHIO", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OF FIRE", "DI FUOCO", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAH", "AHAHAHAHA", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BURN", "BRUCIARE", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I want to", "Voglio", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "see the fire", "vedere il fuoco", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "for glory!", "Per la gloria!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yes, very well", "Sì, molto bene", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's get to work", "Mettiamoci al lavoro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHA", "AHAHAHA", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAHAHAH", "AHAHAHAHAHA", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TO GLORY", "ALLA GLORIA", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAHAH", "AHAHAHAHA", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAH, YES!", "AHAHA, SÌ!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IMPROVE ME", "MIGLIORAMI", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can be", "Posso essere", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So much more!", "Molto di più!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you want.", "Se vuoi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SACRIFICE ME!", "SACRIFICAMI!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YES", "SÌ", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I WILL DIE", "MORIRÒ", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FOR YOU", "PER TE", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's up to you", "Decidi tu", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harder!", "Più forte!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO IT!", "FALLO!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAHA!", "AHAHAHAHA!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YES! MORE!", "SÌ! ANCORA!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Very good.", "Molto bene.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THANK YOU, THANK YOU!", "GRAZIE, GRAZIE!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VICTORY?", "VITTORIA?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TO GLORY!", "PER LA GLORIA!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YES, YES", "SÌ, SÌ", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brine Shrimp", "Artemia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The tiny, fleeting brine shrimp, so small it's as if it's not even there...", "La minuscola e fugace artemia, così piccola da sembrare inesistente...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brollachan", "Brollachan", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wicked Brollachan. It can take many powerful forms...", "Il malvagio Brollachan può assumere molte forme potenti...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brown Recluse", "Ragno recluso marrone", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unassuming Brown Recluse. It attacks when threatened.", "Il modesto ragno recluso marrone attacca quando viene minacciato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Budgerigar", "Cocorita", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A friendly bird of domesticated breed, the Budgerigar will follow your command...", "La cocorita, un amichevole uccello domestico, seguirà i tuoi ordini...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bugbear", "Bugbear", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The horrifying Bugbear. No creatures wish to remain in it's presence.", "L'orribile Bugbear. Nessuna creatura vuole restare in sua presenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Busted Bot", "Bot fuori uso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Busted Conduit", "Conduttore fuori uso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buzzard", "Poiana", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The shameless buzzard- an inescapable symbol of death in the sands.", "La sfacciata poiana, un inevitabile simbolo di morte nelle sabbie.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiny Ant", "Formica spinosa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A friendly ant covered in sharp thorns.", "Una formica amichevole ricoperta di spine affilate.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The splifficated Cactus Cat, it roams the desert drinking the fermented juice of it's lookalike plant...", "Il gatto cactus ubriaco vaga nel deserto bevendo il succo fermentato della pianta a cui somiglia...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caged Beasts", "Bestie in gabbia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor, caged animals. Won't you set them free?", "Poveri animali in gabbia. Non li libererai?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calygreyhound", "Calygreyhound", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The calygreyhound- a confusing chimeric clash which nonetheless stirs the loyalties of it's comrades.", "Il Calygreyhound, una sconcertante chimera che ispira comunque la lealtà dei compagni.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camazotz", "Camazotz", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camazotz, the bat god. He flies low amongst his enemies, slashing them with his bloodstained claws.", "Camazotz, il dio pipistrello. Vola basso tra i nemici e li lacera con artigli insanguinati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cam Drone", "Drone con telecamera", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stocky camel, it is resilient against most any threat", "Il robusto cammello resiste a quasi ogni minaccia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camel Spider", "Solifugo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Camel Spider... an unpleasant arachnid to even gaze upon.", "Il solifugo... un aracnide sgradevole anche solo da guardare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candiru", "Candirù", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bloodsucking fish with a terrifying reputation.", "Un pesce succhiasangue dalla reputazione terrificante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Canopic Hawk", "Falco canopo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A delicate ceramic bird, full of guts...", "Un delicato uccello di ceramica, pieno di viscere...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The much-beloved Capybara... it's fighting spirit is closely tied to it's wellbeing.", "L'amatissimo capibara... il suo spirito combattivo è strettamente legato al suo benessere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caracal", "Caracal", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A quizzacious predator, ready to leap at any unsuspecting prey.", "Un predatore curioso, pronto a balzare su ogni preda ignara.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carrion Fly", "Mosca carognaia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disgusting carrion fly. Drawn to death.", "La ripugnante mosca carognaia. Attratta dalla morte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catalogue Keeper", "Custode del catalogo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catron", "Catron", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cattle Rustler", "Ladro di bestiame", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cellar Spider", "Ragno delle cantine", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Cellar spider. An exemplar of all arachnida.", "Il ragno delle cantine. Un esempio per tutti gli aracnidi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chameleon", "Camaleonte", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A chameleon always changes it's spots, as is the proverb.", "Come dice il proverbio, il camaleonte cambia sempre le sue macchie.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enraged Fey", "Fata furiosa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The development of the changeling is entirely dependant on it's early childhood... violence begets violence.", "Lo sviluppo del mutaforma dipende interamente dalla prima infanzia... La violenza genera violenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pitiful Fey", "Fata pietosa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Changeling", "Mutaforma", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chaos Card", "Carta del caos", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chaos Engine", "Motore del caos", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charred Lump", "Grumo carbonizzato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charybdis", "Cariddi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charybdis, the infernal vortex. Sucks all around it into it's collossal maw.", "Cariddi, il vortice infernale. Risucchia tutto ciò che la circonda nelle sue immense fauci.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A vindictive, nasty little bird.", "Un uccellino vendicativo e maligno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chicken Bones", "Ossa di pollo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awfully sharp... and awfully disposable.", "Terribilmente affilate... e terribilmente usa e getta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chimpanzee", "Scimpanzé", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The true utility of the chimp lies in it's dilligent hands...", "La vera utilità dello scimpanzé risiede nelle sue mani operose...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chiral Crawler", "Strisciante chirale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can a creature that drags its shackles along with it ever truly be free?", "Una creatura che trascina le proprie catene può mai essere davvero libera?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chochin", "Chochin", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aha! The little lantern spook, such a mischevious little spirit it is!", "Ah! Il piccolo spettro della lanterna, che spiritello dispettoso!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chuman", "Chuman", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unholy union.", "Unione empia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This beast of the night will tear apart any small prey he finds...", "Questa bestia della notte farà a pezzi ogni piccola preda che troverà...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clanklion", "Clanklion", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clumsy Pupil", "Allievo maldestro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cobra", "Cobra", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The swift cobra. Usually passive, but it delivers a nasty bite when startled.", "Il rapido cobra. Di solito è tranquillo, ma morde ferocemente se viene spaventato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cockle", "Cuore di mare", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unremarkable cockle, it feeds upon the remnants of the dead...", "Il comune cuore di mare si nutre dei resti dei morti...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Code Thief", "Ladro di codice", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coinchenn", "Coinchenn", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It lurks in the shadows of history, and shows no mercy to its prey.", "Si nasconde nelle ombre della storia e non mostra pietà alle sue prede.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Colossal Squid", "Calamaro colossale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The colossal squid. It drags it's foes down to a watery grave.", "Il calamaro colossale. Trascina i nemici in una tomba d'acqua.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tubular Bells", "Campane tubolari", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cone Snail", "Cono marino", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The venomous cone snail. Beware it's paralysing toxin.", "Il velenoso cono marino. Attento alla sua tossina paralizzante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conjurer", "Evocatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Copepod", "Copepode", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unassuming copepod, resilient to the last.", "L'umile copepode, resistente fino all'ultimo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mysterious copycat. When it perishes, it... warps, to mimic it's murderer.", "Il misterioso imitatore. Quando perisce, si... deforma per assumere l'aspetto del suo assassino.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coral", "Corallo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A stoic coral colony, akin more to the landscape around it than to any other beast...", "Una stoica colonia di corallo, più simile al paesaggio circostante che a qualunque altra bestia...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Counstabot", "Poliziotto bot", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cow", "Mucca", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Centuries of domestication have not made it any less stubborn...", "Secoli di domesticazione non l'hanno resa meno testarda...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cowardly lion. It attempts to live up to the ferocity of it's cousins, but with little success.", "Il leone codardo. Cerca di eguagliare la ferocia dei suoi cugini, ma con scarso successo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowardly Lion", "Leone codardo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowbird", "Molotro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Too cowardly to remain for long, the cowbird is always eager to cause trouble.", "Troppo codardo per fermarsi a lungo, il molotro è sempre pronto a creare scompiglio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time for crab.", "È l'ora del granchio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crab Spider", "Ragno granchio", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The hardy crab spider, it clings relentlessly to any source of food or warmth.", "Il robusto ragno granchio si aggrappa senza sosta a ogni fonte di cibo o calore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crayfish", "Gambero di fiume", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unrelenting crayfish. It changes the orientation of it's claws each turn.", "L'inesorabile gambero di fiume. Cambia l'orientamento delle chele a ogni turno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cremator", "Inceneritore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimson Paladin", "Paladino cremisi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crooked Mouse", "Topo contorto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It was never the same after a run in with a crooked cat...", "Non è più stato lo stesso dopo un incontro con un gatto contorto...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crooked Wraith", "Spettro contorto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strange one, this. Even I don't know its twisted past.", "Una creatura strana, questa. Neppure io conosco il suo passato contorto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crucibulum", "Crucibulum", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiar little snail, forever growing it's conical shell.", "Una piccola lumaca particolare, il cui guscio conico cresce senza sosta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Healer", "Guaritore di cristallo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cubit", "Cubito", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curly-Legged Cat", "Gatto dalle zampe ricurve", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its twisted legs coil and bend in ways inexplicable. It is full of potential.", "Le sue zampe contorte si avvolgono e si piegano in modi inspiegabili. È pieno di potenziale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curruid", "Curruid", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clawed lord of the waves, the Curruid has but one blind spot.", "Signore artigliato delle onde, il Curruid ha un solo punto cieco.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed Child", "Bambino maledetto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That... should not be in my deck...", "Quello... non dovrebbe essere nel mio mazzo...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Stunted... Wolf... I thought I threw him- ...I mean, this, away...", "Il... lupo... gracile... Credevo di averlo butta... volevo dire, di aver buttato via questo...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The... stoat. Did I leave this here?", "L'... ermellino. L'ho lasciato qui?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The... pungent... stinkbug?..", "La... puzzolente... cimice?..", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cyclops", "Ciclope", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The diminutive cyclops. It's great eye holds a perfect image of the past.", "Il minuscolo ciclope. Il suo grande occhio custodisce un'immagine perfetta del passato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aim well.", "Mira bene.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shoot with caution.", "Spara con cautela.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aim me well.", "Mira bene con me.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acceptable draw.", "Pescata accettabile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Survive.", "Sopravvivi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am your instrument.", "Sono il tuo strumento.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will succeed.", "Riuscirò.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you are", "Se ne sei", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "certain.", "certo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I trust", "Mi fido", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bigger", "del quadro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "picture.", "più ampio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Over exposed.", "Sovraesposto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This turn?", "Questo turno?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temporal Misplay.", "Errore temporale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remember this.", "Ricordalo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Certainly.", "Certamente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have", "Hai", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "aimed... well.", "mirato... bene.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Within acceptable", "Entro parametri", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "parameters.", "accettabili.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Betrayal.", "Tradimento.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Judas.", "Giuda.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once more?", "Un'altra volta?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How many times...", "Quante volte ancora...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acceptable.", "Accettabile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Modification.", "Modifica.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is desirable.", "Questo è desiderabile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Picturesque.", "Pittoresco.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Regards.", "Saluti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undesirable.", "Indesiderabile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cease.", "Cessa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is unfriendly.", "È un gesto ostile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cease considerations.", "Smetti di riflettere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Halt.", "Fermo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have been...", "Ho ricevuto...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...dealt a blow", "...un colpo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...a blow", "...un colpo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Suffered.", "Subito.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Assessing damages.", "Valutazione dei danni.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dealt a blow...", "Un colpo subito...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So... familiar...", "Così... familiare...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is unfortunate", "È un peccato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "that we must", "che dobbiamo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "trade blows...", "scambiarci colpi...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I feel... kinship.", "Sento... un legame.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am improved.", "Sono stato migliorato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Improvement", "Miglioramento", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Edit in progress.", "Modifica in corso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A new instrument.", "Un nuovo strumento.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Under analysis", "Analisi in corso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "statistically viable", "statisticamente valido", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A lineup?", "Uno schieramento?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Darter", "Aninga", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mind the splash.", "Attento agli spruzzi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "\"When the Lamb broke the fourth seal, I heard the voice of the fourth living creature saying, \"Come.\" I looked, and behold, an ashen horse; and he who sat on it had the name Death; and Hades was following with him.\"", "«Quando l'Agnello aprì il quarto sigillo, udii la voce del quarto essere vivente dire: “Vieni”. Guardai, ed ecco un cavallo pallido; colui che lo cavalcava si chiamava Morte, e gli inferi lo seguivano.»", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death", "Morte", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deaths Door", "Porta della morte", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't worry, we'll pull you through.", "Non preoccuparti, ti aiuteremo a superarlo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deathstalker", "Scorpione giallo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The deathstalker scorpion. It's tail packs a potent venom.", "Lo scorpione giallo. La sua coda contiene un potente veleno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "De Bug", "De Bug", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What... is that?", "Che... cos'è?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Decorator Crab", "Granchio decoratore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The lowly decorator crab. It scrounges the bottom of the ocean for detritus to stick to it's body.", "L'umile granchio decoratore. Fruga sul fondo dell'oceano in cerca di detriti da attaccarsi al corpo.", Language.Italian);


        }
    }
    public class NeedMoreWaterMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for NeedMoreWater Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Pack:NMW", "Pacchetto carte: NMW", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cardumen", "Banco di pesci", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cuando una carta que lleve este sello mate a otra criatura en combate, se crea una copia de esa carta en tu mano.", "Quando una carta che possiede questo sigillo uccide un'altra creatura in combattimento, una copia della carta che porta il sigillo viene creata nella tua mano.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rape", "Rana pescatrice", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Engañoso y altamente peligroso ese Rape.", "Quella rana pescatrice è ingannevole ed estremamente pericolosa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "La sangre derramada las atrae...", "Il sangue versato le attira...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Arquero", "Pesce arciere", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Su disparo de agua derriba a los insectos para comérselos.", "Abbatte gli insetti con un getto d'acqua per mangiarli.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Beta", "Pesce combattente", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "El Pez Beta. Una belleza viva de las aguas.", "Il pesce combattente. Una bellezza vivente delle acque.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Gato", "Pesce gatto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "El Pez Gato. Nunca te faltarán cebos.", "Il pesce gatto. Non ti mancheranno mai le esche.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cocodrilo", "Coccodrillo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cocodrilo, gran cazador. Ningún nadador escapa de sus fauces.", "Il coccodrillo, grande cacciatore. Nessun nuotatore sfugge alle sue fauci.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Morena", "Murena", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acecha entre las grietas, esperando a que algo nade demasiado cerca.", "Si nasconde tra le fessure, aspettando che qualcosa nuoti troppo vicino.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez León", "Pesce leone", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Su veneno no es letal, pero sacará a la vista tus puntos débiles.", "Il suo veleno non è letale, ma metterà in mostra i tuoi punti deboli.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Piraña", "Piranha", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pirañas, nunca hay una sola en el agua.", "I piranha non sono mai soli in acqua.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Globo", "Pesce palla", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Su combinación de veneno y espinas es letal para cualquier ser vivo.", "La combinazione di veleno e spine è letale per qualsiasi essere vivente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Remo", "Pesce remo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Una de las bestias mas raras que he fotografiado jamás.", "Una delle bestie più rare che abbia mai fotografato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhyzostoma", "Rizostoma", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nada sobrevive a la Rhyzostoma, ni dentro ni fuera del agua.", "Niente sopravvive alla rizostoma, né dentro né fuori dall'acqua.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Salmón", "Salmone", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "El salmón, pez difícil de pescar.", "Il salmone, un pesce difficile da pescare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Esturión", "Storione", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "El inundible esturión, acorazado marino.", "L'inaffondabile storione, corazzata del mare.", Language.Italian);



        }
    }
    public class SauriaSigilsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for SauriaSigils Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avenging", "Vendicatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever an adjacent card perishes during combat, a card bearing this sigil gains 1 Power.", "Ogni volta che una carta adiacente perisce in combattimento, una carta che possiede questo sigillo ottiene 1 potenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avenging Strike", "Colpo vendicatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The loss of its friend will not go unpunished.", "La perdita del suo amico non resterà impunita.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever a friendly card is killed during combat by an opponent's card, a card bearing this sigil moves to that space and strikes the attacker.", "Ogni volta che una carta alleata viene uccisa in combattimento da una carta avversaria, una carta che possiede questo sigillo si sposta in quello spazio e colpisce l'attaccante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To avenge the fallen...", "Per vendicare i caduti...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleeding", "Sanguinamento", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil loses 1 Health at the end of their owner's turn.", "Una carta che possiede questo sigillo perde 1 salute alla fine del turno del suo proprietario.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How much longer can it endure?", "Quanto potrà resistere ancora?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blessing", "Benedizione", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 Bones to increase Health of this and adjacent creatures by 1 if they have less than 10.", "Paga 4 ossa per aumentare di 1 la salute di questa creatura e delle creature adiacenti con meno di 10 salute.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your beasts feel better now.", "Le tue bestie ora stanno meglio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blizzard", "Bufera di neve", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, unoccupied spaces on its owner's side are filled with blocks of ice.", "Quando una carta che possiede questo sigillo viene giocata, gli spazi liberi sul lato del suo proprietario si riempiono di blocchi di ghiaccio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winter is coming.", "L'inverno sta arrivando.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bone to gnaw on.", "Un osso da rosicchiare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Blast", "Esplosione d'ossa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When initiating combat, a card bearing this sigil dies. Upon death, all other cards take damage equal to the amount of owner's bones.", "All'inizio del combattimento, una carta che possiede questo sigillo muore. Alla sua morte, tutte le altre carte subiscono danni pari alle ossa del suo proprietario.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not a pretty sight", "Non è un bello spettacolo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Gift", "Dono d'ossa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, a Bone is created in your hand. [define:Sauria_Bone]", "Quando una carta che possiede questo sigillo viene giocata, viene creato un osso nella tua mano. [define:Sauria_Bone]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A gift for its master.", "Un dono per il suo maestro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Offering", "Offerta d'ossa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card on the opponent's side of board that costs Bones or Blood. Pay its price in Bones to add it to your hand. Blood is counted as 3 Bones, cannot choose cards that cost neither resource.", "Scegli una carta sul lato avversario del tavolo che costi ossa o sangue. Paga il suo costo in ossa per aggiungerla alla tua mano. Ogni sangue conta come 3 ossa; non puoi scegliere carte che non costano nessuna delle due risorse.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've managed to entice one of my beasts.", "Sei riuscito ad attirare una delle mie bestie.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cannibalistic", "Cannibale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When another card on the owner's side of board takes damage and its Health no longer exceeds Power of the bearer of this sigil, this card attacks it.", "Quando un'altra carta sul lato del proprietario subisce danni e la sua salute non supera più la potenza del portatore di questo sigillo, questa carta la attacca.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A grim opportunity to feast.", "Una macabra occasione per banchettare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caretaker", "Custode", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, all other cards on the owner's side of board heal 1 Health while a card bearing this sigil is alive.", "Alla fine del turno, finché una carta che possiede questo sigillo è viva, tutte le altre carte sul lato del suo proprietario recuperano 1 salute.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It tends to their wounds.", "Si prende cura delle loro ferite.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catapult", "Catapulta", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Bone to select another card on your side of the board to move to another space, including opponent's side of the board.", "Paga 1 osso per spostare un'altra carta dalla tua parte del tavolo in un altro spazio, anche sul lato avversario.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch out for falling beasts.", "Attento alle bestie in caduta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Change Form", "Cambio di forma", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil transform into an alternate form.", "Una carta che possiede questo sigillo si trasforma in una forma alternativa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch it shift its form.", "Guardala cambiare forma.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Shifter", "Mutaforma d'ossa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 Bones to transform this card into an alternate form.", "Paga 3 ossa per trasformare questa carta in una forma alternativa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Concerned", "Preoccupato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a friendly card takes damage, a card bearing this sigil attempts to move to its closest adjacent space. If that space is occupied, it attempts to move one space in that direction instead.", "Quando una carta alleata subisce danni, una carta che possiede questo sigillo tenta di raggiungere lo spazio adiacente a essa più vicino. Se è occupato, tenta invece di muoversi di uno spazio in quella direzione.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It responds to its ally's distress.", "Risponde al pericolo del suo alleato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cruelty", "Crudeltà", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals damage to another card through any other means, it deals 1 damage to its target.", "Quando una carta che possiede questo sigillo infligge danni a un'altra carta con qualsiasi altro mezzo, infligge al bersaglio 1 danno aggiuntivo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This beasts wishes to inflict more grievous injuries.", "Questa bestia vuole infliggere ferite più gravi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deep Freeze", "Congelamento profondo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil perishes within 2 turns, the creature within is released.", "Se una carta che possiede questo sigillo perisce entro 2 turni, la creatura al suo interno viene liberata.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Free at last.", "Finalmente libero.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Desperate Push", "Spinta disperata", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil perishes during combat while opposing space is occupied, it pushes the opposing cards back.", "Se una carta che possiede questo sigillo perisce in combattimento mentre lo spazio di fronte è occupato, respinge le carte avversarie.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps its sacrifice will pay off.", "Forse il suo sacrificio darà i suoi frutti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dismember", "Smembramento", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals damage to another card, gain bones equal to the damage dealt, up to 5 bones at once.", "Quando una carta che possiede questo sigillo infligge danni a un'altra carta, ottieni ossa pari ai danni inflitti, fino a 5 ossa alla volta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How gruesome.", "Che orrore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Embolden", "Incoraggiare", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, if there are adjacent cards with less Power than the bearer of this sigil, lose 1 Power and give 1 Power to them.", "Alla fine del turno del proprietario, se ci sono carte adiacenti con meno potenza del portatore di questo sigillo, esso perde 1 potenza e dà loro 1 potenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its strength with its allies.", "Condivide la sua forza con gli alleati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enduring", "Duraturo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 2 Health at the start of its third turn on the board.", "Una carta che possiede questo sigillo ottiene 2 salute all'inizio del suo terzo turno sul tavolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prolonged combat is fortifying this beast.", "Il combattimento prolungato fortifica questa bestia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Erratic March", "Marcia imprevedibile", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will move in the direction inscribed on the sigil at the end of its owner's turn. If there are cards in its way or this card is at edge of the board, it will try to move to the opponent's side of board first.", "Alla fine del turno del suo proprietario, una carta che possiede questo sigillo si muove nella direzione indicata. Se ci sono carte sul suo cammino o si trova al bordo del tavolo, tenta prima di passare sul lato avversario.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its movements are unpredictable.", "I suoi movimenti sono imprevedibili.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fervor", "Fervore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 1 Power at the start of its third turn on the board.", "Una carta che possiede questo sigillo ottiene 1 potenza all'inizio del suo terzo turno sul tavolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prolonged combat is making this beast grow more ferocious.", "Il combattimento prolungato rende questa bestia più feroce.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Genetic Flaw", "Difetto genetico", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil loses 1 Health at the end of their owner's turn.", "Una carta che possiede questo sigillo perde 1 salute alla fine del turno del suo proprietario.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps it's not meant to live.", "Forse non è destinato a vivere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Genetic Perfection", "Perfezione genetica", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If card bearing this sigil has its stats reduced below their normal values, it gains 1 Power and/or Health at the end of its owner's turn. If this card has Genetic Flaw sigil, remove it.", "Se le statistiche di una carta che possiede questo sigillo scendono sotto i valori normali, essa ottiene 1 potenza e/o salute alla fine del turno del suo proprietario. Se ha il sigillo Difetto genetico, rimuovilo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is perfection incarnate.", "È la perfezione incarnata.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Catapult", "Catapulta maggiore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 Bones to select another card on your side of the board to move to another space, including opponent's side of the board. If there is an obstruction with a free opposing space, it takes damage equal to this card's Attack first. If obstruction remains, selected card attempts to move to its opposing space instead.", "Paga 3 ossa per spostare un'altra carta dal tuo lato in un altro spazio, anche sul lato avversario. Se il bersaglio contiene un ostacolo e lo spazio di fronte è libero o occupato dalla carta scelta, l'ostacolo subisce prima danni pari all'attacco del portatore di questo sigillo. Se rimane, la carta scelta tenta di spostarsi nello spazio di fronte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good aim.", "Bel tiro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Embolden", "Grande incoraggiamento", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, if there are any cards on owner's side of the board with less Power than the bearer of this sigil, lose 1 Power and give 1 Power to them.", "Alla fine del turno del proprietario, se ci sono carte sul suo lato con meno potenza del portatore di questo sigillo, esso perde 1 potenza e dà loro 1 potenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its strength with all of its allies.", "Condivide la sua forza con tutti gli alleati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Grudge Bearer", "Grande portatore di rancore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever cards belonging to the owner of the card bearing this sigil are struck, the attacker is marked. At the start of the owner's turn, this card attacks all marked cards owned by the opponent.", "Ogni volta che una carta del proprietario di una carta che possiede questo sigillo viene colpita, l'attaccante viene marchiato. All'inizio del turno del proprietario, questa carta attacca tutte le carte avversarie marchiate.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death is the only suitable punishment.", "La morte è l'unica punizione appropriata.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Nurture", "Grande allevamento", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, if there are any cards on owner's side of the board with less Health than the bearer of this sigil, lose 1 Health and give 1 Health to them.", "Alla fine del turno del proprietario, se ci sono carte sul suo lato con meno salute del portatore di questo sigillo, esso perde 1 salute e dà loro 1 salute.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its essence with all of its allies.", "Condivide la sua essenza con tutti gli alleati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grievous Display", "Spettacolo atroce", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil attacks an opposing creature and it perishes, creatures to the left and right of the target lose 1 Power.", "Quando una carta che possiede questo sigillo attacca una creatura avversaria e questa perisce, le creature a sinistra e a destra del bersaglio perdono 1 potenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not easy on the eyes.", "Non è un bello spettacolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ground Pound", "Colpo al suolo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, cards in opposing and adjacent spaces take 1 damage. This effect is additionally activated when moving 2 spaces away from last position or the opponent's side of board.", "Quando una carta che possiede questo sigillo viene giocata, le carte adiacenti a sinistra e a destra nella stessa fila e quella di fronte subiscono 1 danno. L'effetto si attiva anche quando cambia lato o si muove di almeno 2 spazi nella stessa fila.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A less than graceful landing.", "Un atterraggio poco aggraziato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ground Smash", "Schianto al suolo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, it deals damage to cards in opposing and adjacent spaces equal to its Attack or at least 1 damage. This effect is additionally activated when moving 2 spaces away from last position or the opponent's side of board.", "Quando una carta che possiede questo sigillo viene giocata, infligge alle carte adiacenti a sinistra e a destra nella stessa fila e a quella di fronte danni pari al suo attacco, almeno 1. L'effetto si attiva anche quando cambia lato o si muove di almeno 2 spazi nella stessa fila.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a nasty shockwave.", "Che violenta onda d'urto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grudge Bearer", "Portatore di rancore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, the attacker is marked. At the start of the owner's turn, this card attacks a random marked card owned by the opponent.", "Quando una carta che possiede questo sigillo viene colpita, l'attaccante viene marchiato. All'inizio del turno del suo proprietario, questa carta attacca una carta avversaria marchiata a caso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It will remember this.", "Se ne ricorderà.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grudge-Powered", "Alimentato dal rancore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of opponent's creatures marked by Grudge Bearer sigils and the number of said creatures killed by the bearer of this sigil.", "Il valore rappresentato da questo sigillo è pari al numero di creature avversarie marchiate dai sigilli Portatore di rancore più il numero di tali creature uccise dal portatore di questo sigillo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of opponent's creatures marked by Grudge Bearer sigils and the number of said creatures killed by [creature].", "La potenza di [creature] è pari al numero di creature avversarie marchiate dai sigilli Portatore di rancore più il numero di tali creature uccise da [creature].", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grudge Target", "Bersaglio del rancore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will be attacked by opponent's cards bearing Grudge Bearer sigils.", "Una carta che possiede questo sigillo viene attaccata dalle carte avversarie con i sigilli Portatore di rancore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A permanent stain.", "Una macchia indelebile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hasty Escape", "Fuga precipitosa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon taking damage, the bearer of this sigil returns to owner's hand if it's still alive.", "Quando subisce danni, il portatore di questo sigillo torna nella mano del suo proprietario se è ancora vivo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sometimes, cowards do survive.", "A volte i codardi sopravvivono.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigger Block of Ice", "Blocco di ghiaccio più grande", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A block of ice, nothing to see", "Un blocco di ghiaccio, niente da vedere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its meal with its newfound family.", "Condivide il pasto con la sua nuova famiglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knock Back", "Respingere", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals damage to another card, it attempts to move its target to an adjacent space, prioritizing right.", "Quando una carta che possiede questo sigillo infligge danni a un'altra carta, tenta di spostare il bersaglio in uno spazio adiacente, dando priorità alla destra.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A nasty blow.", "Un brutto colpo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Juicy Meat", "Carne succosa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meat", "Carne", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Makes you salivate.", "Fa venire l'acquolina in bocca.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Memento", "Ricordo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil perishes during combat, adjacent cards gain 1 Power.", "Se una carta che possiede questo sigillo perisce in combattimento, le carte adiacenti ottengono 1 potenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its friends will not forgive those fiends.", "I suoi amici non perdoneranno quei mostri.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete and total extermination is the only reasonable response.", "Uno sterminio completo e totale è l'unica risposta ragionevole.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Micro", "Micro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Movement Command", "Ordine di movimento", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, move the bearer of this sigil to a selected empty space.", "Una volta per turno, sposta il portatore di questo sigillo in uno spazio vuoto scelto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The beast follows your command.", "La bestia segue il tuo comando.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nurture", "Allevare", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, if there are adjacent cards with less Health than the bearer of this sigil, lose 1 Health and give 1 Health to them.", "Alla fine del turno del proprietario, se ci sono carte adiacenti con meno salute del portatore di questo sigillo, esso perde 1 salute e dà loro 1 salute.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its essence with its allies.", "Condivide la sua essenza con gli alleati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Outburst", "Esplosione", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, a card bearing this sigil performs an additional attack against opposing space if it's occupied by a card whose Attack is above 0.", "Alla fine del turno del suo proprietario, una carta che possiede questo sigillo attacca una volta in più lo spazio di fronte se contiene una carta con attacco superiore a 0.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It won't be moving for long at this rate.", "Di questo passo, non si muoverà ancora a lungo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasitoid Propagation", "Propagazione parassitoide", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil kills another creature, a copy of this card is created in your hand.", "Quando una carta che possiede questo sigillo uccide un'altra creatura, una copia di questa carta viene creata nella tua mano.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life can be unsightly at times.", "A volte la vita può essere sgradevole da vedere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parental Care", "Cure parentali", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, creatures with Fledgling sigil adjacent to a card bearing this sigil gain 1 Health.", "Alla fine del turno del proprietario, le creature con il sigillo Astro nascente adiacenti a una carta che possiede questo sigillo ottengono 1 salute.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good parent.", "Un buon genitore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parting Bone", "Osso d'addio", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil dies or is sacrificed, a Bone is created in your hand. [define:Sauria_Bone]", "Quando una carta che possiede questo sigillo muore o viene sacrificata, viene creato un osso nella tua mano. [define:Sauria_Bone]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A parting gift for its master.", "Un dono d'addio per il suo maestro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Persistent", "Persistenza", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil would die during combat for the first time, it revives and gains 2 Power.", "Quando una carta che possiede questo sigillo sta per morire in combattimento per la prima volta, torna in vita e ottiene 2 potenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That creature will not give up so easily.", "Quella creatura non si arrenderà così facilmente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protective", "Protettivo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an adjacent card is struck, a card bearing this sigil strikes the attacker.", "Quando una carta adiacente viene colpita, una carta che possiede questo sigillo colpisce l'attaccante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It doesn't appreciate having its comrades hurt.", "Non gradisce che i suoi compagni vengano feriti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protective Parent", "Genitore protettivo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When owner's cards with Fledgling sigil are struck, bearer of this sigil strikes the attacker.", "Quando le carte del proprietario con il sigillo Astro nascente vengono colpite, il portatore di questo sigillo colpisce l'attaccante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Few things inspire more awe and fear than a protective parent.", "Poche cose incutono tanto timore e rispetto quanto un genitore protettivo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pursuer", "Inseguitore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever an opponent's card moves to another space, a card bearing this sigil attempts to move to its current opposing space. If successful, it deals 1 damage to its opposing space.", "Ogni volta che una carta avversaria si muove, una carta che possiede questo sigillo tenta di raggiungere lo spazio di fronte alla sua nuova posizione. Se riesce, infligge 1 danno a quella carta se è ancora viva.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is no escape...", "Non c'è scampo...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quake", "Terremoto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 Bones to deal 1 damage to all enemy cards. This sigil is removed afterwards.", "Paga 4 ossa per infliggere 1 danno a tutte le carte nemiche. Poi questo sigillo viene rimosso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrifying display of power.", "Una terrificante dimostrazione di potenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Served Dinner", "Cena servita", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card on the owner's side of board. Add stats of the card bearing this sigil to the selected card. This card dies afterwards. This effect can also be activated by sacrificing or killing this page directly.", "Scegli una carta sul lato del proprietario. Aggiungi alla carta scelta le statistiche della carta che possiede questo sigillo. Quest'ultima poi muore. L'effetto può attivarsi anche sacrificando o uccidendo direttamente questa carta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dinner is served.", "La cena è servita.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shoal Strike", "Colpo di branco", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, it deals 1 damage to all of opponent's submerged cards and forces them to surface.", "Quando una carta che possiede questo sigillo viene giocata, infligge 1 danno a tutte le carte avversarie sommerse e le costringe a emergere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The hunt begins...", "La caccia ha inizio...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skittish", "Schivo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card moves into space opposing the one bearing this sigil, deal 1 damage to it, then move to a random unoccupied space on the owner's side of board if possible.", "Quando una carta entra nello spazio di fronte al portatore di questo sigillo, infliggile 1 danno, poi sposta il portatore in uno spazio libero casuale sul lato del proprietario, se possibile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature appears to be rather skittish.", "Questa creatura sembra piuttosto schiva.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sprinter Strike", "Colpo scattante", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenener a card bearing this sigil moves, it deals 1 damage to its opposing space. If said space is not occupied, the opponent is deald 1 damage immediately.", "Ogni volta che una carta che possiede questo sigillo si muove, infligge 1 danno allo spazio di fronte. Se è vuoto, l'avversario subisce subito 1 danno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A swift strike.", "Un colpo rapido.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sticky Tongue", "Lingua appiccicosa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owners turn, a card bearing this sigil attempts to drag creatures adjacent to opposing space or queued behind it in front of itself, prioritizing the latter. If affected card has 1 Health, this card immediately attacks it.", "All'inizio del turno del proprietario, una carta che possiede questo sigillo tenta di attirare davanti a sé le creature adiacenti allo spazio di fronte o in coda dietro di esso, dando priorità a queste ultime. Se la carta attirata ha 1 salute, la attacca subito.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a sticky situation.", "Una situazione appiccicosa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tactical Retreat", "Ritirata tattica", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, the bearer of this sigil returns to owner's hand if it's still alive.", "Alla fine del turno del proprietario, il portatore di questo sigillo torna nella sua mano se è ancora vivo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It doesn't feel the need to stay on the board.", "Non sente il bisogno di restare sul tavolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TearThrough", "Lacerazione", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If opposing space is occupied, a card bearing this sigil will move in the direction inscribed on the sigil at the end of its owner's turn, dealing 1 damage to the card in that space and trying to move it as well.", "Se lo spazio di fronte è occupato, alla fine del turno del proprietario una carta che possiede questo sigillo si muove nella direzione indicata, infligge 1 danno alla carta in quello spazio e tenta di spostare anche lei.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A brutal display", "Una dimostrazione brutale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Territorial", "Territoriale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When another creature moves into an adjacent or opposing space, a card bearing this sigil attacks it.", "Quando un'altra creatura entra in uno spazio adiacente o di fronte, una carta che possiede questo sigillo la attacca.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To intrude upon its territory...", "Invadere il suo territorio...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tyranny", "Tirannia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Blood to increase Attack and Health of this and adjacent creatures by 1, then remove this sigil.", "Paga 2 sangue per aumentare di 1 l'attacco e la salute di questa creatura e di quelle adiacenti, poi rimuovi questo sigillo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sacrifice this beast is willing to make.", "Un sacrificio che questa bestia è disposta a compiere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vicious Growth", "Crescita feroce", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil kills another creature, it gains 1 Power and 1 Health.", "Quando una carta che possiede questo sigillo uccide un'altra creatura, ottiene 1 potenza e 1 salute.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One life to nourish another.", "Una vita per nutrirne un'altra.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wounding", "Ferita", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals damage to another card without Made of Stone, its target gains Bleeding effect. Bleeding cards lose 1 Health at the end of their owner's turn.", "Quando una carta che possiede questo sigillo infligge danni a una carta senza Tempra di pietra, il bersaglio riceve l'effetto Sanguinamento. Le carte sanguinanti perdono 1 salute alla fine del turno del loro proprietario.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This must sting.", "Deve bruciare.", Language.Italian);



            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's a Grudgin'", "Questo merita rancore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a card collect grudges from 10 marked cards in a single battle", "Fai accumulare a una carta rancori da 10 carte marchiate in una sola battaglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete and Total Extermination", "Sterminio completo e totale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a card with Greater Grudge Bearer wipe out 4 marked cards at once.", "Fai eliminare 4 carte marchiate in una volta da una carta con Grande portatore di rancore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Completely Boned", "Del tutto disossato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wipe out the whole board via Bone Blast.", "Svuota tutto il tavolo con Esplosione d'ossa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plateosaurus School of Thought", "La scuola di pensiero del Plateosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a philosopher bother 10 cards with questions in a single battle.", "Fai infastidire 10 carte dalle domande di un filosofo in una sola battaglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrible Roommate", "Pessimo coinquilino", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a territorial card lash out at friendly cards in a single battle", "Fai attaccare carte alleate da una carta territoriale in una sola battaglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beast Cannon", "Cannone di bestie", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kill at least 2 enemy cards by throwing a hefty beast at them.", "Uccidi almeno 2 carte nemiche lanciando loro contro una bestia pesante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Et Tu, Majungasaurus?", "Anche tu, Majungasaurus?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a cannibalistic card devour 10 friendly cards in a single battle.", "Fai divorare 10 carte alleate a una carta cannibale in una sola battaglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'Tis But A Scratch", "È solo un graffio", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have one of your cards survive 10 turns while bleeding.", "Fai sopravvivere una delle tue carte per 10 turni mentre sanguina.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empathetic", "Empatico", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a nurturing card sacrifice 10 Health in a single battle.", "Fai sacrificare 10 salute a una carta che alleva gli alleati in una sola battaglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rally", "Raccolta", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have an emboldening card sacrifice 10 Power in a single battle.", "Fai sacrificare 10 potenza a una carta che incoraggia gli alleati in una sola battaglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ascended Arts", "Arti ascese", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a certain card fully remove cost of 6 cards in a single run.", "Fai rimuovere del tutto il costo di 6 carte a una certa carta in una sola avventura.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raptor Attack", "Attacco dei raptor", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain at least 10 Raptor cards in a single run.", "Ottieni almeno 10 carte Raptor in una sola avventura.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jurassic World", "Mondo giurassico", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with 3 secret cards. Life finds a way.", "Completa un'avventura con 3 carte segrete. La vita trova sempre una via.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apex Predators", "Superpredatori", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have three biggest theropods in your deck in a single run.", "Tieni i tre teropodi più grandi nel tuo mazzo durante una sola avventura.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "King of the Monsters", "Re dei mostri", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unleash the King of the Monsters upon the enemy.", "Scatena il Re dei mostri contro il nemico.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ballad of Big Al", "La ballata di Al il grande", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Help get the big girl back on her feet. Poor thing.", "Aiuta la ragazzona a rimettersi in piedi. Poverina.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Indomitable One", "L'indomabile", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Create a genetic abomination with more teeth.", "Crea un abominio genetico con più denti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Monster Resurrected", "Il mostro risorto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Make Spinosaurus feel like a monster.", "Fai sentire Spinosaurus come un mostro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jurassic Painter", "Pittore giurassico", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Promote Stokesosaurus to a painter.", "Promuovi Stokesosaurus a pittore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All Outta Gum", "A corto di gomme", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give the little guy balls of steel.", "Dai al piccoletto palle d'acciaio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Novel Look", "Nuovo aspetto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take the frills off the crested critter.", "Togli il collare alla creatura con la cresta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bird Up", "Piume in alto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Put too many feathers where they don't belong.", "Metti troppe piume dove non dovrebbero esserci.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wu's Secrets", "I segreti di Wu", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have Compstegnathus, Spinoraptor and Ankylodocus in your deck in a single run.", "Tieni Compstegnathus, Spinoraptor e Ankylodocus nel tuo mazzo durante una sola avventura.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Welcome to Jurassic Park", "Benvenuti a Jurassic Park", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with Jurassic Park deck and at least 7 related cards.", "Completa un'avventura con il mazzo Jurassic Park e almeno 7 carte correlate.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prehistoric Collection", "Collezione preistorica", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Play a copy of every common Sauria card.", "Gioca una copia di ogni carta Sauria comune.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rare Fossils", "Fossili rari", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Play a copy of every rare Sauria card.", "Gioca una copia di ogni carta Sauria rara.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paleo-Novice", "Paleo-novizio", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with 5 Sauria decks.", "Completa avventure con almeno 5 mazzi iniziali Sauria diversi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dino-Fan", "Fan dei dinosauri", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with 20 Sauria decks.", "Completa avventure con almeno 20 mazzi iniziali Sauria diversi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deck-O-Saurus", "Mazzo-sauro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with every available Sauria deck.", "Completa un'avventura con ciascun mazzo Sauria disponibile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gyarouucore", "Gyarouucore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtained every other achievement! Good job!", "Hai ottenuto tutti gli altri obiettivi! Ben fatto!", Language.Italian);

        }
    }
    public class SauriaCardsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for SauriaCards Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acrocanthosaurus", "Acrocanthosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acrocanthosaurus, terror of the North. It does not take much to provoke this giant into attacking.", "Acrocanthosaurus, il terrore del Nord. Basta poco per provocare l'attacco di questo gigante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allosaurus", "Allosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This tenacious predator doesn't know when to stop its assault.", "Questo tenace predatore non sa quando fermare il suo assalto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amargasaurus", "Amargasaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amargasaurus, a surprisingly small beast for its kind. Size is relative, however.", "Amargasaurus, una bestia sorprendentemente piccola per la sua specie. Le dimensioni sono però relative.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "American Lion", "Leone americano", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The American Lion, a vicious feline predator with a soft heart. It does not extend its kindness towards its prey, however.", "Il leone americano, un feroce predatore felino dal cuore tenero. Non mostra però alcuna bontà verso le sue prede.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "American Lion Cub", "Cucciolo di leone americano", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An American Lion Cub, an adorable kitten. It's hard to imagine something like this growing up to become a terrifying predator", "Un cucciolo di leone americano, un adorabile gattino. È difficile immaginare che diventerà un terrificante predatore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ankylosaurus", "Ankylosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sturdy Ankylosaurus. It may not feel claws and teeth strike its hide, but it does not appreciate being pestered during mealtime.", "Il robusto Ankylosaurus. Forse non sente artigli e denti colpire la sua pelle, ma non gradisce essere disturbato durante il pasto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anomalocaris", "Anomalocaris", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ancient Anomalocaris, one of the first apex predators to live in this world. It does its best against modern beasts.", "L'antico Anomalocaris, uno dei primi superpredatori di questo mondo. Fa del suo meglio contro le bestie moderne.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apatosaurus", "Apatosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The formidable Apatosaurus. It doesn't need to be the biggest of its kind to crush enemies into dust.", "Il formidabile Apatosaurus. Non deve essere il più grande della sua specie per ridurre i nemici in polvere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Argentinosaurus", "Argentinosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The titanic Argentinosaurus, truly a sight to behold. Make sure to keep your distance if you do not wish to be crushed.", "Il titanico Argentinosaurus, uno spettacolo da vedere. Mantieni le distanze se non vuoi essere schiacciato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arthropleura", "Arthropleura", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arthropleura, an oversized centipede with a taste for decaying plants. Its movements are unpredictable.", "Arthropleura, un centopiedi gigantesco che ama le piante in decomposizione. I suoi movimenti sono imprevedibili.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspidorhynchus", "Aspidorhynchus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is much bigger fish out there, but Aspidorhynchus is still perfectly capable of biting your fingers off.", "Ci sono pesci molto più grandi, ma Aspidorhynchus è comunque capace di staccarti le dita con un morso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Australovenator", "Australovenator", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vicious Australovenator. It pierces and tears through the hide of its victims with its enlarged claws.", "Il feroce Australovenator. Trafigge e lacera la pelle delle vittime con i suoi grandi artigli.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Austroraptor", "Austroraptor", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The keen-eyed Austroraptor, a skilled fisher of light build. It's far from harmless, however.", "Austroraptor dall'occhio acuto, un abile pescatore dalla corporatura leggera. È tutt'altro che innocuo, però.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baryonyx", "Baryonyx", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baryonyx, a crocodile-faced beast with a taste for fish. Refrain from smiling if you do not wish to expand its diet.", "Baryonyx, una bestia dal muso di coccodrillo che ama il pesce. Evita di sorridere se non vuoi ampliare la sua dieta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beipiaosaurus", "Beipiaosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Beipiaosaurus is armed with sharp claws to rend its foes apart...but it does not have the courage to stand up to anything bigger.", "Questo Beipiaosaurus ha artigli affilati per fare a pezzi i nemici... ma non ha il coraggio di affrontare creature più grandi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brachiosaurus", "Brachiosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mighty Brachiosaurus. It can use its immense size to draw aggressors away from allies.", "Il possente Brachiosaurus. Può usare la sua immensa mole per attirare gli aggressori lontano dagli alleati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brachiosaurus Hatchling", "Cucciolo di Brachiosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Brachiosaurus hatchling. It will take some time for it to reach its full size.", "Un cucciolo di Brachiosaurus. Ci vorrà tempo prima che raggiunga la piena dimensione.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brachytrachelopan", "Brachytrachelopan", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brachytrachelopan, a bizarre creature for its kind. Though it lacks their characteristic long neck, its long tail makes up for its absence.", "Brachytrachelopan, una creatura bizzarra per la sua specie. Pur non avendo il caratteristico collo lungo, compensa con la lunga coda.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camarasaurus", "Camarasaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ginormous Camarasaurus. Though it does not wish to bring harm directly, its great size allows it to fling beasts across the battlefield.", "L'enorme Camarasaurus. Non vuole ferire direttamente, ma la sua mole gli permette di scagliare bestie attraverso il campo di battaglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria", "Sauria", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carnotaurus", "Carnotaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though not as swift as commonly believed, this beast can hardly be stopped once it gains momentum.", "Pur non essendo veloce come si crede, questa bestia è quasi impossibile da fermare una volta preso slancio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cartorhynchus", "Cartorhynchus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Cartorhynchus may be tiny, but there is bigger fish following its trail.", "Questo Cartorhynchus sarà anche minuscolo, ma un pesce più grande segue le sue tracce.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caturus", "Caturus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caturus, an imposing predator to some, an enticing snack for others.", "Caturus, un predatore imponente per alcuni, uno spuntino invitante per altri.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cearadactylus", "Cearadactylus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Too busy fretting over its meals, Cearadactylus does not make for a great fighter.", "Troppo occupato a preoccuparsi dei pasti, Cearadactylus non è un gran combattente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cephalaspis", "Cephalaspis", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cephalaspis, an armored fish shaped like a shovel. Its thick armor lets it feed in peace.", "Cephalaspis, un pesce corazzato a forma di pala. La sua spessa corazza gli permette di nutrirsi in pace.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ceratodus", "Ceratodus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The peculiar Ceratodus, a fish with the ability to live on land. Makes for a fine meal.", "Il curioso Ceratodus, un pesce capace di vivere sulla terraferma. È un buon pasto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ceratosaurus", "Ceratosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though often overshadowed by its bigger competitors, Ceratosaurus is a formidable threat in its own right.", "Sebbene sia spesso messo in ombra da concorrenti più grandi, Ceratosaurus è una minaccia formidabile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chasmosaurus", "Chasmosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stalwart Chasmosaurus. It uses its shield-like frill to protect allies.", "Il saldo Chasmosaurus. Usa il collare a forma di scudo per proteggere gli alleati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chungkingosaurus", "Chungkingosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though it may not be eager to hurt other creatures, you do not want to get near the tail of Chungkingosaurus.", "Anche se non desidera ferire altre creature, è meglio non avvicinarsi alla coda di Chungkingosaurus.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coelophysis", "Coelophysis", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coelophysis, one of the first of its kind. Many more terrible beasts have spawned from its lineage.", "Coelophysis, uno dei primi della sua specie. Molte altre bestie terribili sono nate dalla sua discendenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compsognathus", "Compsognathus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The diminutive Compsognathus. It can hardly pose a threat while alone.", "Il minuscolo Compsognathus. Da solo è a malapena una minaccia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corythosaurus", "Corythosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corythosaurus, a cautious beast that does not travel alone. It finds safety in a herd.", "Corythosaurus, una bestia prudente che non viaggia da sola. Trova sicurezza nel branco.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dacentrurus", "Dacentrurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dacentrurus, a beast with an oddly elongated neck that fiercely protects its allies.", "Dacentrurus, una bestia dal collo insolitamente allungato che protegge ferocemente i suoi alleati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Daeodon", "Daeodon", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The terrible Daeodon. It may not be a pig, but it is certainly prepared for war.", "Il terribile Daeodon. Forse non è un maiale, ma è certamente pronto per la guerra.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinocheirus", "Deinocheirus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once thought to be a terrible beast, Deinocheirus turned out to be far more bizarre than anyone expected. Its strength is not to be underestimated, however.", "Un tempo ritenuto una terribile bestia, Deinocheirus si è rivelato molto più bizzarro del previsto. La sua forza non va però sottovalutata.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinonychus", "Deinonychus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinonychus, a vicious hunter known for the enlarged claws adorning its feet. How's that for a 'six-foot turkey'?", "Deinonychus, un feroce cacciatore noto per i grandi artigli ai piedi. Che ne dici di questo «tacchino alto sei piedi»?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sicilian Dwarf Elephant", "Elefante nano siciliano", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sicilian Dwarf Elephant, a severely undersized counterpart of one of the biggest animals to roam the land today. Such is life on small island.", "L'elefante nano siciliano, una versione minuscola di uno dei più grandi animali terrestri odierni. Questa è la vita su una piccola isola.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Desmatosuchus", "Desmatosuchus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though not blessed with sharp teeth or claws, Desmatosuchus tries to make up for it with its thick hide", "Pur non avendo denti o artigli affilati, Desmatosuchus cerca di compensare con la sua pelle spessa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dilophosaurus", "Dilophosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This little critter cripples prey by spitting its uncharacteristic venom.", "Questa piccola creatura immobilizza le prede sputando il suo insolito veleno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dilophosaurus, a terror of the Early Jurassic period. Losing its ridiculous frill does not hinder its venomous nature.", "Dilophosaurus, un terrore del Giurassico inferiore. La perdita del suo ridicolo collare non ne ostacola la natura velenosa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimetrodon", "Dimetrodon", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimetrodon, a reptilian mammal with an impressive sail. Its sharp teeth are a far bigger concern, however.", "Dimetrodon, un rettile mammaliano con una vela impressionante. I suoi denti affilati sono però un problema ben maggiore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimorphodon", "Dimorphodon", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimorphodon, a mostly unremarkable little critter. Do not startle it, those teeth will leave a mark during its hasty retreat.", "Dimorphodon, una piccola creatura piuttosto comune. Non spaventarla: i suoi denti lasceranno il segno durante la fuga precipitosa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dinosaur Egg", "Uovo di dinosauro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigger Dinosaur Egg", "Uovo di dinosauro più grande", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An egg left behind by some dinosaur. I wonder what will hatch from it?", "Un uovo lasciato da un dinosauro. Chissà cosa ne uscirà?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diplodocus", "Diplodocus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If sheer size alone is not enough to deter predators, then perhaps a mighty tail whip will make them reconsider.", "Se la sola mole non basta a scoraggiare i predatori, forse una potente frustata di coda li farà ricredere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dryosaurus", "Dryosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dryosaurus, an adorable creature with a flighty attitude.", "Dryosaurus, un'adorabile creatura dal temperamento timoroso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dunkleosteus", "Dunkleosteus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ravenous Dunkleosteus, an armored fish from distant past. Its true length has little bearing on its crushing jaws.", "Il vorace Dunkleosteus, un pesce corazzato di un lontano passato. La sua vera lunghezza conta poco di fronte alle sue mascelle possenti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Edmontosaurus", "Edmontosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Edmontosaurus, a massive creature with very few natural predators. Do not expect to find it alone.", "Edmontosaurus, un'enorme creatura con pochissimi predatori naturali. Non aspettarti di trovarla da sola.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elasmosaurus", "Elasmosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elasmosaurus, a prehistoric beast with an incredibly long neck. It can snatch prey far out of the reach of others.", "Elasmosaurus, una bestia preistorica dal collo incredibilmente lungo. Può afferrare prede ben fuori dalla portata degli altri.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eobasileus", "Eobasileus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eobasileus, the largest of its kind. Do not stand in its path if you wish to see the sun rise again.", "Eobasileus, il più grande della sua specie. Non intralciarlo se vuoi vedere un'altra alba.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Euoplocephalus", "Euoplocephalus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The thick hide of this Euoplocephalus and the equally hefty club at the end of its tail protect it from most predators", "La pelle spessa di questo Euoplocephalus e la robusta mazza all'estremità della coda lo proteggono dalla maggior parte dei predatori.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gallimimus", "Gallimimus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gallimimus, a bird-like beast that is rather quick on its feet. It is about as friendly as it looks.", "Gallimimus, una bestia simile a un uccello, piuttosto veloce sulle zampe. È amichevole quanto sembra.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gastornis", "Gastornis", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vigilant Gastornis. It watches over its comrades, growing furious if it loses any.", "Il vigile Gastornis. Veglia sui compagni e si infuria se ne perde uno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Ground Sloth", "Bradipo terricolo gigante", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Giant Ground Sloth, a massive beast far surpassing its modern relatives. It is much less friendly than you would think.", "Il bradipo terricolo gigante, un'enorme bestia che supera di gran lunga i suoi parenti moderni. È molto meno amichevole di quanto si pensi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gigantoraptor", "Gigantoraptor", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gigantoraptor, a disturbingly large beast. Any attempts to resist will only further provoke it.", "Gigantoraptor, una bestia inquietantemente grande. Ogni tentativo di resistenza non farà che provocarla ulteriormente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gojirasaurus", "Gojirasaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once the biggest predator to roam the land, Gojirasaurus' reign did not last. It's hard to match the titans that followed it.", "Un tempo il più grande predatore terrestre, Gojirasaurus non regnò a lungo. È difficile competere con i titani che lo seguirono.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guanlong", "Guanlong", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guanlong, a vicious predator emboldened by the thrill of combat. Many more terrible beasts have spawned from its lineage.", "Guanlong, un feroce predatore reso audace dall'emozione del combattimento. Molte altre terribili bestie sono nate dalla sua discendenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hadrosaurus", "Hadrosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vengeful Hadrosaurus. It makes quick work of those who harm members of its herd.", "Il vendicativo Hadrosaurus. Si sbarazza rapidamente di chi ferisce i membri del suo branco.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haolong", "Haolong", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haolong, a bizarre beast covered in many sharp quills. Very few predators dare to clamp their jaws around its prickly hide.", "Haolong, una bizzarra bestia coperta di aculei affilati. Pochi predatori osano azzannare la sua pelle spinosa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Herrerasaurus", "Herrerasaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Herrerasaurus hails from the age before dinosaurs took over the world. Being more primitive does not make it any less successful.", "Questo Herrerasaurus proviene dall'epoca precedente al dominio dei dinosauri. Essere più primitivo non lo rende meno efficace.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hesperornis", "Hesperornis", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hesperornis, a swimming bird with a taste for fish. It has yet to lose its teeth.", "Hesperornis, un uccello nuotatore che ama il pesce. Non ha ancora perso i denti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Homalocephale", "Homalocephale", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an adorable Homalocephale. Alas, a grim fate awaits this poor creature. Will your heart sink when you hear its cries?", "Che adorabile Homalocephale. Ahimè, un triste destino attende questa povera creatura. Ti si stringerà il cuore sentendo le sue grida?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyornis", "Ichthyornis", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyornis, a prehistoric bird with sharp teeth. It is no less annoying than its modern counterparts.", "Ichthyornis, un uccello preistorico dai denti affilati. È fastidioso quanto i suoi equivalenti moderni.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyosaurus", "Ichthyosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The swift Ichthyosaurus. It can attack submerged foes in the blink of an eye.", "Il rapido Ichthyosaurus. Può attaccare nemici sommersi in un batter d'occhio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iguanodon", "Iguanodon", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mind your manners before this Iguanodon if you do not wish to feel its clawed thumb pierce you.", "Comportati bene davanti a questo Iguanodon se non vuoi essere trafitto dal suo pollice artigliato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inostrancevia", "Inostrancevia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inostrancevia, a surprisingly agile apex predator of its age. The grievous injuries left by the beast's fangs are far less suprising.", "Inostrancevia, un superpredatore sorprendentemente agile per la sua epoca. Le gravi ferite lasciate dalle sue zanne sorprendono molto meno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Irish Elk", "Alce irlandese", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The majestic Irish Elk, the biggest of its kind. Its massive horns grant it extended reach.", "Il maestoso alce irlandese, il più grande della sua specie. Le sue enormi corna gli danno una maggiore portata.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Irritator", "Irritator", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The patient Irritator. Though it primarily feeds on fish, its claws are perfectly suited for tearing into other beasts.", "Il paziente Irritator. Sebbene si nutra soprattutto di pesce, i suoi artigli sono perfetti per lacerare altre bestie.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Isisaurus", "Isisaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Isisaurus leads a herd of its own. Though they do not belong to its kind, those beasts trust this experienced titan.", "Questo Isisaurus guida un branco tutto suo. Pur non appartenendo alla sua specie, quelle bestie si fidano di questo esperto titano.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jeholopterus", "Jeholopterus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jeholopterus, nothing more than a bug-eating critter. Don't expect much else out of it.", "Jeholopterus, niente più di una piccola creatura mangia-insetti. Non aspettarti altro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Katifelis", "Katifelis", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Katifelis, an unremarkable feline. It does not respond well to approaching strangers.", "Katifelis, un felino comune. Non reagisce bene agli sconosciuti che si avvicinano.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kentrosaurus", "Kentrosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kentrosaurus, a herbivore with a threatening appearance. Said appearance is far from deceiving, however.", "Kentrosaurus, un erbivoro dall'aspetto minaccioso. E l'apparenza non inganna affatto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Koolasuchus", "Koolasuchus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Koolasuchus, a dreadfull creature lurking in the water. It does not pass up any opportunity to feast.", "Koolasuchus, una terribile creatura in agguato nell'acqua. Non si lascia sfuggire alcuna occasione di banchettare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lambeosaurus", "Lambeosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The solitary Lambeosaurus. It strikes its foes multiple times when disturbed.", "Il solitario Lambeosaurus. Quando viene disturbato colpisce i nemici più volte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Liopleurodon", "Liopleurodon", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While much smaller than some may believe, Liopleurodon is still a vicious predator, always ready to tear its prey apart.", "Sebbene sia molto più piccolo di quanto alcuni credano, Liopleurodon resta un feroce predatore, sempre pronto a fare a pezzi le sue prede.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Majungasaurus", "Majungasaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The voracious Majungasaurus. It will not hesitate to devour its own comrades to sate its hunger.", "Il vorace Majungasaurus. Non esiterà a divorare i propri compagni per saziare la fame.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Masiakasaurus", "Masiakasaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Masiakasaurus, a bizarre dinosaur of unimpressive size. It does not stay in battle for long.", "Masiakasaurus, uno strano dinosauro di dimensioni modeste. Non resta a lungo in battaglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mawsonia", "Mawsonia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mawsonia, an enormous fish drifting in search of prey. Pray you do not bump into one while swimming.", "Mawsonia, un enorme pesce che vaga in cerca di prede. Prega di non incontrarne uno mentre nuoti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megalania", "Megalania", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The monstrous Megalania. A single bite from this oversized reptile is enough to cripple most beasts.", "La mostruosa Megalania. Un solo morso di questo enorme rettile basta a mettere fuori combattimento la maggior parte delle bestie.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Metriacanthosaurus", "Metriacanthosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Metriacanthosaurus mercilessly tears into its prey, unwilling to let any meal get away from its jaws.", "Questo Metriacanthosaurus lacera le prede senza pietà, deciso a non lasciar sfuggire alcun pasto dalle sue fauci.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Microceratus", "Microceratus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unlike its bigger relatives, Microceratus stands on two legs and lacks any meaningful protection against predators. The best it can do is draw attention of something bigger.", "A differenza dei parenti più grandi, Microceratus cammina su due zampe e non ha una vera difesa contro i predatori. Al massimo può attirare l'attenzione di qualcosa di più grande.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minmi", "Minmi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Minmi may seem adorable, but it is far from defenseless. In fact, defense might be all it has.", "Questo Minmi può sembrare adorabile, ma è tutt'altro che indifeso. Anzi, forse la difesa è tutto ciò che ha.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muttaburrasaurus", "Muttaburrasaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The persistent Muttaburrasaurus. It does not fall in battle while its herd is still in danger.", "Il tenace Muttaburrasaurus. Non cade in battaglia finché il suo branco è in pericolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nanotyrannus", "Nanotyrannus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Living in the shadow of the King does not make this beast any less formidable.", "Vivere all'ombra del Re non rende questa bestia meno formidabile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nigersaurus", "Nigersaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nigersaurus, a beast with countless teeth. It loses many while feeding, but they regrow just as quickly.", "Nigersaurus, una bestia dai denti innumerevoli. Ne perde molti mentre mangia, ma ricrescono altrettanto rapidamente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothosaurus", "Nothosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though this Nothosaurus is clumsy on land, it is an adept swimmer with a mouth full of sharp teeth.", "Questo Nothosaurus è goffo sulla terraferma, ma è un abile nuotatore con la bocca piena di denti affilati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Olorotitan", "Olorotitan", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Olorotitan is more concerned about helping its allies than itself. Such altruism.", "Questo Olorotitan pensa più ad aiutare gli alleati che a sé stesso. Che altruismo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Othnielia", "Othnielia", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Othnielia, hardly more than a snack for more ferocious beasts.", "Othnielia, poco più di uno spuntino per le bestie più feroci.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ouranosaurus", "Ouranosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though it is not an outstanding fighter, this Ouranosaurus encourages its comrades to fight with greater strength.", "Questo Ouranosaurus non è un combattente eccezionale, ma incoraggia i compagni a lottare con più forza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oviraptor", "Oviraptor", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once thought to be a mere egg thief, this feathered fiend takes great care of its young.", "Un tempo considerato un semplice ladro di uova, questo diavolo piumato si prende grande cura dei suoi piccoli.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pachycephalosaurus", "Pachycephalosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stubborn Pachycephalosaurus. It will attack anything that intrudes upon its territory regardless of size.", "Il testardo Pachycephalosaurus. Attacca chiunque invada il suo territorio, indipendentemente dalla taglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pachyrhinosaurus", "Pachyrhinosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The nomadic Pachyrhinosaurus. It lost many brothers during its travels. It cannot bear to lose more.", "Il nomade Pachyrhinosaurus. Ha perso molti fratelli durante i suoi viaggi e non sopporterebbe di perderne altri.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasaurolophus", "Parasaurolophus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The peaceful Parasaurolophus. Its peculiar crest allows it to call upon its allies when in trouble.", "Il pacifico Parasaurolophus. La sua particolare cresta gli permette di chiamare gli alleati quando è in difficoltà.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasaurolophus Hatchling", "Cucciolo di Parasaurolophus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A meek Parasaurolophus hatchling. It has yet to develop a prominent crest to match its parents.", "Un mite cucciolo di Parasaurolophus. Non ha ancora sviluppato una cresta prominente come quella dei genitori.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Patagopelta", "Patagopelta", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While far from the biggest armored dinosaur, Patagopelta is still perfectly capable of enduring blows.", "Pur non essendo il più grande dinosauro corazzato, Patagopelta è comunque capace di resistere ai colpi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plateosaurus", "Plateosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plateosaurus, one of the first titans to roam the land. Though its descendants have far surpassed its size, it is by no means small.", "Plateosaurus, uno dei primi titani a vagare sulla terra. Anche se i suoi discendenti lo hanno superato in dimensioni, non è affatto piccolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Platybelodon", "Platybelodon", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Platybelodon, a beast so bizarre that few would believe it existed. It can use its unsightly skull to uproot obstacles in your path.", "Platybelodon, una bestia così bizzarra che pochi crederebbero alla sua esistenza. Può usare il suo sgradevole cranio per sradicare gli ostacoli sul tuo cammino.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raptor Plushie", "Peluche Raptor", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A cute little toy, nothing more.", "Un grazioso giocattolino, niente di più.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stuffing", "Imbottitura", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All that's left of a toy.", "Tutto ciò che resta di un giocattolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Postosuchus", "Postosuchus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Postosuchus, a bipedal crocodilian. Its bite is no less devastating than that of its modern relatives.", "Postosuchus, un coccodrilliforme bipede. Il suo morso è devastante quanto quello dei suoi parenti moderni.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Proceratosaurus", "Proceratosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The deceptive Proceratosaurus. It makes up for its lacking offense with whatever wit you may attribute to a beast.", "L'ingannevole Proceratosaurus. Compensa la scarsa capacità offensiva con tutta l'astuzia che si può attribuire a una bestia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Procompsognathus", "Procompsognathus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Procompsognathus, a tiny terror with a surprisingly potent venom. It's particularly fond of feasting on greedy old men.", "Procompsognathus, un minuscolo terrore dal veleno sorprendentemente potente. Ama soprattutto banchettare con vecchi avidi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prongdeer", "Cervo dalle corna forcute", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prongdeer, a relatively small horned creature with an ill-fitting pair of fangs. They are not just for show, however.", "Il cervo dalle corna forcute, una creatura cornuta relativamente piccola con un paio di zanne fuori posto. Non sono solo decorative, però.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protoceratops", "Protoceratops", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Protoceratops may not seem like a threat, but the ferocity it displays when desperate is a sight to behold.", "Questo Protoceratops non sembra una minaccia, ma la ferocia che mostra quando è disperato è uno spettacolo da vedere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protosphyraena", "Protosphyraena", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protosphyraena, a lightning-fast predator that cleaves its prey in half with its extended snout.", "Protosphyraena, un predatore rapido come un fulmine che taglia in due le prede con il lungo muso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Psittacosaurus", "Psittacosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The timid Psittacosaurus. Many beasts form bonds with this adorable creature. Few wish to see it hurt.", "Il timido Psittacosaurus. Molte bestie stringono legami con questa adorabile creatura. Poche desiderano vederla ferita.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pteranodon", "Pteranodonte", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pteranodon, an iconic flying reptile. It may not have teeth to maul you with, but that beak spells trouble.", "Pteranodonte, un iconico rettile volante. Forse non ha denti per dilaniarti, ma quel becco è una minaccia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pterodaustro", "Pterodaustro", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...No, I did not fabricate this creature. Even the most bizarre forms can serve their own purposes.", "...No, non ho inventato questa creatura. Anche le forme più bizzarre possono avere una loro utilità.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Qianzhousaurus", "Qianzhousaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ambitious Qianzhousaurus. Though yet to reach the true King's might, it has potential for growth.", "L'ambizioso Qianzhousaurus. Non ha ancora raggiunto la potenza del vero Re, ma ha il potenziale per crescere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quercylurus", "Quercylurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quercylurus, a massive beast resembling saber-toothed cats. It gnaws on the many bones of its numerous victims.", "Quercylurus, un'enorme bestia simile ai felini dai denti a sciabola. Rosicchia le numerose ossa delle sue vittime.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhamphorhynchus", "Rhamphorhynchus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhamphorhynchus, a tiny flying reptile with a mouth full of sharp teeth. Though it prefers fish, it can and will bite your fingers.", "Rhamphorhynchus, un minuscolo rettile volante con la bocca piena di denti affilati. Preferisce il pesce, ma può e saprà morderti le dita.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacabambaspis", "Sacabambaspis", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The jawless Sacabambaspis, an adorable little fish with an armored hide.", "Il Sacabambaspis senza mascelle, un adorabile pesciolino dalla pelle corazzata.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sansanosmilus", "Sansanosmilus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sansanosmilus, a cat-like predator with a particularly wounding bite. Smaller size does not make it any less dangerous.", "Sansanosmilus, un predatore simile a un felino dal morso particolarmente doloroso. La taglia minore non lo rende meno pericoloso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sarcoprion", "Sarcoprion", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sarcoprion, a monstrous shark with a bizarre set of jaws. It uses them to cut its prey in half.", "Sarcoprion, uno squalo mostruoso dalle strane mascelle. Le usa per tagliare in due le prede.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Segisaurus", "Segisaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Segisaurus, hardly more than a pest. It comes in great numbers, however.", "Segisaurus, poco più di una seccatura. Si presenta però in gran numero.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shringasaurus", "Shringasaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shringasaurus, a horned reptile from the distant past. It shoves its attackers back in retaliation.", "Shringasaurus, un rettile cornuto di un lontano passato. Respinge gli aggressori per contrattaccare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shunosaurus", "Shunosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shunosaurus, a long-necked creature with a club at the end of its tail. It can land debilitating strikes upon its enemies.", "Shunosaurus, una creatura dal lungo collo con una mazza all'estremità della coda. Può sferrare colpi debilitanti ai nemici.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Simosuchus", "Simosuchus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Simosuchus, an adorable and completely harmless crocodilian. It protects itself with its thick scales.", "Simosuchus, un coccodrilliforme adorabile e del tutto innocuo. Si protegge con le sue spesse scaglie.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sinosauropteryx", "Sinosauropteryx", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sneaky Sinosauropteryx, a feathered reptilian pest resembling a racoon in more than appearance.", "Il furtivo Sinosauropteryx, un fastidioso rettile piumato che somiglia a un procione non solo nell'aspetto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stegosaurus", "Stegosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This territorial Stegosaurus is not willing to share room with anyone, friend or foe.", "Questo Stegosaurus territoriale non vuole dividere lo spazio con nessuno, amico o nemico.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stokesosaurus", "Stokesosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stokesosaurus, an unassuming predator. Perhaps it is more intelligent than it appears at a glance.", "Stokesosaurus, un predatore modesto. Forse è più intelligente di quanto sembri a prima vista.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stygimoloch", "Stygimoloch", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stygimoloch, a stubborn beast with an unpleasant attitude. It won't go down without a fight.", "Stygimoloch, una bestia testarda dal carattere sgradevole. Non cadrà senza combattere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Styracosaurus", "Styracosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The tenacious Styracosaurus. It's not content with simply fending off its attackers.", "Il tenace Styracosaurus. Non si accontenta di respingere i suoi aggressori.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Suchomimus", "Suchomimus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Suchomimus, a beats with a narrow snout that primarily hunts fish. It is no stranger to hunting prey on land, however.", "Suchomimus, una bestia dal muso stretto che caccia soprattutto pesci. Non è però estranea alla caccia sulla terraferma.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Supersaurus", "Supersaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The altruistic Supersaurus. It is determined to use what's left of its essence to support its comrades.", "L'altruista Supersaurus. È deciso a usare ciò che resta della sua essenza per sostenere i compagni.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tapejara", "Tapejara", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The illustrious Tapejara. It calls upon its kin to aid it in battle.", "L'illustre Tapejara. Chiama i suoi simili ad aiutarlo in battaglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiktaalik", "Tiktaalik", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiktaalik, the great progenitor. You may thank it for your ability to live on land.", "Tiktaalik, il grande progenitore. Puoi ringraziarlo per la tua capacità di vivere sulla terraferma.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Titanis", "Titanis", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Titanis, an oversized carnivorous bird with a foul temper. Don't expect to outrun this beast.", "Titanis, un enorme uccello carnivoro dal pessimo carattere. Non sperare di correre più veloce di questa bestia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torosaurus", "Torosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This elderly beast can hardly muster the will to retaliate. I advise against testing its patience, however.", "Questa anziana bestia riesce a malapena a trovare la volontà di reagire. Ti sconsiglio comunque di mettere alla prova la sua pazienza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Triceratops", "Triceratops", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Many have tried to best this lone Triceratops. Few could walk away.", "Molti hanno cercato di battere questo Triceratops solitario. Pochi sono riusciti ad andarsene.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Triceratops Hatchling", "Cucciolo di Triceratops", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A playful Triceratops hatchling. Cherish these moments before it turns into a fierce behemoth.", "Un giocoso cucciolo di Triceratops. Fai tesoro di questi momenti prima che diventi un feroce colosso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Troodon", "Troodon", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "New life shall spring from those unfortunate to feel its venomous bite.", "Una nuova vita germoglierà da chi avrà la sfortuna di subire il suo morso velenoso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tyrannosaurus Hatchling", "Cucciolo di Tyrannosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The innocent Tyrannosaurus hatchling. When the time comes, the throne will belong to this little creature.", "L'innocente cucciolo di Tyrannosaurus. Quando verrà il momento, il trono apparterrà a questa piccola creatura.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utahraptor", "Utahraptor", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utahraptor, an unpleasantly large beast for its kind. It can disembowel you in seconds.", "Utahraptor, una bestia spiacevolmente grande per la sua specie. Può sventrarti in pochi secondi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utatsusaurus", "Utatsusaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The nimble Utatsusaurus. It has little trouble passing over obstacles.", "L'agile Utatsusaurus. Supera gli ostacoli senza difficoltà.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Velociraptor", "Velociraptor", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The swift Velociraptor, a tiny menace of the desert. Were you expecting something bigger?", "Il rapido Velociraptor, una minuscola minaccia del deserto. Ti aspettavi qualcosa di più grande?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woolly Rhinoceros", "Rinoceronte lanoso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woolly Rhinoceros, a particularly hairy beast with eyesight that does not help its temper. Its long horn can pierce multiple foes.", "Il rinoceronte lanoso, una bestia molto pelosa la cui vista non aiuta il suo carattere. Il lungo corno può trafiggere più nemici.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Xiphactinus", "Xiphactinus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Xiphactinus, a monstrous fish with endless appetite. A single bite is not enough to sate it.", "Xiphactinus, un pesce mostruoso dall'appetito insaziabile. Un solo morso non basta a saziarlo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yutyrannus", "Yutyrannus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The fiendish Yutyrannus. It tears its prey apart while it's still alive.", "Il diabolico Yutyrannus. Fa a pezzi le sue prede mentre sono ancora vive.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zhenyuanopterus", "Zhenyuanopterus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zhenyuanopterus, a flying pest with a mouth full of needle-like teeth. It accompanies larger beasts into battle.", "Zhenyuanopterus, una seccatura volante dalla bocca piena di denti simili ad aghi. Accompagna in battaglia le bestie più grandi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria Cards", "Carte Sauria", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of around [count] cards consisting of a random assortment of prehistoric animals, mostly reptiles.", "Una raccolta di circa [count] carte con una selezione casuale di animali preistorici, soprattutto rettili.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A set of [summary] exclusively featuring a random assortment of prehistoric animals, mostly reptiles.", "Un set di [summary] composto esclusivamente da una selezione casuale di animali preistorici, soprattutto rettili.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fisher", "Pescatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, a Ceratodus is created in your hand. [define:Sauria_Ceratodus]", "Quando una carta che possiede questo sigillo viene giocata, viene creato un Ceratodus nella tua mano. [define:Sauria_Ceratodus]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A successful hunt for fish.", "Una pesca fruttuosa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fisher Strike", "Colpo del pescatore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil kills another creature, a Ceratodus is created in your hand. [define:Sauria_Ceratodus]", "Quando una carta che possiede questo sigillo uccide un'altra creatura, viene creato un Ceratodus nella tua mano. [define:Sauria_Ceratodus]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It appears the beast caught something.", "La bestia sembra aver catturato qualcosa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Promise of such a feast is too enticing for them to ignore.", "La promessa di un simile banchetto è troppo allettante per ignorarla.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mysterious power infuses your beast.", "Un potere misterioso pervade la tua bestia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something is off...", "Qualcosa non va...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks like it left something precious.", "Sembra aver lasciato qualcosa di prezioso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Marine Shuffle", "Mescolanza marina", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil kills another creature, a free Ceratodus is shuffled into your side deck. [define:Sauria_Ceratodus]", "Quando una carta che possiede questo sigillo uccide un'altra creatura, un Ceratodus gratuito viene mescolato nel tuo mazzo secondario. [define:Sauria_Ceratodus]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A surprise awaits you.", "Ti aspetta una sorpresa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks like it lost some teeth while grazing. They are yours to keep.", "Sembra aver perso qualche dente mentre brucava. Puoi tenerli.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not alone anymore.", "Non è più solo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nourishment", "Nutrimento", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A small sacrifice for small growth.", "Un piccolo sacrificio per una piccola crescita.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an abhorent creature, crafted by the hands of madmen...", "Che creatura abominevole, creata dalle mani di folli...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parting Fish", "Pesce d'addio", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil dies or is sacrificed, a Ceratodus is created in your hand. [define:Sauria_Ceratodus]", "Quando una carta che possiede questo sigillo muore o viene sacrificata, viene creato un Ceratodus nella tua mano. [define:Sauria_Ceratodus]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So many questions to ask.", "Così tante domande da fare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Another beast rises from its ashes.", "Un'altra bestia risorge dalle sue ceneri.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fatal mistake.", "Un errore fatale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can you feel the ground beneath your feet rumble?", "Senti la terra tremare sotto i piedi?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everything will be dragged to the depths.", "Tutto verrà trascinato negli abissi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not satisfied with its stolen goods just yet.", "Non è ancora soddisfatto della refurtiva.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Being in the presence of that animal is making it feel like a monster.", "La presenza di quell'animale lo fa sentire come un mostro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Taking up the arts? Interesting.", "Ti dedichi alle arti? Interessante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such is the might of a titan.", "Tale è la potenza di un titano.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The king has no need for restraint. More sacrifices must be made.", "Il re non ha bisogno di trattenersi. Servono altri sacrifici.", Language.Italian);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ancient Iguanodon", "Iguanodon antico", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A remnant of an old belief and proof of science's perpetual march, this beast has much to learn.", "Retaggio di un'antica convinzione e prova dell'incessante progresso della scienza, questa bestia ha molto da imparare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ankylodocus", "Ankylodocus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Far less abominable than most of its artificial kin, Ankylodocus can almost be called a gentle giant.", "Molto meno abominevole della maggior parte dei suoi simili artificiali, Ankylodocus può quasi essere definito un gigante gentile.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anzu", "Anzu", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anzu, the vicious beast that brings thunder. Do not invite its wrath upon yourself.", "Anzu, la feroce bestia che porta il tuono. Non attirare la sua ira su di te.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Archelon", "Archelon", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wise Archelon. It fortifies its allies upon entering the battle.", "Il saggio Archelon. Fortifica i suoi alleati entrando in battaglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Basilosaurus", "Basilosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Basilosaurus, the King Lizard. While not even remotely related to reptiles, it certainly earns the title of royalty.", "Basilosaurus, il re lucertola. Pur non essendo minimamente imparentato con i rettili, merita certamente il suo titolo regale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beautiful Feather", "Bella piuma", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dazzling.", "Sfolgorante.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brontosaurus", "Brontosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brontosaurus, the so-called thunderbringer. Its name may not be entirely unearned.", "Brontosaurus, il cosiddetto portatore di tuono. Forse non deve il suo nome al caso.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carchadontosaurus", "Carcharodontosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bloodthirsty Carcharodontosaurus. The smell of blood drives it into a frenzy.", "Il sanguinario Carcharodontosaurus. L'odore del sangue lo manda in delirio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cave Bear", "Orso delle caverne", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The reclusive Cave Bear. Though it may not be a vicious predator, it gives shelter to a fair share of beasts craving flesh.", "Il solitario orso delle caverne. Forse non è un feroce predatore, ma offre rifugio a molte bestie affamate di carne.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compstegnathus", "Compstegnathus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compstegnathus, a deformed beast bred for nefarious deeds. I do not enjoy looking at it.", "Compstegnathus, una bestia deforme allevata per scopi nefasti. Non mi piace guardarla.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cryolophosaurus", "Cryolophosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This crested beast brings the unforgiving cold of winter with it. When it enters battle, you may find some poor creatures trapped in ice as a result.", "Questa bestia crestuta porta con sé il freddo spietato dell'inverno. Quando entra in battaglia, alcune povere creature potrebbero rimanere intrappolate nel ghiaccio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an unsightly beast, truly an eyesore. Who could have spawned it?", "Che bestia sgradevole, un vero pugno nell'occhio. Chi può averla generata?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinosuchus Hatchling", "Cucciolo di Deinosuchus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A helpless Deinosuchus hatchling. It has yet to grow into a fearsome apex predator.", "Un cucciolo di Deinosuchus indifeso. Deve ancora crescere fino a diventare un temibile superpredatore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fish Meat", "Carne di pesce", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Juicy Fish Meat", "Carne di pesce succosa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giganotosaurus", "Giganotosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The horrifying Giganotosaurus. Though it normally hunts alone, big enough prey may attract more of its kind.", "Il terrificante Giganotosaurus. Anche se di solito caccia da solo, una preda abbastanza grande può attirare altri suoi simili.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Godzilla", "Godzilla", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The legendary King of the Monsters. It will take more than claws and fangs to take it down.", "Il leggendario Re dei mostri. Ci vorranno più di artigli e zanne per abbatterlo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Godzillasaurus", "Godzillasaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once a relatively peaceful beast, Godzillasaurus would go down in history as the King of the Monsters.", "Un tempo una bestia relativamente pacifica, Godzillasaurus passerà alla storia come Re dei mostri.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gwangi", "Gwangi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The voracious Gwangi, a relic of the past. Do not attribute malice to this poor creature, it merely wishes to live.", "Il vorace Gwangi, un relitto del passato. Non attribuire malizia a questa povera creatura: vuole solo vivere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Homotherium", "Homotherium", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Homotherium, a vicious pack hunter. It will endlessly pursue its prey to nourish its kin.", "Homotherium, un feroce cacciatore di branco. Insegue senza sosta le prede per nutrire i suoi simili.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hypsilophodon", "Hypsilophodon", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Hypsilophodon should be little more than prey for most beast... However...", "Questo Hypsilophodon dovrebbe essere poco più di una preda per la maggior parte delle bestie... Eppure...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyotitan", "Ichthyotitan", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyotitan, an awe-inspiring aquatic titan. Its sheer size alone dictates the flow of tides.", "Ichthyotitan, un imponente titano acquatico. La sua sola mole determina il corso delle maree.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Indominus", "Indominus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such is the power of science...", "Questo è il potere della scienza...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaellynasaura", "Leaellynasaura", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mysterious Leaellynasaura. Other beasts seem to undergo drastic changes in its presence.", "Il misterioso Leaellynasaura. Le altre bestie sembrano subire cambiamenti drastici in sua presenza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leedsichthys", "Leedsichthys", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The gigantic Leedsichthys, one of the biggest fish to ever inhabit the oceans. However, it is hardly one of the most dangerous.", "Il gigantesco Leedsichthys, uno dei pesci più grandi che abbiano mai abitato gli oceani. Non è però tra i più pericolosi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maiasaura", "Maiasaura", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maiasaura, the 'Good Mother Lizard'. It will not let harm befall the little ones as long as it breathes.", "Maiasaura, la «buona madre lucertola». Finché respirerà, non permetterà che i piccoli subiscano alcun male.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megalodon", "Megalodonte", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The titanic Megalodon, an apex predator plagued by insatiable hunger. Make sure it always has prey to feast on.", "Il titanico Megalodonte, un superpredatore tormentato da una fame insaziabile. Assicurati che abbia sempre una preda da divorare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megalosaurus", "Megalosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megalosaurus, one of the first to be discovered. Though its own fame did not last, it paves the path for others to attain it.", "Megalosaurus, uno dei primi a essere scoperti. Anche se la sua fama non è durata, apre la strada a quella degli altri.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Microraptor", "Microraptor", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This particularly petty Microraptor resembles ravens in more than its appearance. Do not get on its bad side.", "Questo Microraptor particolarmente meschino assomiglia ai corvi non solo nell'aspetto. Non fartelo nemico.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mosasaurus", "Mosasaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This aquatic behemoth is no less vicious than any land-dwelling titan of its time.", "Questo colosso acquatico è feroce quanto qualunque titano terrestre della sua epoca.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigger Mysterious Egg", "Uovo misterioso più grande", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something about this egg doesn't seem right...", "C'è qualcosa che non va in questo uovo...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noasaurus", "Noasaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Valley of the Dinosaurs is in danger... Alas, few heed its words.", "La valle dei dinosauri è in pericolo... Ahimè, pochi ascoltano le sue parole.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ornithomimus", "Ornithomimus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vain Ornithomimus, a feast for the eyes. When threatened, it flees and leaves behind colorful feathers for predators to marvel at.", "Il vanitoso Ornithomimus, una gioia per gli occhi. Quando è minacciato fugge, lasciando piume colorate da far ammirare ai predatori.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paraceratherium", "Paraceratherium", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paraceratherium, one of the largest mammals to set foot on land. Kindred beasts walk by its side.", "Paraceratherium, uno dei più grandi mammiferi ad aver camminato sulla terra. Bestie affini camminano al suo fianco.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Philosoraptor", "Filosoraptor", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The pensive Philosoraptor, always asking the questions none dare to voice aloud.", "Il pensieroso Filosoraptor pone sempre le domande che nessuno osa pronunciare ad alta voce.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pyroraptor", "Pyroraptor", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Like a bird of legend, Pyroraptor rose from the ashes to greet the world. Perhaps it could use a bit more fire?", "Come un uccello leggendario, Pyroraptor è risorto dalle ceneri per salutare il mondo. Forse gli servirebbe un po' più di fuoco?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quetzalcoatlus", "Quetzalcoatlus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The terrible Quetzalcoatlus, an alarmingly massive ruler of skies with an appetite to match.", "Il terribile Quetzalcoatlus, un dominatore dei cieli di dimensioni allarmanti e dall'appetito altrettanto grande.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Real Parasaurolophus", "Vero Parasaurolophus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Definitely Real Parasaurolophus", "Parasaurolophus assolutamente vero", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasaurolophus, a dragon with a bizarre appearance. It produces flames by igniting the fuel stored in its crest via flint-like teeth.", "Parasaurolophus, un drago dall'aspetto bizzarro. Produce fiamme accendendo il carburante nella cresta con denti simili alla selce.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhedosaurus", "Rhedosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Rhedosaurus from a distant world. The plague it carries in its blood is much too alien for most creatures to bear.", "Un Rhedosaurus di un mondo lontano. La peste nel suo sangue è troppo aliena perché la maggior parte delle creature possa sopportarla.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shantungosaurus", "Shantungosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shantungosaurus, absurdly massive for something that can stand on its rear legs. Their herds are as awe-inspiring as they are terrifying.", "Shantungosaurus, incredibilmente massiccio per una creatura capace di stare sulle zampe posteriori. I suoi branchi sono tanto maestosi quanto terrificanti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spicomellus", "Spicomellus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spicomellus, a beast covered in numerous spikes. It does not look pleasant to touch and it is even less pleasant to strike.", "Spicomellus, una bestia coperta di numerose spine. Toccarla non sembra piacevole, e colpirla lo è ancora meno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spinoraptor", "Spinoraptor", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An abomination born of science, Spinoraptor is an adept fisher and hunter.", "Abominio nato dalla scienza, Spinoraptor è un abile pescatore e cacciatore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spinosaurus", "Spinosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bizarre reptile of monstrous size, few marine animals can evade its narrow jaws.", "Uno strano rettile di dimensioni mostruose. Pochi animali marini possono sfuggire alle sue strette fauci.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The monstrous Spinosaurus, the only being worthy of challenging the King.", "Il mostruoso Spinosaurus, l'unico essere degno di sfidare il Re.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanatosdrakon", "Thanatosdrakon", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanatosdrakon, a beast that has breached the boundary between life and death... Hm... Perhaps this creature has been blessed by...", "Thanatosdrakon, una bestia che ha varcato il confine tra la vita e la morte... Mmh... Forse questa creatura è stata benedetta da...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Al", "Al il grande", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Al, a female Allosaurus that has suffered greatly during its short life. Perhaps you can help this poor creature?", "Al il grande, una femmina di Allosaurus che ha sofferto molto nella sua breve vita. Forse puoi aiutare questa povera creatura?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Wars", "Guerra delle ossa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They fought to protect their pride, sparing no expense. In the end, what were they left with?", "Hanno lottato per difendere il loro orgoglio, senza badare a spese. Alla fine, cosa è rimasto loro?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Therizinosaurus", "Therizinosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Therizinosaurus can hardly see these days. However, you do not want to approach a half-blind giant with claws of such length.", "Questo Therizinosaurus ormai vede a malapena. Tuttavia, è meglio non avvicinarsi a un gigante mezzo cieco con artigli tanto lunghi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Titanosaurus", "Titanosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life was not meant to reach such sizes on land. This titan bears more resemblance to a force of nature than a beast.", "La vita sulla terraferma non era destinata a raggiungere tali dimensioni. Questo titano somiglia più a una forza della natura che a una bestia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tupandactylus", "Tupandactylus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The majestic Tupandactylus. Many flying creatures find themselves drawn to its exceptional crest.", "Il maestoso Tupandactylus. Molte creature volanti sono attratte dalla sua straordinaria cresta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tyrannosaurus", "Tyrannosaurus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The infamous Tyrant Lizard King. Do you have the courage to oppose the largest land predator the world has ever seen?", "Il famigerato re delle lucertole tiranne. Hai il coraggio di affrontare il più grande predatore terrestre che il mondo abbia mai visto?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feathered Tyrannosaurus", "Tyrannosaurus piumato", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This whole...feather thing is getting out of hand. Have you considered that not every dinosaur was covered in them?", "Tutta questa... storia delle piume sta sfuggendo di mano. Hai considerato che non tutti i dinosauri ne erano ricoperti?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Velocipastor", "Velocipastore", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I... uh... I'm afraid there's little I can say to explain this. It was worth the time.", "Io... ehm... temo di non poter spiegare molto. Ne è valsa la pena.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woolly Mammoth", "Mammut lanoso", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woolly Mammoth, an iconic beast of the Ice Age. They are never alone.", "Il mammut lanoso, una bestia iconica dell'era glaciale. Non sono mai soli.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So many bones to claim...", "Così tante ossa da raccogliere...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinosuchus Juvenile", "Giovane Deinosuchus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A juvenile Deinosuchus. It is still growing, but it is already a fearsome predator.", "Un giovane Deinosuchus. Sta ancora crescendo, ma è già un temibile predatore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinosuchus", "Deinosuchus", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinosuchus, a fearsome apex predator. Not even prehistoric giants could escape from its jaws.", "Deinosuchus, un temibile superpredatore. Nemmeno i giganti preistorici potevano sfuggire alle sue fauci.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater defense is more than sufficient.", "Una difesa maggiore è più che sufficiente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not satisfied yet...", "Non è ancora soddisfatto...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astonishing recovery.", "Una ripresa sorprendente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The beast is offering comrades to assist you in this battle.", "La bestia ti offre compagni per aiutarti in questa battaglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is getting out of hand.", "La situazione sta sfuggendo di mano.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is strength in numbers.", "L'unione fa la forza.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something wicked lurks in these waters.", "Qualcosa di malvagio si nasconde in queste acque.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There are more of them now? End this before it gets any worse.", "Ora sono ancora di più? Metti fine alla cosa prima che peggiori.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a voracious little beast.", "Che piccola bestia vorace.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It still has room for growth.", "Ha ancora spazio per crescere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What did you do to that beast?", "Cosa hai fatto a quella bestia?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's... It's Godzilla!!!", "È... È Godzilla!!!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's done being a victim.", "Ha smesso di essere una vittima.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A feast for its kin.", "Un banchetto per i suoi simili.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It still clings to its glory, unwilling to be surpassed.", "Si aggrappa ancora alla propria gloria e non vuole essere superato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria Cards (Blood)", "Carte Sauria (sangue)", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of around [count] cards that cost Blood. Features a random assortment of prehistoric animals, mostly reptiles.", "Una raccolta di circa [count] carte che costano sangue. Contiene una selezione casuale di animali preistorici, soprattutto rettili.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria Cards (Bones)", "Carte Sauria (ossa)", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of around [count] cards that cost Bones. Features a random assortment of prehistoric animals, mostly reptiles.", "Una raccolta di circa [count] carte che costano ossa. Contiene una selezione casuale di animali preistorici, soprattutto rettili.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria Cards (Mixed)", "Carte Sauria (miste)", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of around [count] cards that cost Blood and Bones. Features a random assortment of prehistoric animals, mostly reptiles.", "Una raccolta di circa [count] carte che costano sangue e ossa. Contiene una selezione casuale di animali preistorici, soprattutto rettili.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ginormous Camarasaurus. Its great size allows it to fling beasts across the battlefield.", "L'enorme Camarasaurus. La sua mole gli permette di scagliare bestie attraverso il campo di battaglia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Blood to increase Health of a card bearing this sigil by 1, then remove this sigil.", "Paga 1 sangue per aumentare di 1 la salute di una carta che possiede questo sigillo, poi rimuovi questo sigillo.", Language.Italian);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue, the most reliable among the r... This beast shouldn't be human... Hm...", "Blue, la più affidabile tra i r... Questa bestia non dovrebbe essere umana... Mmh...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Hm?[w:0.5]", "[e:Curious]Mmh?[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]You're...[w:0.3][e:Anger] You're not Owen.[w:0.5]", "[e:Curious]Tu sei...[w:0.3][e:Anger] Non sei Owen.[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I could tear you to bits right now[w:0.5].[w:0.5].[w:0.5].[w:0.5]", "[e:Anger]Potrei farti a pezzi proprio ora[w:0.5].[w:0.5].[w:0.5].[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]But Owen doesn't like it when we do that.[w:0.5]", "[e:Anger]Ma a Owen non piace quando lo facciamo.[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Maybe if he", "[e:Quiet]Forse se lui", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Pleased to meet you!", "[e:Laughter]Piacere di conoscerti!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Take good care of me and everything will be fine.", "[e:Neutral]Prenditi cura di me e andrà tutto bene.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Hey there!", "[e:Neutral]Ehi!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I can make quick work of 'em.", "[e:Laughter]Posso sbarazzarmene in fretta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Ready to go!", "[e:Neutral]Pronta a partire!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]If you want them dead, let me know!", "[e:Laughter]Se li vuoi morti, fammelo sapere!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Another task? I can handle it.", "[e:Neutral]Un altro compito? Posso occuparmene.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]I've never been in a place like this...[w:0.5]", "[e:Curious]Non sono mai stata in un posto simile...[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]But hey, if there are no fences here[w:0.5]", "[e:Laughter]Ma se qui non ci sono recinti[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Then I don't need to restrain myself.", "[e:Quiet]Allora non devo trattenermi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I don't get to just kill things often.", "[e:Laughter]Non mi capita spesso di poter uccidere così.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Roger that!", "[e:Laughter]Ricevuto!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I'm excited to tear into prey again.", "[e:Neutral]Non vedo l'ora di fare di nuovo a pezzi le prede.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Got it!", "[e:Neutral]Capito!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Weakness means death.", "[e:Quiet]Debolezza significa morte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Consider it done!", "[e:Neutral]Come se fosse già fatto!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Is this the right choice?", "[e:Curious]È la scelta giusta?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]I'll remember this.[c:]", "[e:Anger][c:R]Me lo ricorderò.[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Don't expect to get away with this.", "[e:Quiet]Non pensare di passarla liscia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]So be it.", "[e:Anger]E così sia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Wuh?", "[e:Surprise]Eh?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Oooh, what's this?", "[e:Curious]Oooh, cos'è questo?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]What's going to happen next?", "[e:Curious]Cosa succederà adesso?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I trust your decisions.", "[e:Laughter]Mi fido delle tue decisioni.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I don't feel like participating.", "[e:Anger]Non ho voglia di partecipare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]No.", "[e:Anger]No.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Think again.", "[e:Anger]Ripensaci.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Can't say I didn't expect this.[w:0.4]", "[e:Anger]Non posso dire di non aspettarmelo.[w:0.4]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]It's okay, I've done this with the rest of my pack", "[e:Neutral]Va bene, l'ho già fatto con il resto del mio branco", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]plenty of times, this is nothing", "[e:Neutral]molte volte, non è niente", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You're dead.", "[e:Anger]Sei morto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I did not appreciate that.", "[e:Anger]Non l'ho apprezzato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'll return the favour.", "[e:Quiet]Ti restituirò il favore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Just a natural part of the hunt.", "[e:Neutral]Una parte naturale della caccia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I'll return the favour.", "[e:Neutral]Ti restituirò il favore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Oh, a test?[w:0.5]", "[e:Surprise]Oh, una prova?[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I've always been good at those!", "[e:Laughter]Sono sempre stata brava in questo!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Is it done?", "[e:Curious]È finito?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Did I do good?", "[e:Laughter]Sono stata brava?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]How did it go?", "[e:Neutral]Com'è andata?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Ooooh...[w:0.5]", "[e:Surprise]Oooh...[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Don't mind if I do!", "[e:Laughter]Non me lo faccio ripetere!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I've been looking forward to this.", "[e:Quiet]Aspettavo questo momento.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You were simply not good enough.", "[e:Laughter]Semplicemente non eri abbastanza bravo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Where are the others?[w:0.3].[leshy:I might have made a mistake... Very well.][w:2]", "[e:Anger]Dove sono gli altri?[w:0.3].[leshy:Forse ho commesso un errore... Molto bene.][w:2]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Oh, hi!", "[e:Laughter]Oh, ciao!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Didn't expect to see you again!", "[e:Laughter]Non pensavo di rivederti!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How are you?", "Come stai?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Huh?", "[e:Surprise]Eh?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I'll remember this.", "[e:Anger]Me lo ricorderò.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Don't get cocky.", "[e:Anger]Non montarti la testa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Angry]I don't like the way he smells...[w:0.5]", "[e:Angry]Non mi piace il suo odore...[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's kill him!", "[e:Laughter]Uccidiamolo!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This guy...[w:0.5]", "[e:Anger]Questo tizio...[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Make it hurt this time.", "[e:Neutral]Questa volta fagli male.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I hate the noise.", "[e:Anger]Odio quel rumore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Kill him.", "[e:Anger]Uccidilo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Fish...[w:0.3]?[w:0.5]", "[e:Surprise]Pesce...[w:0.3]?[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I never really liked that stuff.[w:0.3]", "[e:Neutral]Non mi è mai piaciuto molto.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'll eat him instead.", "[e:Quiet]Mangerò lui, invece.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I won't fall for his tricks.", "[e:Anger]Non cadrò nei suoi trucchi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Can't even enjoy eating him...", "[e:Anger]Non posso nemmeno godermi il momento di mangiarlo...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]We've done this before, let's kill him again!", "[e:Neutral]L'abbiamo già fatto, uccidiamolo di nuovo!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Wuh?[w:0.5] He wasn't on our side?[w:0.5]", "[e:Curious]Eh?[w:0.5] Non era dalla nostra parte?[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Then I can kill him?", "[e:Quiet]Allora posso ucciderlo?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Oh, the two-faced guy again! Let's beat him up!", "[e:Laughter]Oh, di nuovo il tizio con due facce! Pestiamolo!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Two birds with one stone!", "[e:Laughter]Due piccioni con una fava!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's get rid of him.", "[e:Neutral]Sbarazziamoci di lui.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Oh, this is the end?[w:0.5]", "[e:Curious]Oh, è la fine?[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Well, it's been fun.[w:0.5]", "[e:Neutral]Beh, è stato divertente.[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]We'll see each other again, right?[w:0.5]", "[e:Neutral]Ci rivedremo, vero?[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I hope we get to have a good time later!", "[e:Laughter]Spero che ci divertiremo ancora!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]The finale![w:0.5]", "[e:Laughter]Il gran finale![w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]This should be fun!", "[e:Neutral]Sarà divertente!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]It sucks having to part ways...[w:0.5]", "[e:Anger]È brutto doversi separare...[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I hope to see you again!", "[e:Laughter]Spero di rivederti!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's end this with a bang!", "[e:Laughter]Chiudiamo col botto!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]I think...[w:0.3]", "[e:Curious]Credo...[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]I think I've seen somebody like this before.[w:0.5]", "[e:Curious]Credo di aver già visto qualcuno così.[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Owen scolded me for snarling at that guy.", "[e:Anger]Owen mi ha sgridata perché ho ringhiato a quel tizio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I'd rather not deal with those cannons.", "[e:Anger]Preferirei non occuparmi di quei cannoni.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Not again...", "[e:Anger]Non di nuovo...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This isn't particularly fun.", "[e:Anger]Non è particolarmente divertente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Oh, what's this?[w:0.5]", "[e:Surprise]Oh, cos'è questo?[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Well, I guess my task is still the same!", "[e:Laughter]Beh, immagino che il mio compito sia sempre lo stesso!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I like when they struggle more.", "[e:Neutral]Mi piace quando si dimenano di più.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Oh, this one looks fun!", "[e:Laughter]Oh, questo sembra divertente!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's just kill them.", "[e:Neutral]Uccidiamoli e basta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Oh, another one!", "[e:Laughter]Oh, un altro!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]What will it be this time?", "[e:Neutral]Cosa sarà questa volta?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]This woman?[w:0.5]", "[e:Surprise]Questa donna?[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Owen always told me to be more gentle with the elderly.[w:0.4]", "[e:Neutral]Owen mi diceva sempre di essere più gentile con gli anziani.[w:0.4]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Y'know, don't startle them and all that?[w:0.5]", "[e:Neutral]Sai, non spaventarli e cose così?[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I didn't listen.", "[e:Quiet]Non l'ho ascoltato.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Weakness means death.", "[e:Laughter]Debolezza significa morte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]If she's our enemy, then we should kill her!", "[e:Laughter]Se è nostra nemica, dobbiamo ucciderla!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]No hesitation!", "[e:Neutral]Senza esitare!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I've never liked their smell.[w:0.5]", "[e:Anger]Non mi è mai piaciuto il loro odore.[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Reminded me of him.[w:0.3]", "[e:Anger]Mi ricordava lui.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Now, let's kill them!", "[e:Laughter]Ora uccidiamoli!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]More faces means more to bite!", "[e:Neutral]Più facce significa più cose da mordere!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]You think they'll live with one of his faces clawed off?", "[e:Curious]Pensi che sopravvivranno se gli strappo una delle sue facce con gli artigli?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I wonder if he'll feel spongy...", "[e:Neutral]Mi chiedo se sarà spugnoso...", Language.Italian);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm... Maybe something got mixed up in there...", "Mmh... Forse lì dentro si è mescolato qualcosa...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You.[w:0.5]", "Tu.[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't know who you are.", "Non so chi sei.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't particularly care either.", "E non mi interessa particolarmente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Either you get me out of this mess or[w:0.5].[w:0.5].[w:0.5][e:Laughter].[w:0.5]", "O mi tiri fuori da questo pasticcio oppure[w:0.5].[w:0.5].[w:0.5][e:Laughter].[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]No, I [e:Quiet]don't[w:0.5][e:Laughter] need to spell it out.[w:0.5]", "[e:Laughter]No, [e:Quiet]non[w:0.5][e:Laughter] devo spiegartelo.[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet][c:R]Know your place and you will live.[c:]", "[e:Quiet][c:R]Conosci il tuo posto e vivrai.[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Make it quick.", "[e:Neutral]Fa' in fretta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Morsels, all for me.", "[e:Laughter]Bocconcini, tutti per me.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]A fine opportunity.", "[e:Neutral]Una buona occasione.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Now is a good time to feed me.", "[e:Laughter]È un buon momento per nutrirmi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Good timing. I was feeling quite peckish.", "[e:Laughter]Tempismo perfetto. Cominciavo ad avere fame.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I've been looking for something", "[e:Laughter]Cerco qualcosa", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]to tear into since I got into this mess.", "[e:Laughter]da fare a pezzi da quando sono finito in questo pasticcio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I won't make it quick.", "[e:Quiet]Non farò in fretta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I won't leave anything behind.", "[e:Laughter]Non lascerò niente.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]A feast, just for me.", "[e:Laughter]Un banchetto, tutto per me.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Don't expect to survive.", "[e:Neutral]Non aspettarti di sopravvivere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Who wishes to die first?", "[e:Quiet]Chi vuole morire per primo?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I've been itching for a fight.", "[e:Quiet]Muoio dalla voglia di combattere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Are you sure about this choice?", "[e:Curious]Sei sicuro di questa scelta?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]You traitor!!![c:]", "[e:Anger][c:R]Traditore!!![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'll remember this.", "[e:Quiet]Me lo ricorderò.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]You bastard!!![c:]", "[e:Anger][c:R]Bastardo!!![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise][c:R]You...![c:]", "[e:Surprise][c:R]Tu...![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Oh, what's this now?", "[e:Curious]Oh, cos'è questo adesso?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Who will die this time?", "[e:Curious]Chi morirà questa volta?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]There is only one correct choice.", "[e:Laughter]C'è una sola scelta giusta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Do not make any choices I would make you regret.", "[e:Quiet]Non fare scelte che ti farei rimpiangere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's get this done and over with.", "[e:Neutral]Finiamola una volta per tutte.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Pick anyone else.", "[e:Neutral]Scegli chiunque altro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You did this on purpose...[w:0.4]", "[e:Anger]L'hai fatto apposta...[w:0.4]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:R]Didn't you!?[c:][w:0.5]", "[c:R]Non è vero!?[c:][w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I'll let it slide for now.", "[e:Neutral]Per questa volta lascerò correre.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]You dare...![c:]", "[e:Anger][c:R]Come osi...![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]I'll tear you limb from limb!!![c:]", "[e:Anger][c:R]Ti strapperò un arto alla volta!!![c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]You've made your choice.", "[e:Quiet]Hai fatto la tua scelta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Tsk!", "[e:Anger]Tsk!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Gh!", "[e:Anger]Gh!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Is this some kind of a test?[w:0.5]", "[e:Surprise]È una specie di prova?[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I don't expect to fail.", "[e:Laughter]Non mi aspetto di fallire.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Are we done?", "[e:Curious]Abbiamo finito?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I shall aid you.", "[e:Laughter]Ti aiuterò.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Waste of my time.", "[e:Neutral]Uno spreco del mio tempo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Interesting...[w:0.5]", "[e:Curious]Interessante...[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]There are enough voices screaming from within my blood.", "[e:Neutral]Ci sono già abbastanza voci che urlano nel mio sangue.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]What's another one?", "[e:Quiet]Cosa cambia una voce in più?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Become a part of me.", "[e:Laughter]Diventa parte di me.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I shall claim your power.", "[e:Quiet]Reclamerò il tuo potere.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]It is only natural.", "[e:Laughter]È del tutto naturale.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]What did you do to me!?[c:][w:0.5].[leshy:It appears that this beast is... more human than it appeared. No matter.][w:2]", "[e:Anger][c:R]Cosa mi hai fatto!?[c:][w:0.5].[leshy:Sembra che questa bestia sia... più umana di quanto apparisse. Non importa.][w:2]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We meet again.", "[e:Laughter]Ci incontriamo di nuovo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You shall serve me once more.", "[e:Laughter]Mi servirai ancora una volta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do not disappoint me this time.", "Non deludermi questa volta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]No, you can't...!", "[e:Surprise]No, non puoi...!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Curse you!!!", "[e:Anger]Maledetto!!!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I will remember this!!!", "[e:Anger]Me lo ricorderò!!!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]What an eyesore...", "[e:Neutral]Che pugno nell'occhio...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Get rid of him.[w:0.5]", "Sbarazzati di lui.[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The noise bothers me.", "Quel rumore mi disturba.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You...[w:0.5]", "[e:Anger]Tu...[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Do not make the same mistakes.", "[e:Neutral]Non fare gli stessi errori.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This noise again...", "[e:Anger]Di nuovo questo rumore...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Get him out of my sight.", "[e:Anger]Toglimelo dalla vista.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]This...[w:0.5] This smell...[w:0.5]", "[e:Surprise]Questo...[w:0.5] Questo odore...[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]I remember a smell like this...[w:0.5]", "[e:Surprise]Ricordo un odore simile...[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]We must get out of here.", "[e:Surprise]Dobbiamo uscire da qui.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Don't let those things near me!", "[e:Surprise]Non lasciare che quelle cose si avvicinino a me!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]I won't die like this again!", "[e:Surprise]Non morirò di nuovo così!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]There's something lurking in the waters...", "[e:Surprise]C'è qualcosa in agguato nell'acqua...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I have little patience for traitors.[w:0.5]", "[e:Anger]Ho poca pazienza per i traditori.[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet][c:R]Skin him alive.[c:]", "[e:Quiet][c:R]Scorticalo vivo.[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]He'll make for a fine pelt.", "[e:Laughter]Sarà una bella pelle.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]The smell in the air is pleasant.", "[e:Laughter]L'odore nell'aria è piacevole.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet][c:R]Let's enrich it further with his blood.[c:]", "[e:Quiet][c:R]Arricchiamolo ulteriormente con il suo sangue.[c:]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You should know how this works by now.", "[e:Laughter]Ormai dovresti sapere come funziona.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]This is it...[w:0.5]", "[e:Curious]Ci siamo...[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]We've made it this far.[w:0.5]", "[e:Neutral]Siamo arrivati fin qui.[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose you weren't too bad.[w:0.5]", "Suppongo che tu non sia stato tanto male.[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I won't miss you[w:0.5], but I've seen worse humans.[w:0.5]", "Non mi mancherai[w:0.5], ma ho visto esseri umani peggiori.[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Let's put an end to his games.", "[e:Quiet]Mettiamo fine ai suoi giochi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You can do this.[w:0.5]", "[e:Laughter]Puoi farcela.[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Be of service to me once again.", "[e:Laughter]Servimi ancora una volta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We shall part soon.[w:0.5]", "[e:Laughter]Presto ci separeremo.[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I hope to see you again.", "[e:Laughter]Spero di rivederti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]It's been fun so far.[w:0.5]", "[e:Laughter]Finora è stato divertente.[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's have some more fun in the future.", "[e:Laughter]Divertiamoci ancora in futuro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Not...[w:0.5] Not the water again...[w:0.5]", "[e:Surprise]Non...[w:0.5] Non di nuovo l'acqua...[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]What will attack me this time?", "[e:Surprise]Cosa mi attaccherà questa volta?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I don't appreciate getting shot with cannons. Kill him quickly.", "[e:Anger]Non mi piace essere colpito dai cannoni. Uccidilo in fretta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This moron again...", "[e:Anger]Di nuovo questo idiota...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]There isn't even anything to gnaw on.", "[e:Anger]Non c'è nemmeno niente da rosicchiare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]The air is different.[w:0.5]", "[e:Surprise]L'aria è diversa.[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]They are prey all the same.", "[e:Laughter]Restano comunque prede.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]What a chore.", "[e:Neutral]Che seccatura.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Perhaps something bigger to chew on?", "[e:Laughter]Forse qualcosa di più grande da masticare?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Eyesore.", "[e:Neutral]Un pugno nell'occhio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]This changes nothing.", "[e:Laughter]Questo non cambia nulla.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]They should know their place.", "[e:Laughter]Dovrebbero conoscere il proprio posto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Hmph.[w:0.5]", "[e:Neutral]Mpf.[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]This foolish hag has outlived her usefulness.[w:0.5]", "[e:Neutral]Questa vecchia sciocca non è più utile.[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Her skull would be a fine decoration for a totem.", "[e:Quiet]Il suo teschio sarebbe una bella decorazione per un totem.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's shave off what few years she has left.", "[e:Laughter]Accorciamo i pochi anni che le restano.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]One foot in the grave, another soon to come.", "[e:Laughter]Un piede nella fossa, l'altro lo seguirà presto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]She'd die in a few years regardless.", "[e:Laughter]Morirebbe comunque entro pochi anni.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Not particularly surprising.[w:0.5]", "[e:Neutral]Non è particolarmente sorprendente.[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]These experimental types don't know loyalty.[w:0.5]", "[e:Neutral]Questi tipi sperimentali non conoscono la lealtà.[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'd rather get my claws on that bastard Wu", "[e:Quiet]Preferirei mettere gli artigli su quel bastardo di Wu", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]but this shall do for now.", "[e:Laughter]ma questo andrà bene per ora.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's return the favour.", "[e:Neutral]Restituiamo il favore.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]There won't be much left to stitch together.", "[e:Laughter]Non resterà molto da ricucire.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Two heads to tear off.[e:Quiet]What a treat.", "[e:Neutral]Due teste da strappare.[e:Quiet]Che delizia.", Language.Italian);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Owen", "Owen", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A human? ...No matter. I have a feeling this man will prove himself capable against claws and fangs of your opponents.", "Un umano? ...Non importa. Ho la sensazione che quest'uomo saprà affrontare artigli e zanne dei tuoi avversari.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]I don't know what this whole thing is about[w:0.3]", "[e:Curious]Non so di cosa si tratti[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]but we'll make it", "[e:Laughter]ma ce la faremo", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]trust me.", "[e:Laughter]fidati di me.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Stay on guard.", "[e:Anger]Stai in guardia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]So much for taking a break, huh.", "[e:Laughter]Addio pausa, eh.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You can count on me.", "[e:Laughter]Puoi contare su di me.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Let's hope working at Jurassic World didn't make me rusty...", "[e:Quiet]Speriamo che lavorare a Jurassic World non mi abbia arrugginito...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I don't like doing this, but it's us or them here.", "[e:Anger]Non mi piace farlo, ma qui o noi o loro.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This rifle better not act up on me now...", "[e:Anger]Spero che questo fucile non mi tradisca proprio ora...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's do this.", "[e:Neutral]Facciamolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Gotta focus if we both want to keep our skins.", "[e:Quiet]Dobbiamo concentrarci se vogliamo salvare la pelle entrambi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Not sure about this position, but I can make it work.", "[e:Quiet]Non sono sicuro di questa posizione, ma posso cavarmela.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Now would be a bad time to forget my training.", "[e:Quiet]Sarebbe un pessimo momento per dimenticare l'addestramento.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Wait, what are you doing!?", "[e:Surprise]Aspetta, cosa stai facendo!?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Huh, why me?", "[e:Surprise]Eh, perché io?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I haven't told her I-", "[e:Anger]Non le ho detto che io...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]What kind of-", "[e:Anger]Che razza di...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Whatever this is, I don't like it.", "[e:Anger]Qualunque cosa sia, non mi piace.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'd rather sit this one out.", "[e:Quiet]Preferirei non partecipare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]If I have to...", "[e:Quiet]Se devo...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I have a bad feeling about this one.", "[e:Anger]Ho una brutta sensazione.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Could you pick anyone else?", "[e:Quiet]Potresti scegliere qualcun altro?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'd rather not...", "[e:Quiet]Preferirei di no...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Damn...[w:0.3]", "[e:Anger]Dannazione...[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]The situation is worse than I thought.[w:0.3]", "[e:Anger]La situazione è peggiore di quanto pensassi.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I can still handle this, don't worry.", "[e:Laughter]Posso ancora cavarmela, non preoccuparti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Shit!", "[e:Anger]Merda!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This will leave a mark.", "[e:Anger]Questo lascerà il segno.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Sure, I could use another scar.", "[e:Anger]Certo, un'altra cicatrice mi mancava proprio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Ow!", "[e:Anger]Ahi!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Tsk, got careless.", "[e:Anger]Tsk, mi sono distratto.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]A trial?[w:0.3]", "[e:Surprise]Una prova?[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Well, did we pass it?", "[e:Curious]Allora, l'abbiamo superata?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]How did we do?", "[e:Curious]Come ce la siamo cavata?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I have a good feeling about this one.", "[e:Laughter]Ho una buona sensazione stavolta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I didn't just blow it, did I?", "[e:Quiet]Non ho mandato tutto all'aria, vero?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Me?[w:0.3]", "[e:Surprise]Io?[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Well... Sorry, buddy", "[e:Quiet]Beh... Scusa, amico", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]but it looks like there's no other choice.", "[e:Quiet]ma sembra che non ci sia altra scelta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I hate doing this.", "[e:Quiet]Odio fare questo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]If we want to survive...", "[e:Quiet]Se vogliamo sopravvivere...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Really wish we could avoid this, but...", "[e:Quiet]Vorrei davvero evitarlo, ma...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]What is this place?[w:0.3]", "[e:Curious]Che posto è questo?[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Well, you look like a reasonable fellow.", "[e:Laughter]Beh, sembri una persona ragionevole.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]If we stick together", "[e:Laughter]Se restiamo uniti", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]we can escape in one piece", "[e:Laughter]possiamo uscirne tutti interi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Hello again.", "[e:Laughter]Di nuovo ciao.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Did you miss me?", "[e:Laughter]Ti sono mancato?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guess we're doing this again...", "Pare che si ricominci...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Hold on, this looks bad!", "[e:Surprise]Aspetta, sembra mettersi male!", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]A prospector?[w:0.5]", "[e:Curious]Un cercatore d'oro?[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This feels like some kind of an attraction[w:0.5]", "Sembra una specie di attrazione[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]But we won't be having fun here, are we?", "[e:Anger]Ma non ci divertiremo qui, vero?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This guy again?[w:0.3]", "[e:Anger]Di nuovo quel tizio?[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Let's be a bit more careful this time.", "[e:Anger]Stavolta stiamo un po' più attenti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I'll keep hearing this ringing for the rest of my life.", "[e:Anger]Sentirò questo ronzio per il resto della vita.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You know what's gonna happen soon. Get ready.", "[e:Anger]Sai cosa succederà presto. Preparati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Woah![w:0.5]", "[e:Surprise]Wow![w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]This guy's huge![w:0.5]", "[e:Surprise]Questo tizio è enorme![w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]But I've dealt with bigger fish than this.", "[e:Laughter]Ma ho già affrontato pesci più grossi.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's do this.", "[e:Laughter]Facciamolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]This guy again...[w:0.3]", "[e:Curious]Di nuovo quel tizio...[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We've done this before, let's get him.", "[e:Laughter]L'abbiamo già fatto, prendiamolo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You know...[w:0.3]", "[e:Anger]Sai...[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]maybe I don't need to feel so bad about the sharks we fed to that thing.", "[e:Anger]forse non devo sentirmi così in colpa per gli squali che abbiamo dato in pasto a quella cosa.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]The smell doesn't get any better...", "[e:Anger]L'odore non migliora...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I knew something was off[w:0.3]", "[e:Anger]Sapevo che qualcosa non andava[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Guess I've got a good grasp of people too.", "[e:Laughter]A quanto pare so capire bene anche le persone.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Get ready.", "[e:Laughter]Preparati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Nothing to worry about", "[e:Laughter]Niente di cui preoccuparsi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I can disarm the traps from afar.", "[e:Laughter]posso disinnescare le trappole da lontano.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We shouldn't have any trouble at all.", "[e:Laughter]Non dovremmo avere alcun problema.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Here we go.", "[e:Laughter]Si comincia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]If you don't want to sacrifice anybody", "[e:Laughter]Se non vuoi sacrificare nessuno", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]let me get rid of these things myself.", "[e:Laughter]lascia che mi sbarazzi io di queste cose.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]So this is the guy behind everything?[w:0.3]", "[e:Curious]Quindi è lui il responsabile di tutto?[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Not sure what I was expecting", "[e:Curious]Non so cosa mi aspettassi", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]But it doesn't matter.[w:0.3]", "[e:Anger]Ma non importa.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Let's end this.", "[e:Anger]Mettiamo fine a tutto questo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We've done this before", "[e:Laughter]L'abbiamo già fatto", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]let's do it again.", "[e:Laughter]facciamolo di nuovo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This guy's no joke.", "[e:Anger]Questo tizio fa sul serio.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Don't let your guard down.", "[e:Anger]Non abbassare la guardia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We've got this, don't worry.", "[e:Laughter]Ce la faremo, non preoccuparti.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]A...[w:0.3]pirate?", "[e:Surprise]Un...[w:0.3] pirata?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Hah, good one![w:0.3]", "[e:Laughter]Ah, bella questa![w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Well, there's only one thing left to do.", "[e:Laughter]Beh, rimane una sola cosa da fare.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Watch out for the cannons.", "[e:Anger]Attento ai cannoni.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This will be tough, but we can do this.", "[e:Anger]Sarà dura, ma possiamo farcela.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This guy isn't playing around, stay on guard.", "[e:Anger]Questo tizio fa sul serio, stai in guardia.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Is this some kind of...[w:0.5] Magic?[w:0.5]", "[e:Surprise]È una specie di...[w:0.5] magia?[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Well, I guess this is going to get much weirder.", "[e:Quiet]Beh, credo che le cose diventeranno molto più strane.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]They're getting empowered. Stay alert.", "[e:Anger]Si stanno potenziando. Stai all'erta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Not this thing again...", "[e:Anger]Non di nuovo questa cosa...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]How come I don't get fancy toys like this?", "[e:Curious]Perché io non ho giocattoli così eleganti?", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Just a little handicap, nothing more.", "[e:Laughter]Solo un piccolo svantaggio, niente di più.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's not give up just yet.", "[e:Laughter]Non arrendiamoci ancora.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]What?[w:0.5] You of all people?[w:0.5]", "[e:Surprise]Cosa?[w:0.5] Proprio tu?[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I wish it didn't come down to this, but...[w:0.3]", "[e:Neutral]Vorrei che non si fosse arrivati a questo, ma...[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Guess we've got no choice.", "[e:Quiet]Credo che non abbiamo scelta.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This one's tough. Get ready.", "[e:Anger]Questo è tosto. Preparati.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]One wrong move and we're done for.", "[e:Anger]Una mossa sbagliata e per noi è finita.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I really don't like dealing with her...", "[e:Anger]Non mi piace per niente affrontarla...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I always got bad vibes from these guys.[w:0.5]", "[e:Anger]Questi tipi mi hanno sempre dato una brutta impressione.[w:0.5]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I've seen people like them.[w:0.3]", "[e:Anger]Ho già visto persone come loro.[w:0.3]", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Whatever drives them,", "[e:Anger]Qualunque cosa li spinga,", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]we can get through just fine.", "[e:Laughter]ce la caveremo benissimo.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]These guys again...", "[e:Neutral]Di nuovo questi tizi...", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Come on, we didn't get this far just to kick the bucket here.", "[e:Laughter]Forza, non siamo arrivati fin qui per lasciarci le penne.", Language.Italian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]This is getting dangerous. Get ready.", "[e:Neutral]La situazione si fa pericolosa. Preparati.", Language.Italian);


        }
    }
